(201101, 2011, 'K1-C1-L1-O01', null, 1, 'أن يعرف الطالب الكيمياء', 'أن يعرّف الطالب الكيمياء.', '[]'::jsonb, 'أن يعرّف الطالب الكيمياء.', 'ضبط الفعل «يعرّف» بالشدة لرفع اللبس مع «يعرِف»، وحذف المسافة قبل النقطة.', 'إملائي', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["الكيمياء","المادة","التغيرات"]'::jsonb, null, '[14,18,38]'::jsonb, 'مغطى', 'الفكرة الرئيسة للدرس: «الكيمياء هي دراسة المادة والتغيرات التي تطرأ عليها»، وتتكرر في النص (ص14) والخلاصة (ص18). السؤال 25 في تقويم الفصل يطلب تعريف الكيمياء والمادة الكيميائية.', null, 'approved', '2026-10-17'::timestamptz),
(201102, 2011, 'K1-C1-L1-O02', null, 2, 'أن يعرف الطالب المادة الكيميائية .', 'أن يعرّف الطالب المادة الكيميائية.', '[]'::jsonb, 'أن يعرّف الطالب المادة الكيميائية.', 'ضبط الفعل «يعرّف» بالشدة لرفع اللبس مع «يعرِف»، وحذف المسافة قبل النقطة.', 'إملائي', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["المادة الكيميائية","المادة النقية","تركيب محدد وثابت"]'::jsonb, null, '[15,18,38]'::jsonb, 'مغطى', '«المادة الكيميائية لها تركيب محدد وثابت وتسمى بالمادة النقية» (ص15)، ومثالها غاز الأوزون O3 المكوّن من ذرات الأكسجين، وتتكرر في الخلاصة (ص18). السؤال 2 يطلب تعريفها وإعطاء مثالين.', null, 'approved', '2026-10-17'::timestamptz),
(201103, 2011, 'K1-C1-L1-O03', null, 3, 'أن يذكر الطالب أضرار الأشعة فوق البنفسجية UVB .', 'أن يذكر الطالب أضرار الأشعة فوق البنفسجية (UVB).', '[]'::jsonb, 'أن يذكر الطالب أضرار الأشعة فوق البنفسجية (UVB).', 'حذف المسافة قبل النقطة وإدخال الرمز UVB بين قوسين.', 'إملائي', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["الأشعة فوق البنفسجية UVB","إعتام العين","سرطان الجلد","سلاسل الغذاء"]'::jsonb, null, '[15,18]'::jsonb, 'مغطى', 'التعرض الزائد للأشعة فوق البنفسجية مؤذٍ للنباتات والحيوانات، والمستويات العالية من UVB يمكن أن تسبب إعتامًا في العين وسرطانًا في الجلد عند الإنسان، وتقلل من نواتج المحاصيل الزراعية، وتسبب خللًا في سلاسل الغذاء (ص15). السؤال 5 يطلب تفسير قلق العلماء من تزايد UVB.', null, 'approved', '2026-10-17'::timestamptz),
(201104, 2011, 'K1-C1-L1-O04', null, 4, 'أن يوضح الطالب كيف يتكون الأوزون و أهميته و تركيبه و مكان تواجده .', 'أن يوضح الطالب كيف يتكوّن الأوزون، وأهميته، وتركيبه، ومكان وجوده.', '["أن يوضح الطالب كيف يتكوّن الأوزون.","أن يوضح الطالب أهمية طبقة الأوزون.","أن يذكر الطالب تركيب جزيء الأوزون.","أن يحدد الطالب مكان وجود طبقة الأوزون في الغلاف الجوي."]'::jsonb, 'أن يوضح الطالب كيف يتكوّن الأوزون، وأهميته، وتركيبه، ومكان وجوده.', 'تصحيح علامات الترقيم وتبديل «تواجده» بـ«وجوده». الهدف مركّب من أربعة مطالب، ويُنصح بتقسيمه عند كتابة الأسئلة.', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["تكوّن الأوزون","O3","الستراتوسفير","امتصاص الأشعة فوق البنفسجية"]'::jsonb, null, '[15,16,18,38]'::jsonb, 'مغطى', 'التكوّن: تحلل الأشعة فوق البنفسجية جزيئات O2 في الأجزاء العليا من الستراتوسفير إلى ذرات O، وتتحد كل ذرة مع جزيء O2 فيتكوّن O3 (الشكل 1-3، ص16)، ويمتص الأوزون الأشعة فوق البنفسجية فيتحلل فينشأ توازن بين O2 وO3. الأهمية: يمتص معظم الأشعة الضارة قبل وصولها إلى الأرض. التركيب: ثلاث ذرات أكسجين (O3). المكان: طبقة الستراتوسفير على ارتفاع 10–50 km، ويتركز نحو 90% من غاز الأوزون فيها (ص15).', null, 'approved', '2026-10-17'::timestamptz),
(201105, 2011, 'K1-C1-L1-O05', null, 5, 'أن يذكر الطالب قياس كمية الأوزون في الغلاف الجوي .', 'أن يذكر الطالب كيفية قياس كمية الأوزون في الغلاف الجوي.', '[]'::jsonb, 'أن يذكر الطالب كيفية قياس كمية الأوزون في الغلاف الجوي.', 'العبارة «قياس كمية الأوزون» غير محددة؛ جرى توضيح المطلوب (طريقة القياس ووحدته) ليصبح قابلًا للقياس.', 'صياغة', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["وحدة دوبسون DU","قياس الأوزون","مطياف بريور"]'::jsonb, null, '[16,17,27]'::jsonb, 'مغطى', 'بدأ دوبسون (1889–1976م) قياس كمية الأوزون في عشرينيات القرن الماضي، وتقاس كميته في الستراتوسفير بأجهزة على الأرض أو بالونات أو أقمار اصطناعية أو صواريخ؛ ووحدة القياس دوبسون DU، والمستوى الطبيعي 300 DU (ص16). الشكل 1-4 مطياف بريور، والشكل 1-15 مطياف الأشعة فوق البنفسجية والمرئية.', null, 'approved', '2026-10-17'::timestamptz),
(201106, 2011, 'K1-C1-L1-O06', null, 6, 'أن يوضح الطالب سبب تقلص طبقة الأوزون في الغلاف الجوي .', 'أن يوضح الطالب سبب تقلّص طبقة الأوزون في الغلاف الجوي.', '[]'::jsonb, 'أن يوضح الطالب سبب تقلّص طبقة الأوزون في الغلاف الجوي.', 'حذف المسافة قبل النقطة وضبط «تقلّص».', 'إملائي', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["تقلص طبقة الأوزون","مركبات CFCs","ذرة الكلور","ClO"]'::jsonb, null, '[17,18,25,30,38]'::jsonb, 'مغطى', 'لاحظ فريق بحث بريطاني انخفاض كمية الأوزون في الستراتوسفير (ص17). وفق نموذج مولينا ورولاند تصل CFCs إلى الستراتوسفير فتفصل الأشعة فوق البنفسجية ذرة الكلور Cl، فتتحد مع O3 مكوّنة O2 وClO، ثم تتحد ClO مع ذرة O فتتحرر Cl لتدمّر جزيء أوزون آخر وهكذا (الشكل 1-13، ص25). ويضيف الكتاب مواد أخرى تفكك الأوزون: رابع كلوريد الكربون CCl4 وميثيل الكلوروفورم والمواد المحتوية على البروم (ص30). السؤال 28 يطلب سبب تناقص سمك الطبقة.', null, 'approved', '2026-10-17'::timestamptz),
(201107, 2011, 'K1-C1-L1-O07', null, 7, 'أن يفسر الطالب سبب استخدام مركبات الكلوروفلوروكربون للتبريد', 'أن يفسر الطالب سبب استخدام مركبات الكلوروفلوروكربون في التبريد.', '[]'::jsonb, 'أن يفسر الطالب سبب استخدام مركبات الكلوروفلوروكربون في التبريد.', 'استبدال اللام بـ«في» (الأدق لغويًا) وإضافة النقطة.', 'لغوي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["مركبات الكلوروفلوروكربون","التبريد","مبردات آمنة"]'::jsonb, null, '[17,18]'::jsonb, 'مغطى', 'استُعملت في البداية غازات ضارة كالأمونيا للتبريد، وقد تتسرب فتؤذي أفراد البيت، فبحث الكيميائيون عن مبردات أكثر أمنًا؛ وحضّر ميجلي عام 1928م أول مركّب من CFCs، وهي غير سامة لأنها لا تتفاعل مباشرة مع المواد الأخرى، فكانت مبردات مثالية، وبدأ استعمالها في الثلاجات وأجهزة التكييف عام 1935م (ص17). السؤال «ماذا قرأت؟» (ص17) والسؤال 4 (ص18).', null, 'approved', '2026-10-17'::timestamptz),
(201108, 2011, 'K1-C1-L1-O08', null, 8, 'أن يوضح الطالب الهدف من اجتماع الزعماء في مونتريال .', 'أن يوضح الطالب الهدف من اجتماع الزعماء في مونتريال.', '[]'::jsonb, 'أن يوضح الطالب الهدف من اجتماع الزعماء في مونتريال.', 'حذف المسافة قبل النقطة.', 'إملائي', 'سليم ويعتمد', 'فهم', 'حقائق ومصطلحات', '["ميثاق مونتريال","1987م","إنهاء استعمال CFCs"]'::jsonb, null, '[30]'::jsonb, 'مغطى', 'اجتمع عام 1987م زعماء عدة دول في مونتريال بكندا (منها المملكة العربية السعودية) ووقّعوا ميثاق مونتريال الذي يقضي بإنهاء استعمال هذه المركبات ووضع قيود على كيفية استعمالها. كما وافقت دول مجلس التعاون الخليجي على نظام موحّد بشأن المواد المستنفذة لطبقة الأوزون (المعدّل 2012) لإحلال البدائل الآمنة. الشكل 1-17 يبيّن تراجع الاستهلاك العالمي لـ CFCs بعد الميثاق دون تقلص فوري لكمياتها فوق القارة المتجمدة.', null, 'approved', '2026-10-17'::timestamptz),
(201109, 2011, 'K1-C1-L1-O09', null, 9, 'أن يوضح الطالب العوامل التي تستثير تكون الأوزون فوق القارة القطبية الجنوبية .', 'أن يوضح الطالب العوامل التي تستثير تكوّن ثقب الأوزون فوق القارة القطبية الجنوبية.', '[]'::jsonb, 'أن يوضح الطالب العوامل التي تستثير تكوّن ثقب الأوزون فوق القارة القطبية الجنوبية.', 'الأصل «تكون الأوزون»، وموضوع الكتاب هو تكوّن «ثقب» الأوزون؛ أضيفت كلمة «ثقب» لمطابقة المقصود. تحتاج مراجعة المالك.', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["ثقب الأوزون","القارة المتجمدة الجنوبية","الغيوم الجليدية","الكلور والبروم النشطان"]'::jsonb, null, '[31,32]'::jsonb, 'مغطى', 'يتكوّن ثقب الأوزون سنويًا فوق القارة المتجمدة الجنوبية في فصل الربيع. تتكوّن غيوم جليدية في الستراتوسفير عندما تنخفض الحرارة إلى −78°C، وتحدث فيها تغيرات تساعد على إنتاج كلور وبروم نشطين كيميائيًا؛ وعند ارتفاع الحرارة في الربيع يبدأ هذان العنصران بالتفاعل مع الأوزون فيتناقص (ص31). الأسئلة: «ماذا قرأت؟» (ص31) ومختبر تحليل البيانات (ص32).', null, 'approved', '2026-10-17'::timestamptz),
(201110, 2011, 'K1-C1-L1-O10', null, 10, 'أن تعلل الطالب سبب تكون غاز الاوزون فوق خط الاستواء', 'أن يعلل الطالب سبب تكوّن غاز الأوزون فوق خط الاستواء.', '[]'::jsonb, 'أن يعلل الطالب سبب تكوّن غاز الأوزون فوق خط الاستواء.', 'تصحيح «تعلل» إلى «يعلل»، وهمزة «الأوزون»، وإضافة النقطة.', 'إملائي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["خط الاستواء","أشعة الشمس العمودية","تيارات الهواء في الستراتوسفير"]'::jsonb, null, '[16]'::jsonb, 'مغطى', '«يتكوّن [الأوزون] فوق خط الاستواء لأن أشعة الشمس تكون عمودية وقوية هناك، ثم يتحرك حول الأرض بفعل تيارات الهواء في الستراتوسفير»، ولذلك يعد مؤشرًا مناسبًا يساعد على تتبع حركة الرياح في طبقة الستراتوسفير (ص16).', null, 'approved', '2026-10-17'::timestamptz),
(201111, 2011, 'K1-C1-L1-O11', null, 11, 'أن يعدد الطالب اجهزة قياس ثقب الاوزون', 'أن يعدّد الطالب الأجهزة المستخدمة في قياس كمية الأوزون ومراقبة ثقب الأوزون.', '[]'::jsonb, 'أن يعدّد الطالب الأجهزة المستخدمة في قياس كمية الأوزون ومراقبة ثقب الأوزون.', 'تصحيح الهمزة في «أجهزة» وتوضيح أن الأجهزة تقيس كمية الأوزون لا الثقب نفسه.', 'صياغة', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["مطياف بريور","البالونات","الأقمار الاصطناعية","الصواريخ والطائرات"]'::jsonb, null, '[16,17,27,31]'::jsonb, 'مغطى', 'يذكر الكتاب أن الكمية تقاس بأجهزة موجودة على الأرض أو بالونات أو أقمار اصطناعية أو صواريخ (ص16)، وأن البالونات والطائرات والأقمار الاصطناعية أيّدت قياسات الثقب (ص17). أجهزة بالاسم: مطياف بريور (الشكل 1-4) ومطياف الأشعة فوق البنفسجية والمرئية (الشكل 1-15، ص27)، وصور الأقمار الاصطناعية (الأشكال 1-5 و1-18). لا يعرض الكتاب قائمة منظمة بالأجهزة.', null, 'approved', '2026-10-17'::timestamptz),
(201112, 2011, 'K1-C1-L1-O12', null, 12, 'أن يذكر الطالب العناصر المكوّنة لمركبات الكلوروفلوروكربون ومجالات استخدامها.', 'أن يذكر الطالب العناصر المكوّنة لمركبات الكلوروفلوروكربون ومجالات استخدامها.', '[]'::jsonb, 'أن يذكر الطالب العناصر المكوّنة لمركبات الكلوروفلوروكربون ومجالات استخدامها.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["CFCs","الكلور والفلور والكربون","علب الرش","الثلاجات والمكيفات"]'::jsonb, null, '[17,18,38]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). CFCs مادة مكوّنة من الكلور والفلور والكربون، حضّر ميجلي أول مركّب منها عام 1928م. استُعملت في أجهزة التكييف المنزلية والثلاجات وتصنيع البوليمرات ودفع الرذاذ من علب الرش (ملطفات الجو والمبيدات الحشرية) (ص17). السؤال 27 (ص38) والسؤال 4 (ص18).', null, 'approved', '2026-10-17'::timestamptz),
(201113, 2011, 'K1-C1-L1-O13', null, 13, 'أن يفسر الطالب رسومًا بيانية تمثّل تركيز CFCs وكمية غاز الأوزون عبر الزمن.', 'أن يفسر الطالب رسومًا بيانية تمثّل تركيز CFCs وكمية غاز الأوزون عبر الزمن.', '[]'::jsonb, 'أن يفسر الطالب رسومًا بيانية تمثّل تركيز CFCs وكمية غاز الأوزون عبر الزمن.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تحليل', 'إجراءات ومهارات', '["الرسم البياني","تركيز CFCs","ppt","وحدة دوبسون"]'::jsonb, null, '[18,30,31,32,38,39]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). الشكل 1-6: ارتفع تركيز CFC-11 في الغلاف الجوي من نحو 140 إلى نحو 270 ppt بين 1977 و1995م (ppt: جزء من تريليون). الشكل 1-17: تراجع الاستهلاك العالمي لـ CFCs بعد ميثاق مونتريال مع بقاء كميتها فوق القارة المتجمدة دون تقلص مباشر. مختبر تحليل البيانات (ص32): كمية الأوزون ودرجة الحرارة على ارتفاع 20–24 km عامي 2004 و2005م. الأسئلة 30 و48 و49.', null, 'approved', '2026-10-17'::timestamptz),
(201114, 2011, 'K1-C1-L1-O14', null, 14, 'أن يحسب الطالب عدد جزيئات الأوزون الناتجة عن عدد معلوم من ذرات الأكسجين، ويربط بين عدد الذرات وعدد الجزيئات.', 'أن يحسب الطالب عدد جزيئات الأوزون الناتجة عن عدد معلوم من ذرات الأكسجين، ويربط بين عدد الذرات وعدد الجزيئات.', '[]'::jsonb, 'أن يحسب الطالب عدد جزيئات الأوزون الناتجة عن عدد معلوم من ذرات الأكسجين، ويربط بين عدد الذرات وعدد الجزيئات.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'حل مسائل', '["جزيء الأوزون O3","ذرة الأكسجين","عدد الجزيئات"]'::jsonb, null, '[15,16,38,39]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). يتكوّن جزيء الأوزون من ثلاث ذرات أكسجين (ص15–16). السؤال 29 (ص38): 6 و9 و27 ذرة أكسجين تعطي 2 و3 و9 جزيئات أوزون. السؤال 41 (ص39): تتفاعل ذرة C مع جزيء O3 فينتج CO وO2، فيلزم 24 جزيء أوزون لإنتاج 24 جزيء O2.', null, 'approved', '2026-10-17'::timestamptz),
(201201, 2012, 'K1-C1-L2-O01', null, 1, 'أن يفسر الطالب سبب وجود عدة فروع لعلم الكيمياء.', 'أن يفسر الطالب سبب وجود عدة فروع لعلم الكيمياء.', '[]'::jsonb, 'أن يفسر الطالب سبب وجود عدة فروع لعلم الكيمياء.', 'الصياغة سليمة.', 'لا تغيير', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["فروع الكيمياء","تنوع المادة"]'::jsonb, null, '[21,36]'::jsonb, 'مغطى', '«بسبب وجود أنواع كثيرة من المادة فإن مجالات الدراسة في الكيمياء تتنوع؛ إذ تقسم الكيمياء تقليديًا إلى فروع تركز على دراسة معينة»، ويتداخل كثير منها (مثلًا تشترك العضوية وكيمياء البوليمرات في دراسة البلاستيك). السؤال 8 (ص21) والجدول 1-1.', null, 'approved', '2026-10-17'::timestamptz),
(201202, 2012, 'K1-C1-L2-O02', null, 2, 'أن يقارن الطالب بين الكتلة و الوزن .', 'أن يقارن الطالب بين الكتلة والوزن.', '[]'::jsonb, 'أن يقارن الطالب بين الكتلة والوزن.', 'حذف المسافة قبل «و» وقبل النقطة.', 'إملائي', 'سليم ويعتمد', 'تحليل', 'مفاهيم', '["الكتلة","الوزن","قوة الجاذبية"]'::jsonb, null, '[19,20,21,38]'::jsonb, 'مغطى', 'الكتلة مقياس كمية المادة وهي ثابتة في أي مكان؛ والوزن مقياس كمية المادة وقوة جذب الأرض لها، وهو يتغير بتغير موضع الجسم (يقل عند الابتعاد عن سطح الأرض). وزن الجسم = كتلته × تسارع الجاذبية الأرضية المحلي (ص20). ولذلك يستعمل العلماء الكتلة. الأسئلة 9 و13 و14 و31 و33.', null, 'approved', '2026-10-17'::timestamptz),
(201203, 2012, 'K1-C1-L2-O03', null, 3, 'ان يفسر الطالب سبب اهتمام الكيميائيين بالوصف تحت المجهري للمادة', 'أن يفسر الطالب سبب اهتمام الكيميائيين بالوصف تحت المجهري للمادة.', '[]'::jsonb, 'أن يفسر الطالب سبب اهتمام الكيميائيين بالوصف تحت المجهري للمادة.', 'تصحيح همزة «أن» وإضافة النقطة.', 'إملائي', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["المستوى تحت المجهري","الذرات","الخواص الملحوظة"]'::jsonb, null, '[20,21,36]'::jsonb, 'مغطى', 'تتركب المواد من ذرات صغيرة جدًا لا ترى بالمجاهر الضوئية (تريليون ذرة تشغل حيزًا يساوي النقطة في آخر الجملة). تفسّر بنية المادة وتركيبها وسلوكها على المستوى تحت المجهري، وكل ما نلاحظه يعتمد على تركيب الذرات والتغيرات التي تحدث لها؛ فهدف الكيمياء تفسير الأحداث التي لا ترى بالعين المجردة (ص20). السؤالان 10 و11.', null, 'approved', '2026-10-17'::timestamptz),
(201204, 2012, 'K1-C1-L2-O04', null, 4, 'ان يحدد الطالب المجالات التي يدرسها كل فرع من فروع الكيمياء .', 'أن يحدد الطالب المجالات التي يدرسها كل فرع من فروع الكيمياء.', '[]'::jsonb, 'أن يحدد الطالب المجالات التي يدرسها كل فرع من فروع الكيمياء.', 'تصحيح همزة «أن» وحذف المسافة قبل النقطة.', 'إملائي', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["الكيمياء العضوية","الكيمياء غير العضوية","الكيمياء الفيزيائية","الكيمياء التحليلية","الكيمياء الحيوية","الكيمياء البيئية"]'::jsonb, null, '[21,36,38,39]'::jsonb, 'مغطى', 'الجدول 1-1 يعرض عشرة فروع ومجال دراسة كل منها مع أمثلة: العضوية (المواد المحتوية على كربون)، غير العضوية (المواد التي لا تحتوي على كربون عمومًا)، الفيزيائية (سلوك المادة وتغيراتها وتغيرات الطاقة المصاحبة)، التحليلية (أنواع المواد ومكوناتها)، الحيوية (المادة والعمليات الحيوية في المخلوقات الحية)، البيئية (المادة والبيئة)، الصناعية (العمليات الكيميائية في الصناعة)، كيمياء البوليمرات (البلمرات والمواد البلاستيكية)، الذرية (نظريات تركيب المادة)، الحرارية (الحرارة الناتجة عن العمليات الكيميائية). الأسئلة 32 و44.', null, 'approved', '2026-10-17'::timestamptz),
(201205, 2012, 'K1-C1-L2-O05', null, 5, 'أن يعرّف الطالب المادة، ويميّز بين ما يُعدّ مادة وما لا يُعدّ مادة.', 'أن يعرّف الطالب المادة، ويميّز بين ما يُعدّ مادة وما لا يُعدّ مادة.', '[]'::jsonb, 'أن يعرّف الطالب المادة، ويميّز بين ما يُعدّ مادة وما لا يُعدّ مادة.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["المادة","الكتلة","الحيز","الهواء"]'::jsonb, null, '[14,19]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). المادة: كل ما له كتلة ويشغل حيزًا (ص14). الهواء مادة (لأنه يشغل حيزًا وله كتلة؛ البالون المنفوخ أثقل). ليست مادة: الأفكار والآراء والحرارة والضوء وموجات الراديو والمجالات المغناطيسية (ص19).', null, 'approved', '2026-10-17'::timestamptz),
(201206, 2012, 'K1-C1-L2-O06', null, 6, 'أن يعرّف الطالب النموذج، ويذكر أمثلة على النماذج التي يستعملها العلماء وفائدتها.', 'أن يعرّف الطالب النموذج، ويذكر أمثلة على النماذج التي يستعملها العلماء وفائدتها.', '[]'::jsonb, 'أن يعرّف الطالب النموذج، ويذكر أمثلة على النماذج التي يستعملها العلماء وفائدتها.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["النموذج","نموذج حاسوبي","نموذج مادي"]'::jsonb, null, '[20,21]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). النموذج تفسير مرئي أو لفظي أو رياضي للبيانات التجريبية. يستعمله العلماء لتوضيح الأفكار المعقدة ولاختبار مفهوم أو تصميم قبل إنتاجه (نموذج توسعة الحرم المكي، نموذج الطائرة، النموذج الحاسوبي للطائرة)، ويستعمله الكيميائيون لتمثيل المادة والذرات (ص20). السؤالان 11 و12 (ص21).', null, 'approved', '2026-10-17'::timestamptz),
(201301, 2013, 'K1-C1-L3-O01', null, 1, 'ان يعرف الطالب الطريقة العلمية.', 'أن يعرّف الطالب الطريقة العلمية.', '[]'::jsonb, 'أن يعرّف الطالب الطريقة العلمية.', 'تصحيح همزة «أن» وضبط «يعرّف».', 'إملائي', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["الطريقة العلمية","الطريقة النظامية"]'::jsonb, null, '[22,26,37]'::jsonb, 'مغطى', 'الطريقة العلمية طريقة منظمة تستعمل في الدراسات العلمية (كيميائية أو حيوية أو فيزيائية) لحل المشكلات وللتحقق من عمل العلماء الآخرين (ص22). في مراجعة المفردات: «الطريقة النظامية: أسلوب منظم لحل المشكلات». الخلاصة (ص26).', null, 'approved', '2026-10-17'::timestamptz),
(201302, 2013, 'K1-C1-L3-O02', null, 2, 'أن يقارن الطالب بين أنواع البيانات.', 'أن يقارن الطالب بين أنواع البيانات.', '[]'::jsonb, 'أن يقارن الطالب بين أنواع البيانات.', 'الصياغة سليمة (الأنواع: النوعية والكمية).', 'لا تغيير', 'سليم ويعتمد', 'تحليل', 'مفاهيم', '["البيانات النوعية","البيانات الكمية"]'::jsonb, null, '[23,26,38,41]'::jsonb, 'مغطى', 'البيانات النوعية ملاحظات تصف باستعمال الحواس (اللون، الرائحة، الشكل، الملمس، الطعم)، والبيانات الكمية معلومات رقمية (درجة الحرارة، الضغط، الحجم، كمية الناتج، السرعة، الطول) (ص23، الشكل 1-10). الأسئلة 16 و36 و39 و9 و10.', null, 'approved', '2026-10-17'::timestamptz),
(201303, 2013, 'K1-C1-L3-O03', null, 3, 'أن يصف الطالب الفرق بين الفرضية و النظرية و القانون العلمي.', 'أن يصف الطالب الفرق بين الفرضية والنظرية والقانون العلمي.', '["أن يعرّف الطالب الفرضية.","أن يعرّف الطالب النظرية العلمية.","أن يعرّف الطالب القانون العلمي.","أن يقارن الطالب بين الفرضية والنظرية والقانون العلمي."]'::jsonb, 'أن يصف الطالب الفرق بين الفرضية والنظرية والقانون العلمي.', 'حذف المسافات قبل «و». الهدف مركّب من ثلاثة مفاهيم، ويمكن تقسيمه عند كتابة الأسئلة.', 'إملائي', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["الفرضية","النظرية","القانون العلمي"]'::jsonb, null, '[23,25,26,37,38]'::jsonb, 'مغطى', 'الفرضية تفسير مؤقت لظاهرة ما أو لما حدث تمت ملاحظته، وهي قابلة للاختبار (ص23). النظرية تفسّر ظاهرة طبيعية بناء على مشاهدات واستقصاءات مع الزمن، وتبقى عرضة للبحث والتعديل، وتعد ناجحة إذا أمكن استعمالها للتوقع الصحيح. القانون العلمي يصف علاقة في الطبيعة تدعمها عدة تجارب دون استثناءات، كقانون نيوتن للجاذبية (ص26). الأسئلة 18 و37.', null, 'approved', '2026-10-17'::timestamptz),
(201304, 2013, 'K1-C1-L3-O04', null, 4, 'ان يحدد الطالب أنواع المتغيرات و الفرق بينهم.', 'أن يحدد الطالب أنواع المتغيرات والفرق بينها.', '[]'::jsonb, 'أن يحدد الطالب أنواع المتغيرات والفرق بينها.', 'حذف المسافة قبل «و»، وتغيير «بينهم» (ضمير العاقل) إلى «بينها».', 'لغوي', 'يعتمد بعد التعديل', 'تذكر', 'مفاهيم', '["المتغير المستقل","المتغير التابع","العامل الثابت"]'::jsonb, null, '[24,26,38,40,41]'::jsonb, 'مغطى', 'المتغير المستقل هو الذي يخطط لتغييره (درجة الحرارة في تجربة ذوبان الملح)؛ والتابع تتغير قيمته تبعًا لتغير المستقل (سرعة الذوبان) ولا يمكن التحكم في كيفية تغيره؛ والعامل الثابت (كمية الملح والماء وتحريك المزيج) يجب أن يبقى ثابتًا (ص24). الأسئلة 17 و38 وأسئلة الاختبار 5 و12 و13.', null, 'approved', '2026-10-17'::timestamptz),
(201305, 2013, 'K1-C1-L3-O05', null, 5, 'أن يوضح الطالب الهدف من النتائج في التجربة.', 'أن يوضح الطالب دور النتائج والبيانات التجريبية في اختبار الفرضية والتوصل إلى الاستنتاج.', '[]'::jsonb, 'أن يوضح الطالب دور النتائج والبيانات التجريبية في اختبار الفرضية والتوصل إلى الاستنتاج.', '«الهدف من النتائج» غير محدد؛ المقترح يربطه بما يعرضه الكتاب (تحليل البيانات ومقارنتها بالفرضية للاستنتاج). يحتاج موافقة المالك على التفسير.', 'تحويل إلى هدف قابل للقياس', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["النتائج","الاستنتاج","اختبار الفرضية"]'::jsonb, null, '[24,25,40]'::jsonb, 'مغطى جزئيًا', 'يذكر الكتاب أن التجربة تُظهر قدرًا كبيرًا من البيانات يحللها العلماء ويقارنونها بالفرضية للتوصل إلى استنتاج؛ وأن تأييد البيانات للفرضية يشير إلى أنها قد تكون صحيحة دون إثباتها، وأن عدم دعمها يعني رفضها أو تعديلها (ص25). لا يعرّف «النتائج» مصطلحًا مستقلًا ولا يذكر «هدفها»، وتظهر خانة «النتيجة» فارغة في صفحة دفتر المختبر (ص40).', null, 'approved', '2026-10-17'::timestamptz),
(201306, 2013, 'K1-C1-L3-O06', null, 6, 'أن يحدد الطالب خطوات الطريقة العلمية.', 'أن يحدد الطالب خطوات الطريقة العلمية.', '[]'::jsonb, 'أن يحدد الطالب خطوات الطريقة العلمية.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تذكر', 'إجراءات ومهارات', '["الملاحظة","الفرضية","التجربة","الاستنتاج","النظرية","القانون العلمي"]'::jsonb, null, '[22,26,37]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). الشكل 1-9: الملاحظات (المعرفة الحالية، بيانات نوعية، بيانات كمية) ثم الفرضية ثم التجارب ثم الاستنتاج، وتتكرر الخطوات حتى تدعم الفرضية أو تلغيها، وقد تنتهي بنظرية أو قانون علمي (ص22). هذا الهدف ورد في أهداف الكتاب للدرس ولم يرد في الملف الرسمي.', null, 'approved', '2026-10-17'::timestamptz),
(201307, 2013, 'K1-C1-L3-O07', null, 7, 'أن يفسر الطالب سبب عدم استعمال العلماء مجموعة محددة من الخطوات بالترتيب نفسه في كل بحث.', 'أن يفسر الطالب سبب عدم استعمال العلماء مجموعة محددة من الخطوات بالترتيب نفسه في كل بحث.', '[]'::jsonb, 'أن يفسر الطالب سبب عدم استعمال العلماء مجموعة محددة من الخطوات بالترتيب نفسه في كل بحث.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["الطريقة العلمية","الإبداع الفردي","وصف الطريقة"]'::jsonb, null, '[22,26]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). كل عالم يعمل على فهم بناء على رؤية فردية وإبداع ذاتي، ولا يقصد بخطوات الطريقة العلمية أن تنفذ بالترتيب؛ ولذلك يجب أن يصف العلماء طرائقهم عند عرض النتائج ليتمكن غيرهم من تأكيدها، وإلا فهناك شك في صدقها (ص22). السؤال 15.', null, 'approved', '2026-10-17'::timestamptz),
(201308, 2013, 'K1-C1-L3-O08', null, 8, 'أن يوضح الطالب دور الضابط في التجربة، ويحدده في تجربة معطاة.', 'أن يوضح الطالب دور الضابط في التجربة، ويحدده في تجربة معطاة.', '[]'::jsonb, 'أن يوضح الطالب دور الضابط في التجربة، ويحدده في تجربة معطاة.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["الضابط","المقارنة","العامل الثابت"]'::jsonb, null, '[24,25,26,41]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). الضابط يستعمل للمقارنة: الماء عند درجة حرارة الغرفة 20°C في تجربة ذوبان الملح، وأنابيب الكاشف في الشكل 1-12 (حمضي/ماء/قاعدي) تمثل ضوابط لأن حموضة محاليلها معروفة (ص24). السؤال 17 (الضابط الذي ستقارن به) وسؤال الاختبار 8.', null, 'approved', '2026-10-17'::timestamptz),
(201309, 2013, 'K1-C1-L3-O09', null, 9, 'أن يقوّم الطالب مدى دعم البيانات التجريبية للفرضية، ويحدد ما يُفعل عند عدم دعمها لها.', 'أن يقوّم الطالب مدى دعم البيانات التجريبية للفرضية، ويحدد ما يُفعل عند عدم دعمها لها.', '[]'::jsonb, 'أن يقوّم الطالب مدى دعم البيانات التجريبية للفرضية، ويحدد ما يُفعل عند عدم دعمها لها.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تقويم', 'إجراءات ومهارات', '["دعم الفرضية","رفض الفرضية","تعديل الفرضية"]'::jsonb, null, '[25,38,40]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). الاستنتاج حكم قائم على المعلومات التي يتم الحصول عليها؛ لا يمكن إثبات الفرضية، وتأييد البيانات يشير إلى أنها قد تكون صحيحة، وإذا لم تدعمها البيانات فعلينا رفضها أو تعديلها (ص25). السؤال 40 وسؤال الاختبار 3 و4.', null, 'approved', '2026-10-17'::timestamptz),
(201310, 2013, 'K1-C1-L3-O10', null, 10, 'أن يوضح الطالب كيف يُستعمل النموذج العلمي في إجراء توقعات يمكن اختبارها.', 'أن يوضح الطالب كيف يُستعمل النموذج العلمي في إجراء توقعات يمكن اختبارها.', '[]'::jsonb, 'أن يوضح الطالب كيف يُستعمل النموذج العلمي في إجراء توقعات يمكن اختبارها.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["النموذج العلمي","نموذج مولينا ورولاند","التوقع","ضبط المتغيرات"]'::jsonb, null, '[25,26]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). النماذج العلمية الجيدة يمكن فحصها واستعمالها للتوقع: توقّع نموذج مولينا ورولاند تكوّن الكلور وتناقص الأوزون، وأيّدت قياسات مجموعة أخرى تفاعل الأوزون مع الكلور، ففازا بجائزة نوبل عام 1995م. وضبط المتغيرات في الجو صعب (رياح، تغير الأشعة فوق البنفسجية، غازات أخرى) فتُحاكى الظروف مخبريًا (ص25). السؤال 19 (ص26).', null, 'approved', '2026-10-17'::timestamptz),
(201401, 2014, 'K1-C1-L4-O01', null, 1, 'ان يقارن الطالب بين البحث النظري و البحث التطبيقي.', 'أن يقارن الطالب بين البحث النظري والبحث التطبيقي.', '[]'::jsonb, 'أن يقارن الطالب بين البحث النظري والبحث التطبيقي.', 'تصحيح همزة «أن» وحذف المسافات قبل «و» وقبل النقطة.', 'إملائي', 'سليم ويعتمد', 'تحليل', 'مفاهيم', '["البحث النظري","البحث التطبيقي"]'::jsonb, null, '[27,33,37,41]'::jsonb, 'مغطى', 'البحث النظري يجرى من أجل المعرفة نفسها (مولينا ورولاند دفعهما حب الاستطلاع إلى دراسة CFCs)، والبحث التطبيقي يجرى لحل مشكلة محددة (مراقبة كميات CFCs وتغيرات الأوزون السنوية والبحث عن بدائل لها)؛ وقد تحوّل البحث النظري إلى تطبيقي بعد اكتشاف ثقب الأوزون عام 1985م (ص27). مثال الأشعة السينية. السؤالان 21 و22 وسؤال الاختبار 6.', null, 'approved', '2026-10-17'::timestamptz),
(201402, 2014, 'K1-C1-L4-O02', null, 2, 'أن يطبق الطالب تعليمات السلامة في المختبر.', 'أن يطبق الطالب تعليمات السلامة في المختبر.', '[]'::jsonb, 'أن يطبق الطالب تعليمات السلامة في المختبر.', 'الصياغة سليمة.', 'لا تغيير', 'سليم ويعتمد', 'تطبيق', 'إجراءات ومهارات', '["السلامة في المختبر","النظارات الواقية","المواد الكيميائية"]'::jsonb, null, '[28,29,33,39,40]'::jsonb, 'مغطى', 'الجدول 1-2 يضم 24 تعليمة: دراسة التجربة قبل الحضور، عدم إجراء تجارب دون إذن، فهم رموز السلامة، لبس النظارة والمعطف والقفازات، عدم لبس العدسات اللاصقة، عدم إدخال الطعام، قراءة بطاقة العبوة، أخذ كميات قليلة وعدم إعادة المتبقي إلى العبوة الأصلية، عدم التذوق، إضافة الحمض إلى الماء ببطء، التخلص من النفايات، غسل اليدين. الأسئلة 23 و42 و43 وسؤال الاختبار 1.', null, 'approved', '2026-10-17'::timestamptz),
(201403, 2014, 'K1-C1-L4-O03', null, 3, 'أن يذكر الطالب فوائد الكيمياء', 'أن يذكر الطالب فوائد الكيمياء.', '[]'::jsonb, 'أن يذكر الطالب فوائد الكيمياء.', 'إضافة النقطة.', 'إملائي', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["فوائد الكيمياء","التقنية","الأدوية واللقاحات"]'::jsonb, null, '[14,32,33]'::jsonb, 'مغطى', 'تتيح الكيمياء الراحة والرفاهية (التبريد والثلاجات والمكيفات، كريمات الوقاية من الشمس) (ص14)؛ ويشارك الكيميائيون في حل مشكلة الأوزون وفي اكتشاف أدوية ولقاحات (الإيدز والأنفلونزا) (ص32)؛ وتطورات تقنية كالسيارة العاملة بالهواء المضغوط (دون ملوثات) والغواصة الصغيرة (4 mm) لتشخيص الأمراض (ص33). السؤالان 20 و47.', null, 'approved', '2026-10-17'::timestamptz),
(201404, 2014, 'K1-C1-L4-O04', null, 4, 'أن يعرف الطالب الاكتشافات غير المقصودة،ويعطي أمثلة.', 'أن يعرّف الطالب الاكتشافات غير المقصودة ويعطي أمثلة عليها.', '[]'::jsonb, 'أن يعرّف الطالب الاكتشافات غير المقصودة ويعطي أمثلة عليها.', 'ضبط «يعرّف» وتصحيح مواضع الفاصلة وإضافة «عليها».', 'صياغة', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["الاكتشافات غير المقصودة","البنسلين","النايلون"]'::jsonb, null, '[28,33,37,39]'::jsonb, 'مغطى', 'تحدث بعض الاكتشافات دون قصد (ص33): اكتشاف فلمنج للبنسلين عندما لاحظ منطقة خالية من البكتيريا حول فطر أخضر في طبق مزروع ببكتيريا ستافيلوكوكس؛ واكتشاف النايلون عام 1931م حين سحب جوليان هيل أليافًا طويلة من قضيب زجاجي غمس في مخلوط محاليل، ثم طُوّر عام 1934م، واستُعمل بديلًا للحرير في المظلات (ص28). لا يعطي الكتاب تعريفًا نصيًا مستقلًا، وإنما أمثلة وخلاصة.', null, 'approved', '2026-10-17'::timestamptz),
(201405, 2014, 'K1-C1-L4-O05', null, 5, 'أن يعرّف الطالب التقنية، ويذكر أمثلة على منتجات تقنية حسّنت حياتنا.', 'أن يعرّف الطالب التقنية، ويذكر أمثلة على منتجات تقنية حسّنت حياتنا.', '[]'::jsonb, 'أن يعرّف الطالب التقنية، ويذكر أمثلة على منتجات تقنية حسّنت حياتنا.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["التقنية","المنتجات التقنية","البحث التطبيقي"]'::jsonb, null, '[19,27,33]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). «التقنية: التطبيق العملي للمعرفة العلمية» (مراجعة المفردات ص19). أمثلة: السيارة العاملة بالهواء المضغوط والغواصة الصغيرة (ص33). السؤالان 20 و22. هدف الدرس في الكتاب يتضمن التقنية.', null, 'approved', '2026-10-17'::timestamptz),
(201406, 2014, 'K1-C1-L4-O06', null, 6, 'أن يصنّف الطالب عينة ماء (يسر، متوسط، عسر، عسر جدًا) بحساب تركيز الكالسيوم أو الماغنسيوم بوحدة mg/L.', 'أن يصنّف الطالب عينة ماء (يسر، متوسط، عسر، عسر جدًا) بحساب تركيز الكالسيوم أو الماغنسيوم بوحدة mg/L.', '[]'::jsonb, 'أن يصنّف الطالب عينة ماء (يسر، متوسط، عسر، عسر جدًا) بحساب تركيز الكالسيوم أو الماغنسيوم بوحدة mg/L.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'حل مسائل', '["عسر الماء","تركيز Ca وMg","mg/L"]'::jsonb, null, '[35]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). التصنيف: 0–60 يسر، 61–120 متوسط، 121–180 عسر، أكثر من 180 عسر جدًا (mg/L). مثال: عينة 50 mL (=0.05 L) تحتوي 7.3 mg ماغنسيوم، فالتركيز 146 mg/L وهو «عسر». يطلب النشاط أيضًا تحديد المتغيرات المستقلة والتابعة والعينة الضابطة.', null, 'approved', '2026-10-17'::timestamptz),
(202101, 2021, 'K1-C2-L1-O01', null, 1, 'أن يقارن الطالب بين الماء النقي وماء البحر.', 'أن يقارن الطالب بين الماء النقي وماء البحر.', '[]'::jsonb, 'أن يقارن الطالب بين الماء النقي وماء البحر.', 'الصياغة سليمة.', 'لا تغيير', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["الماء النقي","ماء البحر","المادة الكيميائية النقية","المخلوط"]'::jsonb, null, '[44]'::jsonb, 'مغطى جزئيًا', 'يذكر الكتاب أن «الماء النقي» مادة كيميائية نقية مكونة من الهيدروجين والأكسجين، وأن ماء الشرب وماء البحر «ليسا نقيين» لأن العينات المأخوذة من أماكن مختلفة تحتوي على كميات مختلفة من المعادن والمواد الذائبة الأخرى. لا يقدّم الكتاب مقارنة تفصيلية بين الماءين في الخواص أو التركيب.', null, 'approved', '2026-10-17'::timestamptz),
(202102, 2021, 'K1-C2-L1-O02', null, 2, 'أن يعرف الطالب حالات المادة.', 'أن يعرّف الطالب حالات المادة.', '[]'::jsonb, 'أن يعرّف الطالب حالات المادة.', 'ضبط الفعل «يعرّف» بالشدة لرفع اللبس مع «يعرِف».', 'إملائي', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["حالات المادة","الصلبة","السائلة","الغازية","البلازما"]'::jsonb, null, '[45,46]'::jsonb, 'مغطى', 'حالات المادة هي الصلبة والسائلة والغازية، ويمكن تصنيف جميع المواد في الطبيعة ضمن إحداها، وتتميز كل حالة بطريقة ملء المادة للوعاء الذي توضع فيه (ص45). يذكر الكتاب حالة رابعة هي البلازما: غاز متأين تكون فيه الإلكترونات حرة وغير مرتبطة بالذرة أو الجزيء، ومعظم مكونات النجوم بلازما. الجسيمات متراصة في الصلب، وأقل تراصًّا في السائل، ومتباعدة جدًّا في الغاز (الأشكال 2-2 إلى 2-4).', null, 'approved', '2026-10-17'::timestamptz),
(202103, 2021, 'K1-C2-L1-O03', null, 3, 'أن يقارن الطالب بين الحالة الصلبة للمادة و السائلة.', 'أن يقارن الطالب بين الحالة الصلبة والحالة السائلة للمادة.', '[]'::jsonb, 'أن يقارن الطالب بين الحالة الصلبة والحالة السائلة للمادة.', 'تصحيح العطف والمسافات، وتوضيح أن المقارنة بين حالتين للمادة نفسها.', 'لغوي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["المادة الصلبة","السائل","الشكل والحجم","قابلية الانضغاط","ترتيب الجسيمات"]'::jsonb, null, '[45]'::jsonb, 'مغطى', 'المادة الصلبة لها شكل وحجم محددان وجسيماتها متراصة بإحكام وغير قابلة للانضغاط وتتمدد قليلًا بالتسخين (أمثلة: الخشب والحديد والسكر)، ولا تحدَّد بالتماسك أو القساوة (الأسمنت قاس والشمع لين وكلاهما صلب). السائل حجمه ثابت ويأخذ شكل الوعاء، وجسيماته غير ثابتة في أماكنها وأقل تراصًّا فتتحرك وتتجاوز بعضها، وهو غير قابل للانضغاط ويتمدد بالتسخين (أمثلة: الماء والدم والزئبق).', null, 'approved', '2026-10-17'::timestamptz),
(202104, 2021, 'K1-C2-L1-O04', null, 4, 'أن يقارن الطالب بين الغاز و البخار.', 'أن يقارن الطالب بين الغاز والبخار.', '[]'::jsonb, 'أن يقارن الطالب بين الغاز والبخار.', 'تصحيح المسافة حول حرف العطف.', 'إملائي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["الغاز","البخار","الحالة الغازية","درجة الحرارة العادية"]'::jsonb, null, '[46]'::jsonb, 'مغطى', 'كلمة «غاز» تشير إلى مادة توجد في الحالة الغازية في درجات الحرارة العادية، أما «بخار» فتشير إلى الحالة الغازية لمادة توجد عادة صلبة أو سائلة في درجات الحرارة العادية؛ فبخار الماء سُمّي بخارًا لأن الماء يوجد سائلًا في درجات الحرارة العادية. والغاز يأخذ شكل الإناء وحجمه، وجسيماته متباعدة جدًّا فتنضغط بسهولة.', null, 'approved', '2026-10-17'::timestamptz),
(202105, 2021, 'K1-C2-L1-O05', null, 5, 'أن يعرف الطالب الخواص الفيزيائية.', 'أن يعرّف الطالب الخواص الفيزيائية.', '[]'::jsonb, 'أن يعرّف الطالب الخواص الفيزيائية.', 'ضبط الفعل «يعرّف» بالشدة لرفع اللبس مع «يعرِف».', 'إملائي', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["الخاصية الفيزيائية","الكتلة","الكثافة","اللون"]'::jsonb, null, '[47]'::jsonb, 'مغطى', 'الخاصية الفيزيائية «خاصية يمكن ملاحظتها أو قياسها دون التغير في تركيب العينة». تصف الخواص الفيزيائية المواد النقية، ومن أمثلتها الكثافة واللون والرائحة والقساوة ودرجة الانصهار ودرجة الغليان (الجدول 2-1). مثال: شكل قلم الرصاص ولونه ووزنه.', null, 'approved', '2026-10-17'::timestamptz),
(202106, 2021, 'K1-C2-L1-O06', null, 6, 'أن يقارن الطالب بين الخواص الفيزيائية المميزة وغير المميزة.', 'أن يقارن الطالب بين الخواص الفيزيائية المميزة وغير المميزة.', '[]'::jsonb, 'أن يقارن الطالب بين الخواص الفيزيائية المميزة وغير المميزة.', 'الصياغة سليمة.', 'لا تغيير', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["الخاصية المميزة","الخاصية غير المميزة","الكثافة","الكتلة"]'::jsonb, null, '[47]'::jsonb, 'مغطى', 'الخواص غير المميزة تعتمد على كمية المادة الموجودة (الكتلة والطول والحجم)، أما الخواص المميزة فلا تعتمد على كمية المادة (الكثافة ودرجة الانصهار ودرجة الغليان)؛ فكثافة مادة عند درجة حرارة وضغط ثابتين واحدة مهما كانت كميتها. يمكن تعرّف المادة بخواصها المميزة، وقد تكفي خاصية مميزة واحدة (كرائحة التوابل، الشكل 2-5).', null, 'approved', '2026-10-17'::timestamptz),
(202107, 2021, 'K1-C2-L1-O07', null, 7, 'أن يعرف الطالب الخواص الكيميائية ويذكر أمثلة عليها.', 'أن يعرّف الطالب الخواص الكيميائية ويذكر أمثلة عليها.', '[]'::jsonb, 'أن يعرّف الطالب الخواص الكيميائية ويذكر أمثلة عليها.', 'ضبط الفعل «يعرّف» بالشدة لرفع اللبس مع «يعرِف».', 'إملائي', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["الخاصية الكيميائية","الصدأ","التفاعل الكيميائي"]'::jsonb, null, '[48]'::jsonb, 'مغطى', 'تظهر الخاصية الكيميائية عندما يتغير تركيب المادة باتحادها مع مادة أخرى أو بتعرضها لمؤثر كالحرارة أو الكهرباء؛ وهي قدرة المادة على الاتحاد مع غيرها أو التحول إلى مادة أخرى. أمثلة: تكوّن الصدأ عند اتحاد الحديد مع أكسجين الهواء الرطب، وعدم تفاعل الحديد مع غاز النيتروجين في درجة حرارة الغرفة (عدم القدرة على التغير خاصية كيميائية أيضًا)، وتحول النحاس إلى الأخضر في الهواء (الجدول 2-2).', null, 'approved', '2026-10-17'::timestamptz),
(202108, 2021, 'K1-C2-L1-O08', null, 8, 'أن يوضح الطالب تأثير العوامل الخارجية على حالات المادة .', 'أن يوضح الطالب تأثير العوامل الخارجية على حالات المادة.', '[]'::jsonb, 'أن يوضح الطالب تأثير العوامل الخارجية على حالات المادة.', 'حذف المسافة قبل النقطة.', 'إملائي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["الضغط","درجة الحرارة","الظروف القياسية","حالة الماء"]'::jsonb, null, '[49,50]'::jsonb, 'مغطى', 'يذكر الكتاب أن خواص المادة تعتمد على الظروف التي تُلاحَظ عندها (الضغط ودرجة الحرارة)، ويمثّل بالماء عند الظروف القياسية (25°C و1 atm): سائل كثافته 1.00 g/cm³، وأعلى من 100°C غاز كثافته 0.0006 g/cm³، ودون 0°C صلب كثافته 0.92 g/cm³ (فيطفو الجليد، الشكل 2-7). وتعتمد حالة المادة على درجة حرارة الوسط وضغطه، وعند تغيّر درجة الحرارة تتحول معظم المواد من حالة إلى أخرى (ص50).', null, 'approved', '2026-10-17'::timestamptz),
(202109, 2021, 'K1-C2-L1-O09', null, 9, 'أن يعرّف الطالب المادة الكيميائية النقية ويذكر أمثلة عليها.', 'أن يعرّف الطالب المادة الكيميائية النقية ويذكر أمثلة عليها.', '[]'::jsonb, 'أن يعرّف الطالب المادة الكيميائية النقية ويذكر أمثلة عليها.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["المادة الكيميائية النقية","ملح الطعام","الماء النقي","التركيب الثابت"]'::jsonb, null, '[44,69]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). المادة الكيميائية النقية هي المادة ذات التركيب المنتظم والثابت، كملح الطعام (يتكون دائمًا من كلوريد الصوديوم بنسبة 100% ولا يتغير تركيبه من عينة إلى أخرى سواء استُخرج من البحر أو من منجم، الشكل 1-2) والماء النقي (هيدروجين وأكسجين). السؤالان 31 و32 في تقويم الفصل يطلبان ثلاثة أمثلة على مواد نقية وتعليل كون ثاني أكسيد الكربون مادة نقية.', null, 'approved', '2026-10-17'::timestamptz),
(202110, 2021, 'K1-C2-L1-O10', null, 10, 'أن يصف الطالب البلازما بوصفها حالة رابعة للمادة ويذكر أمثلة عليها.', 'أن يصف الطالب البلازما بوصفها حالة رابعة للمادة ويذكر أمثلة عليها.', '[]'::jsonb, 'أن يصف الطالب البلازما بوصفها حالة رابعة للمادة ويذكر أمثلة عليها.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["البلازما","غاز متأين","النجوم","لوحات النيون"]'::jsonb, null, '[45,67]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). البلازما حالة مميزة من حالات المادة يمكن وصفها بأنها غاز متأين تكون فيه الإلكترونات حرة وغير مرتبطة بالذرة أو الجزيء. معظم المواد في الكون في حالة البلازما: معظم مكونات النجوم في درجات حرارة عالية، وتوجد أيضًا في لوحات إعلانات النيون والمصابيح الكهربائية وشاشات التلفاز. يرد المصطلح في المفردات الجديدة وفي مراجعة الفصل.', null, 'approved', '2026-10-17'::timestamptz),
(202111, 2021, 'K1-C2-L1-O11', null, 11, 'أن يستعمل الطالب الخواص الفيزيائية المميزة (الكثافة ودرجتي الانصهار والغليان) في تعرّف المواد المجهولة.', 'أن يستعمل الطالب الخواص الفيزيائية المميزة (الكثافة ودرجتي الانصهار والغليان) في تعرّف المواد المجهولة.', '[]'::jsonb, 'أن يستعمل الطالب الخواص الفيزيائية المميزة (الكثافة ودرجتي الانصهار والغليان) في تعرّف المواد المجهولة.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'إجراءات ومهارات', '["الخواص المميزة","درجة الانصهار","درجة الغليان","الكثافة","تعرّف المواد"]'::jsonb, null, '[47,51,69]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). الكثافة ودرجتا الانصهار والغليان خواص مميزة «يمكن استعمالها في تعيين المواد المجهولة» (ص51)، والجدول 2-1 (ص47) يعطي حالة المواد عند 25°C ودرجات انصهارها وغليانها وكثافتها. السؤال 41 (ص69) يطلب تسمية مادة بيضاء مجهولة بمقارنة خواصها بالجدول 2-6، والسؤال 40 يسأل هل درجة غليان الماء خاصية مميزة (250 mL و1000 mL)، والسؤال 9 في الاختبار المقنن.', null, 'approved', '2026-10-17'::timestamptz),
(202112, 2021, 'K1-C2-L1-O12', null, 12, 'أن يصنف الطالب خواص معطاة للمادة إلى فيزيائية وكيميائية.', 'أن يصنف الطالب خواص معطاة للمادة إلى فيزيائية وكيميائية.', '[]'::jsonb, 'أن يصنف الطالب خواص معطاة للمادة إلى فيزيائية وكيميائية.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'إجراءات ومهارات', '["الخاصية الفيزيائية","الخاصية الكيميائية","تصنيف الخواص"]'::jsonb, null, '[48,49,69]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). يتدرب الكتاب على تصنيف الخواص: السؤال 3 في التقويم 2-1 (الحديد والأكسجين يكوّنان الصدأ، الحديد أكبر كثافة من الألومنيوم، احتراق المغنسيوم، عدم امتزاج الزيت والماء، انصهار الزئبق عند -39°C)، والسؤال 38 (لون الألومنيوم، كثافة الذهب 19 g/cm³، اشتعال الصوديوم في الماء، غليان الماء عند 100°C، تكوّن طبقة سوداء على الفضة، سيولة الزئبق)، والجدول 2-2 لخواص النحاس.', null, 'approved', '2026-10-17'::timestamptz),
(202201, 2022, 'K1-C2-L2-O01', null, 1, 'أن يحل الطالب مسائل حسابية على قانون حفظ الكتلة.', 'أن يحل الطالب مسائل حسابية على قانون حفظ الكتلة.', '[]'::jsonb, 'أن يحل الطالب مسائل حسابية على قانون حفظ الكتلة.', 'الصياغة سليمة.', 'لا تغيير', 'سليم ويعتمد', 'تطبيق', 'حل مسائل', '["قانون حفظ الكتلة","كتلة المتفاعلات","كتلة النواتج"]'::jsonb, null, '[51,52,53,70,71]'::jsonb, 'مغطى', 'قانون حفظ الكتلة: «كتلة المتفاعلات = كتلة النواتج»، أي أن الكتلة لا تفنى ولا تستحدث في أثناء التفاعل الكيميائي. المثال المحلول 2-1 (ص52): 10.0 g من أكسيد الزئبق II تعطي 9.26 g زئبق، فكتلة الأكسجين = 10.00 - 9.26 = 0.74 g (بخطوات: تحليل المسألة، حساب المطلوب، تقويم الإجابة). مسائل تدريبية 5-9 (ص52)، و13 (ص53)، و49-52 (ص70)، و77 (ص71).', null, 'approved', '2026-10-17'::timestamptz),
(202202, 2022, 'K1-C2-L2-O02', null, 2, 'أن يعدد الطالب أدلة حدوث التفاعل الكيميائي.', 'أن يعدّد الطالب أدلة حدوث التفاعل الكيميائي.', '[]'::jsonb, 'أن يعدّد الطالب أدلة حدوث التفاعل الكيميائي.', 'ضبط الفعل «يعدّد» بالشدة.', 'إملائي', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["أدلة التفاعل الكيميائي","تغير اللون","تكوّن غاز","الصدأ","التعفن"]'::jsonb, null, '[43,51,53,69]'::jsonb, 'مغطى جزئيًا', 'يعرض الكتاب «دلائل حدوث التفاعلات الكيميائية» (ص51) عبر اختلاف خواص المواد الناتجة عن المتفاعلة: الصدأ بني برتقالي مسحوق لا ينجذب للمغناطيس بخلاف الحديد، وتعفّن الفواكه والخبز يغيّر الطعم وقابلية الهضم. ويذكر (ص53) أن تغير اللون وظهور غاز مؤشران على التفاعل؛ ولا يضع قائمة صريحة بأربعة أدلة كما يطلب السؤالان 12 و45.', null, 'approved', '2026-10-17'::timestamptz),
(202203, 2022, 'K1-C2-L2-O03', null, 3, 'أن يعرف الطالب التغير الفيزيائي و يعطي أمثلة', 'أن يعرّف الطالب التغير الفيزيائي ويعطي أمثلة عليه.', '[]'::jsonb, 'أن يعرّف الطالب التغير الفيزيائي ويعطي أمثلة عليه.', 'ضبط «يعرّف»، وضبط العطف وإضافة «عليه» وعلامة الترقيم.', 'صياغة', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["التغير الفيزيائي","تغير الحالة","الانصهار","التجمد","التكثف"]'::jsonb, null, '[50,51,53]'::jsonb, 'مغطى', 'التغير الفيزيائي هو التغير الذي يحدث دون أن يغير تركيب المادة. أمثلته: تشكيل صفيحة ألومنيوم في صورة كرة، وتقطيع ورقة، وكسر لوح زجاجي، وتغير الحالة (انصهار الجليد وغليان الماء وتكثف بخار الماء وتجمّده، الشكل 2-8)، وفي خلاصة 2-2: «يغير الخواص الفيزيائية دون أن يغير تركيب المادة».', null, 'approved', '2026-10-17'::timestamptz),
(202204, 2022, 'K1-C2-L2-O04', null, 4, 'أن يعرف الطالب التغير الكيميائي و يعطي أمثلة', 'أن يعرّف الطالب التغير الكيميائي ويعطي أمثلة عليه.', '[]'::jsonb, 'أن يعرّف الطالب التغير الكيميائي ويعطي أمثلة عليه.', 'ضبط «يعرّف»، وضبط العطف وإضافة «عليه» وعلامة الترقيم.', 'صياغة', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["التغير الكيميائي","التفاعل الكيميائي","المتفاعلات","النواتج","الصدأ"]'::jsonb, null, '[51,53]'::jsonb, 'مغطى', 'التغير الكيميائي عملية تتضمن تغيّر مادة أو أكثر إلى مواد جديدة، ويسمى أيضًا التفاعل الكيميائي، وللمواد الناتجة تراكيب وخواص مختلفة عن المتفاعلة. أمثلة: تكوّن صدأ الحديد من تفاعل الحديد مع أكسجين الهواء، وتعفّن الطعام، وتحلل أكسيد الزئبق II بالحرارة إلى زئبق وأكسجين (الشكل 2-10). ويُشار إليه بمصطلحات: تحلل، انفجار، صدأ، تأكسد، تآكل، فقدان البريق، تخمر، احتراق، تعفن.', null, 'approved', '2026-10-17'::timestamptz),
(202205, 2022, 'K1-C2-L2-O05', null, 5, 'أن يذكر الطالب أمثلة على تغيرات الحالة (الانصهار والتجمد والتبخر والتكثف والغليان) ويصنفها تغيرات فيزيائية.', 'أن يذكر الطالب أمثلة على تغيرات الحالة (الانصهار والتجمد والتبخر والتكثف والغليان) ويصنفها تغيرات فيزيائية.', '[]'::jsonb, 'أن يذكر الطالب أمثلة على تغيرات الحالة (الانصهار والتجمد والتبخر والتكثف والغليان) ويصنفها تغيرات فيزيائية.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["تغير الحالة","الانصهار","التجمد","التبخر","التكثف","الغليان"]'::jsonb, null, '[50,51,69]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). تغير الحالة هو تحوّل المادة من حالة إلى أخرى، وهو تغير فيزيائي لأن تركيب المادة لا يتغير. يمثّل الكتاب بدورة الماء: دون 0°C يكون الماء صلبًا (جليدًا) وعند التسخين ينصهر، وعند 100°C يبدأ الماء السائل بالغليان ويتحول إلى بخار، والشكل 2-8 يبيّن التكثف والتجمد. ودرجتا الانصهار والغليان خاصيتان فيزيائيتان مهمتان. السؤالان 42b و44 في تقويم الفصل.', null, 'approved', '2026-10-17'::timestamptz),
(202206, 2022, 'K1-C2-L2-O06', null, 6, 'أن يصنف الطالب تغيرات معطاة إلى فيزيائية وكيميائية مع التعليل.', 'أن يصنف الطالب تغيرات معطاة إلى فيزيائية وكيميائية مع التعليل.', '[]'::jsonb, 'أن يصنف الطالب تغيرات معطاة إلى فيزيائية وكيميائية مع التعليل.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'إجراءات ومهارات', '["التغير الفيزيائي","التغير الكيميائي","تصنيف التغيرات"]'::jsonb, null, '[53,69,71,72,73]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). يتكرر في التقويم تصنيف تغيرات: السؤال 10 (سحق علبة ألومنيوم، تدوير العلب، اتحاد الألومنيوم مع الأكسجين)، والسؤال 42 (كسر قلم، تجمد الماء، قلي البيض، حرق الخشب، تغير لون ورق الشجر)، والسؤالان 43 (تخمر الموز) و44 (تغير الحالة)، و81 (سلق البيض)، و87 (خروج الغاز من المشروب الغازي)، و94 (إنتاج الفحم من الخشب)، و11 في الاختبار المقنن (احتراق الجازولين). السؤال 14 (ص53) يقوّم عبارة أن مظهر المادة لا يتغير في التغير الفيزيائي.', null, 'approved', '2026-10-17'::timestamptz),
(202207, 2022, 'K1-C2-L2-O07', null, 7, 'أن يحدد الطالب المتفاعلات والنواتج في تفاعل كيميائي.', 'أن يحدد الطالب المتفاعلات والنواتج في تفاعل كيميائي.', '[]'::jsonb, 'أن يحدد الطالب المتفاعلات والنواتج في تفاعل كيميائي.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'مفاهيم', '["المتفاعلات","النواتج","التفاعل الكيميائي"]'::jsonb, null, '[51,53,69]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). المتفاعلات هي المواد التي يبدأ بها التفاعل، والنواتج هي المواد الجديدة المتكونة (ص51)، وفي التفاعل الكيميائي تتحول المتفاعلات إلى نواتج (خلاصة 2-2). تطبيقات: «عيّن المتفاعلات والنواتج في تفاعل تكوّن الصدأ» (الشكل 2-9)، والسؤال 46 (صدأ الحديد: الحديد والأكسجين وبخار الماء متفاعلات، وأكسيد الحديد ناتج)، وتحلل أكسيد الزئبق II إلى زئبق وأكسجين.', null, 'approved', '2026-10-17'::timestamptz),
(202208, 2022, 'K1-C2-L2-O08', null, 8, 'أن ينص الطالب على قانون حفظ الكتلة ويفسر انطباقه على أمثلة من الحياة (كاحتراق الشمعة).', 'أن ينص الطالب على قانون حفظ الكتلة ويفسر انطباقه على أمثلة من الحياة (كاحتراق الشمعة).', '[]'::jsonb, 'أن ينص الطالب على قانون حفظ الكتلة ويفسر انطباقه على أمثلة من الحياة (كاحتراق الشمعة).', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مبادئ وقوانين', '["قانون حفظ الكتلة","لافوازييه","النظام المغلق","احتراق الشمعة"]'::jsonb, null, '[51,53,69]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ينص القانون على أن الكتلة لا تفنى ولا تستحدث في أثناء التفاعل الكيميائي (إلا بقدرة الله تعالى) أي أنها محفوظة. والفضل في اكتشافه لاستعمال الميزان الحساس، وكان لافوازييه (1743-1794م) أول من استعمله في التفاعلات الكيميائية، ويجرى التفاعل في وعاء مغلق فلا يخرج الأكسجين وتُقاس الكتلة قبل التفاعل وبعده (ص53). السؤال 47: شمعة اشتعلت ثلاث ساعات وبقي نصفها، «وضّح لماذا لا يخالف هذا المثال قانون حفظ الكتلة».', null, 'approved', '2026-10-17'::timestamptz),
(202301, 2023, 'K1-C2-L3-O01', null, 1, 'أن يعرف الطالب المخاليط.', 'أن يعرّف الطالب المخلوط.', '[]'::jsonb, 'أن يعرّف الطالب المخلوط.', 'ضبط «يعرّف»، وتوحيد المصطلح بصيغة المفرد «المخلوط» كما يُعرَّف.', 'صياغة', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["المخلوط","المادة النقية"]'::jsonb, null, '[54,57]'::jsonb, 'مغطى', 'المخلوط «مزيج مكون من مادتين نقيتين أو أكثر مع احتفاظ كل من هذه المواد بخواصها الأصلية». يختلف تركيب المخاليط بحسب نسب مكوناتها فيمكن تحضير عدد لا نهائي منها، ومعظم المواد في الطبيعة مخاليط. أمثلة: مخلوط الزئبق-الفضة (الحشوة السنية) ومخلوط الزيت والتوابل والخل (الشكل 2-11).', null, 'approved', '2026-10-17'::timestamptz),
(202302, 2023, 'K1-C2-L3-O02', null, 2, 'أن يقارن الطالب بين المخاليط المتجانسة وغير المتجانسة.', 'أن يقارن الطالب بين المخاليط المتجانسة وغير المتجانسة.', '[]'::jsonb, 'أن يقارن الطالب بين المخاليط المتجانسة وغير المتجانسة.', 'الصياغة سليمة.', 'لا تغيير', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["المخلوط المتجانس","المخلوط غير المتجانس","المحلول"]'::jsonb, null, '[54,55]'::jsonb, 'مغطى', 'المخلوط غير المتجانس لا تمتزج فيه المواد بل تبقى متمايزة وتركيبه غير منتظم (سلطة الخضار، وعصير البرتقال الطبيعي: عصير ولب يطفو). المخلوط المتجانس له تركيب ثابت وتمتزج مكوناته بانتظام، فتركيب أي قطعتين من مملغم الفضة والزئبق واحد مهما اختلف الحجم. ويسمى المخلوط المتجانس محلولًا.', null, 'approved', '2026-10-17'::timestamptz),
(202303, 2023, 'K1-C2-L3-O03', null, 3, 'أن يميز الطالب طرائق فصل المخاليط.', 'أن يميّز الطالب بين طرائق فصل المخاليط (الترشيح والتقطير والتبلور والتسامي والكروماتوجرافيا).', '[]'::jsonb, 'أن يميّز الطالب بين طرائق فصل المخاليط (الترشيح والتقطير والتبلور والتسامي والكروماتوجرافيا).', 'تحديد الطرائق المطلوب التمييز بينها ليصبح الهدف قابلًا للقياس.', 'تحويل إلى هدف قابل للقياس', 'يعتمد بعد التعديل', 'فهم', 'إجراءات ومهارات', '["الترشيح","التقطير","التبلور","التسامي","الكروماتوجرافيا","الفصل بالمغناطيس"]'::jsonb, null, '[56,57,68,70,71]'::jsonb, 'مغطى', 'عمليات الفصل فيزيائية تعتمد على اختلاف الخواص الفيزيائية: الفصل بالمغناطيس (برادة الحديد من الرمل)، والترشيح (مخلوط غير متجانس صلب-سائل بحاجز مسامي)، والتقطير (يعتمد على اختلاف درجات الغليان للمخاليط المتجانسة)، والتبلور (ترسيب بلورات السكر من محلوله المشبع بتبخر الماء)، والتسامي (تبخر المادة الصلبة دون تصهر لفصل صلبين أحدهما يتسامى)، والكروماتوجرافيا (الطور المتحرك والطور الثابت وقوى التماسك، تجربة فصل الأصباغ ص57). تطبيقات: الأسئلة 17 و54 و86.', null, 'approved', '2026-10-17'::timestamptz),
(202304, 2023, 'K1-C2-L3-O04', null, 4, 'أن يصنف الطالب أنواع المحاليل.', 'أن يصنّف الطالب أنواع المحاليل.', '[]'::jsonb, 'أن يصنّف الطالب أنواع المحاليل.', 'ضبط «يصنّف» بالشدة.', 'إملائي', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["المحلول","غاز-غاز","غاز-سائل","صلب-سائل","السبيكة"]'::jsonb, null, '[55]'::jsonb, 'مغطى', 'المحاليل مخاليط متجانسة قد تكون صلبة أو سائلة أو غازية، وتُصنَّف بحالتي المادتين (الجدول 2-3): غاز-غاز (هواء أسطوانة الغوص)، غاز-سائل (الأكسجين وثاني أكسيد الكربون الذائبان في ماء البحر)، سائل-غاز (الهواء الرطب)، سائل-سائل (ماء المطر وماء البحر)، صلب-سائل (الأملاح الذائبة في ماء البحر)، صلب-صلب (أسطوانة الغوص من مزيج المعادن، أي سبيكة).', null, 'approved', '2026-10-17'::timestamptz),
(202305, 2023, 'K1-C2-L3-O05', null, 5, 'أن يقارن الطالب بين المخلوط والمادة النقية.', 'أن يقارن الطالب بين المخلوط والمادة النقية.', '[]'::jsonb, 'أن يقارن الطالب بين المخلوط والمادة النقية.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["المخلوط","المادة النقية","التركيب الثابت"]'::jsonb, null, '[54,57,69]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). المادة النقية ذات تركيب منتظم وثابت، أما المخلوط فمزيج من مادتين نقيتين أو أكثر يختلف تركيبه بحسب نسب مكوناته، وتحتفظ مكوناته بخواصها الأصلية ويمكن فصلها بطرائق فيزيائية. أسئلة: 16 في التقويم 2-3، و53 (صف خواص المخلوط)، و55 (تصحيح عبارة «المخلوط مادة ناتجة عن اتحاد مادتين»)، والشكل 2-20 يربط المخاليط بالمواد النقية بتغيرات فيزيائية.', null, 'approved', '2026-10-17'::timestamptz),
(202306, 2023, 'K1-C2-L3-O06', null, 6, 'أن يصنف الطالب مواد معطاة إلى مخاليط متجانسة أو غير متجانسة.', 'أن يصنف الطالب مواد معطاة إلى مخاليط متجانسة أو غير متجانسة.', '[]'::jsonb, 'أن يصنف الطالب مواد معطاة إلى مخاليط متجانسة أو غير متجانسة.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'إجراءات ومهارات', '["المخلوط المتجانس","المخلوط غير المتجانس","تصنيف المخاليط"]'::jsonb, null, '[57,70,71]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). تطبيقات التصنيف: السؤال 15 (ماء الصنبور، الهواء، فطيرة الزبيب)، و56 و57 (ماء البحر)، و76 (النحاس الأصفر، السَّلطة، الدم، مسحوق شراب مذاب في الماء)، و79 (الهواء، الدخان، التراب، الماء النقي، الترسبات، الماء الموحل)، و80 (ماء الشرب، الماء المالح، الهيليوم، ماء البحر، الهواء)، و82 (البيتزا). أمثلة الكتاب: الدم والحليب غير متجانسان، والفولاذ والجازولين والشاي متجانسة (الشكل 2-20).', null, 'approved', '2026-10-17'::timestamptz),
(202307, 2023, 'K1-C2-L3-O07', null, 7, 'أن يشرح الطالب مبدأ عمل الكروماتوجرافيا في فصل مكونات مخلوط.', 'أن يشرح الطالب مبدأ عمل الكروماتوجرافيا في فصل مكونات مخلوط.', '[]'::jsonb, 'أن يشرح الطالب مبدأ عمل الكروماتوجرافيا في فصل مكونات مخلوط.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["الكروماتوجرافيا","الطور المتحرك","الطور الثابت","ورق الكروماتوجرافيا"]'::jsonb, null, '[56,57,70]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). الكروماتوجرافيا (التحليل الاستشرابي) طريقة لفصل مكونات المخلوط (الطور المتحرك، غالبًا مادة سائلة أو غازية) بالاعتماد على قابلية انجذاب كل مكون لسطح مادة أخرى (الطور الثابت، كورق الكروماتوجرافيا). يتباعد أولًا المكون الذي قوى تماسك جزيئاته أقل على الورقة ثم الذي يليه (الشكل 2-14). تجربة فصل الأصباغ (ص57)، والسؤال 58 «ما الكروماتوجرافيا؟ وكيف تعمل؟»، وصفحة «في الميدان» (الكروماتوجرافيا الغازية).', null, 'approved', '2026-10-17'::timestamptz),
(202308, 2023, 'K1-C2-L3-O08', null, 8, 'أن يعرّف الطالب السبيكة ويذكر أمثلة عليها.', 'أن يعرّف الطالب السبيكة ويذكر أمثلة عليها.', '[]'::jsonb, 'أن يعرّف الطالب السبيكة ويذكر أمثلة عليها.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["السبيكة","الفولاذ","البرونز","الذهب الأبيض"]'::jsonb, null, '[55,71]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). السبيكة مخلوط متجانس (محلول صلب) من الفلزات، أو من فلز ولا فلز يكون فيه الفلز المكوّن الأساسي. الفولاذ مخلوط من الحديد واللافلز الكربون، ووجود ذرات الكربون يزيد من صلابة الفلز. تمزج المصانع أنواعًا من الفلزات في سبائك للحصول على مواد أكثر قوة ومقاومة، والمجوهرات تصنع من سبائك منها البرونز والذهب الأبيض. السؤال 76a: النحاس الأصفر (سبيكة من الخارصين والنحاس).', null, 'approved', '2026-10-17'::timestamptz),
(202401, 2024, 'K1-C2-L4-O01', null, 1, 'أن يصف الطالب ترتيب العناصر في الجدول الدوري.', 'أن يصف الطالب ترتيب العناصر في الجدول الدوري.', '[]'::jsonb, 'أن يصف الطالب ترتيب العناصر في الجدول الدوري.', 'الصياغة سليمة.', 'لا تغيير', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["الجدول الدوري","الدورات","المجموعات","مندليف"]'::jsonb, null, '[59,64,73]'::jsonb, 'مغطى', 'ينظم الجدول الدوري العناصر في شبكة تسمى صفوفها الأفقية «الدورات» وأعمدتها «المجموعات» أو «العائلات»؛ والعناصر في المجموعة الواحدة لها خواص فيزيائية وكيميائية متشابهة، وسُمّي دوريًّا لأن نمط الخواص المتشابهة يتكرر من دورة إلى أخرى. صمم مندليف (1834-1907م) أول جدول رتب فيه العناصر المعروفة على أساس تشابهاتها وكتلها (الشكل 2-17). السؤال 25 (الملامح التنظيمية للجدول) والسؤال 5 في الاختبار (Li وNa وK وCs في مجموعة واحدة).', null, 'approved', '2026-10-17'::timestamptz),
(202402, 2024, 'K1-C2-L4-O02', null, 2, 'أن يشرح الطالب سلوك المركبات وفق قانون النسب المتضاعفة.', 'أن يشرح الطالب سلوك المركبات وفق قانون النسب المتضاعفة.', '[]'::jsonb, 'أن يشرح الطالب سلوك المركبات وفق قانون النسب المتضاعفة.', 'إضافة علامة الترقيم.', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مبادئ وقوانين', '["قانون النسب المتضاعفة","النسبة العددية البسيطة","فوق أكسيد الهيدروجين","كلوريد النحاس"]'::jsonb, null, '[63,64,70,71]'::jsonb, 'مغطى', 'ينص القانون على أنه عند تكوين مركبات مختلفة من اتحاد العناصر نفسها فإن النسبة بين كتل أحد العناصر التي تتحد مع كتلة ثابتة من عنصر آخر هي نسبة عددية بسيطة وصحيحة (مثل 2:3 أو 1:2). أمثلة: H₂O وH₂O₂ (نسبة كتلتي الأكسجين 1:2)، وكلوريد النحاس I وII (64.20% و47.27% نحاس؛ نسبة Cu/Cl في I إلى II = 1.793/0.8964 = 2:1، الجدول 2-5 والشكل 2-21). تطبيقات: الأسئلة 27 و28 و30 و71 و73 و74.', null, 'approved', '2026-10-17'::timestamptz),
(202403, 2024, 'K1-C2-L4-O03', null, 3, 'أن يقارن الطالب بين العنصر والمركب مع ذكر أمثلة', 'أن يقارن الطالب بين العنصر والمركب مع ذكر أمثلة.', '[]'::jsonb, 'أن يقارن الطالب بين العنصر والمركب مع ذكر أمثلة.', 'إضافة علامة الترقيم.', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["العنصر","المركب","التحليل الكهربائي"]'::jsonb, null, '[58,59,60,61,64,70]'::jsonb, 'مغطى', 'العنصر مادة كيميائية نقية لا يمكن تجزئتها إلى أجزاء أصغر منها بطرائق فيزيائية أو كيميائية (92 عنصرًا طبيعيًّا؛ أمثلة: Cu وO وAu). المركب يتكون من عنصرين مختلفين أو أكثر متحدين كيميائيًّا ويمكن تحليله إلى مكوناته بطرائق كيميائية (كالتحليل الكهربائي للماء)، وتختلف خواصه عن خواص عناصره (يوديد البوتاسيوم KI، والماء). أمثلة المركبات: NaCl وH₂O والسكر. يوجد نحو 10 ملايين مركب معروف، ويُكتشف أو يُحضَّر نحو 100000 سنويًّا.', null, 'approved', '2026-10-17'::timestamptz),
(202404, 2024, 'K1-C2-L4-O04', null, 4, 'أن يذكر الطالب الاسم العلمي لملح الطعام وصيغته', 'أن يذكر الطالب الاسم العلمي لملح الطعام وصيغته الكيميائية.', '[]'::jsonb, 'أن يذكر الطالب الاسم العلمي لملح الطعام وصيغته الكيميائية.', 'إضافة «الكيميائية» لتحديد نوع الصيغة.', 'لغوي', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["كلوريد الصوديوم","NaCl","الصيغة الكيميائية"]'::jsonb, null, '[59,62]'::jsonb, 'مغطى', 'ملح الطعام يسمى «كلوريد الصوديوم» وصيغته الكيميائية NaCl، وهو مكوَّن من ذرة واحدة من الصوديوم Na وذرة واحدة من الكلور Cl (ص59). السؤال 62a في التقويم يطلب تسمية العناصر المكونة لـ NaCl.', null, 'approved', '2026-10-17'::timestamptz),
(202405, 2024, 'K1-C2-L4-O05', null, 5, 'أن يشرح الطالب طريقة فصل الماء.', 'أن يشرح الطالب طريقة فصل الماء إلى عنصريه (الهيدروجين والأكسجين).', '[]'::jsonb, 'أن يشرح الطالب طريقة فصل الماء إلى عنصريه (الهيدروجين والأكسجين).', 'توضيح المقصود بعبارة «فصل الماء» كما يرد في الكتاب (تحليل الماء إلى مكوناته).', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'إجراءات ومهارات', '["التحليل الكهربائي","الماء","الهيدروجين","الأكسجين"]'::jsonb, null, '[60]'::jsonb, 'مغطى', 'يمكن تجزئة المركبات بطرائق كيميائية، والجهاز في الشكل 2-18 يحلل الماء إلى عنصريه بعملية «التحليل الكهربائي»: يقوم التيار الكهربائي (بطارية 9V) بتحليل H₂O إلى غاز الهيدروجين H₂ عند الكاثود (المهبط) وغاز الأكسجين O₂ عند الأنود (المصعد)، ويكون حجم الهيدروجين الناتج ضعف حجم الأكسجين لأن الماء من ذرتي هيدروجين وذرة أكسجين. «ماذا قرأت؟ اشرح عملية التحليل الكهربائي».', null, 'approved', '2026-10-17'::timestamptz),
(202406, 2024, 'K1-C2-L4-O06', null, 6, 'أن يحل الطالب مسائل حسابية على قانون النسبة المئوية بالكتلة.', 'أن يحل الطالب مسائل حسابية على النسبة المئوية بالكتلة.', '[]'::jsonb, 'أن يحل الطالب مسائل حسابية على النسبة المئوية بالكتلة.', 'النسبة المئوية بالكتلة ليست قانونًا في الكتاب بل علاقة حسابية؛ لذا حُذفت كلمة «قانون».', 'صياغة', 'يعتمد بعد التعديل', 'تطبيق', 'حل مسائل', '["النسبة المئوية بالكتلة","كتلة العنصر","كتلة المركب"]'::jsonb, null, '[61,62,70,71]'::jsonb, 'مغطى', 'النسبة المئوية بالكتلة (%) = (كتلة العنصر ÷ كتلة المركب) × 100 (ص61). مثال: تحليل 20.00 g من سكر المائدة يعطي 8.44 g C و1.30 g H و10.26 g O، أي 42.20% و6.50% و51.30% (الجدول 2-4). مسائل تدريبية 19-23 (ص62): 12.4 g هيدروجين في 78.0 g مركب، وغيرها؛ وأسئلة 66 و68-72.', null, 'approved', '2026-10-17'::timestamptz),
(202407, 2024, 'K1-C2-L4-O07', null, 7, 'أن ينص الطالب على قانون النسب الثابتة ويفسر انطباقه على المركبات.', 'أن ينص الطالب على قانون النسب الثابتة ويفسر انطباقه على المركبات.', '[]'::jsonb, 'أن ينص الطالب على قانون النسب الثابتة ويفسر انطباقه على المركبات.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مبادئ وقوانين', '["قانون النسب الثابتة","النسبة المئوية بالكتلة","السكروز"]'::jsonb, null, '[61,62,64,70]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ينص قانون النسب الثابتة على أن المركب يتكون دائمًا من العناصر نفسها بنسب كتلية ثابتة مهما اختلفت كمياتها، وكتلة المركب تساوي مجموع كتل عناصره (ص61). تحليل 20.00 g من سكر المائدة و500.0 g من سكر القصب يعطي النسب نفسها: 42.20% كربون و6.50% هيدروجين و51.30% أكسجين (الجدول 2-4). السؤالان 26 و65، و«ماذا قرأت؟ اكتب نص قانون النسب الثابتة».', null, 'approved', '2026-10-17'::timestamptz),
(202408, 2024, 'K1-C2-L4-O08', null, 8, 'أن يستنتج الطالب العناصر المكونة للمركب وأعداد ذراتها من صيغته الكيميائية.', 'أن يستنتج الطالب العناصر المكونة للمركب وأعداد ذراتها من صيغته الكيميائية.', '[]'::jsonb, 'أن يستنتج الطالب العناصر المكونة للمركب وأعداد ذراتها من صيغته الكيميائية.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'إجراءات ومهارات', '["الرمز الكيميائي","الصيغة الكيميائية","الرقم السفلي"]'::jsonb, null, '[58,59,70,71]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). لكل عنصر اسم ورمز من حرف أو حرفين أو ثلاثة، يُكتب الحرف الأول كبيرًا وباقي الأحرف صغيرة. الرمز يسهّل كتابة صيغ المركبات: NaCl من ذرة Na وذرة Cl، وH₂O من ذرتي هيدروجين وذرة أكسجين، والرقم السفلي يبيّن عدد الذرات (ص59). السؤال 62: تسمية العناصر في NaCl وC₂H₅OH وNH₃ وBr₂، والسؤال 78 (عدد جزيئات الماء من 100 ذرة هيدروجين و100 ذرة أكسجين).', null, 'approved', '2026-10-17'::timestamptz),
(202409, 2024, 'K1-C2-L4-O09', null, 9, 'أن يحدد الطالب، بحساب النسب المئوية بالكتلة، ما إذا كانت عينتان من المركب نفسه.', 'أن يحدد الطالب، بحساب النسب المئوية بالكتلة، ما إذا كانت عينتان من المركب نفسه.', '[]'::jsonb, 'أن يحدد الطالب، بحساب النسب المئوية بالكتلة، ما إذا كانت عينتان من المركب نفسه.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تحليل', 'حل مسائل', '["قانون النسب الثابتة","النسبة المئوية بالكتلة","تحليل العينات"]'::jsonb, null, '[62,64,72,73]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). عينات المركب الواحد لها النسب الكتلية نفسها، والمركبات ذات النسب الكتلية المختلفة هي مركبات مختلفة (ص62). تطبيقات: السؤال 22 (مركبان: 15.0 g H مع 120.0 g O و2.0 g H مع 32.0 g O)، والسؤال 23 (مركبان فيهما النسبة نفسها من الكربون)، والسؤال 28 (مركبان للحديد 52.46/22.54 و43.53/12.47)، والسؤال 85 (رسم بياني لأربع عينات من X وY)، والسؤال 88 (مركبات الرصاص)، والسؤالان 1 و2 في الاختبار المقنن (كلور-فلور).', null, 'approved', '2026-10-17'::timestamptz),
(202410, 2024, 'K1-C2-L4-O10', null, 10, 'أن يطبق الطالب قانون النسب المتضاعفة لحساب نسبة كتل عنصر متحد مع كتلة ثابتة من عنصر آخر في مركبين.', 'أن يطبق الطالب قانون النسب المتضاعفة لحساب نسبة كتل عنصر متحد مع كتلة ثابتة من عنصر آخر في مركبين.', '[]'::jsonb, 'أن يطبق الطالب قانون النسب المتضاعفة لحساب نسبة كتل عنصر متحد مع كتلة ثابتة من عنصر آخر في مركبين.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'حل مسائل', '["قانون النسب المتضاعفة","النسبة العددية البسيطة","المركبان I وII"]'::jsonb, null, '[63,64,70,71]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). لتطبيق القانون يُقارَن مركبان من العنصرين نفسهما بحساب كتلة أحد العنصرين لكل 1 g من الآخر ثم قسمة نسبتي المركبين: في كلوريد النحاس 1.793 g Cu/g Cl إلى 0.8964 g Cu/g Cl = 2.00 أي 2:1 (ص63)، ولماء وفوق أكسيد الهيدروجين نسبة كتلتي الأكسجين 1:2. السؤال 71 (CO وCO₂: 4.82 g C لكل 6.44 g O و20.13 g C لكل 53.7 g O) والسؤال 74 والسؤال 28 (استعمال القانون لبيان العلاقة بين مركبين مختلفين).', null, 'approved', '2026-10-17'::timestamptz),
(202411, 2024, 'K1-C2-L4-O11', null, 11, 'أن يفسر الطالب اختلاف خواص المركب عن خواص العناصر المكونة له.', 'أن يفسر الطالب اختلاف خواص المركب عن خواص العناصر المكونة له.', '[]'::jsonb, 'أن يفسر الطالب اختلاف خواص المركب عن خواص العناصر المكونة له.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["خواص المركبات","يوديد البوتاسيوم","الماء","التفاعل الكيميائي"]'::jsonb, null, '[60,64,70]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). تختلف خواص المركب عن خواص العناصر الداخلة في تركيبه لأنه ناتج عن تفاعل كيميائي بين العناصر: الماء مركب مستقر سائل بينما الهيدروجين والأكسجين غازان عديما اللون والرائحة ويتفاعلان بشدة مع عدة عناصر؛ ويوديد البوتاسيوم KI ملح أبيض بينما البوتاسيوم فلز فضي واليود I₂ صلب أسود يوجد على هيئة غاز بنفسجي. السؤال 64 «هل تختلف خواص المركب عن خواص العناصر المكونة له؟».', null, 'approved', '2026-10-17'::timestamptz),
(202412, 2024, 'K1-C2-L4-O12', null, 12, 'أن يصنف الطالب مواد معطاة إلى عنصر أو مركب أو مخلوط متجانس أو مخلوط غير متجانس.', 'أن يصنف الطالب مواد معطاة إلى عنصر أو مركب أو مخلوط متجانس أو مخلوط غير متجانس.', '[]'::jsonb, 'أن يصنف الطالب مواد معطاة إلى عنصر أو مركب أو مخلوط متجانس أو مخلوط غير متجانس.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'إجراءات ومهارات', '["تصنيف المادة","عنصر","مركب","مخلوط متجانس","مخلوط غير متجانس"]'::jsonb, null, '[61,64,71]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). يلخص الشكل 2-20 تصنيف المادة: مخاليط (متجانسة مثل الفولاذ والجازولين والشاي، وغير متجانسة مثل الدم والحليب) ومواد كيميائية نقية (عناصر مثل الأكسجين والذهب والحديد، ومركبات مثل الملح والسكر). السؤال 80 (ماء الشرب النقي، الماء المالح، الهيليوم، ماء البحر، الهواء: متجانس أم غير متجانس، مركب أم عنصر)، والسؤال 79، والسؤال 84 (H₂+O₂ يكوّن مركبًا بينما N₂+O₂ في الهواء مخلوط)، والسؤال 18 (خريطة مفاهيمية).', null, 'approved', '2026-10-17'::timestamptz),
(203101, 2031, 'K1-C3-L1-O01', null, 1, 'أن يوضح الطالب أول من اهتم بدراسة المادة.', 'أن يذكر الطالب أول من اقترح وجود الذرات.', '[]'::jsonb, 'أن يذكر الطالب أول من اقترح وجود الذرات.', 'قرار المالك: حذف «أول من اهتم بدراسة المادة» (غير دقيق) وإبقاء «أول من اقترح وجود الذرات» (ديموقريطوس)', 'صياغة', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["ديموقريطوس","الذرة"]'::jsonb, null, '[76,77]'::jsonb, 'مغطى', 'يذكر الكتاب أن الفلاسفة اليونانيين القدماء، ومنهم ديموقريطوس، اقترحوا أن المادة تتكون من جسيمات صغيرة لا تتجزأ سماها «ذرات» (ص76).', null, 'approved', '2026-10-17'::timestamptz),
(203102, 2031, 'K1-C3-L1-O02', null, 2, 'تقارن بين النماذج الذرية لديمقريطس و أرسطو و جون دالتون.', 'أن يقارن الطالب بين أفكار ديموقريطوس وأرسطو وجون دالتون عن المادة والذرة.', '[]'::jsonb, 'أن يقارن الطالب بين أفكار ديموقريطوس وأرسطو وجون دالتون عن المادة والذرة.', 'بدأ الهدف بالفعل «تقارن» بدل «أن يقارن الطالب»؛ وتصحيح «ديمقريطس» إلى «ديموقريطوس» كما في الكتاب؛ وأرسطو لم يقترح نموذجًا ذريًّا بل أنكر الذرات فعُدّل التعبير إلى «أفكار».', 'صياغة', 'يعتمد بعد التعديل', 'تحليل', 'مفاهيم', '["ديموقريطوس","أرسطو","دالتون","نظرية دالتون الذرية"]'::jsonb, null, '[77,78,79]'::jsonb, 'مغطى', 'الجدول 3-1: ديموقريطوس (المادة من ذرات تتحرك في الفراغ، صلبة متجانسة لا تفنى ولا تتجزأ، أنواعها المختلفة لها أحجام وأشكال مختلفة)، وأرسطو (384–322 ق.م: لا وجود للفراغ، والمادة من التراب والنار والهواء والماء). الجدول 3-2: فرضيات دالتون (1803م): ذرات العنصر الواحد متشابهة، تختلف عن ذرات العناصر الأخرى، تتحد بنسب عددية بسيطة، ولا تتجزأ ولا تفنى. سؤال 3-1 رقم 1 و6 يطلبان المقارنة وخريطة مفاهيمية. ملاحظة: أرسطو أنكر وجود الذرات ولم يقدم نموذجًا ذريًّا.', null, 'approved', '2026-10-17'::timestamptz),
(203103, 2031, 'K1-C3-L1-O03', null, 3, 'أن يفهم الطالب كيف فسرت نظرية دالتون قانون حفظ الكتلة.', 'أن يفسر الطالب كيف فسّرت نظرية دالتون الذرية قانون حفظ الكتلة.', '[]'::jsonb, 'أن يفسر الطالب كيف فسّرت نظرية دالتون الذرية قانون حفظ الكتلة.', '«يفهم» فعل غير قابل للقياس مباشرة؛ استُبدل بـ«يفسر» مع تصحيح الصياغة.', 'تحويل إلى هدف قابل للقياس', 'يعتمد بعد التعديل', 'فهم', 'مبادئ وقوانين', '["قانون حفظ الكتلة","نظرية دالتون الذرية","التفاعل الكيميائي"]'::jsonb, null, '[79]'::jsonb, 'مغطى', 'قانون حفظ الكتلة: الكتلة ثابتة (محفوظة) في التفاعلات الكيميائية فلا تنقص ولا تزيد. تفسير دالتون: ما يحدث للذرات في التفاعل هو فقط انفصال أو اتحاد أو إعادة ترتيب، فهي لا تتحطم ولا تستحدث ذرات أخرى، فيبقى عدد ذرات كل عنصر قبل التفاعل وبعده نفسه. الشكل 3-3 (12 كتلة متفاعلات = 12 كتلة نواتج) والسؤالان 4 و37 من التقويم، والسؤال 5 تطبيق عددي.', null, 'approved', '2026-10-17'::timestamptz),
(203104, 2031, 'K1-C3-L1-O04', null, 4, 'أن يفسر الطالب سبب رفض أرسطو لفكرة الذرات وسبب عجز ديموقريطوس عن إثبات أفكاره.', 'أن يفسر الطالب سبب رفض أرسطو لفكرة الذرات وسبب عجز ديموقريطوس عن إثبات أفكاره.', '[]'::jsonb, 'أن يفسر الطالب سبب رفض أرسطو لفكرة الذرات وسبب عجز ديموقريطوس عن إثبات أفكاره.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["أرسطو","ديموقريطوس","الفراغ","التجارب الضابطة"]'::jsonb, null, '[77,78,79]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). رفض أرسطو الذرات لأنها تتعارض مع أفكاره عن الطبيعة (اعتقد ديموقريطوس بتحرك الذرات في الفراغ بينما لم يعتقد أرسطو بوجود الفراغ)، ولتأثيره الكبير رُفضت نظرية ديموقريطوس. لم يستطع ديموقريطوس إثبات أفكاره لعدم قدرته على إجراء تجارب ضابطة، ولم يجب عما يربط الذرات معًا. أسئلة 33–35 ص103 و«ماذا قرأت» ص78.', null, 'approved', '2026-10-17'::timestamptz),
(203105, 2031, 'K1-C3-L1-O05', null, 5, 'أن يذكر الطالب الفرضيات الرئيسة لنظرية دالتون الذرية.', 'أن يذكر الطالب الفرضيات الرئيسة لنظرية دالتون الذرية.', '[]'::jsonb, 'أن يذكر الطالب الفرضيات الرئيسة لنظرية دالتون الذرية.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["نظرية دالتون الذرية"]'::jsonb, null, '[78,79,101]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). الجدول 3-2: تتكون المادة من أجزاء صغيرة جدًّا تسمى الذرات؛ الذرات لا تتجزأ ولا تفنى؛ ذرات العنصر الواحد متشابهة في الحجم والكتلة والخواص الكيميائية وتختلف عن ذرات العناصر الأخرى؛ تتحد ذرات العناصر بنسب عددية بسيطة لتكوين المركبات؛ وفي التفاعلات تنفصل الذرات أو تتحد أو يُعاد ترتيبها. أسئلة 3 و36 ص79 و103.', null, 'approved', '2026-10-17'::timestamptz),
(203106, 2031, 'K1-C3-L1-O06', null, 6, 'أن يبيّن الطالب جوانب الخطأ في نظرية دالتون الذرية.', 'أن يبيّن الطالب جوانب الخطأ في نظرية دالتون الذرية.', '[]'::jsonb, 'أن يبيّن الطالب جوانب الخطأ في نظرية دالتون الذرية.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تحليل', 'مفاهيم', '["نظرية دالتون","تجزؤ الذرة","النظائر"]'::jsonb, null, '[79,83,91,105]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). تبيّن لاحقًا أن دالتون كان مخطئًا في أن الذرات لا يمكن تجزئتها (فالذرة تتجزأ إلى إلكترونات وبروتونات ونيوترونات)، وفي أن جميع ذرات العنصر الواحد متماثلة (النظائر تختلف في الكتلة). السؤال 36 «أيها تبيّن مؤخرًا أنه خطأ؟» و88 و63.', null, 'approved', '2026-10-17'::timestamptz),
(203201, 2032, 'K1-C3-L2-O01', null, 1, 'أن يعرف الطالب الذرة .', 'أن يعرّف الطالب الذرة.', '[]'::jsonb, 'أن يعرّف الطالب الذرة.', 'ضبط الفعل «يعرّف» بالتشديد، وحذف المسافة قبل النقطة.', 'إملائي', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["الذرة","النواة","العنصر"]'::jsonb, null, '[80,88,101]'::jsonb, 'مغطى', 'الذرة هي أصغر جزء في العنصر له خواص العنصر (الخلاصة ص88، دليل المراجعة ص101). مثال الكتاب: تجزئة قطعة نحاس إلى جسيمات أصغر فأصغر حتى الوصول إلى أصغر جزء يحتفظ بخواص النحاس. السؤال 2 من التقويم 3-1: «عرّف الذرة بأسلوبك الخاص».', null, 'approved', '2026-10-17'::timestamptz),
(203202, 2032, 'K1-C3-L2-O02', null, 2, 'أن يذكر الطالب مكونات الذرة .', 'أن يذكر الطالب مكونات الذرة.', '[]'::jsonb, 'أن يذكر الطالب مكونات الذرة.', 'حذف المسافة قبل النقطة.', 'إملائي', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["الإلكترون","البروتون","النيوترون","النواة"]'::jsonb, null, '[86,88]'::jsonb, 'مغطى', 'تتكون الذرة من ثلاثة جسيمات أساسية: الإلكترون والبروتون والنيوترون؛ يوجد البروتونات والنيوترونات في النواة، وتتحرك الإلكترونات في الفراغ المحيط بالنواة (الشكل 3-14، الجدول 3-3). السؤالان 38 و42 (تسمية مكونات الذرة في الشكل 3-22).', null, 'approved', '2026-10-17'::timestamptz),
(203203, 2032, 'K1-C3-L2-O03', null, 3, 'أن يوضح الطالب أهمية استخدام جهاز STM.', 'أن يوضح الطالب أهمية استخدام جهاز المجهر النفقي الماسح (STM).', '[]'::jsonb, 'أن يوضح الطالب أهمية استخدام جهاز المجهر النفقي الماسح (STM).', 'كتابة المصطلح بالعربية مع اختصاره؛ المعنى ثابت.', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'حقائق ومصطلحات', '["المجهر النفقي الماسح STM","تقنية النانو"]'::jsonb, null, '[81,87,107]'::jsonb, 'مغطى', 'جهاز STM (المجهر النفقي الماسح) يسمح برؤية الذرات المفردة (الشكل 3-5: ذرات الجرافيت)، ويتيح دراسة الذرات وجعلها تتحرك لتكون أشكالًا وأنماطًا وآلات بسيطة في تقنية النانو. مختبر تحليل البيانات (ص87) يفسر صورة STM للجرافيت HOPG؛ والسؤال 54 «ما التقنية المستعملة في تصوير الذرات منفردة؟».', null, 'approved', '2026-10-17'::timestamptz),
(203204, 2032, 'K1-C3-L2-O04', null, 4, 'أن يشرح الطالب كيف تم اكتشاف الإلكترون داخل الذرة ؟', 'أن يشرح الطالب كيف اكتُشف الإلكترون داخل الذرة.', '[]'::jsonb, 'أن يشرح الطالب كيف اكتُشف الإلكترون داخل الذرة.', 'حذف علامة الاستفهام وتصحيح الصياغة (بناء للمجهول) وإنهاؤها بنقطة.', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["أشعة المهبط","أنبوب أشعة المهبط","طومسون","الإلكترون"]'::jsonb, null, '[81,82,83]'::jsonb, 'مغطى', 'استعمل العلماء أنابيب أشعة المهبط (مفرغة من الهواء بقطبين: المهبط الكاثود السالب والمصعد الأنود الموجب). أشعة المهبط سيل من جسيمات مشحونة بشحنة سالبة تنحرف في المجالين المغناطيسي والكهربائي (الشكل 3-7)، ولا يتغير سلوكها بتغير فلز القطبين أو الغاز، فاستنتج طومسون (1897م) أنها موجودة في جميع المواد وسُميت الإلكترونات (e⁻). وجد أن كتلة الجسيم أقل كثيرًا من كتلة ذرة الهيدروجين، فاستنتج أن الذرة تتجزأ (نال جائزة نوبل 1906م). أسئلة 47 و48 و49 و52 و97 و89.', null, 'approved', '2026-10-17'::timestamptz),
(203205, 2032, 'K1-C3-L2-O05', null, 5, 'أن يشرح الطالب كيف تم حساب مقدار كتلة الإلكترون و شحنته.', 'أن يشرح الطالب كيف حُسبت كتلة الإلكترون وشحنته.', '[]'::jsonb, 'أن يشرح الطالب كيف حُسبت كتلة الإلكترون وشحنته.', 'تصحيح الصياغة (بناء للمجهول) وضبط الواو.', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'إجراءات ومهارات', '["تجربة قطرة الزيت (ميليكان)","نسبة الشحنة إلى الكتلة","شحنة الإلكترون","كتلة الإلكترون"]'::jsonb, null, '[82,83]'::jsonb, 'مغطى جزئيًا', 'نسبة الشحنة إلى الكتلة: قاس طومسون تأثير المجالين المغناطيسي والكهربائي في جسيمات أشعة المهبط. شحنة الإلكترون: بجهاز ميليكان (قطرة الزيت، الشكل 3-8) ضبط سرعة سقوط قطرات الزيت المشحونة فوجد أن الشحنة تزداد بمضاعفات محددة، وأبسط مقدار مشترك يعادل 1.602×10⁻¹⁹ كولوم (شحنة –1). كتلة الإلكترون حُسبت من هذه الشحنة ونسبة الشحنة إلى الكتلة: 9.1×10⁻²⁸ g أي 1/1840 من كتلة ذرة الهيدروجين. لا يعرض الكتاب خطوات حسابية تفصيلية.', null, 'approved', '2026-10-17'::timestamptz),
(203206, 2032, 'K1-C3-L2-O06', null, 6, 'أن يقارن الطالب بين نموذج طومسون و نموذج رذرفورد للذرة.', 'أن يقارن الطالب بين نموذج طومسون ونموذج رذرفورد للذرة.', '[]'::jsonb, 'أن يقارن الطالب بين نموذج طومسون ونموذج رذرفورد للذرة.', 'حذف مسافة زائدة قبل الواو.', 'إملائي', 'سليم ويعتمد', 'تحليل', 'مفاهيم', '["نموذج طومسون","نموذج رذرفورد","النواة"]'::jsonb, null, '[84,86,103]'::jsonb, 'مغطى', 'نموذج طومسون: كرة موجبة الشحنة موزعة بانتظام تتناثر فيها إلكترونات سالبة (الشكل 3-9). نموذج رذرفورد: معظم الشحنة الموجبة ومعظم الكتلة في نواة صغيرة وكثيفة في المركز، والإلكترونات السالبة ترتبط بالنواة بالتجاذب وتتحرك في فراغ كبير، والذرة متعادلة (الشكل 3-13). نموذج طومسون لم يفسر نتائج رقاقة الذهب. أسئلة 8 و39 و40 و107.', null, 'approved', '2026-10-17'::timestamptz),
(203207, 2032, 'K1-C3-L2-O07', null, 7, 'أن يشرح الطالب تجربة رذرفورد.', 'أن يشرح الطالب تجربة رذرفورد.', '[]'::jsonb, 'أن يشرح الطالب تجربة رذرفورد.', 'لا تغيير.', 'لا تغيير', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["تجربة رقاقة الذهب","جسيمات ألفا","النواة"]'::jsonb, null, '[85,86]'::jsonb, 'مغطى', 'عام 1911م وجّه رذرفورد شعاعًا من جسيمات ألفا الموجبة نحو صفيحة رقيقة من الذهب يحيط بها شاشة مغلفة بكبريتيد الخارصين تومض عند الاصطدام (الشكل 3-11). معظم الجسيمات مرت دون انحراف أو بانحراف قليل، وانحرف عدد قليل بزاوية كبيرة، وارتد عدد قليل جدًّا إلى الخلف. توقع رذرفورد (حسب نموذج طومسون) انحرافًا قليلًا فقط، فاستنتج أن الشحنة الموجبة والكتلة مركزتان في نواة صغيرة. أسئلة 50 و51 و91.', null, 'approved', '2026-10-17'::timestamptz),
(203208, 2032, 'K1-C3-L2-O08', null, 8, 'أن يذكر الطالب اسم العالم الذي قام باكتشاف النيوترون و شحنة النيوترون', 'أن يذكر الطالب اسم العالم الذي اكتشف النيوترون وشحنة النيوترون.', '[]'::jsonb, 'أن يذكر الطالب اسم العالم الذي اكتشف النيوترون وشحنة النيوترون.', 'حذف «قام بـ» الحشوية، وضبط الواو، وإضافة النقطة الختامية.', 'لغوي', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["النيوترون","جيمس شادويك"]'::jsonb, null, '[84,87,88]'::jsonb, 'مغطى', 'في عام 1932م بيّن العالم جيمس شادويك أن النواة تحتوي أيضًا على جسيمات متعادلة سُميت النيوترونات (n)، كتلتها قريبة من كتلة البروتون ولا تحمل شحنة كهربائية (الشحنة صفر)؛ وحصل شادويك على جائزة نوبل في الفيزياء عام 1935م. الجدول 3-3 والخلاصة ص88.', null, 'approved', '2026-10-17'::timestamptz),
(203209, 2032, 'K1-C3-L2-O09', null, 9, 'أن يصف الطالب خصائص أشعة المهبط.', 'أن يصف الطالب خصائص أشعة المهبط.', '[]'::jsonb, 'أن يصف الطالب خصائص أشعة المهبط.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["أشعة المهبط","الجسيمات المشحونة","الإلكترون"]'::jsonb, null, '[81,82,103]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). أشعة المهبط (Cathode rays) سيل من جسيمات مشحونة بشحنة سالبة تسير من المهبط إلى المصعد داخل أنبوب مفرغ، وتنحرف عند مرورها في المجال المغناطيسي وكذلك نحو الصفيحة الموجبة في المجال الكهربائي (الشكل 3-7)، ولا يتغير سلوكها بتغير فلز القطبين أو الغاز في الأنبوب. أسئلة 47–49 و52 و89 و97.', null, 'approved', '2026-10-17'::timestamptz),
(203210, 2032, 'K1-C3-L2-O10', null, 10, 'أن يفسر الطالب سبب كون الذرة متعادلة كهربائيًا.', 'أن يفسر الطالب سبب كون الذرة متعادلة كهربائيًا.', '[]'::jsonb, 'أن يفسر الطالب سبب كون الذرة متعادلة كهربائيًا.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["تعادل الذرة","الشحنة الموجبة","الشحنة السالبة"]'::jsonb, null, '[84,86,88,103,106]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). الذرة متعادلة كهربائيًا لأن عدد البروتونات الموجبة في النواة يساوي عدد الإلكترونات السالبة المحيطة بها، فتلغي الشحنات الموجبة السالبة (ص86 و88). أسئلة 43 و92 و96 (النواة موجبة والذرة متعادلة).', null, 'approved', '2026-10-17'::timestamptz),
(203211, 2032, 'K1-C3-L2-O11', null, 11, 'أن يقارن الطالب بين الإلكترون والبروتون والنيوترون من حيث الشحنة النسبية والكتلة والموقع في الذرة.', 'أن يقارن الطالب بين الإلكترون والبروتون والنيوترون من حيث الشحنة النسبية والكتلة والموقع في الذرة.', '[]'::jsonb, 'أن يقارن الطالب بين الإلكترون والبروتون والنيوترون من حيث الشحنة النسبية والكتلة والموقع في الذرة.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تحليل', 'حقائق ومصطلحات', '["الشحنة النسبية","الكتلة النسبية","موقع الجسيم"]'::jsonb, null, '[88,103]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). الجدول 3-3: الإلكترون e⁻ شحنته –1، كتلته النسبية 1/1840، كتلته الحقيقية 9.11×10⁻²⁸ g، يقع في الفراغ المحيط بالنواة؛ البروتون p شحنته +1، كتلته 1.673×10⁻²⁴ g؛ النيوترون n شحنته صفر، كتلته 1.675×10⁻²⁴ g؛ والبروتون والنيوترون في النواة، كتلة كل منهما النسبية 1. أسئلة 10 و41 و45 و11. (يغطي هدف الكتاب «تميّز بين الجسيمات من حيث الشحنة والكتلة» ص80.)', null, 'approved', '2026-10-17'::timestamptz),
(203212, 2032, 'K1-C3-L2-O12', null, 12, 'أن يفسر الطالب كون معظم حجم الذرة فراغًا وكون النواة شديدة الكثافة.', 'أن يفسر الطالب كون معظم حجم الذرة فراغًا وكون النواة شديدة الكثافة.', '[]'::jsonb, 'أن يفسر الطالب كون معظم حجم الذرة فراغًا وكون النواة شديدة الكثافة.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["فراغ الذرة","كثافة النواة","حجم النواة"]'::jsonb, null, '[86,88,106]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). تشغل النواة حيزًا صغيرًا جدًّا (حوالي 0.0001 من حجم الذرة) وتحوي أكثر من 99.97% من كتلتها فهي كثيفة جدًّا، وقطر الذرة يعادل تقريبًا عشرة آلاف مرة قطر النواة، ومعظم حجم الذرة فراغ تتحرك فيه الإلكترونات (ص86 و88، الخلاصة). أسئلة 53 و95 و110.', null, 'approved', '2026-10-17'::timestamptz),
(203301, 2033, 'K1-C3-L3-O01', null, 1, 'أن يعرف الطالب العدد الذري.', 'أن يعرّف الطالب العدد الذري.', '[]'::jsonb, 'أن يعرّف الطالب العدد الذري.', 'ضبط الفعل «يعرّف» بالتشديد.', 'إملائي', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["العدد الذري","هوية الذرة"]'::jsonb, null, '[89,102]'::jsonb, 'مغطى', 'العدد الذري لذرة العنصر هو عدد البروتونات في النواة؛ يحدد هوية الذرة ويُكتب أعلى رمز العنصر (الشكل 3-15 ص89). تغير العدد الذري من عنصر لآخر هو ما يميز العناصر (اكتشاف هنري موزلي). السؤالان 20 و21.', null, 'approved', '2026-10-17'::timestamptz),
(203302, 2033, 'K1-C3-L3-O02', null, 2, 'أن يوجد الطالب قيمة العدد الذري و البروتونات و الإلكترونات.', 'أن يحدد الطالب العدد الذري وعدد البروتونات وعدد الإلكترونات للذرة المتعادلة.', '[]'::jsonb, 'أن يحدد الطالب العدد الذري وعدد البروتونات وعدد الإلكترونات للذرة المتعادلة.', '«يوجد» غير دقيق وصيغة العبارة ناقصة؛ استُبدل بـ«يحدد» مع توضيح المطلوب دون تغيير المعنى.', 'صياغة', 'يعتمد بعد التعديل', 'تطبيق', 'حل مسائل', '["العدد الذري","البروتونات","الإلكترونات","الجدول الدوري"]'::jsonb, null, '[89,90,104]'::jsonb, 'مغطى', 'العدد الذري = عدد البروتونات = عدد الإلكترونات في الذرة المتعادلة. المثال 3-1 (ص90): Pb عدده الذري 82 فيحوي 82 بروتونًا و82 إلكترونًا؛ ذرة بها 8 بروتونات هي الأكسجين O؛ ذرة بها 30 إلكترونًا هي Zn، باستعمال الجدول الدوري. مسائل تدريبية 12–15، وأسئلة 44 و57 و64 و68 و71–73 و92.', null, 'approved', '2026-10-17'::timestamptz),
(203303, 2033, 'K1-C3-L3-O03', null, 3, 'أن يعرف الطالب النظائر.', 'أن يعرّف الطالب النظائر.', '[]'::jsonb, 'أن يعرّف الطالب النظائر.', 'ضبط الفعل «يعرّف» بالتشديد.', 'إملائي', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["النظائر","عدد النيوترونات"]'::jsonb, null, '[91,102]'::jsonb, 'مغطى', 'النظائر ذرات للعنصر نفسه لها عدد البروتونات نفسه لكنها تختلف في عدد النيوترونات؛ مثال: ثلاثة نظائر للبوتاسيوم (39، 40، 41) فيها 19 بروتونًا و20 أو 21 أو 22 نيوترونًا (الشكل 3-17)، ونظيرا النحاس Cu-63 وCu-65. نظائر العنصر لها السلوك الكيميائي نفسه. أسئلة 56 و62 و63.', null, 'approved', '2026-10-17'::timestamptz),
(203304, 2033, 'K1-C3-L3-O04', null, 4, 'أن يطبق الطالب مسائل حسابية على قانون العدد الكتلي.', 'أن يطبق الطالب قانون العدد الكتلي في حل مسائل حسابية.', '[]'::jsonb, 'أن يطبق الطالب قانون العدد الكتلي في حل مسائل حسابية.', 'تعديل الصياغة لتصبح قابلة للقياس (يطبق القانون في حل المسائل).', 'صياغة', 'يعتمد بعد التعديل', 'تطبيق', 'حل مسائل', '["العدد الكتلي","عدد النيوترونات","رمز النظير"]'::jsonb, null, '[91,92,104,105]'::jsonb, 'مغطى', 'العدد الكتلي = العدد الذري + عدد النيوترونات (ص91). المثال 3-2: النيون عدده الذري 10 وعدده الكتلي 22 فعدد النيوترونات = 22 – 10 = 12، ورمز النظير ²²₁₀Ne (نيون-22). مسائل تدريبية 16 و17، وأسئلة 59 و65–67 و93 و99 في تقويم الفصل، وأسئلة 6 و10 في الاختبار المقنن.', null, 'approved', '2026-10-17'::timestamptz),
(203305, 2033, 'K1-C3-L3-O05', null, 5, 'أن يعرف الطالب الكتلة الذرية والوحدة.', 'أن يعرّف الطالب الكتلة الذرية ووحدة الكتل الذرية (amu).', '[]'::jsonb, 'أن يعرّف الطالب الكتلة الذرية ووحدة الكتل الذرية (amu).', 'ضبط «يعرّف»، وتوضيح «الوحدة» بأنها وحدة الكتل الذرية.', 'صياغة', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["الكتلة الذرية","وحدة الكتل الذرية amu"]'::jsonb, null, '[93,102]'::jsonb, 'مغطى', 'وحدة الكتل الذرية (amu) تعادل 1/12 من كتلة ذرة الكربون-12 وتساوي تقريبًا كتلة بروتون أو نيوترون واحد (الكربون-12 هو الذرة المعيارية)؛ ويُرمز لها u أيضًا. الكتلة الذرية للعنصر هي متوسط كتل نظائر العنصر الموجودة في الطبيعة (الكلور 35.453 amu). الجدول 3-4: كتلة البروتون 1.007276 amu، والنيوترون 1.008665 amu، والإلكترون 0.000549 amu. السؤال 61.', null, 'approved', '2026-10-17'::timestamptz),
(203306, 2033, 'K1-C3-L3-O06', null, 6, 'أن يحل الطالب مسائل حسابية على نسبة النظائر.', 'أن يحل الطالب مسائل حسابية على نسبة وجود النظائر لحساب الكتلة الذرية.', '[]'::jsonb, 'أن يحل الطالب مسائل حسابية على نسبة وجود النظائر لحساب الكتلة الذرية.', 'توضيح المطلوب («نسبة وجود النظائر» وحساب الكتلة الذرية المتوسطة) دون تغيير المعنى.', 'صياغة', 'يعتمد بعد التعديل', 'تطبيق', 'حل مسائل', '["نسبة وجود النظير","الكتلة الذرية المتوسطة","إسهام النظير"]'::jsonb, null, '[93,94,95,105,109]'::jsonb, 'مغطى', 'الكتلة الذرية المتوسطة = مجموع (كتلة كل نظير × نسبة وجوده). الشكل 3-18: الكلور-35 (34.969 amu، 75.78%) والكلور-37 (36.966 amu، 24.22%) → 35.453 amu. المثال 3-3: النظيران 6X (6.015 amu، 7.59%) و7X (7.016 amu، 92.41%) → 6.939 amu، والعنصر الليثيوم Li. مسائل تدريبية 18 و19، وأسئلة 23 و24 و69 و74–76 و102 و112 و114 والاختبار المقنن 11.', null, 'approved', '2026-10-17'::timestamptz),
(203307, 2033, 'K1-C3-L3-O07', null, 7, 'أن يفسر الطالب سبب أن الكتل الذرية ليست اعداد صحيحة', 'أن يفسر الطالب سبب كون الكتل الذرية ليست أعدادًا صحيحة.', '[]'::jsonb, 'أن يفسر الطالب سبب كون الكتل الذرية ليست أعدادًا صحيحة.', 'تصحيح همزة «أعدادًا» وعبارة «سبب أن»، وإضافة النقطة.', 'إملائي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["الكتلة الذرية","متوسط كتل النظائر","النظائر"]'::jsonb, null, '[93,94,105,107]'::jsonb, 'مغطى', 'كتلة البروتون والنيوترون قريبة من 1 amu، فيُتوقع أن الكتلة الذرية عدد صحيح، لكنها متوسط كتل نظائر العنصر في الطبيعة ولكل نظير كتلة مختلفة، فليست عددًا صحيحًا (مثال الكلور 35.453 amu من الكلور-35 والكلور-37). نسبة الوجود تجعل المتوسط أقرب إلى النظير الأكثر وجودًا (الفلور-19، البروم-79 و-81). أسئلة 22 و113 والتجربة ص94.', null, 'approved', '2026-10-17'::timestamptz),
(203308, 2033, 'K1-C3-L3-O08', null, 8, 'أن يكتب الطالب رمز النظير واسمه مستعملًا العدد الذري والعدد الكتلي.', 'أن يكتب الطالب رمز النظير واسمه مستعملًا العدد الذري والعدد الكتلي.', '[]'::jsonb, 'أن يكتب الطالب رمز النظير واسمه مستعملًا العدد الذري والعدد الكتلي.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'إجراءات ومهارات', '["رمز النظير","العدد الكتلي","العدد الذري"]'::jsonb, null, '[91,92,104,106]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). يُكتب النظير باسم العنصر والعدد الكتلي (نحاس-63) أو بالرمز الكيميائي والعدد الذري أسفل اليسار والعدد الكتلي أعلاه (⁶³₂₉Cu). المثال 3-2 (ص92) يطلب تسمية النظير وكتابة رمزه، وأسئلة 60 و70 و71 و72 و99 و101.', null, 'approved', '2026-10-17'::timestamptz),
(203309, 2033, 'K1-C3-L3-O09', null, 9, 'أن يحدد الطالب النظير الأكثر وجودًا في الطبيعة اعتمادًا على الكتلة الذرية المتوسطة ونسب الوجود.', 'أن يحدد الطالب النظير الأكثر وجودًا في الطبيعة اعتمادًا على الكتلة الذرية المتوسطة ونسب الوجود.', '[]'::jsonb, 'أن يحدد الطالب النظير الأكثر وجودًا في الطبيعة اعتمادًا على الكتلة الذرية المتوسطة ونسب الوجود.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تحليل', 'مفاهيم', '["النظير الأكثر وجودًا","الكتلة الذرية المتوسطة"]'::jsonb, null, '[94,95,106,109]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). تقترب الكتلة الذرية للعنصر من كتلة النظير الأكثر وجودًا؛ مثال: الفلور-19 هو الوحيد تقريبًا (كتلته 19 amu)، والبروم-79 أكثر من البروم-81 رغم أن متوسط كتلة البروم 79.904 amu. أسئلة 19 و74 و100 و123 والاختبار المقنن 12.', null, 'approved', '2026-10-17'::timestamptz),
(203310, 2033, 'K1-C3-L3-O10', null, 10, 'أن يفسر الطالب سبب تشابه نظائر العنصر في سلوكها الكيميائي رغم اختلافها في الكتلة.', 'أن يفسر الطالب سبب تشابه نظائر العنصر في سلوكها الكيميائي رغم اختلافها في الكتلة.', '[]'::jsonb, 'أن يفسر الطالب سبب تشابه نظائر العنصر في سلوكها الكيميائي رغم اختلافها في الكتلة.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["النظائر","السلوك الكيميائي","الإلكترونات"]'::jsonb, null, '[91,104]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). تختلف النظائر في عدد النيوترونات فتكون كتلة النظائر الأكبر نيوترونات أكبر، لكن ذراتها لها السلوك الكيميائي نفسه، لأن السلوك الكيميائي يحدده عدد الإلكترونات (يتبع عدد البروتونات). وجود النظائر يبيّن خطأ فرضية دالتون بتطابق ذرات العنصر الواحد. أسئلة 56 و62 و63.', null, 'approved', '2026-10-17'::timestamptz),
(203311, 2033, 'K1-C3-L3-O11', null, 11, 'أن يذكر الطالب مساهمة هنري موزلي في فهم الذرة.', 'أن يذكر الطالب مساهمة هنري موزلي في فهم الذرة.', '[]'::jsonb, 'أن يذكر الطالب مساهمة هنري موزلي في فهم الذرة.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["هنري موزلي","العدد الذري"]'::jsonb, null, '[89,106]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). اكتشف العالم هنري موزلي أن ذرات كل عنصر تحتوي على عدد معين من البروتونات في النواة (العدد الذري) يميز العنصر عن غيره (ص89)؛ السؤال 98 «ما مساهمة هنري موزلي في فهمنا الحديث للذرة؟».', null, 'approved', '2026-10-17'::timestamptz),
(203401, 2034, 'K1-C3-L4-O01', null, 1, 'أن يقارن الطالب بين التفاعل الكيميائي والتفاعل النووي.', 'أن يقارن الطالب بين التفاعل الكيميائي والتفاعل النووي.', '[]'::jsonb, 'أن يقارن الطالب بين التفاعل الكيميائي والتفاعل النووي.', 'لا تغيير.', 'لا تغيير', 'سليم ويعتمد', 'تحليل', 'مفاهيم', '["التفاعل الكيميائي","التفاعل النووي"]'::jsonb, null, '[96,98,102,105]'::jsonb, 'مغطى', 'التفاعل الكيميائي تغير في المادة تشارك فيه إلكترونات الذرة فقط، وقد تُعاد ترتيب الذرات لكن هويتها (عنصرها) تبقى ثابتة. التفاعل النووي تغير في نواة الذرة قد يحوّل عنصرًا إلى عنصر آخر (اكتُشف عام 1890م من ملاحظة الإشعاعات). الخلاصة ص98: الكيميائية تغير في عدد الإلكترونات المحيطة بالذرة والنووية تغير في أنوية الذرات. أسئلة 27 و82 والاختبار المقنن.', null, 'approved', '2026-10-17'::timestamptz),
(203402, 2034, 'K1-C3-L4-O02', null, 2, 'أن يفسر الطالب العلاقة بين الأنوية غير المستقرة والتحلل الإشعاعي.', 'أن يفسر الطالب العلاقة بين الأنوية غير المستقرة والتحلل الإشعاعي.', '[]'::jsonb, 'أن يفسر الطالب العلاقة بين الأنوية غير المستقرة والتحلل الإشعاعي.', 'لا تغيير.', 'لا تغيير', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["النواة غير المستقرة","التحلل الإشعاعي","النشاط الإشعاعي"]'::jsonb, null, '[96,98,105]'::jsonb, 'مغطى', 'تفقد الأنوية غير المستقرة الطاقة بإصدار إشعاعات في عملية تلقائية تسمى التحلل الإشعاعي، فتتحول إلى ذرات مستقرة غالبًا لعنصر آخر (مثال الحجر المتساقط الذي يفقد طاقة الوضع). عامل الاستقرار الرئيس نسبة النيوترونات إلى البروتونات. الأسئلة 25 و77–79 و84–86.', null, 'approved', '2026-10-17'::timestamptz),
(203403, 2034, 'K1-C3-L4-O03', null, 3, 'أن يقارن الطالب بين أشعة ألفا وبيتا و جاما.', 'أن يقارن الطالب بين أشعة ألفا وأشعة بيتا وأشعة جاما.', '[]'::jsonb, 'أن يقارن الطالب بين أشعة ألفا وأشعة بيتا وأشعة جاما.', 'تصحيح الفراغ قبل «جاما» وتوضيح «أشعة» مع كل نوع، وإضافة النقطة.', 'صياغة', 'يعتمد بعد التعديل', 'تحليل', 'مفاهيم', '["جسيم ألفا","جسيم بيتا","أشعة جاما","الجدول 3-5"]'::jsonb, null, '[97,98]'::jsonb, 'مغطى', 'الجدول 3-5: ألفا (⁴₂He أو α): كتلة 4 amu، شحنة +2 (نواة هيليوم-4)، تنحرف نحو الصفيحة السالبة؛ بيتا (e⁻ أو β): كتلة 1/1840 amu، شحنة –1 (إلكترون ينتج من تفكك النيوترون إلى بروتون وإلكترون)، تنحرف نحو الصفيحة الموجبة؛ جاما (γ): طاقة عالية، دون كتلة ولا شحنة، لا تنحرف، وترافق ألفا وبيتا. الشكل 3-21. أسئلة 80 و81 و103 و105.', null, 'approved', '2026-10-17'::timestamptz),
(203404, 2034, 'K1-C3-L4-O04', null, 4, 'أن يعرّف الطالب النشاط الإشعاعي والإشعاع.', 'أن يعرّف الطالب النشاط الإشعاعي والإشعاع.', '[]'::jsonb, 'أن يعرّف الطالب النشاط الإشعاعي والإشعاع.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["النشاط الإشعاعي","الإشعاع"]'::jsonb, null, '[96,102,105]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). النشاط الإشعاعي: عملية تصدر فيها بعض المواد إشعاعات (لاحظها العلماء عام 1890م)؛ والإشعاعات هي الطاقة والجسيمات المنبعثة من المواد المشعة، وتصدرها الأنوية غير المستقرة. أسئلة 77 و78 و80.', null, 'approved', '2026-10-17'::timestamptz),
(203405, 2034, 'K1-C3-L4-O05', null, 5, 'أن يحدد الطالب العامل الرئيس في استقرار نواة الذرة.', 'أن يحدد الطالب العامل الرئيس في استقرار نواة الذرة.', '[]'::jsonb, 'أن يحدد الطالب العامل الرئيس في استقرار نواة الذرة.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تذكر', 'مفاهيم', '["استقرار النواة","نسبة النيوترونات إلى البروتونات"]'::jsonb, null, '[98,102,105]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). العامل الرئيس في استقرار النواة هو نسبة النيوترونات إلى البروتونات؛ الأنوية التي تحوي عددًا كبيرًا أو قليلًا من النيوترونات غير مستقرة وتفقد طاقة بالتحلل الإشعاعي بإطلاق جسيمات ألفا وبيتا لتغيّر هذه النسبة. أسئلة 25 و84 والخلاصة ص98.', null, 'approved', '2026-10-17'::timestamptz),
(203406, 2034, 'K1-C3-L4-O06', null, 6, 'أن يحدد الطالب تأثير إصدار جسيم ألفا وجسيم بيتا وأشعة جاما في العدد الذري والعدد الكتلي للذرة.', 'أن يحدد الطالب تأثير إصدار جسيم ألفا وجسيم بيتا وأشعة جاما في العدد الذري والعدد الكتلي للذرة.', '[]'::jsonb, 'أن يحدد الطالب تأثير إصدار جسيم ألفا وجسيم بيتا وأشعة جاما في العدد الذري والعدد الكتلي للذرة.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'مبادئ وقوانين', '["العدد الذري","العدد الكتلي","التحلل الإشعاعي"]'::jsonb, null, '[97,98,105]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ألفا (He-4) يقل العدد الذري بمقدار 2 والعدد الكتلي بمقدار 4 (Ra-226 → Rn-222 + α)؛ بيتا (إلكترون) يزيد العدد الذري بمقدار 1 ولا يتغير العدد الكتلي (C-14 → N-14 + β)؛ جاما لا تغيّر العدد الذري أو الكتلي (U-238 → Th-234 + α + 2γ). أسئلة 28 و29 و83 و103 والاختبار المقنن 2 و13.', null, 'approved', '2026-10-17'::timestamptz),
(203407, 2034, 'K1-C3-L4-O07', null, 7, 'أن يكتب الطالب معادلة نووية موزونة لتحلل إشعاعي.', 'أن يكتب الطالب معادلة نووية موزونة لتحلل إشعاعي.', '[]'::jsonb, 'أن يكتب الطالب معادلة نووية موزونة لتحلل إشعاعي.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'إجراءات ومهارات', '["المعادلة النووية","الاتزان النووي"]'::jsonb, null, '[97,98,105]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). المعادلة النووية تبيّن العدد الذري والعدد الكتلي للجسيمات المتضمنة في التفاعل؛ يجب حفظ الكميات (العدد الكتلي والعدد الذري) عند موازنتها (سؤال 26). أمثلة الكتاب: ²²⁶₈₈Ra → ²²²₈₆Rn + α، ¹⁴₆C → ¹⁴₇N + β. سؤال 87: كتابة معادلة موزونة لتحلل البورون-10 (ألفا) والسيزيوم-137 (بيتا).', null, 'approved', '2026-10-17'::timestamptz),
(204101, 2041, 'K1-C4-L1-O01', null, 1, 'أن يعرف الطالب التفاعل الكيميائي', 'أن يعرّف الطالب التفاعل الكيميائي.', '[]'::jsonb, 'أن يعرّف الطالب التفاعل الكيميائي.', 'ضبط الفعل «يعرّف» بالشدة لرفع اللبس مع «يعرِف»، وإضافة النقطة.', 'إملائي', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["التفاعل الكيميائي","التغير الكيميائي","إعادة ترتيب الذرات"]'::jsonb, null, '[112,146]'::jsonb, 'مغطى', 'التفاعل الكيميائي (ويسمى أيضًا التغير الكيميائي) هو العملية التي يعاد فيها ترتيب الذرات في مادة أو أكثر لتكوين مواد مختلفة. وتذكّر «مراجعة المفردات» بأن التغير الكيميائي عملية تتضمن تحول مادة أو أكثر إلى مادة جديدة. من الأمثلة: حرائق الغابات، والقرص الفوار في الماء، وإنتاج النايلون.', null, 'approved', '2026-10-17'::timestamptz),
(204102, 2041, 'K1-C4-L1-O02', null, 2, 'أن يتعرف الطالب على مؤشرات حدوث تفاعل كيميائي', 'أن يعدد الطالب مؤشرات حدوث التفاعل الكيميائي.', '[]'::jsonb, 'أن يعدد الطالب مؤشرات حدوث التفاعل الكيميائي.', '«يتعرف على» فعل غير قابل للقياس مباشرة وفيه حرف جر زائد؛ استُبدل بـ«يعدد» لأن الكتاب يطلب «عدد ثلاثة من المؤشرات».', 'تحويل إلى هدف قابل للقياس', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["مؤشرات التفاعل الكيميائي","تغير اللون","تصاعد غاز","الراسب"]'::jsonb, null, '[111,112,113,122]'::jsonb, 'مغطى', 'يذكر الكتاب أن بعض التفاعلات يصعب اكتشافها، وأن الكثير منها يُظهر مؤشرات فيزيائية: تغير درجة الحرارة (تفاعل يطلق طاقة حرارة وضوء كاحتراق الخشب، أو يمتص الحرارة)، وتغير اللون (تحول لون الموز من الأخضر إلى الأصفر، وتغير لون المسامير الملقاة)، وظهور رائحة، وتصاعد غاز، وتكوّن مادة صلبة. الشكل 4-2 والتجربة الاستهلالية ص111 (تغير لون الكاشف ودرجة الحرارة وتصاعد غاز)، والسؤال 10 ص122.', null, 'approved', '2026-10-17'::timestamptz),
(204103, 2041, 'K1-C4-L1-O03', null, 3, 'أن يحسب الطالب عدد الإلكترونات التي تستوعبها المستويات(١,٢,٣,٤ )الرئيسية', 'أن يحسب الطالب أقصى عدد من الإلكترونات يستوعبه كل مستوى من مستويات الطاقة الرئيسة (1، 2، 3، 4).', '[]'::jsonb, 'أن يحسب الطالب أقصى عدد من الإلكترونات يستوعبه كل مستوى من مستويات الطاقة الرئيسة (1، 2، 3، 4).', 'تحديد المطلوب بعبارة «أقصى عدد»، وتصحيح كتابة الأرقام والمسافات.', 'صياغة', 'يعتمد بعد التعديل', 'تطبيق', 'حل مسائل', '["مستوى الطاقة الرئيس","e = 2n²","سعة المستوى"]'::jsonb, null, '[113,122]'::jsonb, 'مغطى', 'يعطي الكتاب القانون e = 2n² لحساب أقصى عدد من الإلكترونات في مستوى الطاقة الرئيس (n)، ويذكر القيم: المستوى الأول إلكترونان، والثاني ثمانية، والثالث ثمانية عشر «وهكذا» (فيُحسب الرابع بالقانون = 32). ويرد القانون في خلاصة الدرس ص122.', null, 'approved', '2026-10-17'::timestamptz),
(204104, 2041, 'K1-C4-L1-O04', null, 4, 'أن يعدد الطالب مستويات الطاقة الثانوية في مستوى الطاقة الرئيس', 'أن يعدد الطالب مستويات الطاقة الثانوية في مستوى الطاقة الرئيس.', '[]'::jsonb, 'أن يعدد الطالب مستويات الطاقة الثانوية في مستوى الطاقة الرئيس.', 'لا تغيير جوهري؛ أضيفت النقطة الختامية.', 'لا تغيير', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["مستويات الطاقة الثانوية","s p d f"]'::jsonb, null, '[113,114]'::jsonb, 'مغطى', 'الجدول 4-1: المستوى الرئيس 1 فيه المستوى الثانوي s فقط؛ والثاني s وp؛ والثالث s وp وd؛ والرابع s وp وd وf. وتزداد طاقة الإلكترونات في المستويات الثانوية بالترتيب s ثم p ثم d ثم f (ص113).', null, 'approved', '2026-10-17'::timestamptz),
(204105, 2041, 'K1-C4-L1-O05', null, 5, 'أن يذكر الطالب عدد الإلكترونات في كل مستوى ثانوي', 'أن يذكر الطالب أقصى عدد من الإلكترونات في كل مستوى طاقة ثانوي.', '[]'::jsonb, 'أن يذكر الطالب أقصى عدد من الإلكترونات في كل مستوى طاقة ثانوي.', 'توضيح المطلوب بعبارة «أقصى عدد» لأن الكتاب يعطي السعة العظمى.', 'صياغة', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["سعة المستوى الثانوي","s=2","p=6","d=10","f=14"]'::jsonb, null, '[114]'::jsonb, 'مغطى', 'أقصى سعة من الإلكترونات: المستوى الثانوي s إلكترونان، وp ستة، وd عشرة، وf أربعة عشر. ويضيف الكتاب أن أقصى سعة «لمستوى الطاقة الفرعي» إلكترونان فقط (يقصد الفلك الواحد داخل المستوى الثانوي؛ ينبغي ألا تُبنى عليه أسئلة).', null, 'approved', '2026-10-17'::timestamptz),
(204106, 2041, 'K1-C4-L1-O06', null, 6, 'أن يكتب الطالب التوزيع الإلكتروني لبعض ذرات العناصر', 'أن يكتب الطالب التوزيع الإلكتروني لذرات بعض العناصر.', '[]'::jsonb, 'أن يكتب الطالب التوزيع الإلكتروني لذرات بعض العناصر.', 'إعادة ترتيب العبارة لتصبح أوضح لغويًا («لبعض ذرات العناصر» ← «لذرات بعض العناصر»).', 'صياغة', 'يعتمد بعد التعديل', 'تطبيق', 'إجراءات ومهارات', '["التوزيع الإلكتروني","تسلسل مستويات الطاقة","استثناءات Cr وCu"]'::jsonb, null, '[113,114,118,122,146,151]'::jsonb, 'مغطى', 'التوزيع يتبع تسلسل مستويات الطاقة (الشكلان 4-3 و4-4): 1s 2s 2p 3s 3p 4s 3d … والجدول 4-2 يعطي توزيع Li وB وNe وCl وFe وTi وCr وCu وZn. استثناءان: Cr (4s¹ 3d⁵) وCu (4s¹ 3d¹⁰) وليس 4s² 3d⁴ ولا 4s² 3d⁹. تدريبات: س3 ص118 (K وCl)، س11 ص122 (Al وO)، س64–65 ص146 (كتابة التوزيع وتحديد العنصر من توزيعه)، س8–9 ص151.', null, 'approved', '2026-10-17'::timestamptz),
(204107, 2041, 'K1-C4-L1-O07', null, 7, 'أن يذكر الطالب عدد التأكسد لبعض العناصر و الأيونات', 'أن يذكر الطالب أعداد التأكسد لبعض العناصر والأيونات.', '[]'::jsonb, 'أن يذكر الطالب أعداد التأكسد لبعض العناصر والأيونات.', 'تصحيح الإفراد إلى الجمع «أعداد» ليتفق مع «بعض العناصر والأيونات».', 'لغوي', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["عدد التأكسد","أيونات الفلزات الانتقالية","المجموعات 1 و2 و15 و16 و17"]'::jsonb, null, '[115]'::jsonb, 'مغطى', 'عدد التأكسد هو عدد الإلكترونات التي تفقدها ذرة العنصر أو تكتسبها أو تشارك بها في أثناء التفاعل. الجدول 4-3: المجموعة 1 (+1)، 2 (+2)، 15 (−3)، 16 (−2)، 17 (−1). أما الفلزات الانتقالية وفلزات المجموعتين 13 و14 فلها أكثر من عدد تأكسد، وتُعرف أعدادها بالشحنة الظاهرة على الأيون كما في الجدول 4-4 (مثل Fe²⁺ وFe³⁺ وCu⁺ وCu²⁺).', null, 'approved', '2026-10-17'::timestamptz),
(204108, 2041, 'K1-C4-L1-O08', null, 8, 'أن يتعرف الطالب على بعض الأيونات العديدة الذرات', 'أن يذكر الطالب أسماء وصيغ بعض الأيونات العديدة الذرات.', '[]'::jsonb, 'أن يذكر الطالب أسماء وصيغ بعض الأيونات العديدة الذرات.', '«يتعرف على» غير قابل للقياس؛ حُدّد المطلوب (اسم الأيون وصيغته) كما يعرضه الجدول 4-5.', 'تحويل إلى هدف قابل للقياس', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["الأيون العديد الذرات","الجدول 4-5"]'::jsonb, null, '[116,118,122]'::jsonb, 'مغطى', 'الجدول 4-5 يعرض 26 أيونًا عديد الذرات باسمها وصيغتها، منها: NH₄⁺ الأمونيوم، NO₃⁻ النترات، OH⁻ الهيدروكسيد، CN⁻ السيانيد، MnO₄⁻ البرمنجنات، HCO₃⁻ البيكربونات، ClO⁻ الهيبوكلورايت، CO₃²⁻ الكربونات، SO₄²⁻ الكبريتات، CrO₄²⁻ الكرومات، Cr₂O₇²⁻ ثنائي الكرومات، PO₄³⁻ الفوسفات، CH₃COO⁻ الأسيتات.', null, 'approved', '2026-10-17'::timestamptz),
(204109, 2041, 'K1-C4-L1-O09', null, 9, 'ان يذكر الطالب الرموز المستخدمة في المعادلات الكيميائية', 'أن يذكر الطالب الرموز المستخدمة في المعادلات الكيميائية.', '[]'::jsonb, 'أن يذكر الطالب الرموز المستخدمة في المعادلات الكيميائية.', 'تصحيح همزة «أن» (كُتبت «ان» في الأصل).', 'إملائي', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["رموز المعادلة","(s)","(l)","(g)","(aq)","السهم"]'::jsonb, null, '[117,126,128]'::jsonb, 'مغطى', 'الجدول 4-6: (+) يفصل بين مادتين أو أكثر من المتفاعلات أو النواتج؛ (→) يفصل المتفاعلات عن النواتج؛ (⇌) يدل على تفاعل عكسي؛ (s) صلبة؛ (l) سائلة؛ (g) غازية؛ (aq) محلول مائي، وتُكتب أسفل صيغة المادة بين قوسين. ويرد الرمز Δ فوق السهم للدلالة على التسخين (ص126) والرمز NR لعدم حدوث تفاعل (ص128).', null, 'approved', '2026-10-17'::timestamptz),
(204110, 2041, 'K1-C4-L1-O10', null, 10, 'أن يكتب الطالب الصيغ الكيميائية لبعض المركبات الأيونية', 'أن يكتب الطالب الصيغ الكيميائية لبعض المركبات الأيونية.', '[]'::jsonb, 'أن يكتب الطالب الصيغ الكيميائية لبعض المركبات الأيونية.', 'لا تغيير جوهري؛ أضيفت النقطة الختامية.', 'لا تغيير', 'سليم ويعتمد', 'تطبيق', 'إجراءات ومهارات', '["الصيغة الكيميائية","المركب الأيوني","تبديل أعداد التأكسد"]'::jsonb, null, '[116,118,122,146]'::jsonb, 'مغطى', 'خطوات الكتاب: (1) اكتب رمز الأيون الموجب يسارًا والأيون السالب أو صيغة الأيون العديد الذرات يمينًا؛ (2) اكتب عدد التأكسد أسفل كل منهما؛ (3) بدّل أعداد التأكسد بين شقّي المركب واقسم على العامل المشترك إن وُجد، وضع الأيون العديد الذرات بين قوسين إذا زاد عدده على واحد. أمثلة: Al(OH)₃ وMgCl₂. تدريبات: س4 ص118 (Mg²⁺ مع NO₃⁻)، س12 ص122 (Fe³⁺ مع O²⁻)، س66 ص146.', null, 'approved', '2026-10-17'::timestamptz),
(204111, 2041, 'K1-C4-L1-O11', null, 11, 'أن يسمي الطالب المركبات الأيونية', 'أن يسمي الطالب المركبات الأيونية.', '[]'::jsonb, 'أن يسمي الطالب المركبات الأيونية.', 'لا تغيير جوهري؛ أضيفت النقطة الختامية.', 'لا تغيير', 'سليم ويعتمد', 'تطبيق', 'إجراءات ومهارات', '["تسمية المركبات الأيونية","الأرقام اللاتينية"]'::jsonb, null, '[117]'::jsonb, 'مغطى', 'قواعد الكتاب: يُسمى الأيون السالب أولًا ثم الموجب؛ الأيون السالب الأحادي الذرة يشتق اسمه من اسم العنصر مضافًا إليه المقطع «يد»؛ إذا كان للأيون الموجب أكثر من عدد تأكسد يُشار إليه بالرقم اللاتيني بعد اسمه؛ والمركب ذو الأيون العديد الذرات يُسمى بتسمية هذا الأيون أولًا. أمثلة: كلوريد الصوديوم NaCl، أكسيد الألومنيوم Al₂O₃، كلوريد الكوبلت II CoCl₂، هيدروكسيد الصوديوم NaOH، كرومات الفضة Ag₂CrO₄، نترات النحاس II Cu(NO₃)₂، أكسيد الحديد II FeO، أكسيد الحديد III Fe₂O₃.', null, 'approved', '2026-10-17'::timestamptz),
(204112, 2041, 'K1-C4-L1-O12', null, 12, 'أن يمثل الطالب التفاعلات الكيميائية بمعادلات لفظية .', 'أن يمثل الطالب التفاعلات الكيميائية بمعادلات لفظية.', '[]'::jsonb, 'أن يمثل الطالب التفاعلات الكيميائية بمعادلات لفظية.', 'لا تغيير جوهري؛ أضيفت النقطة الختامية.', 'لا تغيير', 'سليم ويعتمد', 'تطبيق', 'إجراءات ومهارات', '["المعادلة اللفظية","المتفاعلات","النواتج"]'::jsonb, null, '[118,146,148]'::jsonb, 'مغطى', 'المعادلة اللفظية تعبّر بالكلمات عن المواد المتفاعلة والناتجة: «بروميد الألومنيوم ← البروم + الألومنيوم» وتُقرأ «الألومنيوم والبروم يتفاعلان لإنتاج بروميد الألومنيوم». وهي تفتقر إلى المعلومات الكمية. تدريبات: س5 ص118 (كلورات البوتاسيوم)، س70 ص146 (كتابة معادلات لفظية لمعادلات رمزية)، س87 ص148.', null, 'approved', '2026-10-17'::timestamptz),
(204113, 2041, 'K1-C4-L1-O13', null, 13, 'أن يزن الطالب المعادلات الكيميائية', 'أن يزن الطالب المعادلات الكيميائية.', '[]'::jsonb, 'أن يزن الطالب المعادلات الكيميائية.', 'لا تغيير جوهري؛ أضيفت النقطة الختامية.', 'لا تغيير', 'سليم ويعتمد', 'تطبيق', 'إجراءات ومهارات', '["وزن المعادلات","المعامل","أبسط نسبة"]'::jsonb, null, '[119,120,121,122,146]'::jsonb, 'مغطى', 'الجدول 4-7 يلخص ست خطوات: (1) اكتب المعادلة غير الموزونة بالصيغ الصحيحة والحالات الفيزيائية؛ (2) عُدّ ذرات كل عنصر في المتفاعلات؛ (3) وفي النواتج؛ (4) غيّر المعاملات فقط ولا تغيّر الأرقام السفلية في الصيغ؛ (5) اكتب المعاملات في أبسط نسبة عددية صحيحة؛ (6) تأكد. مثال H₂ + Cl₂ → 2HCl، والمثال 4-1: 2NaOH + CaBr₂ → Ca(OH)₂ + 2NaBr، والمخطط الشكل 4-8. تدريبات: س6–8، 16–17، 69، 71.', null, 'approved', '2026-10-17'::timestamptz),
(204114, 2041, 'K1-C4-L1-O14', null, 14, 'أن يمثل الطالب التفاعلات الكيميائية بمعادلات رمزية', 'أن يمثل الطالب التفاعلات الكيميائية بمعادلات رمزية.', '[]'::jsonb, 'أن يمثل الطالب التفاعلات الكيميائية بمعادلات رمزية.', 'لا تغيير جوهري؛ أضيفت النقطة الختامية.', 'لا تغيير', 'سليم ويعتمد', 'تطبيق', 'إجراءات ومهارات', '["المعادلة الرمزية","الصيغة الكيميائية","الحالة الفيزيائية"]'::jsonb, null, '[118,119,125,126,146,147]'::jsonb, 'مغطى', 'المعادلة الرمزية تستخدم رموز العناصر وصيغ المركبات مع الحالات الفيزيائية: Al(s) + Br₂(l) → AlBr₃(s)، وC(s) + S(s) → CS₂(l). وتبقى ناقصة لأنها لا توضح أعداد الذرات (الشكل 4-6)، فيُحتاج إلى المعادلة الرمزية الموزونة (ص119). تدريبات: س1–2 وس5 ص118، س18–24، س72–76 ص146–147.', null, 'approved', '2026-10-17'::timestamptz),
(204115, 2041, 'K1-C4-L1-O15', null, 15, 'أن يفسر الطالب أهمية وزن المعادلات الكيميائية في ضوء قانون حفظ الكتلة.', 'أن يفسر الطالب أهمية وزن المعادلات الكيميائية في ضوء قانون حفظ الكتلة.', '[]'::jsonb, 'أن يفسر الطالب أهمية وزن المعادلات الكيميائية في ضوء قانون حفظ الكتلة.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مبادئ وقوانين', '["قانون حفظ الكتلة","المعادلة الموزونة"]'::jsonb, null, '[119,122,149]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ينص قانون حفظ الكتلة على أن المادة لا تفنى ولا تستحدث خلال التغير الكيميائي، لذا يجب أن تظهر المعادلة أعدادًا متساوية من ذرات كل عنصر على جانبي السهم (Al + Br₂ → AlBr₃ غير موزونة، و2Al + 3Br₂ → 2AlBr₃ موزونة، الشكلان 4-6 و4-7). وتحت عنوان «تحقيق قانون حفظ الكتلة» ص122. أسئلة: س9 ص122 (فسّر أهمية وزن المعادلات)، س100 ص149 (حساب كتلة الناتج الآخر من كتل المتفاعلات).', null, 'approved', '2026-10-17'::timestamptz),
(204116, 2041, 'K1-C4-L1-O16', null, 16, 'أن يميز الطالب بين المعامل والرقم السفلي في الصيغة الكيميائية، موضحًا أن وزن المعادلة يتم بتغيير المعاملات فقط.', 'أن يميز الطالب بين المعامل والرقم السفلي في الصيغة الكيميائية، موضحًا أن وزن المعادلة يتم بتغيير المعاملات فقط.', '[]'::jsonb, 'أن يميز الطالب بين المعامل والرقم السفلي في الصيغة الكيميائية، موضحًا أن وزن المعادلة يتم بتغيير المعاملات فقط.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["المعامل","الرقم السفلي","أبسط نسبة عددية"]'::jsonb, null, '[119,120,122]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). المعامل هو العدد الذي يُكتب قبل المادة المتفاعلة أو الناتجة، وهو عادة عدد صحيح ولا يُكتب إذا كان 1، وتُكتب المعاملات في أبسط نسبة عددية صحيحة. وتنص الخطوة 4 على ألا يُغيَّر أبدًا أو يُرقَّم ضمن الصيغة الكيميائية لأن ذلك يغيّر نوع المادة. أسئلة: س14 ص122 (لماذا تُختصر المعاملات إلى أبسط نسبة؟)، س15 ص122 (هل يمكن تعديل الأرقام في الصيغة؟).', null, 'approved', '2026-10-17'::timestamptz),
(204117, 2041, 'K1-C4-L1-O17', null, 17, 'أن يكتب الطالب التوزيع الإلكتروني لبعض الأيونات الموجبة والسالبة.', 'أن يكتب الطالب التوزيع الإلكتروني لبعض الأيونات الموجبة والسالبة.', '[]'::jsonb, 'أن يكتب الطالب التوزيع الإلكتروني لبعض الأيونات الموجبة والسالبة.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'إجراءات ومهارات', '["التوزيع الإلكتروني للأيون","الشحنة"]'::jsonb, null, '[115,151]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). يمكن كتابة التوزيع الإلكتروني للأيون الموجب بتوزيع العدد الذري لذرته المتعادلة مطروحًا منه مقدار الشحنة الموجبة، وللأيون السالب بتوزيع العدد الذري لذرته المتعادلة مضافًا إليه مقدار الشحنة السالبة. سؤال تطبيقي: س13 ص151 (توزيع أيون الفوسفور P³⁻ وكيف يختلف عن ذرة P).', null, 'approved', '2026-10-17'::timestamptz),
(204118, 2041, 'K1-C4-L1-O18', null, 18, 'أن يرتب الطالب مستويات الطاقة الثانوية تصاعديًا بحسب طاقتها عند كتابة التوزيع الإلكتروني.', 'أن يرتب الطالب مستويات الطاقة الثانوية تصاعديًا بحسب طاقتها عند كتابة التوزيع الإلكتروني.', '[]'::jsonb, 'أن يرتب الطالب مستويات الطاقة الثانوية تصاعديًا بحسب طاقتها عند كتابة التوزيع الإلكتروني.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'إجراءات ومهارات', '["تسلسل مستويات الطاقة","تداخل المستويات","4s و3d"]'::jsonb, null, '[113,114,151]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). تتوزع الإلكترونات داخل المستويات الثانوية بدءًا من الأقل طاقة، وقد تتداخل مستويات ثانوية لمستويات رئيسة مختلفة، فطاقة 4s أقل من 3d فيُكتب 4s قبل 3d (الشكل 4-3). ويبيّن الشكل 4-4 ترتيب الملء: 1s 2s 2p 3s 3p 4s 3d 4p 5s 4d 5p 6s 4f… وتعتمد عليه س8–9 ص151 (خيارات تضع 3d قبل 4s).', null, 'approved', '2026-10-17'::timestamptz),
(204119, 2041, 'K1-C4-L1-O19', null, 19, 'أن يميز الطالب بين المتفاعلات والنواتج في المعادلة الكيميائية.', 'أن يميز الطالب بين المتفاعلات والنواتج في المعادلة الكيميائية.', '[]'::jsonb, 'أن يميز الطالب بين المتفاعلات والنواتج في المعادلة الكيميائية.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'حقائق ومصطلحات', '["المتفاعلات","النواتج"]'::jsonb, null, '[117,146]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). المتفاعلات هي المواد الموجودة عند بداية التفاعل، والنواتج هي المواد المتكونة خلال التفاعل؛ وتُكتب المتفاعلات يسار السهم والنواتج يمينه، ويُفصل بين أكثر من متفاعل أو ناتج بإشارة (+). أسئلة: س63 ص146 (وضح الفرق بين المتفاعلات والنواتج)، س68 ص146 (حدد المتفاعلات في تفاعل معطى).', null, 'approved', '2026-10-17'::timestamptz),
(204201, 2042, 'K1-C4-L2-O01', null, 1, 'أن يصنف الطالب التفاعلات الكيميائية', 'أن يصنف الطالب التفاعلات الكيميائية إلى تكوين واحتراق وتفكك وإحلال.', '[]'::jsonb, 'أن يصنف الطالب التفاعلات الكيميائية إلى تكوين واحتراق وتفكك وإحلال.', 'تحديد أنواع التصنيف الأربعة كما يعرضها الدرس ليصبح المطلوب قابلًا للقياس.', 'تحويل إلى هدف قابل للقياس', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["تصنيف التفاعلات","التكوين","الاحتراق","التفكك","الإحلال"]'::jsonb, null, '[123,124,125,126,132,147,150,151]'::jsonb, 'مغطى', 'أنواع التفاعل الأربعة: التكوين، الاحتراق، التفكك، الإحلال. الجدول 4-9 يلخص المواد المتفاعلة والنواتج المتوقعة والمعادلة العامة: تكوين A + B → AB؛ احتراق A + O₂ → AO؛ تفكك AB → A + B؛ إحلال بسيط A + BX → AX + B؛ إحلال مزدوج AX + BY → AY + BX. وقد يندرج تفاعل في أكثر من نوع (H₂ + O₂ → H₂O احتراق وتكوين، أما احتراق CH₄ فليس تكوينًا). أسئلة: س18–21، س37، س77–78، س80–81، واختبار مقنن س4 وس11.', null, 'approved', '2026-10-17'::timestamptz),
(204202, 2042, 'K1-C4-L2-O02', null, 2, 'أن يقارن الطالب بين تفاعلات الإحلال', 'أن يقارن الطالب بين تفاعلي الإحلال البسيط والإحلال المزدوج.', '[]'::jsonb, 'أن يقارن الطالب بين تفاعلي الإحلال البسيط والإحلال المزدوج.', 'تحديد طرفي المقارنة (نوعا الإحلال في الدرس) ليصبح الهدف قابلًا للقياس.', 'تحويل إلى هدف قابل للقياس', 'يعتمد بعد التعديل', 'تحليل', 'مفاهيم', '["الإحلال البسيط","الإحلال المزدوج","تبادل الأيونات"]'::jsonb, null, '[127,130,131,132]'::jsonb, 'مغطى', 'الإحلال البسيط: عنصر يحل محل عنصر آخر في مركب، A + BX → AX + B (مثل 2Li + 2H₂O → 2LiOH + H₂؛ Cu + 2AgNO₃ → Cu(NO₃)₂ + 2Ag). الإحلال المزدوج: تبادل الأيونات بين مركبين، AX + BY → AY + BX، وتبادل الأيونان السالبان موقعيهما وارتبطا بأيونين موجبين مختلفين، وتنتج دائمًا ماء أو راسبًا أو غازًا (Ca(OH)₂ + 2HCl → CaCl₂ + 2H₂O). السؤال 35 ص132 ينص على المقارنة.', null, 'approved', '2026-10-17'::timestamptz),
(204203, 2042, 'K1-C4-L2-O03', null, 3, 'أن يستخدم الطالب سلسلة النشاط الكيميائي في توقع حدوث تفاعلات الإحلال البسيط', 'أن يستخدم الطالب سلسلة النشاط الكيميائي في توقع حدوث تفاعلات الإحلال البسيط.', '[]'::jsonb, 'أن يستخدم الطالب سلسلة النشاط الكيميائي في توقع حدوث تفاعلات الإحلال البسيط.', 'لا تغيير جوهري؛ أضيفت النقطة الختامية.', 'لا تغيير', 'سليم ويعتمد', 'تطبيق', 'إجراءات ومهارات', '["سلسلة النشاط الكيميائي","تفاعل الإحلال البسيط","NR"]'::jsonb, null, '[127,128,129,132,147,148,149,151]'::jsonb, 'مغطى', 'سلسلة النشاط (الشكل 4-15) للفلزات: ليثيوم، روبيديوم، بوتاسيوم، كالسيوم، صوديوم، ماغنسيوم، ألومنيوم، منجنيز، خارصين، حديد، نيكل، قصدير، رصاص، نحاس، فضة، بلاتين، ذهب (من الأنشط إلى الأقل نشاطًا)، وللهالوجينات: فلور، كلور، بروم، يود. يحل الفلز محل أي فلز يقع بعده في السلسلة ولا يحل محل ما قبله (Ag + Cu(NO₃)₂ → NR). المثال 4-2: Fe + CuSO₄ → FeSO₄ + Cu؛ Br₂ + MgCl₂ → NR؛ 3Mg + 2AlCl₃ → 3MgCl₂ + 2Al. لا يظهر الهيدروجين في السلسلة المعروضة. تدريبات: س25–28، س38، س79، س86، س92 (Na وK مع الماء)، س98، س106–107، اختبار مقنن س5.', null, 'approved', '2026-10-17'::timestamptz),
(204204, 2042, 'K1-C4-L2-O04', null, 4, 'أن يستخدم الطالب سلسلة النشاط الكيميائي في المقارنة بين نشاط العناصر', 'أن يستخدم الطالب سلسلة النشاط الكيميائي في المقارنة بين نشاط العناصر.', '[]'::jsonb, 'أن يستخدم الطالب سلسلة النشاط الكيميائي في المقارنة بين نشاط العناصر.', 'لا تغيير جوهري؛ أضيفت النقطة الختامية.', 'لا تغيير', 'سليم ويعتمد', 'تطبيق', 'إجراءات ومهارات', '["نشاط الفلزات","نشاط الهالوجينات"]'::jsonb, null, '[127,128,132,144,147]'::jsonb, 'مغطى', 'النشاط الكيميائي هو قدرة الفلز على التفاعل مع مادة أخرى؛ أنشط الفلزات في أعلى السلسلة (الليثيوم) وأقلها نشاطًا في أسفلها (الذهب). وتُرتَّب الهالوجينات بحسب النشاط: F > Cl > Br > I، فالفلور يحل محل البروم في NaBr ولا يحل البروم محل الفلور في NaF. أسئلة: س34 ص132 (اشرح كيف رُتبت السلسلة)، س79 ص147 (أي فلز يحل محل الآخر)، «تحليل التدرج في الخواص» س1–4 ص128، ومختبر تطوير سلسلة النشاط ص144.', null, 'approved', '2026-10-17'::timestamptz),
(204205, 2042, 'K1-C4-L2-O05', null, 5, 'أن يكتب الطالب معادلات كيميائية موزونة لتفاعلات الإحلال المزدوج', 'أن يكتب الطالب معادلات كيميائية موزونة لتفاعلات الإحلال المزدوج.', '[]'::jsonb, 'أن يكتب الطالب معادلات كيميائية موزونة لتفاعلات الإحلال المزدوج.', 'لا تغيير جوهري؛ أضيفت النقطة الختامية.', 'لا تغيير', 'سليم ويعتمد', 'تطبيق', 'إجراءات ومهارات', '["الإحلال المزدوج","المعادلة الموزونة"]'::jsonb, null, '[130,131,147,148]'::jsonb, 'مغطى', 'الجدول 4-8 يعطي ست خطوات: اكتب صيغ المتفاعلات؛ عيّن الأيونات الموجبة والسالبة في كل مركب؛ اربط كل أيون موجب بالأيون السالب في المركب الآخر؛ اكتب صيغ النواتج بدلالة أعداد التأكسد؛ اكتب المعادلة الكاملة؛ زن المعادلة. مثال: Al(NO₃)₃ + H₂SO₄ → Al₂(SO₄)₃ + HNO₃ ثم 2Al(NO₃)₃ + 3H₂SO₄ → Al₂(SO₄)₃ + 6HNO₃. تدريبات: س29–32 ص131، س75 ص147، س70c، س92c.', null, 'approved', '2026-10-17'::timestamptz),
(204206, 2042, 'K1-C4-L2-O06', null, 6, 'أن يكتب الطالب معادلات رمزية موزونة لتفاعلات التكوين.', 'أن يكتب الطالب معادلات رمزية موزونة لتفاعلات التكوين.', '[]'::jsonb, 'أن يكتب الطالب معادلات رمزية موزونة لتفاعلات التكوين.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'إجراءات ومهارات', '["تفاعل التكوين","A + B → AB"]'::jsonb, null, '[123,125,147]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). تفاعل التكوين تفاعل تتحد فيه مادتان أو أكثر لتكوين مادة واحدة (A + B → AB). وتفاعل عنصرين هو دائمًا تكوين (2Na + Cl₂ → 2NaCl)، ويكون كذلك اتحاد مركبين (CaO + H₂O → Ca(OH)₂) ومركب مع عنصر (2SO₂ + O₂ → 2SO₃). تدريبات: س18–20 ص125، س83 ص147 (بورون + فلور، جرمانيوم + كبريت، كالسيوم + نيتروجين).', null, 'approved', '2026-10-17'::timestamptz),
(204207, 2042, 'K1-C4-L2-O07', null, 7, 'أن يكتب الطالب معادلات رمزية موزونة لتفاعلات الاحتراق.', 'أن يكتب الطالب معادلات رمزية موزونة لتفاعلات الاحتراق.', '[]'::jsonb, 'أن يكتب الطالب معادلات رمزية موزونة لتفاعلات الاحتراق.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'إجراءات ومهارات', '["تفاعل الاحتراق","الأكسجين","الهيدروكربونات"]'::jsonb, null, '[124,125,132,147,151]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). في تفاعل الاحتراق يتحد الأكسجين مع مادة مطلقًا طاقة على شكل حرارة وضوء. أمثلة: C + O₂ → CO₂؛ 2H₂ + O₂ → 2H₂O (احتراق وتكوين معًا). ليس كل احتراق تكوينًا: CH₄ + 2O₂ → CO₂ + 2H₂O ينتج أكثر من مركب؛ والهيدروكربونات (كالميثان والنفط) تحترق منتجة CO₂ وماء وطاقة. الجدول 4-9: نواتج الاحتراق أكاسيد. تدريبات: س82 (الميثانول)، س84 (Ba وB وC₃H₆O وC₈H₁₈)، س76a (البيوتان)، اختبار مقنن س6 (الإيثانول).', null, 'approved', '2026-10-17'::timestamptz),
(204208, 2042, 'K1-C4-L2-O08', null, 8, 'أن يكتب الطالب معادلات رمزية موزونة لتفاعلات التفكك.', 'أن يكتب الطالب معادلات رمزية موزونة لتفاعلات التفكك.', '[]'::jsonb, 'أن يكتب الطالب معادلات رمزية موزونة لتفاعلات التفكك.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'إجراءات ومهارات', '["تفاعل التفكك","AB → A + B"]'::jsonb, null, '[126,147]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). تفاعل التفكك تفاعل يتفكك فيه مركب واحد لإنتاج عنصرين أو أكثر أو مركبات جديدة، وهو عكس التكوين (AB → A + B)، ويحتاج غالبًا إلى طاقة (حرارة أو ضوء أو كهرباء). أمثلة: NH₄NO₃ ⟶(Δ) N₂O + 2H₂O؛ 2NaN₃ → 2Na + 3N₂ (أكياس الهواء في السيارات). تدريبات: س22–24 ص126، س72 ص147 (HI)، س85 ص147 (MgBr₂ وCoO وBaCO₃).', null, 'approved', '2026-10-17'::timestamptz),
(204209, 2042, 'K1-C4-L2-O09', null, 9, 'أن يميز الطالب بين الأنواع الثلاثة لتفاعلات الإحلال البسيط (فلز يحل محل الهيدروجين، وفلز يحل محل فلز، ولافلز يحل محل لافلز).', 'أن يميز الطالب بين الأنواع الثلاثة لتفاعلات الإحلال البسيط (فلز يحل محل الهيدروجين، وفلز يحل محل فلز، ولافلز يحل محل لافلز).', '[]'::jsonb, 'أن يميز الطالب بين الأنواع الثلاثة لتفاعلات الإحلال البسيط (فلز يحل محل الهيدروجين، وفلز يحل محل فلز، ولافلز يحل محل لافلز).', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["الإحلال البسيط","فلز","لافلز","الهالوجينات"]'::jsonb, null, '[127,128]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). يعرض الكتاب ثلاثة أنواع: فلز يحل محل الهيدروجين (2Li + 2H₂O → 2LiOH + H₂)، وفلز يحل محل فلز آخر في مركب مذاب في الماء (Cu + 2AgNO₃ → Cu(NO₃)₂ + 2Ag)، ولافلز يحل محل لافلز كما في الهالوجينات (F₂ + 2NaBr → 2NaF + Br₂، أما Br₂ + NaF فلا تتفاعل).', null, 'approved', '2026-10-17'::timestamptz),
(204210, 2042, 'K1-C4-L2-O10', null, 10, 'أن يرتب الطالب مجموعة من الفلزات بحسب نشاطها اعتمادًا على نتائج تفاعلها مع محاليل أملاح فلزات أخرى.', 'أن يرتب الطالب مجموعة من الفلزات بحسب نشاطها اعتمادًا على نتائج تفاعلها مع محاليل أملاح فلزات أخرى.', '[]'::jsonb, 'أن يرتب الطالب مجموعة من الفلزات بحسب نشاطها اعتمادًا على نتائج تفاعلها مع محاليل أملاح فلزات أخرى.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تحليل', 'إجراءات ومهارات', '["سلسلة النشاط","التجربة العملية","ملاحظة التفاعل"]'::jsonb, null, '[132,144]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). مختبر الكيمياء ص144: تُوضع قطع من الألومنيوم والماغنسيوم والخارصين والنحاس في محاليل نترات الألومنيوم والماغنسيوم والخارصين والنحاس (1.0M) في طبق تفاعلات، ويُلاحَظ أين يحدث تفاعل لترتيب الفلزات من الأكثر نشاطًا إلى الأقل، ثم تُقارَن النتيجة بالشكل 4-15 وتُكتب معادلة لكل تفاعل إحلال. ويدعمه س34 ص132.', null, 'approved', '2026-10-17'::timestamptz),
(204301, 2043, 'K1-C4-L3-O01', null, 1, 'ان يصف الطالب المحاليل المائية', 'أن يصف الطالب المحاليل المائية.', '[]'::jsonb, 'أن يصف الطالب المحاليل المائية.', 'تصحيح همزة «أن» (كُتبت «ان» في الأصل).', 'إملائي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["المحلول المائي","المذاب","المذيب"]'::jsonb, null, '[133,142,148]'::jsonb, 'مغطى', 'المحلول المائي محلول يحتوي على مادة أو أكثر مذابة في الماء؛ المادة المذابة هي المذاب، والماء (أكبر مكونات المحلول) هو المذيب دائمًا في المحاليل المائية، أما المواد التي قد تذوب فيه فكثيرة. مثال: مسحوق نكهة الليمون. أسئلة: س55 ص142 (صف المذيب والمذاب)، س87 ص148 (مذاب + مذيب).', null, 'approved', '2026-10-17'::timestamptz),
(204302, 2043, 'K1-C4-L3-O02', null, 2, 'أن يصف الطالب ما يحدث للمركبات الجزيئية و الأيونية عندما تذوب في الماء', 'أن يصف الطالب ما يحدث للمركبات الجزيئية والأيونية عندما تذوب في الماء.', '[]'::jsonb, 'أن يصف الطالب ما يحدث للمركبات الجزيئية والأيونية عندما تذوب في الماء.', 'لا تغيير جوهري؛ أضيفت النقطة الختامية.', 'لا تغيير', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["المركب الجزيئي","المركب الأيوني","التأين","التفكك"]'::jsonb, null, '[133,134,142,148]'::jsonb, 'مغطى', 'بعض المركبات الجزيئية تذوب على شكل جزيئات (السكروز والإيثانول)، وبعضها يكوّن أيونات عند ذوبانه كتأين HCl → H⁺ + Cl⁻ (الشكل 4-18)، وتسمى المركبات التي تنتج أيونات هيدروجين أحماضًا. أما المركبات الأيونية فعند ذوبانها تنفصل أيوناتها عن بعض وتسمى العملية التفكك (NaCl يعطي Na⁺ وCl⁻؛ الشكل 4-19). س96 ص148 (ميّز مركبًا أيونيًّا من مركب تساهمي، وهل تتأين التساهمية جميعها؟).', null, 'approved', '2026-10-17'::timestamptz),
(204303, 2043, 'K1-C4-L3-O03', null, 3, 'أن يقارن الطالب بين المعادلات الأيونية الكاملة و المعادلات الأيونية النهائية', 'أن يقارن الطالب بين المعادلات الأيونية الكاملة والمعادلات الأيونية النهائية.', '[]'::jsonb, 'أن يقارن الطالب بين المعادلات الأيونية الكاملة والمعادلات الأيونية النهائية.', 'لا تغيير جوهري؛ أضيفت النقطة الختامية.', 'لا تغيير', 'سليم ويعتمد', 'تحليل', 'مفاهيم', '["المعادلة الأيونية الكاملة","المعادلة الأيونية النهائية","الأيونات المتفرجة"]'::jsonb, null, '[135,137,142,148]'::jsonb, 'مغطى', 'المعادلة الأيونية الكاملة تبين الجسيمات في المحلول (تُكتب المواد الذائبة على شكل أيونات) ومنها أيونات متفرجة ظاهرة على الطرفين؛ وبشطب الأيونات المتفرجة تُحصل المعادلة الأيونية النهائية التي تشتمل على الجسيمات المشاركة في التفاعل فقط، مثل 2OH⁻ + Cu²⁺ → Cu(OH)₂(s). أسئلة: «ماذا قرأت؟» ص135، س56 ص142، س89–90 ص148.', null, 'approved', '2026-10-17'::timestamptz),
(204304, 2043, 'K1-C4-L3-O04', null, 4, 'أن يكتب الطالب معادلات أيونية كاملة و معادلات أيونية نهائية للتفاعلات في المحاليل المائية', 'أن يكتب الطالب معادلات أيونية كاملة ومعادلات أيونية نهائية للتفاعلات في المحاليل المائية.', '[]'::jsonb, 'أن يكتب الطالب معادلات أيونية كاملة ومعادلات أيونية نهائية للتفاعلات في المحاليل المائية.', 'لا تغيير جوهري؛ أضيفت النقطة الختامية.', 'لا تغيير', 'سليم ويعتمد', 'تطبيق', 'إجراءات ومهارات', '["المعادلة الأيونية الكاملة","المعادلة الأيونية النهائية"]'::jsonb, null, '[135,136,137,138,139,140,141,142,148,149]'::jsonb, 'مغطى', 'الطريقة: اكتب المعادلة الرمزية الموزونة؛ اكتب المواد الأيونية الذائبة (aq) على شكل أيونات وأبقِ الصلب والسائل والغاز بصيغها؛ احذف الأيونات المتفرجة؛ اكتب النهائية بأبسط نسبة صحيحة. أمثلة محلولة: 4-3 (Ba²⁺ + CO₃²⁻ → BaCO₃(s))، 4-4 (H⁺ + OH⁻ → H₂O)، 4-5 (2H⁺ + S²⁻ → H₂S(g))، وHCl + NaHCO₃ ص140. تدريبات: س39–53، س57، س60 ص142، س93 ص148، س99 ص149، وتجربة NaOH مع MgSO₄ ص135.', null, 'approved', '2026-10-17'::timestamptz),
(204305, 2043, 'K1-C4-L3-O05', null, 5, 'أن يتوقع الطالب ما إذاكانت التفاعلات في المحاليل المائية ستؤدي إلى راسب أو ماء أو غاز', 'أن يتوقع الطالب ما إذا كانت التفاعلات في المحاليل المائية ستؤدي إلى راسب أو ماء أو غاز.', '[]'::jsonb, 'أن يتوقع الطالب ما إذا كانت التفاعلات في المحاليل المائية ستؤدي إلى راسب أو ماء أو غاز.', 'تصحيح «إذاكانت» إلى «إذا كانت».', 'إملائي', 'يعتمد بعد التعديل', 'تطبيق', 'مبادئ وقوانين', '["راسب","ماء","غاز","قواعد الذائبية","NR"]'::jsonb, null, '[134,136,137,139,140,142,148,149,150]'::jsonb, 'مغطى جزئيًا', 'يعرض الكتاب أن الإحلال المزدوج في المحاليل ينتج راسبًا (2NaOH + CuCl₂ → Cu(OH)₂(s) + 2NaCl)، أو ماءً (HBr + NaOH → H₂O + NaBr)، أو غازًا (H₂S وCO₂ وHCN، مثل 2HI + Li₂S → H₂S + 2LiI). لكن الدروس لا تضع قاعدة عامة لتوقع تكوّن الراسب؛ تعطي أسئلة التقويم معلومات الترسب في نصها (س94 ص148، س99 ص149، وأمثلة الاختبار ص150)، وتظهر قواعد الذائبية فقط في الجدول 4-11 ضمن «التقويم الإضافي» ص149 (س105–107). س59 ص142 يطلب تحديد نوع الناتج.', null, 'approved', '2026-10-17'::timestamptz),
(204306, 2043, 'K1-C4-L3-O06', null, 6, 'أن يحدد الطالب الأيونات المتفرجة في المعادلة الكيميائية', 'أن يحدد الطالب الأيونات المتفرجة في المعادلة الأيونية الكاملة.', '[]'::jsonb, 'أن يحدد الطالب الأيونات المتفرجة في المعادلة الأيونية الكاملة.', 'الأيونات المتفرجة لا تظهر إلا في المعادلة الأيونية الكاملة لا في المعادلة الكيميائية الرمزية؛ لذا حُدّد المطلوب.', 'صياغة', 'يعتمد بعد التعديل', 'تطبيق', 'مفاهيم', '["الأيونات المتفرجة","المعادلة الأيونية الكاملة"]'::jsonb, null, '[135,137,138,148]'::jsonb, 'مغطى', 'الأيونات المتفرجة مواد متفاعلة وناتجة في الوقت نفسه (لم تشارك في التفاعل) وتظهر على جانبي المعادلة الأيونية الكاملة: Na⁺ وCl⁻ في NaOH + CuCl₂ ص135، وNa⁺ وBr⁻ في HBr + NaOH ص137 (سؤال «ماذا قرأت؟»)، وCl⁻ وLi⁺ في مثال 4-4. س91 ص148 (ما المقصود بالأيون المتفرج؟) وخطوة 3 في تجربة ص135.', null, 'approved', '2026-10-17'::timestamptz),
(204307, 2043, 'K1-C4-L3-O07', null, 7, 'أن يوضح الطالب تكوّن غاز ثاني أكسيد الكربون من تفاعل حمض مع بيكربونات الصوديوم الهيدروجينية بوصفه إحلالًا مزدوجًا يتبعه تفكك.', 'أن يوضح الطالب تكوّن غاز ثاني أكسيد الكربون من تفاعل حمض مع بيكربونات الصوديوم الهيدروجينية بوصفه إحلالًا مزدوجًا يتبعه تفكك.', '[]'::jsonb, 'أن يوضح الطالب تكوّن غاز ثاني أكسيد الكربون من تفاعل حمض مع بيكربونات الصوديوم الهيدروجينية بوصفه إحلالًا مزدوجًا يتبعه تفكك.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["H₂CO₃","تفاعلان متزامنان","المعادلة الكلية","CO₂"]'::jsonb, null, '[139,140,142]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). عند خلط الخل بصودا الخبز يتصاعد CO₂. يحدث تفاعلان متزامنان: إحلال مزدوج HCl + NaHCO₃ → H₂CO₃ + NaCl، ثم تفكك فوري H₂CO₃ → H₂O + CO₂؛ ويُجمعان في معادلة كلية تُحذف منها H₂CO₃: HCl + NaHCO₃ → H₂O + CO₂ + NaCl، والنهائية H⁺ + HCO₃⁻ → H₂O + CO₂. ويرتبط بتفاعل H⁺ مع HCO₃⁻ في الرئتين (الشكل 4-22). أسئلة: س58 وس60 ص142، س57.', null, 'approved', '2026-10-17'::timestamptz),
(205101, 2051, 'K1-C5-L1-O01', null, 1, 'أن يعرف الطالب المول', 'أن يعرّف الطالب المول.', '[]'::jsonb, 'أن يعرّف الطالب المول.', 'ضبط الفعل «يعرّف» بالشدة لرفع اللبس مع «يعرِف»، وإضافة النقطة الختامية.', 'إملائي', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["المول","وحدة النظام الدولي لكمية المادة","الكربون-12"]'::jsonb, null, '[154,155,159]'::jsonb, 'مغطى', 'المول وحدة النظام الدولي الأساسية لقياس كمية المادة، ويعرَّف بأنه عدد ذرات الكربون-12 في عينة كتلتها 12 g من الكربون-12. والمول الواحد من أي مادة يحتوي على 6.02 × 10^23 من الجسيمات الممثلة (ذرات أو جزيئات أو أيونات أو وحدات صيغة). ويرد في المفردات الجديدة وخلاصة الدرس.', null, 'approved', '2026-10-17'::timestamptz),
(205102, 2051, 'K1-C5-L1-O02', null, 2, 'أن يذكر الطالب أمثلة لمبدأ المول في التعاملات اليومية', 'أن يذكر الطالب أمثلة لوحدات عدّ يومية (كالدرزن والزوج والرزمة) تشبه المول.', '[]'::jsonb, 'أن يذكر الطالب أمثلة لوحدات عدّ يومية (كالدرزن والزوج والرزمة) تشبه المول.', 'تحديد المطلوب: الكتاب لا يعرض تطبيقات يومية للمول نفسه بل يشبّهه بوحدات العدّ المألوفة.', 'تحويل إلى هدف قابل للقياس', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["وحدات العد","الدرزن","الزوج","الرزمة","المول"]'::jsonb, null, '[153,154,156,159]'::jsonb, 'مغطى', 'يبيّن الكتاب أن الزوج = 2 والدرزن = 12 والرزمة = 500 ورقة، وأن العدد الذي تمثله الوحدة ثابت أيًّا كان نوع الشيء (الشكل 1-5). ويستعمل الدرزن عامل تحويل (1 درزن = 12 وردة، 3.5 درزن = 42 وردة)، ويسأل في التقويم 5-1 (س10): «فسّر وجه الشبه بين المول والدرزن». لا يذكر الكتاب تطبيقات يومية للمول ذاته.', null, 'approved', '2026-10-17'::timestamptz),
(205103, 2051, 'K1-C5-L1-O03', null, 3, 'أن يعرف الطالب عدد أفوجادرو', 'أن يعرّف الطالب عدد أفوجادرو.', '[]'::jsonb, 'أن يعرّف الطالب عدد أفوجادرو.', 'ضبط الفعل «يعرّف» بالشدة، وإضافة النقطة الختامية.', 'إملائي', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["عدد أفوجادرو","6.02 × 10^23","أميديو أفوجادرو"]'::jsonb, null, '[155,156,159]'::jsonb, 'مغطى', 'عدد أفوجادرو هو عدد الجسيمات الممثلة في مول واحد من أي مادة: 6.0221367 × 10^23 (يُقرَّب في المسائل إلى 6.02 × 10^23)، سُمّي تكريمًا للفيزيائي الإيطالي أميديو أفوجادرو الذي حدّد عام 1811م حجم مول من الغاز. ويُستعمل عاملَ تحويل (6.02×10^23 جسيم / 1 mol) ومقلوبه. وفي التقويم س83 يُسأل عن قيمته العددية.', null, 'approved', '2026-10-17'::timestamptz),
(205104, 2051, 'K1-C5-L1-O04', null, 4, 'أن يحل الطالب مسائل على تحويل المولات إلى جسيمات والعكس', 'أن يحل الطالب مسائل على تحويل المولات إلى جسيمات وتحويل الجسيمات إلى مولات.', '[]'::jsonb, 'أن يحل الطالب مسائل على تحويل المولات إلى جسيمات وتحويل الجسيمات إلى مولات.', 'استبدال «والعكس» بتصريح المطلوب ليكون الهدف أوضح وقابلًا للقياس.', 'صياغة', 'يعتمد بعد التعديل', 'تطبيق', 'حل مسائل', '["التحويل بين المولات والجسيمات","عامل التحويل","عدد أفوجادرو","الجسيمات الممثلة"]'::jsonb, null, '[156,157,158,159,180]'::jsonb, 'مغطى', 'يعرض الكتاب القانونين: عدد الجسيمات = عدد المولات × (6.02×10^23 جسيم / 1 mol)، وعدد المولات = عدد الجسيمات × (1 mol / 6.02×10^23 جسيم). أمثلة: 3.5 mol سكروز = 2.11×10^24 جزيء، و4.50×10^24 ذرة Cu = 7.48 mol (مثال 5-1 بخطواته الثلاث: تحليل، حساب، تقويم). وتتضمن المسائل التدريبية 1–6 وأسئلة التقويم 12 و13 و87–91 مسائل مشابهة (ذرات، جزيئات، وحدات صيغة).', null, 'approved', '2026-10-17'::timestamptz),
(205105, 2051, 'K1-C5-L1-O05', null, 5, 'أن يحدد الطالب الجسيم الممثل (ذرة، جزيء، أيون، وحدة صيغة) في مادة ما.', 'أن يحدد الطالب الجسيم الممثل (ذرة، جزيء، أيون، وحدة صيغة) في مادة ما.', '[]'::jsonb, 'أن يحدد الطالب الجسيم الممثل (ذرة، جزيء، أيون، وحدة صيغة) في مادة ما.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'مفاهيم', '["الجسيمات الممثلة","الذرة","الجزيء","الأيون","وحدة الصيغة"]'::jsonb, null, '[155,159,167]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). الجسيم الممثل هو وحدة البناء المكوّنة للمادة: ذرات النحاس Cu، وجزيئات الماء H2O والسكروز، ووحدات الصيغة في كلوريد الصوديوم NaCl (الشكل 2-5، الشكل 4-5). وتنص الخلاصة على أن الجسيمات الممثلة تشمل الذرات والأيونات والجزيئات ووحدات الصيغة. التقويم س12 يطلب حساب عدد الجسيمات الممثلة لمواد متنوعة.', null, 'approved', '2026-10-17'::timestamptz),
(205106, 2051, 'K1-C5-L1-O06', null, 6, 'أن يفسّر الطالب سبب استخدام الكيميائيين وحدة المول في عدّ جسيمات المادة.', 'أن يفسّر الطالب سبب استخدام الكيميائيين وحدة المول في عدّ جسيمات المادة.', '[]'::jsonb, 'أن يفسّر الطالب سبب استخدام الكيميائيين وحدة المول في عدّ جسيمات المادة.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["المول","عدّ غير مباشر","حجم الذرة","عدد أفوجادرو"]'::jsonb, null, '[154,155,159,180]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). الذرات متناهية الصغر وكثيرة جدًّا حتى في العينات الصغيرة فعدّها مباشرة مستحيل، فابتُكرت وحدة المول لعدّها بطريقة غير مباشرة. وعدد أفوجادرو هائل يناسب الجسيمات الدقيقة ولا يناسب الأجسام الكبيرة (مثال: كرات زجاجية بعدد أفوجادرو تغطي سطح الأرض بعمق يتجاوز ستة كيلومترات). هذا موضوع التقويم س7 («فسّر لماذا يستخدم الكيميائيون المول؟») وس85.', null, 'approved', '2026-10-17'::timestamptz),
(205201, 2052, 'K1-C5-L2-O01', null, 1, 'أن يعرف الطالب الكتلة المولية', 'أن يعرّف الطالب الكتلة المولية.', '[]'::jsonb, 'أن يعرّف الطالب الكتلة المولية.', 'ضبط الفعل «يعرّف» بالشدة، وإضافة النقطة الختامية.', 'إملائي', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["الكتلة المولية","g/mol","الكتلة الذرية","amu"]'::jsonb, null, '[161,167,178]'::jsonb, 'مغطى', 'الكتلة المولية هي الكتلة بالجرامات لمول واحد من أي مادة نقية، ووحدتها g/mol، وهي عدديًّا تساوي الكتلة الذرية للعنصر (مثال: الحديد 55.845 amu فكتلته المولية 55.845 g/mol)، وتساوي كتلة عدد أفوجادرو من جسيمات المادة. ويبيّن الكتاب أن كتلة 1 mol من C-12 هي 12 g.', null, 'approved', '2026-10-17'::timestamptz),
(205202, 2052, 'K1-C5-L2-O02', null, 2, 'أن يحل الطالب مسائل على تحويل المولات إلى كتلة والعكس', 'أن يحل الطالب مسائل على تحويل المولات إلى كتلة وتحويل الكتلة إلى مولات.', '[]'::jsonb, 'أن يحل الطالب مسائل على تحويل المولات إلى كتلة وتحويل الكتلة إلى مولات.', 'استبدال «والعكس» بتصريح المطلوب.', 'صياغة', 'يعتمد بعد التعديل', 'تطبيق', 'حل مسائل', '["التحويل بين المولات والكتلة","الكتلة المولية","عامل التحويل"]'::jsonb, null, '[162,163,164,167,180]'::jsonb, 'مغطى', 'الكتلة (g) = عدد المولات × (الكتلة المولية / 1 mol)، ويُستعمل مقلوب الكتلة المولية للتحويل من الكتلة إلى مولات. أمثلة: 3.00 mol Cu = 191 g (63.546 g/mol)، 0.0450 mol Cr = 2.34 g (مثال 5-2)، 525 g Ca = 13.1 mol (مثال 5-3). ويعلّم الكتاب خطوة «تقويم الإجابة» بالتقدير (أقل من 0.1 أو أكبر من 10 mol). مسائل تدريبية 14–17 وتقويم 97–99 و101.', null, 'approved', '2026-10-17'::timestamptz),
(205203, 2052, 'K1-C5-L2-O03', null, 3, 'أن يحل الطالب مسائل على تحويل الجسيمات إلى الكتلة والعكس', 'أن يحل الطالب مسائل على تحويل عدد الجسيمات إلى كتلة وتحويل الكتلة إلى عدد جسيمات.', '[]'::jsonb, 'أن يحل الطالب مسائل على تحويل عدد الجسيمات إلى كتلة وتحويل الكتلة إلى عدد جسيمات.', 'استبدال «والعكس» بتصريح المطلوب وتحديد «عدد» الجسيمات.', 'صياغة', 'يعتمد بعد التعديل', 'تطبيق', 'حل مسائل', '["التحويل بين الكتلة وعدد الجسيمات","المول وسيطًا","الكتلة المولية","عدد أفوجادرو"]'::jsonb, null, '[165,166,167,181]'::jsonb, 'مغطى', 'لا يوجد تحويل مباشر بين الكتلة وعدد الجسيمات؛ يمر دائمًا عبر المولات (خطوتان). مثال 5-4: 31.1 g Au = 0.158 mol = 9.51×10^22 ذرة؛ مثال 5-5: 5.50×10^22 ذرة He = 0.0914 mol = 0.366 g. ويبيّن الشكل 8-5 ودمج الخطوتين في معادلة واحدة: 1.00 g O2 = 1.88×10^22 جزيء. مسائل 18–20 وتقويم 101 و102 و104.', null, 'approved', '2026-10-17'::timestamptz),
(205204, 2052, 'K1-C5-L2-O04', null, 4, 'أن يميز الطالب بين الكتلة الذرية (amu) والكتلة المولية (g/mol) للعنصر.', 'أن يميز الطالب بين الكتلة الذرية (amu) والكتلة المولية (g/mol) للعنصر.', '[]'::jsonb, 'أن يميز الطالب بين الكتلة الذرية (amu) والكتلة المولية (g/mol) للعنصر.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["الكتلة الذرية","الكتلة المولية","amu","g/mol"]'::jsonb, null, '[161,162,167,180]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). الكتلة المولية للعنصر تساوي عدديًّا كتلته الذرية لكن بوحدة g/mol بدل amu (Fe: 55.845 amu ↔ 55.845 g/mol). والكتلة الذرية تخص ذرة واحدة، والكتلة المولية تخص عدد أفوجادرو من الذرات؛ ويُسأل ذلك في التقويم س23 و92. ويحسب الطالب من النواة كتلة ذرة الكربون-12 بالوحدتين (مختبر حل المشكلات، ص161).', null, 'approved', '2026-10-17'::timestamptz),
(205205, 2052, 'K1-C5-L2-O05', null, 5, 'أن يقارن الطالب بين مولات مواد مختلفة من حيث عدد الجسيمات والكتلة.', 'أن يقارن الطالب بين مولات مواد مختلفة من حيث عدد الجسيمات والكتلة.', '[]'::jsonb, 'أن يقارن الطالب بين مولات مواد مختلفة من حيث عدد الجسيمات والكتلة.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تحليل', 'مفاهيم', '["المول","عدد الجسيمات","الكتلة المولية","المقارنة"]'::jsonb, null, '[160,161,167,180,181]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). المول من أي مادة يحتوي العدد نفسه من الجسيمات لكن كتلته تختلف باختلاف المادة (الفكرة الرئيسة للدرس): مول الفضة ومول الذهب فيهما العدد نفسه من الذرات، أما مول البوتاسيوم فكتلته أكبر من مول الصوديوم. أسئلة التقويم س21 و93 و94 و104 و105 تطلب المقارنة وتفسيرها، وس26 و103 ترتيب كميات بحسب الكتلة أو عدد المولات.', null, 'approved', '2026-10-17'::timestamptz),
(205206, 2052, 'K1-C5-L2-O06', null, 6, 'أن يقدّر الطالب أعدادًا كبيرة من الجسيمات (كعدد جزيئات الماء في كأس) باستخدام التحويلات المولية.', 'أن يقدّر الطالب أعدادًا كبيرة من الجسيمات (كعدد جزيئات الماء في كأس) باستخدام التحويلات المولية.', '[]'::jsonb, 'أن يقدّر الطالب أعدادًا كبيرة من الجسيمات (كعدد جزيئات الماء في كأس) باستخدام التحويلات المولية.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'إجراءات ومهارات', '["تقدير","عدد جزيئات الماء","المول","أعداد كبيرة"]'::jsonb, null, '[176,177]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). يحسب الكتاب أن كأس ماء كتلته 230 g يحوي 13 mol ≈ 8×10^24 جزيء، وأن عدد الكؤوس على الأرض نحو 6×10^21، فعدد الجزيئات في الكأس أكبر ألف مرة من عدد الكؤوس، فيحتمل أن يحوي أي كأس بعض جزيئات ماء مرّت بشخصيات تاريخية. وعبارة «الكتابة في الكيمياء» تطلب استخدام طريقة التقدير لمسألة أخرى.', null, 'approved', '2026-10-17'::timestamptz),
(205301, 2053, 'K1-C5-L3-O01', null, 1, 'أن يحل الطالب مسائل على علاقات المول المرتبطة بالصيغة الكيميائية', 'أن يحل الطالب مسائل على علاقات المول المرتبطة بالصيغة الكيميائية.', '[]'::jsonb, 'أن يحل الطالب مسائل على علاقات المول المرتبطة بالصيغة الكيميائية.', 'الصياغة سليمة؛ أضيفت النقطة الختامية فقط.', 'لا تغيير', 'سليم ويعتمد', 'تطبيق', 'حل مسائل', '["الصيغة الكيميائية","مولات العناصر في مول المركب","عامل التحويل من الصيغة"]'::jsonb, null, '[168,169,170,175,182]'::jsonb, 'مغطى', 'الأرقام السفلية في الصيغة تدل على عدد مولات كل عنصر في مول واحد من المركب، فتُكتب عوامل تحويل مثل (2 mol F / 1 mol CCl2F2). أمثلة: 5.50 mol CCl2F2 تحتوي 11.0 mol F؛ 1.25 mol Al2O3 تحتوي 2.5 mol Al³⁺ (مثال 5-6). مسائل 29–33 وتقويم 50 و108 و112 و113.', null, 'approved', '2026-10-17'::timestamptz),
(205302, 2053, 'K1-C5-L3-O02', null, 2, 'أن يحسب الطالب الكتلة المولية لمركب', 'أن يحسب الطالب الكتلة المولية لمركب.', '[]'::jsonb, 'أن يحسب الطالب الكتلة المولية لمركب.', 'الصياغة سليمة؛ أضيفت النقطة الختامية فقط.', 'لا تغيير', 'سليم ويعتمد', 'تطبيق', 'إجراءات ومهارات', '["الكتلة المولية للمركب","مجموع الكتل المولية للعناصر"]'::jsonb, null, '[170,171,172,175,182]'::jsonb, 'مغطى', 'الكتلة المولية للمركب = مجموع (عدد مولات كل عنصر × كتلته المولية). أمثلة: K2CrO4 = 78.20 + 52.0 + 64.0 = 194.20 g/mol؛ (C3H5)2S = 114.21 g/mol؛ Ca(OH)2 = 74.10 g/mol؛ AlCl3 = 133.33 g/mol. يصنَّف المركب جزيئيًّا أو أيونيًّا في بعض المسائل (س36). مسائل 34–36 و51 و114.', null, 'approved', '2026-10-17'::timestamptz),
(205303, 2053, 'K1-C5-L3-O03', null, 3, 'أن يحل الطالب مسائل على تحويل كتلة مركب إلى عدد جسيمات', 'أن يحل الطالب مسائل على تحويل كتلة مركب إلى عدد جسيمات.', '[]'::jsonb, 'أن يحل الطالب مسائل على تحويل كتلة مركب إلى عدد جسيمات.', 'الصياغة سليمة؛ أضيفت النقطة الختامية فقط.', 'لا تغيير', 'سليم ويعتمد', 'تطبيق', 'حل مسائل', '["كتلة المركب","المولات","عدد الجسيمات","الذرات والأيونات في المركب"]'::jsonb, null, '[173,174,175,182]'::jsonb, 'مغطى', 'تُحوَّل الكتلة إلى مولات بمقلوب الكتلة المولية، ثم إلى وحدات صيغة بعدد أفوجادرو، ثم تُحسب الذرات أو الأيونات بنسبتها في الصيغة. مثال 5-9: 35.6 g AlCl3 = 0.267 mol = 1.61×10^23 وحدة صيغة، أي 1.61×10^23 أيون Al³⁺ و4.83×10^23 أيون Cl⁻، وكتلة وحدة الصيغة 2.21×10^-22 g. مسائل 42–46 وتقويم 117 و118 و121.', null, 'approved', '2026-10-17'::timestamptz),
(205304, 2053, 'K1-C5-L3-O04', null, 4, 'أن يحل الطالب مسائل على تحويل مولات المركب إلى كتلة وتحويل كتلة المركب إلى مولات.', 'أن يحل الطالب مسائل على تحويل مولات المركب إلى كتلة وتحويل كتلة المركب إلى مولات.', '[]'::jsonb, 'أن يحل الطالب مسائل على تحويل مولات المركب إلى كتلة وتحويل كتلة المركب إلى مولات.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'حل مسائل', '["مولات المركب","كتلة المركب","الكتلة المولية","عامل التحويل"]'::jsonb, null, '[171,172,175,182]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). تُحسب الكتلة المولية للمركب أولًا ثم تُستعمل عامل تحويل. مثال 5-7: 2.50 mol من (C3H5)2S = 286 g؛ مثال 5-8: 325 g من Ca(OH)2 = 4.39 mol، مع تحقق بالتقريب (74.10 ≈ 75 g/mol). مسائل 37–41 وتقويم 115 و116 و119. ولا يغطيه أي هدف رسمي في L3 سوى كتلة المركب إلى جسيمات.', null, 'approved', '2026-10-17'::timestamptz),
(205305, 2053, 'K1-C5-L3-O05', null, 5, 'أن يصنف الطالب المركب إلى جزيئي أو أيوني قبل حساب كتلته المولية أو عدد جسيماته.', 'أن يصنف الطالب المركب إلى جزيئي أو أيوني قبل حساب كتلته المولية أو عدد جسيماته.', '[]'::jsonb, 'أن يصنف الطالب المركب إلى جزيئي أو أيوني قبل حساب كتلته المولية أو عدد جسيماته.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تحليل', 'مفاهيم', '["مركب جزيئي","مركب أيوني","وحدة الصيغة","الجزيء"]'::jsonb, null, '[170,171,172,173,174]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). يطلب س36 (ص170) تصنيف كل مركب جزيئيًّا أو أيونيًّا ثم حساب كتلته المولية (Sr(NO3)2 و(NH4)3PO4 والسكروز)، وس41 (ص172) تصنيفه إلى أيوني أو جزيئي قبل التحويل إلى مولات. والجسيم الممثل في المركب الأيوني وحدة الصيغة (AlCl3) وفي الجزيئي الجزيء (CO2، C2H5OH).', null, 'approved', '2026-10-17'::timestamptz),
(205306, 2053, 'K1-C5-L3-O06', null, 6, 'أن يفسّر الطالب كون الكتلة المولية للمركب مجموع الكتل المولية لعناصره بدلالة قانون حفظ الكتلة.', 'أن يفسّر الطالب كون الكتلة المولية للمركب مجموع الكتل المولية لعناصره بدلالة قانون حفظ الكتلة.', '[]'::jsonb, 'أن يفسّر الطالب كون الكتلة المولية للمركب مجموع الكتل المولية لعناصره بدلالة قانون حفظ الكتلة.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مبادئ وقوانين', '["الكتلة المولية للمركب","قانون حفظ الكتلة"]'::jsonb, null, '[170]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). يذكر الكتاب أن الكتلة المولية للمركب توضح قانون حفظ الكتلة؛ فكتلة المتفاعلات تساوي كتلة المركب الناتج. ويوضح الشكل 10-5 كتلًا متكافئة لمول من K2CrO4 وNaCl والسكروز، وأن الكتلة المولية لكل مركب تختلف لاختلاف أعداد الذرات وأنواعها.', null, 'approved', '2026-10-17'::timestamptz)
on conflict do nothing;

insert into public.supplements (objective_id, memo_basis, supplement, key_points, misconceptions, scientific_notes, confidence) values
(201305, 'الكتاب يذكر أن التجربة تعطي بيانات يحللها العلماء ويقارنونها بالفرضية للتوصل إلى استنتاج، وأن البيانات لا تثبت الفرضية بل تؤيدها أو لا تدعمها (ص25)، لكنه لا يعرّف «النتائج» ولا يحدد الهدف منها.', 'النتائج هي ما تسفر عنه التجربة بعد تنفيذها، مثل القياسات والملاحظات المسجلة في جداول أو رسوم بيانية. والهدف منها اختبار الفرضية؛ إذ تحلل النتائج وتقارن بما توقعته الفرضية. فإذا جاءت متفقة مع التوقع دعمت الفرضية، وقد تتكرر التجارب مرات عديدة لزيادة الثقة، لكنها لا تثبتها إثباتًا قاطعًا. وإذا خالفت التوقع رُفضت الفرضية أو عُدّلت. ثم يكتب الطالب استنتاجًا مبنيًا على النتائج. ولكي تكون النتائج موثوقة تُضبط المتغيرات، ويبقى العامل الثابت دون تغيير، ويُغيَّر المتغير المستقل وحده، ويُقاس المتغير التابع، وتُسجل النتائج بدقة ليتمكن غيرك من تكرار التجربة. مثال: قياس زمن ذوبان كمية الملح نفسها في ماء عند 20°C وعند 40°C؛ فإذا ذابت أسرع عند 40°C دعمت النتيجة فرضية أن ارتفاع الحرارة يزيد سرعة الذوبان.', '["النتائج بيانات مسجلة (كمية ونوعية) تنتج من تنفيذ التجربة.","تستعمل النتائج لاختبار الفرضية بمقارنتها بالتوقع.","البيانات تدعم الفرضية أو لا تدعمها ولا تثبتها نهائيًا.","الاستنتاج حكم قائم على النتائج."]'::jsonb, '["أن النتائج تثبت الفرضية إثباتًا نهائيًا.","أن النتائج والاستنتاج شيء واحد.","أن النتيجة التي تخالف الفرضية تعني فشل التجربة."]'::jsonb, 'يتبنى الكتاب مصطلح «الاستنتاج» ولا يستعمل «النتائج» مصطلحًا مستقلًا؛ لذلك يُقترح ربط الهدف بهما معًا.', 'متوسطة'),
(202101, 'الكتاب يذكر أن الماء النقي مادة كيميائية نقية مكونة من الهيدروجين والأكسجين، وأن ماء الشرب وماء البحر ليسا نقيين لاحتوائهما كميات مختلفة من المعادن والمواد الذائبة، دون مقارنة تفصيلية بين الماءين (ص44).', 'الماء النقي مادة كيميائية نقية ذات تركيب ثابت: كل جزيء منه مكوّن من ذرتي هيدروجين وذرة أكسجين (H₂O)، وله خواص فيزيائية مميزة ثابتة عند الظروف القياسية، فيتجمد عند 0°C ويغلي عند 100°C وكثافته 1.00 g/cm³. أما ماء البحر فمخلوط متجانس (محلول) يحتوي على الماء مذابًا فيه ملح الطعام (كلوريد الصوديوم) وأملاح ومعادن أخرى وغازات ذائبة، ويختلف تركيبه من موقع إلى آخر، لذلك فهو ليس مادة نقية. ومن نتائج ذلك أن ماء البحر يتجمد عند درجة أقل من 0°C ويغلي عند درجة أعلى من 100°C ويكون أكثف من الماء النقي. ويمكن الحصول على الماء النقي من ماء البحر بالتقطير، إذ يتبخر الماء ويبقى الملح.', '["الماء النقي مادة كيميائية نقية: تركيبه ثابت (H₂O).","ماء البحر مخلوط متجانس: ماء وأملاح ومعادن وغازات ذائبة، وتركيبه غير ثابت.","للماء النقي خواص مميزة ثابتة (يتجمد عند 0°C ويغلي عند 100°C)، أما ماء البحر فتتغير خواصه بتغير تركيبه.","يفصل الماء النقي عن ماء البحر بالتقطير."]'::jsonb, '["أن ماء البحر ماء نقي لأنه شفاف.","أن ماء الشرب مادة نقية.","أن ماء البحر مخلوط غير متجانس لأن الملح لا يُرى فيه."]'::jsonb, 'المقارنة هنا بمفهوم المادة النقية والمخلوط في الكتاب؛ والتغير الدقيق في درجتي التجمد والغليان مع تركيز المذاب يُذكر نوعيًّا فقط دون حسابات في هذا المستوى.', 'عالية'),
(202202, 'الكتاب يستدل على التفاعل الكيميائي باختلاف خواص النواتج عن المتفاعلات (الصدأ، تعفن الفواكه والخبز)، ويشير في ص53 إلى تغير اللون وظهور غاز، ولا يضع قائمة صريحة بأدلة حدوث التفاعل.', 'من الأدلة التي تشير إلى حدوث تفاعل كيميائي: (1) تغير اللون، كتحول النحاس من الأحمر إلى الأخضر وتحول أكسيد الزئبق II الأحمر إلى زئبق فضي. (2) تصاعد غاز على هيئة فقاعات، كتصاعد الغاز عند إضافة حمض الهيدروكلوريك إلى الخارصين. (3) تكوّن راسب صلب عند خلط محلولين. (4) انطلاق حرارة أو ضوء أو امتصاصها، كاحتراق الخشب. (5) تغير الرائحة أو الطعم، كتعفن الطعام. (6) تكوّن مادة لها خواص مختلفة عن المتفاعلات، كالصدأ الذي لا ينجذب إلى المغناطيس بخلاف الحديد. ولا يكفي دليل واحد دائمًا للحكم؛ فتغير الحالة (كغليان الماء) تظهر فيه فقاعات لكنه تغير فيزيائي لا تتكون فيه مادة جديدة، والدليل القاطع هو تكوّن مادة جديدة بخواص مختلفة.', '["أدلة التفاعل: تغير اللون، تصاعد غاز، تكوّن راسب، انطلاق طاقة (حرارة/ضوء)، تغير الرائحة.","الدليل الأساسي هو تكوّن مادة جديدة بخواص مختلفة.","ظهور فقاعات وحده لا يعني تفاعلًا (غليان الماء تغير فيزيائي)."]'::jsonb, '["أن كل تغير في اللون أو ظهور فقاعات يدل دائمًا على تفاعل كيميائي.","أن ذوبان السكر في الماء تفاعل كيميائي.","أن تغير الحالة تفاعل كيميائي."]'::jsonb, 'القائمة تجمع مؤشرات شائعة في كتب الكيمياء المدرسية؛ ويذكر الكتاب منها صراحةً تغير اللون وظهور الغاز وتغير الخواص وتغير الطعم والرائحة بالتعفن، وبقية المؤشرات (الراسب، الحرارة والضوء) تكميلية.', 'عالية'),
(203205, 'الكتاب يذكر (ص82–83) أن طومسون قاس نسبة الشحنة إلى الكتلة، وأن ميليكان قاس شحنة الإلكترون (1.602×10⁻¹⁹ C) بتجربة قطرة الزيت، وأن كتلة الإلكترون حُسبت منهما فبلغت 9.1×10⁻²⁸ g (1/1840 من كتلة ذرة الهيدروجين)، دون عرض خطوات الحساب.', 'حُسبت شحنة الإلكترون وكتلته على مرحلتين. في المرحلة الأولى قاس طومسون (1897م) نسبة شحنة جسيم أشعة المهبط إلى كتلته (e/m) بدراسة مقدار انحرافه في المجالين المغناطيسي والكهربائي، لكنه لم يستطع تحديد الشحنة وحدها ولا الكتلة وحدها. وفي المرحلة الثانية قاس ميليكان (1910م) شحنة الإلكترون بتجربة قطرة الزيت: رُشّ الزيت بين صفيحتين مشحونتين، وتشحن أشعة X قطرات الزيت بالتصاق إلكترونات بها، فبتغيير شدة المجال الكهربائي ضبط سرعة سقوط القطرات، ووجد أن شحنة كل قطرة تساوي مضاعفات صحيحة لأصغر قيمة هي 1.602×10⁻¹⁹ كولوم وهي شحنة إلكترون واحد (–1). وبمعرفة الشحنة ونسبة الشحنة إلى الكتلة تُحسب كتلة الإلكترون: الكتلة = الشحنة ÷ (الشحنة/الكتلة)، فتبلغ نحو 9.1×10⁻²⁸ g، أي 1/1840 تقريبًا من كتلة ذرة الهيدروجين.', '["طومسون: قاس نسبة الشحنة إلى الكتلة (e/m)","ميليكان: قاس الشحنة بتجربة قطرة الزيت","أصغر شحنة 1.602×10⁻¹⁹ C تمثل شحنة إلكترون واحد (–1)","الكتلة = الشحنة ÷ (الشحنة/الكتلة) ≈ 9.1×10⁻²⁸ g"]'::jsonb, '["أن طومسون حدّد كتلة الإلكترون وحدها مباشرة","أن ميليكان قاس الكتلة (قاس الشحنة)"]'::jsonb, 'نسبة الشحنة إلى الكتلة للإلكترون نحو 1.76×10⁸ C/g؛ وبقسمة 1.602×10⁻¹⁹ C عليها يُحصل على 9.1×10⁻²⁸ g. هذه القيم للاستئناس ولا يطلب الكتاب حسابها عدديًّا.', 'عالية'),
(204305, 'الكتاب يعرض أن تفاعلات الإحلال المزدوج في المحاليل المائية تنتج راسبًا أو ماءً أو غازًا مع أمثلة لكل نوع، لكنه لا يضع في الدروس قاعدة عامة للتنبؤ بالراسب؛ تُعطى معلومات الترسب داخل نص بعض الأسئلة، وتظهر قواعد الذائبية في الجدول 4-11 (ص149) ضمن «التقويم الإضافي».', 'للتنبؤ بنتيجة خلط محلولين مائيين لمركبين أيونيين: اكتب أيونات كل مركب، ثم بدّل الشريكين (إحلال مزدوج) وفحص كل ناتج جديد. يتكوّن راسب إذا كان الناتج مركبًا غير ذائب في الماء حسب قواعد الذائبية: أملاح عناصر المجموعة الأولى وأيون الأمونيوم وجميع النترات ذائبة؛ ومعظم الهاليدات والكبريتات ذائبة (ما عدا هاليدات Ag⁺ وPb²⁺ وHg₂²⁺ وCu⁺، وكبريتات Pb²⁺ وSr²⁺ وBa²⁺)؛ أما الهيدروكسيدات والكبريتيدات والأكاسيد والكربونات والفوسفات والكرومات فغير ذائبة عادة إلا مع المجموعة الأولى وأيون الأمونيوم. ويتكوّن ماء إذا اتحد H⁺ من حمض مع OH⁻ من قاعدة. ويتكوّن غاز إذا نتج H₂S أو HCN أو CO₂ (من كربونات أو بيكربونات مع حمض عبر H₂CO₃ غير المستقر). وإذا بقيت كل الأيونات ذائبة ولم يتكوّن ماء ولا غاز فلا يحدث تفاعل (NR). مثال: KI + AgNO₃ → AgI(s) + KNO₃؛ وNa₂SO₄ + KCl → NR.', '["الإحلال المزدوج في المحلول المائي يُنتج راسبًا أو ماءً أو غازًا؛ وإلا فلا تفاعل (NR).","الراسب: ناتج غير ذائب بحسب قواعد الذائبية (مثل AgI وBaSO₄ وCu(OH)₂ وBaCO₃).","الماء: من اتحاد H⁺ (حمض) مع OH⁻ (قاعدة) ولا يظهر له دليل مرئي.","الغاز: H₂S وHCN وCO₂ (الأخير عبر H₂CO₃ الذي يتفكك فورًا إلى ماء وCO₂).","النترات وأملاح المجموعة الأولى وأملاح الأمونيوم ذائبة دائمًا تقريبًا."]'::jsonb, '["أن كل خلط لمحلولين أيونيين ينتج راسبًا؛ وقد لا يحدث تفاعل إذا بقيت الأيونات كلها ذائبة.","أن عدم وجود راسب أو فقاعات يعني عدم حدوث تفاعل، مع أن تكوّن الماء (التعادل) لا يظهر مؤشرًا مرئيًا.","أن الأيونات المتفرجة تدخل في تكوين الراسب.","أن CO₂ ينتج مباشرة دون المرور بحمض الكربونيك غير المستقر."]'::jsonb, 'قواعد الذائبية عامة ولها استثناءات؛ وبعض الأملاح قليلة الذوبان (كبريتات الكالسيوم وكبريتات الفضة) كما يذكر الكتاب. تنطبق القواعد على المحاليل عند الظروف المعتادة. الجدول 4-11 ص149 هو مرجع الكتاب.', 'عالية')
on conflict do nothing;

insert into public.revisions (entity, entity_id, action, before_json, after_json, note, user_name, at)
select 'objective', o.id, 'approve', '{"reviewStatus":"pending","approvedText":null}'::jsonb, jsonb_build_object('reviewStatus', 'approved', 'approvedText', o.approved_text),
  'مالك المشروع: اعتماد مراجعة الأهداف الرسمية', 'مالك المشروع', '2026-10-17'::timestamptz
from public.objectives o where o.code like 'K1-%' and o.review_status = 'approved'
  and (o.memo_note like 'هدف مضاف من الكتاب%') = false
  and not exists (select 1 from public.revisions r where r.entity = 'objective' and r.entity_id = o.id and r.action = 'approve');

insert into public.revisions (entity, entity_id, action, before_json, after_json, note, user_name, at)
select 'objective', o.id, 'approve', '{"reviewStatus":"pending","approvedText":null}'::jsonb, jsonb_build_object('reviewStatus', 'approved', 'approvedText', o.approved_text),
  'مالك المشروع: اعتماد الأهداف المضافة من الكتاب المدرسي', 'مالك المشروع', '2026-10-17'::timestamptz
from public.objectives o where o.code like 'K1-%' and o.review_status = 'approved'
  and (o.memo_note like 'هدف مضاف من الكتاب%') = true
  and not exists (select 1 from public.revisions r where r.entity = 'objective' and r.entity_id = o.id and r.action = 'approve');

insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K1-C1-L1-O01'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما تعريف الكيمياء؟', null, '["دراسة المادة والتغيرات التي تطرأ عليها","دراسة الكائنات الحية وتركيبها ووظائفها","دراسة الأرض وطبقاتها وصخورها","دراسة الحركة والقوى والطاقة الميكانيكية"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 14 — لماذا ندرس الكيمياء؟'),
('mcq', 2, 'يُطلق العلماء اسم «مادة» على:', null, '["كل ما يمكن رؤيته بالعين المجردة","كل ما يعطي طاقة حرارية أو ضوئية","كل ما له كتلة ويشغل حيزًا","كل ما يتكون من نوع واحد من الذرات"]'::jsonb, 'تذكر', 'تذكر مصطلح', 'سهل', 'الكتاب ص 14 — لماذا ندرس الكيمياء؟'),
('mcq', 3, 'أيّ الأسئلة الآتية يمكن أن يجيب عنها الكيميائي بدراسته للمادة وتغيراتها؟', null, '["كيف تنقسم الخلية الحية إلى خليتين؟","ماذا يحدث لجزيئات غاز الأكسجين عند تعرضها للأشعة فوق البنفسجية؟","كم تبعد المجرات البعيدة عن الأرض؟","ما سرعة انتقال الصوت في الهواء؟"]'::jsonb, 'فهم', 'تصنيف مواقف', 'متوسط', 'الكتاب ص 14 — لماذا ندرس الكيمياء؟'),
('mcq', 4, 'أيّ العبارات الآتية تصف علاقة الكيمياء بحياة الناس وصفًا صحيحًا؟', null, '["يقتصر عمل الكيمياء على المواد الموجودة داخل المختبرات فقط","لا صلة للكيمياء بحفظ الأطعمة في الثلاجات","تدرس الكيمياء حركة الكواكب والنجوم وحدها","تُعنى الكيمياء بصناعة كريمات تقي الجلد من بعض أشعة الشمس الضارة"]'::jsonb, 'تذكر', 'تذكر أهمية', 'متوسط', 'الكتاب ص 14 — لماذا ندرس الكيمياء؟'),
('mcq', 5, 'تحلل جزيئات غاز الأكسجين إلى ذرات منفردة عند تعرضها للأشعة فوق البنفسجية. أيّ جزء من تعريف الكيمياء يمثله هذا الحدث؟', null, '["المادة من حيث كتلتها وحيزها فقط","مصدر الأشعة الصادرة عن الشمس","التغيرات التي تطرأ على المادة","الأجهزة المستعملة في قياس الأشعة"]'::jsonb, 'تطبيق', 'تطبيق التعريف على موقف', 'صعب', 'الكتاب ص 14، 16 — تعريف الكيمياء، تكوّن الأوزون'),
('mcq', 6, 'أيّ مما يأتي يُعدّ مادة وفق تعريف علماء الكيمياء للمادة؟', null, '["الضوء الصادر عن مصباح","الهواء المحبوس داخل بالون","الحرارة المنبعثة من النار","الصوت الصادر عن جرس"]'::jsonb, 'فهم', 'تصنيف أمثلة', 'صعب', 'الكتاب ص 14 — لماذا ندرس الكيمياء؟'),
('mcq', 7, 'ما القاسم المشترك بين الصخور الجبلية والمجرات والنجوم من وجهة نظر الكيمياء؟', null, '["جميعها مكوّنة من مادة","جميعها مصنوعة بتدخل الإنسان","جميعها تتكون من نوع واحد من الذرات","جميعها تقع ضمن طبقة الستراتوسفير"]'::jsonb, 'تذكر', 'تذكر مفهوم', 'سهل', 'الكتاب ص 14 — لماذا ندرس الكيمياء؟'),
('essay', 1, 'عرّف الكيمياء، ثم اذكر مثالين على فوائد دراستها للإنسان.', null, null, 'تذكر', 'تعريف مع أمثلة', 'سهل', 'الكتاب ص 14 — لماذا ندرس الكيمياء؟، 18'),
('essay', 2, 'وضّح المقصود بكلٍّ من «المادة» و«التغيرات» في تعريف الكيمياء، ومثّل لكل منهما بمثال من قصة غاز الأوزون.', null, null, 'فهم', 'توضيح مفهومين بأمثلة', 'متوسط', 'الكتاب ص 14، 16 — تعريف الكيمياء، تكوّن الأوزون'),
('essay', 3, 'حدد هل يدخل كل موقف مما يأتي ضمن اهتمام الكيمياء أم لا، مع التعليل بالاستناد إلى تعريف الكيمياء: (أ) تفاعل ذرة كلور مع جزيء أوزون. (ب) عدّ النجوم التي تظهر في مجرة. (ج) تحلل جزيئات الأكسجين بفعل الأشعة فوق البنفسجية.', null, null, 'تحليل', 'تصنيف مواقف مع تعليل', 'صعب', 'الكتاب ص 14 — لماذا ندرس الكيمياء؟، 16')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K1-C1-L1-O01') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'الكيمياء هي دراسة المادة والتغيرات التي تطرأ عليها، وهذا هو الخيار الصحيح.', '["","هذا تعريف علم الأحياء وليس الكيمياء.","هذا من اهتمامات علوم الأرض (الجيولوجيا).","هذا من اهتمامات الفيزياء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:32:48.068Z"}'::jsonb),
('mcq', 2, 2, 'المادة هي كل ما له كتلة ويشغل حيزًا؛ ولذلك تشمل ما يُرى وما لا يُرى كالغازات.', '["الغازات مادة مع أنها لا تُرى؛ فالرؤية ليست شرطًا لتكون الأشياء مادة.","الطاقة ليست مادة لأنها ليس لها كتلة ولا تشغل حيزًا.","","هذا وصف العنصر، أما المادة فتشمل كل ما له كتلة ويشغل حيزًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:32:48.069Z"}'::jsonb),
('mcq', 3, 1, 'تحلل جزيئات الأكسجين بالأشعة فوق البنفسجية تغير يطرأ على مادة، فهو من صميم دراسة الكيمياء.', '["انقسام الخلية الحية موضوع من موضوعات علم الأحياء.","","قياس المسافات بين المجرات من اهتمامات علم الفلك.","سرعة الصوت من موضوعات الفيزياء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-18T03:32:48.069Z"}'::jsonb),
('mcq', 4, 3, 'توفر دراسة الكيمياء الراحة والرفاهية للناس، ومن ذلك صناعة الكريمات التي تقي من بعض أشعة الشمس الضارة.', '["الكيمياء تدرس مواد العالم من حولنا كله، لا ما في المختبرات فقط.","الكيمياء لها صلة مباشرة بالتبريد وحفظ الأطعمة من التلف في الثلاجات.","دراسة حركة الكواكب والنجوم من اهتمامات علم الفلك، والكيمياء تدرس المادة وتغيراتها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:32:48.070Z"}'::jsonb),
('mcq', 5, 2, 'تحلل جزيء الأكسجين إلى ذرات تغيّر يطرأ على المادة، وهو الجزء الثاني من تعريف الكيمياء.', '["الكتلة والحيز يصفان المادة نفسها، أما تحلل الجزيئات فهو تغيّر يطرأ عليها.","مصدر الأشعة ليس جزءًا من تعريف الكيمياء، والحدث يصف ما يحدث للمادة.","","الأجهزة أدوات قياس وليست جزءًا من تعريف الكيمياء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:32:48.070Z"}'::jsonb),
('mcq', 6, 1, 'الهواء داخل البالون له كتلة ويشغل حيزًا فهو مادة، أما الضوء والحرارة والصوت فهي أشكال من الطاقة وليست مادة.', '["الضوء شكل من أشكال الطاقة وليس له كتلة ولا يشغل حيزًا.","","الحرارة شكل من أشكال الطاقة وليس لها كتلة ولا تشغل حيزًا.","الصوت طاقة تنتقل في الوسط وليس له كتلة ولا يشغل حيزًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:32:48.070Z"}'::jsonb),
('mcq', 7, 0, 'كل ما في العالم من أجسام وأشياء مكوّن من مادة؛ فلها كتلة وتشغل حيزًا.', '["","الصخور والمجرات والنجوم موجودة في الطبيعة دون تدخل الإنسان.","هذه الأجسام مكوّنة من أنواع كثيرة من الذرات.","الستراتوسفير طبقة من طبقات الغلاف الجوي ولا تضم الصخور ولا المجرات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:32:48.070Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الكيمياء هي دراسة المادة والتغيرات التي تطرأ عليها. ومن فوائد دراستها: استعمال مواد التبريد في الثلاجات لحفظ الأطعمة من التلف، واستعمال المكيفات في المنازل والمدارس وأماكن العمل، وصناعة الكريمات الواقية من بعض أشعة الشمس الضارة.', '["تعريف الكيمياء: دراسة المادة والتغيرات التي تطرأ عليها","مثال أول صحيح على فوائد دراسة الكيمياء","مثال ثانٍ صحيح على فوائد دراسة الكيمياء"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر المادة في التعريف","marks":1},{"element":"ذكر التغيرات التي تطرأ عليها في التعريف","marks":1},{"element":"المثال الأول","marks":1},{"element":"المثال الثاني","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف كامل ومثالان صحيحان"},{"level":"2–3 درجات","description":"تعريف صحيح مع مثال واحد، أو مثالان مع نقص في التعريف"},{"level":"1 درجة","description":"ذكر جزء من التعريف أو مثال واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاكتفاء بذكر «المادة» دون «التغيرات التي تطرأ عليها»","ذكر أمثلة لا علاقة لها بالكيمياء كالفلك"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:32:48.070Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المادة هي كل ما له كتلة ويشغل حيزًا، ومثالها غاز الأكسجين O₂ وغاز الأوزون O₃. أما التغيرات فهي ما يطرأ على المادة من تحول؛ ومثالها تحلل جزيئات الأكسجين O₂ بفعل الأشعة فوق البنفسجية إلى ذرات O، ثم اتحاد كل ذرة منها مع جزيء O₂ فيتكوّن الأوزون O₃.', '["المادة: كل ما له كتلة ويشغل حيزًا","مثال على المادة: O₂ أو O₃","التغيرات: ما يطرأ على المادة من تحول","مثال على التغير: تحلل O₂ وتكوّن O₃"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف المادة","marks":1},{"element":"مثال صحيح على المادة","marks":1},{"element":"توضيح معنى التغيرات","marks":1},{"element":"مثال صحيح على تغير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"توضيح صحيح للمصطلحين مع مثالين مناسبين"},{"level":"2–3 درجات","description":"توضيح صحيح لأحد المصطلحين مع مثاله، أو توضيح المصطلحين دون أمثلة"},{"level":"1 درجة","description":"توضيح جزئي أو مثال واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الطاقة كالضوء والحرارة مادة","ذكر مثال على التغير دون أن يكون تحولًا يطرأ على مادة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:32:48.070Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) يدخل ضمن اهتمام الكيمياء؛ لأنه تغيّر يطرأ على مادة (الكلور والأوزون). (ب) لا يدخل؛ لأن عدّ النجوم لا يدرس المادة ولا التغيرات التي تطرأ عليها، وإنما هو من اهتمامات علم الفلك. (ج) يدخل ضمن اهتمام الكيمياء؛ لأن جزيئات الأكسجين (مادة) تتحلل إلى ذرات (تغيّر يطرأ عليها). فمعيار الحكم هو تعريف الكيمياء: دراسة المادة والتغيرات التي تطرأ عليها.', '["(أ) يدخل ضمن الكيمياء لأنه تغيّر في مادة","(ب) لا يدخل لأنه ليس دراسة لمادة ولا لتغيراتها","(ج) يدخل ضمن الكيمياء لأنه تغيّر يطرأ على مادة","الاستناد إلى تعريف الكيمياء في التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم والتعليل في (أ)","marks":1},{"element":"الحكم والتعليل في (ب)","marks":1},{"element":"الحكم والتعليل في (ج)","marks":1},{"element":"الاستناد إلى تعريف الكيمياء","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"أحكام صحيحة للمواقف الثلاثة مع تعليل مستند إلى التعريف"},{"level":"2–3 درجات","description":"أحكام صحيحة مع تعليل ناقص أو غير مستند إلى التعريف"},{"level":"1 درجة","description":"حكم صحيح لموقف أو موقفين دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن (ب) من الكيمياء لأن النجوم مكوّنة من مادة، مع أن عدّها لا يدرس المادة ولا تغيراتها","الحكم دون تعليل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:32:48.071Z"}'::jsonb)
