('mcq', 1, 1, 'المادة الكيميائية لها تركيب محدد وثابت، وهو الخيار الصحيح.', '["المواد الكيميائية توجد في الطبيعة أيضًا، كغاز الأوزون في الغلاف الجوي.","","المواد الضارة وغير الضارة كلها قد تكون مواد كيميائية؛ فالضرر ليس معيارًا لتعريفها.","المادة الكيميائية يكون تركيبها ثابتًا في كل العينات، ولا تتغير نسب مكوناتها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:32:48.072Z"}'::jsonb),
('mcq', 2, 3, 'المادة الكيميائية لها تركيب محدد وثابت وتسمى المادة النقية.', '["ليس كل مادة نقية مركبة؛ فالأكسجين O₂ مادة نقية مكوّنة من نوع واحد من الذرات.","الذوبان خاصية تتعلق بسلوك المادة في مذيب ولا يسمّى به تعريف المادة الكيميائية.","قد تكون المادة الكيميائية طبيعية كالأوزون في الستراتوسفير، فلا تقتصر على المصنعة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:32:48.072Z"}'::jsonb),
('mcq', 3, 0, 'غاز الأوزون O₃ مكوّن من ثلاث ذرات أكسجين، وله تركيب محدد وثابت؛ فهو مادة كيميائية.', '["","الأشعة فوق البنفسجية شكل من أشكال الطاقة وليست مادة.","الستراتوسفير طبقة من طبقات الغلاف الجوي، وليست مادة واحدة ذات تركيب محدد وثابت.","تقلبات الطقس ظواهر جوية وليست مادة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:32:48.072Z"}'::jsonb),
('mcq', 4, 2, 'الأوزون مادة كيميائية، وتركيبها محدد وثابت (ثلاث ذرات أكسجين في الجزيء) مهما كان مصدرها.', '["تركيب الأوزون ثابت، فلا تختلف نسبة الأكسجين فيه بين عينة وأخرى.","ثبات التركيب لا يتأثر بطريقة التحضير أو مصدر العينة.","","يمكن المقارنة، وتبيّن أن للعينتين التركيب نفسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:32:48.072Z"}'::jsonb),
('mcq', 5, 3, 'عدّ المادة كيميائية يعتمد على أن لها تركيبًا محددًا وثابتًا، والأوزون مكوّن من ذرات أكسجين بتركيب ثابت (O₃).', '["مكان الوجود لا يحدد كون المادة كيميائية؛ فالمواد الكيميائية توجد في أماكن كثيرة.","امتصاص الأشعة خاصية للأوزون وليس سببًا لعدّه مادة كيميائية.","الأوزون موجود طبيعيًا في الستراتوسفير، فلا يقتصر تحضيره على الصناعة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-18T03:32:48.072Z"}'::jsonb),
('mcq', 6, 0, 'نسبة الكربون في المادة س ثابتة (7.8%) في العينات الثلاث، أي أن لها تركيبًا محددًا وثابتًا، فهي مادة كيميائية. أما نسبة الكربون في المادة ص فتتغير من عينة لأخرى فليس لها تركيب ثابت.', '["","اختلاف التركيب من عينة لأخرى يدل على أن المادة ليست كيميائية (نقية).","وجود الكربون في المادتين لا يكفي؛ فالمعيار هو ثبات التركيب بين العينات.","اختلاف النسب بين مادتين مختلفتين أمر طبيعي؛ والمعيار هو ثبات التركيب داخل عينات المادة الواحدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:32:48.073Z"}'::jsonb),
('mcq', 7, 2, 'الأوزون O₃ مكوّن من ثلاث ذرات أكسجين.', '["الغلاف الجوي يحتوي النيتروجين بوفرة، لكنه ليس مكوّن الأوزون.","الكلور يفكك الأوزون ولا يدخل في تركيبه.","","لا يحتوي جزيء الأوزون على ذرات هيدروجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-18T03:32:48.073Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المادة الكيميائية مادة لها تركيب محدد وثابت، وتسمى المادة النقية. ومن أمثلتها غاز الأوزون O₃ وغاز الأكسجين O₂.', '["لها تركيب محدد وثابت","تسمى المادة النقية","مثال صحيح أول (كالأوزون O₃)","مثال صحيح ثانٍ (كالأكسجين O₂ أو الماء H₂O)"]'::jsonb, '[]'::jsonb, '[{"element":"تركيب محدد وثابت","marks":1},{"element":"تسميتها المادة النقية","marks":1},{"element":"المثال الأول","marks":1},{"element":"المثال الثاني","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف كامل ومثالان صحيحان"},{"level":"2–3 درجات","description":"تعريف صحيح مع مثال واحد، أو مثالان مع تعريف ناقص"},{"level":"1 درجة","description":"جزء من التعريف أو مثال واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاكتفاء بـ«مادة نقية» دون ذكر ثبات التركيب","عدّ الطاقة مثالًا على مادة كيميائية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:32:48.073Z"}'::jsonb),
('essay', 2, null::int, null, null, 'تُعدّ العينتان المادة الكيميائية نفسها لأن لكل منهما التركيب نفسه: جزيء يتكون من ثلاث ذرات أكسجين (O₃). فالمادة الكيميائية يتميز بأن لها تركيبًا محددًا وثابتًا، وتسمى المادة النقية؛ لذلك لا يتغير تركيبها بتغير مصدرها أو طريقة الحصول عليها.', '["لكل عينة التركيب نفسه (O₃ من ثلاث ذرات أكسجين)","المادة الكيميائية لها تركيب محدد وثابت","ثبات التركيب لا يتأثر بمصدر العينة","تسمى المادة النقية"]'::jsonb, '[]'::jsonb, '[{"element":"بيان أن تركيب العينتين واحد","marks":1},{"element":"ذكر أن المادة الكيميائية لها تركيب محدد وثابت","marks":1},{"element":"ربط ثبات التركيب بعدم تأثره بالمصدر","marks":1},{"element":"ذكر تسميتها المادة النقية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل يربط تماثل التركيب بثبات تركيب المادة الكيميائية"},{"level":"2–3 درجات","description":"تفسير صحيح مع نقص في بعض العناصر"},{"level":"1 درجة","description":"ذكر جزء من الخاصية دون ربط بالعينتين"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المصدر الطبيعي يجعل التركيب مختلفًا عن المحضّر","الاكتفاء بذكر أن الغاز واحد دون ذكر التركيب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:32:48.073Z"}'::jsonb),
('essay', 3, null::int, null, null, 'المادة م هي المادة الكيميائية؛ لأن نسبة الأكسجين فيها ثابتة (88.8%) في جميع العينات، أي أن لها تركيبًا محددًا وثابتًا. أما المادة ن فتتغير نسبة الأكسجين فيها من عينة لأخرى (40.2% و52.7% و61.9%) فليس لها تركيب ثابت، فلا تُعدّ مادة كيميائية. وتتوقع أن تكون نسبة الأكسجين في عينة رابعة من المادة م هي 88.8% أيضًا.', '["المادة م هي المادة الكيميائية","نسبتها ثابتة (88.8%) في كل العينات","نسبة الأكسجين في ن تتغير من عينة لأخرى فليست مادة كيميائية","نسبة الأكسجين المتوقعة في العينة الرابعة من م هي 88.8%"]'::jsonb, '["تحديد أن نسبة الأكسجين في م ثابتة (88.8%) في العينات الثلاث","تحديد أن نسبتها في ن متغيرة (40.2% إلى 61.9%)","الاستنتاج: م مادة كيميائية لأن تركيبها ثابت، وتوقع 88.8% للعينة الرابعة"]'::jsonb, '[{"element":"تحديد المادة م مادة كيميائية","marks":1},{"element":"التعليل بثبات النسبة في م","marks":1},{"element":"بيان أن تغير النسبة في ن ينفي كونها مادة كيميائية","marks":1},{"element":"توقع 88.8% في العينة الرابعة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد صحيح وتعليل كامل وتوقع صحيح"},{"level":"2–3 درجات","description":"تحديد صحيح مع تعليل أو توقع ناقص"},{"level":"1 درجة","description":"تحديد صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اختيار المادة ن لأن نسبها متنوعة","توقع نسبة مختلفة عن 88.8% للعينة الرابعة من م","الاكتفاء بمقارنة المتوسطات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:32:48.073Z"}'::jsonb)
