('mcq', 1, 2, 'يمكن أن تسبب المستويات العالية من UVB إعتامًا في العين وسرطانًا في الجلد عند الإنسان.', '["فقر الدم وهشاشة العظام لا يرتبطان بالتعرض للأشعة فوق البنفسجية.","ارتفاع ضغط الدم وتصلب الشرايين ليسا من أضرار UVB.","","التهاب الكبد والفشل الكلوي ليسا من أضرار UVB."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:32:48.075Z"}'::jsonb),
('mcq', 2, 0, 'المستويات العالية من UVB تقلل من نواتج المحاصيل الزراعية.', '["","UVB مؤذية للنباتات، فلا تزيد الإنتاج بل تقلله.","النباتات تتأثر بالمستويات العالية من UVB فلا يبقى إنتاجها كما هو.","الأثر المعروف هو نقص النواتج، وليس مضاعفتها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:32:48.075Z"}'::jsonb),
('mcq', 3, 3, 'المستويات العالية من UVB تسبب خللًا في سلاسل الغذاء في الطبيعة.', '["الضرر اللاحق بالنباتات والحيوانات يضعف سلاسل الغذاء ولا يقويها.","UVB تؤذي النباتات والحيوانات، وهي حلقات في سلاسل الغذاء، فلا يبقى أثرها معدومًا.","لا يوجد ما يدل على زيادة المفترسات؛ والأثر هو خلل في السلسلة كلها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:32:48.075Z"}'::jsonb),
('mcq', 4, 1, 'طبقة الأوزون تمتص معظم الأشعة فوق البنفسجية الضارة؛ فإذا تقلصت وصل مزيد من UVB إلى الأرض فتتضرر الكائنات الحية.', '["الأوزون يمتص الأشعة فوق البنفسجية ولا يحجب ضوء الشمس اللازم لنمو النباتات.","","الأرض لا تمتص UVB فترتفع حرارتها فورًا؛ والقلق من تضرر الكائنات الحية بالأشعة.","الأوزون لا يتحكم في وصول الأكسجين إلى الكائنات؛ ووظيفته امتصاص الأشعة الضارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-18T03:32:48.075Z"}'::jsonb),
('mcq', 5, 0, 'ارتفاع مستوى UVB يقلل نواتج المحاصيل ويسبب إعتام العين عند الإنسان، فهو السبب المشترك المرجح.', '["","زيادة سمك الطبقة تعني امتصاصًا أكبر للأشعة وانخفاض UVB، فلا تفسر الأضرار.","النيتروجين لا يسبب إعتام العين ولا نقص نواتج المحاصيل.","زيادة الامتصاص تقلل UVB الواصل إلى الأرض، فلا تسبب هذه الأضرار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:32:48.075Z"}'::jsonb),
('mcq', 6, 3, 'إعتام العين من الأضرار التي تسببها المستويات العالية من UVB عند الإنسان.', '["المحاصيل تتضرر بنقص نواتجها لا بإعتام العين.","سلاسل الغذاء تتأثر بالخلل فيها لا بإعتام العين.","النباتات تتضرر بتأثر نموها ونواتجها لا بإعتام العين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:32:48.075Z"}'::jsonb),
('mcq', 7, 1, 'يعتقد بعض العلماء أن وصول UVB إلى حدّ معين يجعل الخلايا غير قادرة على المقاومة، فيموت الكثير من المخلوقات الحية.', '["القدرة على الإصلاح تكون عند المستويات المنخفضة من الأشعة فقط.","","لا تتكيف الخلايا عند هذا الحد، بل تعجز عن المقاومة.","المستويات العالية من UVB مؤذية فلا تنقسم الخلايا دون ضرر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-18T03:32:48.075Z"}'::jsonb),
('essay', 1, null::int, null, null, 'من أضرار UVB: إعتام العين عند الإنسان، وسرطان الجلد عند الإنسان، وتقليل نواتج المحاصيل الزراعية، وإحداث خلل في سلاسل الغذاء في الطبيعة.', '["إعتام العين (الإنسان)","سرطان الجلد (الإنسان)","تقليل نواتج المحاصيل الزراعية","خلل في سلاسل الغذاء في الطبيعة"]'::jsonb, '[]'::jsonb, '[{"element":"ضرر أول مع ما يتأثر به","marks":1},{"element":"ضرر ثانٍ مع ما يتأثر به","marks":1},{"element":"ضرر ثالث مع ما يتأثر به","marks":1},{"element":"ضرر رابع مع ما يتأثر به","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"أربعة أضرار صحيحة مع بيان ما يتأثر بكل منها"},{"level":"2–3 درجات","description":"ضرران أو ثلاثة صحيحة، أو أربعة دون بيان ما يتأثر"},{"level":"1 درجة","description":"ضرر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر أمراض لا ترتبط بالأشعة فوق البنفسجية","ذكر الضرر دون تحديد ما يتأثر به"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:32:48.076Z"}'::jsonb),
('essay', 2, null::int, null, null, 'العبارة غير صحيحة أو غير كافية. فصحيح أن المخلوقات نشأت رغم تعرضها لـ UVB، لأن للخلايا بعض القدرة على إصلاح نفسها عند التعرض لمستويات منخفضة من هذه الأشعة؛ لكن يعتقد بعض العلماء أن وصول مستوى UVB إلى حدّ معين يجعل الخلايا غير قادرة على المقاومة، فيموت الكثير من المخلوقات الحية. وازدياد UVB بسبب تقلص طبقة الأوزون قد يبلغ مستويات تضر الإنسان والنباتات والحيوانات وسلاسل الغذاء.', '["الخلايا تصلح نفسها عند المستويات المنخفضة","عند حدّ معين من UVB تعجز الخلايا عن المقاومة","موت الكثير من المخلوقات الحية","الحكم بأن العبارة غير كافية لنفي الخطر"]'::jsonb, '[]'::jsonb, '[{"element":"بيان صحة الجزء الأول (إصلاح الخلايا عند المستويات المنخفضة)","marks":1},{"element":"بيان عجز الخلايا عند حدّ معين من الأشعة","marks":1},{"element":"ربط ذلك بالخطر على المخلوقات الحية","marks":1},{"element":"الحكم بأن العبارة غير كافية لنفي الخطر","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تقييم كامل يوضح قدرة الخلايا ومحدوديتها ويحكم على العبارة"},{"level":"2–3 درجات","description":"تقييم صحيح مع نقص في التعليل"},{"level":"1 درجة","description":"حكم صحيح دون تعليل كافٍ"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول العبارة كما هي","إنكار قدرة الخلايا على إصلاح نفسها كليًّا","عدم ربط الحكم بمستوى الأشعة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-18T03:32:48.076Z"}'::jsonb),
('essay', 3, null::int, null, null, 'على الإنسان: قد تُصاب العين بالإعتام أو يُصاب الجلد بالسرطان. على المحاصيل: تقل نواتجها الزراعية. على النظام الغذائي: يحدث خلل في سلاسل الغذاء في الطبيعة. وللوقاية يُستعمل دهن الجلد بالكريمات الواقية من أشعة الشمس قبل التعرض لها.', '["ضرر على الإنسان (إعتام العين أو سرطان الجلد)","ضرر على المحاصيل (قلة النواتج)","ضرر على النظام الغذائي (خلل سلاسل الغذاء)","إجراء وقائي (الكريمات الواقية)"]'::jsonb, '[]'::jsonb, '[{"element":"ضرر على الإنسان","marks":1},{"element":"ضرر على المحاصيل","marks":1},{"element":"ضرر على سلاسل الغذاء","marks":1},{"element":"إجراء وقائي مناسب","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"توقع صحيح لثلاثة أضرار مع إجراء وقائي مناسب"},{"level":"2–3 درجات","description":"توقع صحيح لضررين مع الإجراء الوقائي، أو لثلاثة أضرار دونه"},{"level":"1 درجة","description":"توقع ضرر واحد أو إجراء وقائي فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المحاصيل تزداد نواتجها","اقتراح إجراء لا يحمي من الأشعة فوق البنفسجية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:32:48.076Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
