('mcq', 1, 'كيف يتكوّن غاز الأوزون في الأجزاء العليا من الستراتوسفير؟', null, '["تتحد ثلاثة جزيئات O₂ مباشرة دون الحاجة إلى أشعة","تتفاعل ذرات النيتروجين مع جزيئات O₂ بفعل الأشعة فوق البنفسجية","يتفاعل O₂ مع ذرات الكلور فيتكوّن O₃","تتحلل جزيئات O₂ بالأشعة فوق البنفسجية إلى ذرات O، وتتحد كل ذرة مع جزيء O₂"]'::jsonb, 'فهم', 'توضيح عملية', 'متوسط', 'الكتاب ص 15، 16 — طبقة الأوزون، تكوّن الأوزون'),
('mcq', 2, 'كم ذرة أكسجين في جزيء الأوزون، وما رمزه؟', null, '["ذرتا أكسجين، ورمزه O₂","ثلاث ذرات أكسجين، ورمزه O₃","ذرة أكسجين واحدة، ورمزها O","أربع ذرات أكسجين، ورمزه O₄"]'::jsonb, 'تذكر', 'تذكر تركيب', 'سهل', 'الكتاب ص 15، 16 — طبقة الأوزون، تكوّن الأوزون'),
('mcq', 3, 'في أيّ طبقة من طبقات الغلاف الجوي يتركز نحو 90% من غاز الأوزون؟', null, '["التروبوسفير","الميزوسفير","الستراتوسفير","الإكسوسفير"]'::jsonb, 'تذكر', 'تذكر مكان', 'سهل', 'الكتاب ص 15 — طبقة الأوزون (أضرار UVB)'),
('mcq', 4, 'لماذا تُعدّ طبقة الأوزون مهمة للكائنات الحية؟', null, '["لأنها تمتص معظم الأشعة فوق البنفسجية الضارة قبل وصولها إلى الأرض","لأنها تُنتج الأكسجين الذي تتنفسه الكائنات","لأنها تمنع حدوث تقلبات الطقس على الأرض","لأنها تحتوي على الهواء الذي نتنفسه"]'::jsonb, 'فهم', 'تفسير أهمية', 'متوسط', 'الكتاب ص 15 — طبقة الأوزون (أضرار UVB)'),
('mcq', 5, 'يمتص غاز الأوزون الأشعة فوق البنفسجية فيتحلل إلى O₂، ويتكوّن الأوزون من O₂ بفعل الأشعة نفسها. ما نتيجة استمرار العمليتين في الستراتوسفير؟', null, '["اختفاء الأوزون تمامًا من الستراتوسفير","حدوث توازن بين غازي الأكسجين والأوزون","تراكم الأوزون باستمرار دون أن يتحلل","تحول غاز الأكسجين كله إلى أوزون"]'::jsonb, 'تحليل', 'تحليل عمليتين متعاكستين', 'صعب', 'الكتاب ص 16 — تكوّن الأوزون'),
('mcq', 6, 'يتكوّن غاز الأوزون بصورة رئيسة فوق خط الاستواء. ما تفسير ذلك؟', null, '["لأن درجة الحرارة هناك أقل منها في أي مكان آخر","لأن الهواء فوق القطبين لا يحتوي على أكسجين","لأن أشعة الشمس هناك عمودية وقوية","لأن تيارات الهواء تنتج الأوزون من النيتروجين"]'::jsonb, 'فهم', 'تفسير', 'صعب', 'الكتاب ص 16 — تكوّن الأوزون'),
('mcq', 7, 'تمتد طبقة الستراتوسفير التي تضم طبقة الأوزون بين ارتفاعين فوق سطح الأرض؛ ما هما؟', null, '["من 0 km إلى 10 km","من 50 km إلى 85 km","من 85 km إلى 500 km","من 10 km إلى 50 km"]'::jsonb, 'تذكر', 'تذكر مكان', 'سهل', 'الكتاب ص 15 — طبقة الأوزون (أضرار UVB)'),
('essay', 1, 'صف كيف يتكوّن غاز الأوزون في الستراتوسفير، ثم بيّن أهميته، واذكر تركيب جزيئه ومكان وجوده.', null, null, 'فهم', 'توضيح أربعة محاور', 'متوسط', 'الكتاب ص 15، 16 — طبقة الأوزون، تكوّن الأوزون'),
