select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'عند تعرض O₂ للأشعة فوق البنفسجية تتحلل جزيئاته إلى ذرات O منفردة، تتفاعل كل منها مع جزيء O₂ فيتكوّن O₃.', '["الاتحاد المباشر لثلاثة جزيئات O₂ لا يحدث؛ فتكوّن الأوزون يحتاج إلى تحلل O₂ بالأشعة أولًا.","النيتروجين لا يدخل في تكوّن الأوزون؛ إذ يتكوّن من ذرات الأكسجين فقط.","الكلور يفكك الأوزون ولا يكوّنه، والأوزون يتكوّن من الأكسجين وحده.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-18T03:32:48.077Z"}'::jsonb),
('mcq', 2, 1, 'جزيء الأوزون مكوّن من ثلاث ذرات أكسجين، ورمزه O₃.', '["هذا تركيب جزيء غاز الأكسجين O₂ وليس الأوزون.","","الذرة المنفردة O ليست جزيء الأوزون، بل تتحد مع O₂ لتكوّنه.","لا يوجد جزيء أوزون مكوّن من أربع ذرات؛ فرمز الأوزون O₃."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:32:48.077Z"}'::jsonb),
('mcq', 3, 2, 'ينتشر نحو 90% من غاز الأوزون في طبقة الستراتوسفير التي تحيط بالأرض وتحميها.', '["التروبوسفير هي الطبقة الدنيا التي تحوي الهواء الذي نتنفسه وتحدث فيها تقلبات الطقس.","الميزوسفير تقع فوق الستراتوسفير ولا يتركز فيها الأوزون.","","الإكسوسفير أبعد الطبقات عن الأرض ولا يتركز فيها الأوزون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:32:48.077Z"}'::jsonb),
('mcq', 4, 0, 'يمتص غاز الأوزون معظم الأشعة فوق البنفسجية الضارة قبل وصولها إلى الأرض، فتحمي الكائنات الحية.', '["","الأوزون لا ينتج الأكسجين؛ بل يتكوّن منه بفعل الأشعة فوق البنفسجية.","تقلبات الطقس تحدث في التروبوسفير، ولا علاقة لطبقة الأوزون بمنعها.","الهواء الذي نتنفسه يوجد في التروبوسفير، لا في طبقة الأوزون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:32:48.077Z"}'::jsonb),
('mcq', 5, 1, 'تكوّن الأوزون وتحلله يحدثان معًا باستمرار، فينشأ نوع من التوازن بين غازي الأكسجين والأوزون.', '["لو كان التحلل وحده يحدث لاختفى الأوزون، لكن تكوّنه مستمر أيضًا.","","الأوزون يتحلل بامتصاصه الأشعة فلا يتراكم دون تحلل.","الأوزون يتحلل ثانية إلى أكسجين، فلا يتحول الأكسجين كله إلى أوزون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:32:48.077Z"}'::jsonb),
('mcq', 6, 2, 'تكون أشعة الشمس فوق خط الاستواء عمودية وقوية، فيتحلل O₂ بمعدل أكبر ويتكوّن الأوزون بكمية أكبر هناك.', '["البرودة لا علاقة لها بتكوّن الأوزون؛ فالتكوّن يعتمد على الأشعة فوق البنفسجية.","الأكسجين موجود في الهواء فوق القطبين أيضًا.","","الأوزون يتكوّن من الأكسجين وليس من النيتروجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:32:48.077Z"}'::jsonb),
('mcq', 7, 3, 'تمتد طبقة الستراتوسفير بين 10 km و50 km فوق سطح الأرض، وفيها طبقة الأوزون.', '["هذا امتداد التروبوسفير، وهي الطبقة الدنيا.","هذا امتداد الميزوسفير، وهي فوق الستراتوسفير.","هذا امتداد طبقات أعلى (الثيرموسفير والإكسوسفير) لا الستراتوسفير.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:32:48.078Z"}'::jsonb),
('essay', 1, null::int, null, null, 'عندما يتعرض غاز الأكسجين O₂ في الأجزاء العليا من الستراتوسفير للأشعة فوق البنفسجية تتحلل جزيئاته إلى ذرات O منفردة، ثم تتحد كل ذرة مع جزيء O₂ فيتكوّن الأوزون O₃. وأهميته أنه يمتص معظم الأشعة فوق البنفسجية الضارة قبل وصولها إلى الأرض. ويتركب جزيئه من ثلاث ذرات أكسجين (O₃). ويوجد في طبقة الستراتوسفير على ارتفاع بين 10 km و50 km فوق سطح الأرض، ويتركز فيها نحو 90% منه.', '["تحلل O₂ بالأشعة فوق البنفسجية إلى ذرات O","اتحاد كل ذرة O مع جزيء O₂ فيتكوّن O₃","الأهمية: يمتص معظم الأشعة فوق البنفسجية الضارة","التركيب: ثلاث ذرات أكسجين (O₃)","المكان: الستراتوسفير (10 km – 50 km)"]'::jsonb, '[]'::jsonb, '[{"element":"تحلل O₂ إلى ذرات O بالأشعة فوق البنفسجية","marks":1},{"element":"اتحاد ذرة O مع جزيء O₂ لتكوين O₃","marks":1},{"element":"الأهمية: امتصاص الأشعة فوق البنفسجية الضارة","marks":1},{"element":"التركيب: ثلاث ذرات أكسجين","marks":1},{"element":"المكان: طبقة الستراتوسفير","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"توضيح صحيح للتكوّن والأهمية والتركيب والمكان"},{"level":"3–4 درجات","description":"توضيح صحيح لثلاثة من الأربعة محاور أو أكثر مع نقص في التكوّن"},{"level":"1–2 درجة","description":"ذكر محور أو محورين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الأوزون يتكوّن من اتحاد ذرتي أكسجين","وضع الأوزون في التروبوسفير بدلًا من الستراتوسفير","إغفال دور الأشعة فوق البنفسجية في تكوّنه"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-18T03:32:48.078Z"}'::jsonb),
('essay', 2, null::int, null, null, 'تتحلل جزيئات الأكسجين O₂ بفعل الأشعة فوق البنفسجية إلى ذرات O تتحد مع جزيئات O₂ أخرى فيتكوّن الأوزون O₃. وفي الوقت نفسه يمتص الأوزون الأشعة فوق البنفسجية فيتحلل مكوّنًا غاز الأكسجين من جديد. ولأن عمليتي التكوّن والتحلل تحدثان معًا باستمرار، ينشأ نوع من التوازن بين غازي الأكسجين والأوزون في الستراتوسفير.', '["الأكسجين يتحول إلى أوزون بالأشعة فوق البنفسجية","الأوزون يمتص الأشعة فيتحلل إلى أكسجين","العمليتان تحدثان معًا باستمرار فينشأ التوازن"]'::jsonb, '[]'::jsonb, '[{"element":"تكوّن الأوزون من الأكسجين بفعل الأشعة","marks":1},{"element":"تحلل الأوزون إلى أكسجين عند امتصاصه الأشعة","marks":1},{"element":"استمرار العمليتين معًا فينشأ التوازن","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تفسير كامل للعمليتين المتعاكستين واستمرارهما"},{"level":"2 درجة","description":"ذكر إحدى العمليتين مع الإشارة إلى التوازن"},{"level":"1 درجة","description":"ذكر عملية واحدة دون تفسير التوازن"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر عملية التكوّن فقط","القول إن الأوزون يتحلل تمامًا فلا يبقى منه شيء","الخلط بين تحلل O₂ وتحلل O₃"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:32:48.078Z"}'::jsonb),
('essay', 3, null::int, null, null, 'يتكون جزيء الأكسجين من ذرتين (O₂) ويتكون جزيء الأوزون من ثلاث ذرات (O₃). عند تعرض الأكسجين للأشعة فوق البنفسجية تتحلل جزيئاته إلى ذرات O تتحد مع O₂ فيتكوّن الأوزون، أما الأوزون فيمتص الأشعة فيتحلل مكوّنًا الأكسجين. وللأوزون أهمية للكائنات الحية لأنه يمتص معظم الأشعة فوق البنفسجية الضارة قبل وصولها إلى الأرض، فيحميها من أضرارها.', '["O₂ ذرتان وO₃ ثلاث ذرات","O₂ يتحلل بالأشعة إلى ذرات O فيتكوّن O₃","O₃ يمتص الأشعة فيتحلل إلى O₂","الأوزون يمتص معظم الأشعة الضارة فيحمي الكائنات الحية"]'::jsonb, '[]'::jsonb, '[{"element":"المقارنة في عدد الذرات","marks":1},{"element":"مصير الأكسجين عند تعرضه للأشعة","marks":1},{"element":"مصير الأوزون عند تعرضه للأشعة","marks":1},{"element":"تفسير أهمية الأوزون بامتصاص الأشعة الضارة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة صحيحة في المحاور الثلاثة مع تفسير الأهمية"},{"level":"2–3 درجات","description":"مقارنة صحيحة في محورين مع تفسير الأهمية أو العكس"},{"level":"1 درجة","description":"ذكر محور واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل عدد ذرات الأوزون اثنتين","القول إن الأوزون ينتج الأكسجين الذي نتنفسه","نسبة تحلل الأكسجين إلى الأوزون وليس إلى الأشعة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:32:48.078Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
