from (values
('mcq', 1, 0, 'تُقاس كمية غاز الأوزون في الجو بوحدة دوبسون، ويرمز إليها DU.', '["","الوحدة ppt تُستعمل لقياس تركيز مركبات CFCs وليس كمية الأوزون.","mol/L وحدة تركيز المحاليل ولا تُستعمل لكمية الأوزون في الجو.","الكيلومتر وحدة طول؛ يُقاس بها الارتفاع لا كمية الأوزون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-10-18T03:32:48.079Z"}'::jsonb),
('mcq', 2, 3, 'المستوى الطبيعي لكمية الأوزون في الجو هو 300 دوبسون (DU).', '["هذه من القيم المنخفضة التي سُجلت فوق القارة المتجمدة الجنوبية، وهي أقل من المستوى الطبيعي.","هذا من القيم المنخفضة التي سُجلت فوق القارة المتجمدة الجنوبية، وهي أقل من الطبيعي.","هذه قيمة أعلى بكثير من المستوى الطبيعي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:32:48.079Z"}'::jsonb),
('mcq', 3, 1, 'بدأ العالم البريطاني دوبسون (1889–1976م) قياس كمية الأوزون في عشرينيات القرن الماضي، ونُسبت الوحدة إليه.', '["ميجلي حضّر عام 1928م أول مركّب من مركبات CFCs ولم يقس كمية الأوزون.","","مولينا وضع مع رولاند نموذجًا يفسر تدمير CFCs للأوزون.","رولاند شارك مولينا في نموذج تدمير CFCs للأوزون ولم يضع وحدة القياس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-10-18T03:32:48.080Z"}'::jsonb),
('mcq', 4, 2, 'تُقاس كمية الأوزون في الستراتوسفير بأجهزة موجودة على الأرض، أو عن طريق بالونات أو أقمار اصطناعية أو صواريخ.', '["لا يمكن رؤية جزيئات الغاز بالمجهر الضوئي العادي ولا عدّها.","لا تُقاس طبقة الأوزون بمسطرة؛ فهي على ارتفاع بين 10 km و50 km.","","ماء المطر لا يُستعمل وحده لقياس كمية الأوزون في الستراتوسفير."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:32:48.080Z"}'::jsonb),
('mcq', 5, 3, 'يستعمل العلماء أجهزة، منها مطياف بريور، لقياس كمية غاز الأوزون في الجو.', '["البارومتر يقيس الضغط الجوي لا كمية الأوزون.","مقياس سرعة الرياح لا يقيس كمية غاز في الجو.","مقياس الحرارة يقيس درجة الحرارة لا كمية الأوزون.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:32:48.080Z"}'::jsonb),
('mcq', 6, 0, 'يُستعمل مطياف الأشعة فوق البنفسجية والمرئية لقياس كمية غاز الأوزون والغازات الأخرى الموجودة في الستراتوسفير.', '["","الجهاز يقيس كميات الغازات ولا يقيس سرعة الرياح.","الجهاز يقيس غازات الستراتوسفير ولا يقيس حرارة سطح الأرض.","الأقمار الاصطناعية من وسائل القياس وليست مما يقيسه المطياف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:32:48.080Z"}'::jsonb),
('mcq', 7, 2, 'المستوى الطبيعي 300 DU، والمقيس 150 DU؛ والفرق 300 − 150 = 150 DU، فهو أقل من المستوى الطبيعي بمقدار 150 DU.', '["القيمة المقيسة أقل من 300 DU فلا يمكن أن تكون أعلى من المستوى الطبيعي.","الفرق يُحسب بطرح 150 من 300 وليس بجمعهما؛ 450 ناتج جمع خاطئ.","","150 DU لا تساوي 300 DU؛ فالمستوى المقيس أقل من الطبيعي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-18T03:32:48.080Z"}'::jsonb),
('essay', 1, null::int, null, null, 'وحدة القياس هي دوبسون ويرمز إليها DU، والمستوى الطبيعي لكمية الأوزون 300 DU. وقد بدأ العالم البريطاني دوبسون القياس في عشرينيات القرن الماضي. ويقيس العلماء الأوزون بأجهزة موجودة على الأرض، أو بالونات، أو أقمار اصطناعية، أو صواريخ.', '["الوحدة: دوبسون (DU)","المستوى الطبيعي: 300 DU","العالم: دوبسون","ثلاث وسائل من: أجهزة أرضية، بالونات، أقمار اصطناعية، صواريخ"]'::jsonb, '[]'::jsonb, '[{"element":"الوحدة دوبسون DU","marks":1},{"element":"المستوى الطبيعي 300 DU","marks":1},{"element":"اسم العالم دوبسون","marks":1},{"element":"ثلاث وسائل للقياس","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة صحيحة عن العناصر الأربعة"},{"level":"2–3 درجات","description":"ثلاثة عناصر صحيحة أو أكثر مع نقص في الوسائل"},{"level":"1 درجة","description":"عنصر واحد أو اثنان صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين وحدة الأوزون DU ووحدة تركيز CFCs وهي ppt","ذكر قيمة غير 300 DU للمستوى الطبيعي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:32:48.080Z"}'::jsonb),
('essay', 2, null::int, null, null, 'مقدار النقص = 300 DU − 195 DU = 105 DU. النسبة المئوية للنقص = (105 ÷ 300) × 100 = 35%. وهذا يدل على أن مستوى الأوزون أقل من المستوى الطبيعي بنحو 35%، أي أن سُمك طبقة الأوزون فوق هذه المنطقة قد تقلّص عن معدله الطبيعي.', '["مقدار النقص 105 DU","النسبة المئوية للنقص 35%","الدلالة: تقلص سُمك طبقة الأوزون عن المعدل الطبيعي"]'::jsonb, '["مقدار النقص = المستوى الطبيعي − المستوى المقيس = 300 DU − 195 DU = 105 DU","النسبة المئوية للنقص = (105 DU ÷ 300 DU) × 100 = 35%","المستوى المقيس أقل من الطبيعي، فسُمك الطبقة فوق المنطقة متقلص"]'::jsonb, '[{"element":"حساب مقدار النقص 105 DU","marks":1},{"element":"حساب النسبة المئوية 35%","marks":1},{"element":"الدلالة على تقلص سُمك الطبقة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"حساب صحيح للمقدار والنسبة مع الدلالة"},{"level":"2 درجة","description":"حساب صحيح لأحدهما مع الدلالة، أو حسابان دون دلالة"},{"level":"1 درجة","description":"خطوة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة 105 على 195 بدل قسمتها على 300 للحصول على النسبة المئوية","جمع القيمتين بدل طرحهما","عدّ المستوى الأقل من 300 DU دليلًا على زيادة الأوزون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-18T03:32:48.081Z"}'::jsonb),
('essay', 3, null::int, null, null, 'القياسات الأرضية تُجرى في مواقع محددة، أما الأقمار الاصطناعية فتقيس كمية الأوزون فوق منطقة واسعة وبوسيلة مستقلة عن الأجهزة الأرضية. وعندما تؤيد قياسات الأقمار القياسات الأرضية التي أظهرت نقصًا كبيرًا (125–200 DU مقابل 300 DU) يزداد الاطمئنان إلى أن النقص حقيقي وليس خطأ في جهاز أو موقع واحد، وأن تناقص سُمك الطبقة يشمل منطقة واسعة؛ لذلك كان تأكيدها مهمًا قبل الاستنتاج بأن الطبقة تتناقص.', '["القياسات الأرضية محدودة بمواقعها","الأقمار الاصطناعية وسيلة مستقلة تشمل منطقة واسعة","التأييد يؤكد أن النقص حقيقي وليس خطأ جهاز أو موقع","أهمية ذلك قبل الاستنتاج بتناقص سُمك الطبقة"]'::jsonb, '[]'::jsonb, '[{"element":"بيان محدودية القياسات الأرضية","marks":1},{"element":"بيان ميزة الأقمار (وسيلة مستقلة وشاملة)","marks":1},{"element":"استنتاج أن التأكيد يعزز الثقة بحقيقة النقص","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تقويم كامل يبيّن محدودية القياس الأرضي وميزة الأقمار وأثرها في الثقة بالنتيجة"},{"level":"2 درجة","description":"تقويم صحيح لعنصرين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الأقمار تقيس بدلًا من الأجهزة الأرضية دون ذكر التأكيد","عدم ربط التأكيد بالثقة في أن النقص حقيقي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:32:48.081Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K1-C1-L1-O05') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
