from (values
('mcq', 1, 'ما السبب الرئيس لتناقص سُمك طبقة الأوزون وفق نموذج مولينا ورولاند؟', null, '["امتصاص الأوزون للأشعة فوق البنفسجية وحده","تفكك الأوزون بفعل ذرات الكلور الناتجة من مركبات CFCs","زيادة كمية الأكسجين في الستراتوسفير","ازدياد تقلبات الطقس في التروبوسفير"]'::jsonb, 'فهم', 'تفسير سبب', 'متوسط', 'الكتاب ص 25 — نموذج مولينا ورولاند (تدمير CFCs للأوزون)'),
('mcq', 2, 'ماذا يحدث لمركب CCl₃F عند وصول الأشعة فوق البنفسجية إليه في الستراتوسفير؟', null, '["تنفصل عنه ذرة الكربون C فقط","يتحول كله إلى أوزون O₃","تنفصل عنه ذرة الكلور Cl","يتحلل إلى أكسجين وماء"]'::jsonb, 'فهم', 'توضيح خطوة', 'سهل', 'الكتاب ص 25 — نموذج مولينا ورولاند (تدمير CFCs للأوزون)'),
('mcq', 3, 'أيّ المعادلات الآتية تمثّل تفاعل ذرة الكلور مع جزيء الأوزون؟', null, '["Cl + O₃ → ClO + O₂","Cl + O₂ → ClO + O","Cl + O₃ → ClO₃","Cl + O → ClO + O₂"]'::jsonb, 'تطبيق', 'اختيار معادلة', 'متوسط', 'الكتاب ص 25 — نموذج مولينا ورولاند (تدمير CFCs للأوزون)'),
('mcq', 4, 'ماذا يحدث لأول أكسيد الكلور ClO بعد تكوّنه في الستراتوسفير؟', null, '["يتحول إلى Cl₂ ويبقى مستقرًا","يتحد مع O₂ ليكوّن الأوزون O₃","يبقى دون تفاعل في الستراتوسفير","يتحد مع ذرة O فيتكوّن O₂ وتتحرر ذرة Cl"]'::jsonb, 'فهم', 'توضيح خطوة', 'صعب', 'الكتاب ص 25 — نموذج مولينا ورولاند (تدمير CFCs للأوزون)'),
('mcq', 5, 'لماذا يمكن لذرة كلور واحدة أن تدمّر عددًا كبيرًا من جزيئات الأوزون؟', null, '["لأنها تُستهلك في كل دورة فتتحول إلى ClO مستقر","لأن كل ذرة كلور تتحول إلى ثلاث ذرات كلور","لأنها تتحرر من جديد في نهاية الدورة فتتحد مع جزيء أوزون آخر","لأنها تذيب الأوزون في الهواء دون أن تتفاعل معه"]'::jsonb, 'تحليل', 'تفسير آلية متكررة', 'صعب', 'الكتاب ص 25 — نموذج مولينا ورولاند (تدمير CFCs للأوزون)'),
('mcq', 6, 'أيّ المواد الآتية تفكك غاز الأوزون في الستراتوسفير إضافة إلى CFCs؟', null, '["غاز النيتروجين N₂","رابع كلوريد الكربون CCl₄","غاز ثاني أكسيد الكربون CO₂","غاز الأرجون Ar"]'::jsonb, 'تذكر', 'تذكر مواد', 'سهل', 'الكتاب ص 30 — وتستمر القصة'),
('mcq', 7, 'ما المقصود بتقلص سُمك طبقة الأوزون الذي يسمى عادة «ثقب الأوزون»؟', null, '["أن فتحة خالية تمامًا من غاز الأوزون ظهرت في الطبقة","أن الطبقة اختفت من الغلاف الجوي كله","أن غاز الأوزون تحول كله إلى غاز الكلور","أن سُمك الطبقة أصبح أقل كثيرًا من المعدل الطبيعي مع بقاء الغاز"]'::jsonb, 'فهم', 'توضيح مصطلح', 'سهل', 'الكتاب ص 17 — تقلص سُمك طبقة الأوزون'),
('essay', 1, 'فسّر كيف تؤدي مركبات CFCs إلى تناقص سُمك طبقة الأوزون، مبيّنًا خطوات التفاعل بالمعادلات (CCl₃F، Cl، O₃، ClO، O).', null, null, 'فهم', 'تفسير آلية بالمعادلات', 'متوسط', 'الكتاب ص 25 — نموذج مولينا ورولاند (تدمير CFCs للأوزون)'),
('essay', 2, 'اذكر مادتين أخريين غير CFCs تفككان غاز الأوزون، ثم وضّح المقصود بتسمية «ثقب الأوزون» ولماذا لا تعني ثقبًا حقيقيًّا.', null, null, 'فهم', 'تعداد وتوضيح مصطلح', 'متوسط', 'الكتاب ص 17، 30'),
('essay', 3, 'تتفاعل ذرة كلور واحدة وفق خطوتين متتاليتين: Cl + O₃ → ClO + O₂ ثم ClO + O → Cl + O₂. إذا تكررت هاتان الخطوتان 5 مرات بذرة الكلور نفسها، فاحسب عدد جزيئات الأوزون المستهلكة وعدد جزيئات الأكسجين O₂ المتكوّنة، وبيّن ماذا يحدث لذرة الكلور في نهاية كل دورة.', null, null, 'تطبيق', 'حساب مع تفسير', 'صعب', 'الكتاب ص 25 — نموذج مولينا ورولاند (تدمير CFCs للأوزون)')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K1-C1-L1-O06') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
