from (values
('mcq', 1, 1, 'تصل CFCs إلى الستراتوسفير فتفصل الأشعة فوق البنفسجية ذرة الكلور، وتدمّر ذرات الكلور جزيئات الأوزون مرة بعد أخرى، فيتناقص سُمك الطبقة.', '["امتصاص الأشعة يحلل الأوزون لكن يعاد تكوّنه فينشأ توازن طبيعي، فلا يفسر تناقص السُمك.","","الأكسجين لا يدمّر الأوزون؛ فهو مادة تكوينه.","الطقس يحدث في التروبوسفير ولا علاقة له بتناقص الأوزون في الستراتوسفير."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:32:48.081Z"}'::jsonb),
('mcq', 2, 2, 'تجعل الأشعة فوق البنفسجية ذرة الكلور Cl تنفصل عن أحد مركبات CFCs مثل CCl₃F.', '["الأشعة تفصل ذرة الكلور لا الكربون عن المركب.","المركب لا يحتوي إلا الكلور والفلور والكربون فلا يتحول إلى أوزون.","","المركب لا يحتوي هيدروجينًا ولا أكسجينًا فلا يعطي ماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:32:48.081Z"}'::jsonb),
('mcq', 3, 0, 'تتحد ذرة الكلور مع جزيء الأوزون فيتكوّن أول أكسيد الكلور ClO وغاز الأكسجين O₂.', '["","هذا تفاعل مع O₂ لا مع O₃، ولا يدمّر الأوزون.","لا يتكوّن ClO₃ في هذه الخطوة، بل ClO وO₂.","المعادلة غير موزونة، ولا يتفاعل الكلور هنا مع ذرة O بل مع الأوزون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.082Z"}'::jsonb),
('mcq', 4, 3, 'يتحد ClO مع ذرة O فيتكوّن O₂ وتتحرر ذرة Cl، ثم تتحد هذه الذرة مع جزيء أوزون آخر وتتكرر العملية.', '["لا يتحول ClO إلى Cl₂، بل تتحرر منه ذرة Cl حرة تتفاعل ثانية.","لو اتحد ClO مع O₂ لتكوّن الأوزون لما تناقص سُمك الطبقة؛ والتفاعل الفعلي مع ذرة O.","ClO يتفاعل مع ذرة O فيحرر الكلور، فلا يبقى دون تفاعل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:32:48.082Z"}'::jsonb),
('mcq', 5, 2, 'ذرة الكلور تتحد مع O₃ فتكوّن ClO، ثم يتحد ClO مع ذرة O فتتحرر ذرة Cl من جديد وتتحد مع جزيء أوزون آخر، فتتكرر العملية.', '["ClO لا يبقى مستقرًا بل يتفاعل مع O فيحرر الكلور.","عدد ذرات الكلور لا يتضاعف؛ بل تتجدد الذرة نفسها.","","الكلور يتفاعل كيميائيًّا مع الأوزون ولا يذيبه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.082Z"}'::jsonb),
('mcq', 6, 1, 'تبيّن أن رابع كلوريد الكربون CCl₄ وميثيل الكلوروفورم والمواد المحتوية على البروم تفكك غاز الأوزون إضافة إلى CFCs.', '["النيتروجين N₂ ليس من المواد المعروفة بتفكيك الأوزون.","","ثاني أكسيد الكربون CO₂ لا يفكك الأوزون في الستراتوسفير.","الأرجون Ar غاز خامل لا يفكك الأوزون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.082Z"}'::jsonb),
('mcq', 7, 3, 'تسمية «ثقب الأوزون» لا تعني ثقبًا حقيقيًّا؛ فغاز الأوزون ما زال موجودًا لكن سُمك الطبقة أقل كثيرًا من المعدل الطبيعي.', '["لا توجد فتحة خالية تمامًا من الأوزون؛ فالغاز ما زال موجودًا بكمية أقل.","الطبقة لم تختف كلها، بل تقلص سُمكها فوق منطقة.","الأوزون لا يتحول إلى كلور؛ فالكلور يدمّره بتفاعلات متكررة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:32:48.082Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تصل CFCs إلى الستراتوسفير فتجعل الأشعة فوق البنفسجية ذرة الكلور تنفصل عنها: CCl₃F → CCl₂F + Cl. ثم تتحد ذرة الكلور مع جزيء أوزون فتتكوّن O₂ وClO: Cl + O₃ → ClO + O₂. بعد ذلك يتحد ClO مع ذرة O فتتكوّن O₂ وتتحرر ذرة Cl: ClO + O → Cl + O₂. وتتحد الذرة المتحررة مع جزيء أوزون آخر فتتكرر العملية، فيتناقص عدد جزيئات الأوزون وسُمك الطبقة.', '["CCl₃F → CCl₂F + Cl بالأشعة فوق البنفسجية","Cl + O₃ → ClO + O₂","ClO + O → Cl + O₂","تتحرر الذرة Cl وتتكرر العملية فيتناقص الأوزون"]'::jsonb, '[]'::jsonb, '[{"element":"انفصال ذرة الكلور عن CCl₃F بالأشعة","marks":1},{"element":"تفاعل Cl مع O₃","marks":1},{"element":"تفاعل ClO مع O وتحرر Cl","marks":1},{"element":"تكرار العملية وتناقص الأوزون","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل بالمعادلات الثلاث وتكرار العملية"},{"level":"2–3 درجات","description":"تفسير صحيح لخطوتين أو ثلاث مع نقص"},{"level":"1 درجة","description":"ذكر خطوة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة معادلات غير موزونة","القول إن الكلور يُستهلك في التفاعل","نسبة تفكك الأوزون إلى الأشعة وحدها دون CFCs"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.082Z"}'::jsonb),
('essay', 2, null::int, null, null, 'من المواد التي تفكك غاز الأوزون إضافة إلى CFCs: رابع كلوريد الكربون CCl₄، وميثيل الكلوروفورم، والمواد المحتوية على البروم. أما «ثقب الأوزون» فتسمية لتقلص سُمك طبقة الأوزون، وهو ليس ثقبًا حقيقيًّا؛ لأن غاز الأوزون ما زال موجودًا، لكن سُمك الطبقة أقل كثيرًا من المعدل الطبيعي.', '["مادة أولى مفككة للأوزون (CCl₄ مثلًا)","مادة ثانية (ميثيل الكلوروفورم أو مركبات البروم)","الثقب هو تقلص سُمك الطبقة","الأوزون ما زال موجودًا لكن بسُمك أقل كثيرًا من المعدل الطبيعي"]'::jsonb, '[]'::jsonb, '[{"element":"المادة الأولى","marks":1},{"element":"المادة الثانية","marks":1},{"element":"توضيح أن التسمية تعني تقلص سُمك الطبقة","marks":1},{"element":"بيان بقاء الأوزون بكمية أقل من المعدل الطبيعي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مادتان صحيحتان وتوضيح كامل للتسمية"},{"level":"2–3 درجات","description":"مادتان مع توضيح ناقص، أو توضيح كامل مع مادة واحدة"},{"level":"1 درجة","description":"عنصر واحد أو اثنان صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر مواد لا تفكك الأوزون كالنيتروجين","القول إن الطبقة تحتوي فتحة خالية تمامًا من الأوزون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.083Z"}'::jsonb),
('essay', 3, null::int, null, null, 'في الدورة الواحدة يُستهلك جزيء أوزون واحد في الخطوة الأولى، ويتكوّن جزيء O₂ في كل من الخطوتين أي جزيئا O₂. وفي 5 دورات يُستهلك 5 جزيئات من الأوزون ويتكوّن 10 جزيئات من O₂. أما ذرة الكلور فتتحرر من جديد في نهاية كل دورة ولا تُستهلك، ولذلك تستطيع تدمير جزيء أوزون آخر في الدورة التالية.', '["5 جزيئات أوزون تُستهلك","10 جزيئات O₂ تتكوّن","ذرة الكلور تتحرر ولا تُستهلك"]'::jsonb, '["في كل دورة يُستهلك جزيء O₃ واحد (الخطوة الأولى)","في كل دورة يتكوّن جزيئا O₂ (واحد من كل خطوة): 1 + 1 = 2","عدد جزيئات الأوزون المستهلكة في 5 دورات = 5 × 1 = 5","عدد جزيئات O₂ المتكوّنة في 5 دورات = 5 × 2 = 10","ذرة Cl تتكوّن من جديد في الخطوة الثانية فتبقى دون استهلاك"]'::jsonb, '[{"element":"عدد جزيئات الأوزون المستهلكة 5","marks":1},{"element":"عدد جزيئات O₂ المتكوّنة 10","marks":2},{"element":"ذرة الكلور تتحرر ولا تُستهلك","marks":1},{"element":"ذكر خطوات الحساب لكل دورة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حساب صحيح للعددين مع بيان مصير ذرة الكلور وخطوات الحساب"},{"level":"3–4 درجات","description":"حساب صحيح لأحد العددين مع بيان مصير الكلور"},{"level":"1–2 درجة","description":"خطوة صحيحة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب جزيء O₂ واحد فقط لكل دورة","القول إن ذرة الكلور تُستهلك في كل دورة","عدّ ذرة O المتفاعلة جزيء أوزون مستهلكًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.083Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
