('mcq', 1, 2, 'الأمونيا غاز ضار قد تتسرب أبخرته من الثلاجة وتؤذي أفراد البيت، فبحث الكيميائيون عن مبردات أكثر أمنًا.', '["الأمونيا استُعملت فعلًا في التبريد، فالمشكلة ليست في عجزها عن التبريد.","السعر ليس سبب البحث عن بدائل؛ بل خطر تسرب الأبخرة.","","سبب البحث كان سمية الأمونيا لا تفكيكها للأوزون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:32:48.084Z"}'::jsonb),
('mcq', 2, 1, 'CFCs غير سامة لأنها لا تتفاعل مباشرة مع المواد الأخرى، فكانت مبردات مثالية.', '["تفاعلها مع الأوزون ضرر بيئي لا يفسر عدم سميتها.","","CFCs مكوّنة من الكلور والفلور والكربون، أي من ثلاثة عناصر.","هذه المركبات مواد مصنعة تحضَّر في المختبر ولا توجد طبيعيًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:32:48.084Z"}'::jsonb),
('mcq', 3, 3, 'حضّر العالم توماس ميجلي عام 1928م أول مركّب من مركبات CFCs.', '["مولينا وضع مع رولاند نموذج تدمير CFCs للأوزون.","رولاند شارك في وضع نموذج تدمير CFCs للأوزون.","دوبسون بدأ قياس كمية الأوزون ولم يحضّر CFCs.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:32:48.084Z"}'::jsonb),
('mcq', 4, 0, 'بدأ استعمال هذه المواد في صناعة أجهزة التكييف المنزلية والثلاجات عام 1935م.', '["","عام 1928م حُضّر أول مركّب من CFCs ولم يبدأ استعماله بعد.","عام 1987م وُقّع ميثاق مونتريال لإنهاء استعمال هذه المركبات.","عام 1995م وصلت كميات CFCs في الجو إلى مستوى عالٍ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:32:48.084Z"}'::jsonb),
('mcq', 5, 1, 'الأمونيا غاز ضار قد تؤذي أبخرته أفراد البيت عند تسربها، أما CFCs فغير سامة لأنها لا تتفاعل مباشرة مع المواد الأخرى.', '["العبارة معكوسة؛ فالأمونيا هي الضارة وCFCs غير سامة.","","ليست كل المبردات ضارة؛ فCFCs غير سامة.","المبردات قد تتسرب من الثلاجة، وهذا سبب البحث عن مبردات أكثر أمنًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:32:48.084Z"}'::jsonb),
('mcq', 6, 3, 'استُعملت CFCs في تصنيع البوليمرات وفي دفع الرذاذ من علب الرش كما في علب ملطفات الجو وعلب المبيدات الحشرية المنزلية.', '["لم تُستعمل CFCs في تنقية المياه.","صناعة الزجاج لا تعتمد على CFCs.","CFCs ليست أسمدة ولا تُستعمل في تسميد التربة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:32:48.084Z"}'::jsonb),
('mcq', 7, 0, 'تُستعمل الثلاجات في حفظ الأطعمة من التلف، وهذا من الراحة والرفاهية التي توفرها الكيمياء.', '["","الثلاجة لا تنقي الهواء من الغبار.","الثلاجة تستهلك الكهرباء ولا تولدها.","الثلاجة تحفظ الأطعمة ولا تحوّلها إلى مواد أخرى."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-18T03:32:48.084Z"}'::jsonb),
('essay', 1, null::int, null, null, 'كانت الثلاجات تستعمل في البداية غازات ضارة كالأمونيا للتبريد، وقد تتسرب أبخرتها من الثلاجة فتؤذي أفراد البيت؛ فبدأ الكيميائيون البحث عن مبردات أكثر أمنًا. وحضّر توماس ميجلي عام 1928م أول مركّب من CFCs، وهي غير سامة لأنها لا تتفاعل مباشرة مع المواد الأخرى، فظهر أنها مبردات مثالية، وبدأ استعمالها في صناعة الثلاجات وأجهزة التكييف المنزلية عام 1935م.', '["الأمونيا غاز ضار قد تتسرب أبخرته وتؤذي أفراد البيت","البحث عن مبردات أكثر أمنًا (ميجلي 1928م)","CFCs غير سامة","لأنها لا تتفاعل مباشرة مع المواد الأخرى فهي مبردات مثالية"]'::jsonb, '[]'::jsonb, '[{"element":"خطر الأمونيا بتسرب أبخرتها","marks":1},{"element":"البحث عن مبردات أكثر أمنًا وتحضير CFCs","marks":1},{"element":"عدم سمية CFCs","marks":1},{"element":"تعليل ذلك بعدم تفاعلها مباشرة مع المواد الأخرى","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل للأسباب الأربعة"},{"level":"2–3 درجات","description":"ثلاثة أسباب صحيحة"},{"level":"1 درجة","description":"سبب أو سببان فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الأمونيا لا تبرّد","تعليل عدم السمية بوجود CFCs في الطبيعة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:32:48.085Z"}'::jsonb),
('essay', 2, null::int, null, null, 'من استعمالات CFCs: صناعة أجهزة التكييف المنزلية، وصناعة الثلاجات، وتصنيع البوليمرات، ودفع الرذاذ من علب الرش كعلب ملطفات الجو وعلب المبيدات الحشرية. ويرتبط بالتبريد استعمالها في الثلاجات وأجهزة التكييف، وفائدة الثلاجات حفظ الأطعمة من التلف، وفائدة المكيفات توفير الراحة في المنازل والمدارس وأماكن العمل.', '["ثلاثة استعمالات صحيحة","الاستعمالات المرتبطة بالتبريد: الثلاجات وأجهزة التكييف","فائدة التبريد: حفظ الأطعمة أو توفير الراحة"]'::jsonb, '[]'::jsonb, '[{"element":"ثلاثة استعمالات صحيحة","marks":2},{"element":"تحديد الاستعمالات المرتبطة بالتبريد","marks":1},{"element":"فائدة التبريد للناس","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"ثلاثة استعمالات صحيحة مع تحديد التبريد وفائدته"},{"level":"2–3 درجات","description":"استعمالان مع التحديد والفائدة، أو ثلاثة استعمالات دون الفائدة"},{"level":"1 درجة","description":"استعمال واحد أو فائدة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الأمونيا من استعمالات CFCs","ذكر استعمالات لا ترتبط بالمركبات كتنقية المياه"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:32:48.085Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة صحيحة جزئيًّا فقط. فصحيح أن CFCs غير سامة لأنها لا تتفاعل مباشرة مع المواد الأخرى، ولذلك كانت أكثر أمنًا من الأمونيا في البيوت، وقد ظنّ العلماء أنها لا تشكل خطرًا على البيئة. لكن تبيّن لاحقًا أنها تصل إلى الستراتوسفير فتفصل الأشعة فوق البنفسجية ذرة الكلور منها، وتدمّر ذرة الكلور جزيئات الأوزون مرة بعد أخرى فيتناقص سُمك طبقة الأوزون. لذلك لا تُعدّ آمنة للبيئة، ووقّعت الدول ميثاق مونتريال لإنهاء استعمالها.', '["CFCs غير سامة ولا تتفاعل مباشرة، لذا كانت آمنة في البيوت","تصل CFCs إلى الستراتوسفير وتتحرر ذرة Cl بالأشعة","الكلور يدمّر الأوزون فيتناقص سُمك الطبقة","الحكم: العبارة غير صحيحة لأنها ضارة بالبيئة"]'::jsonb, '[]'::jsonb, '[{"element":"بيان الجزء الصحيح من العبارة (عدم السمية)","marks":1},{"element":"ذكر دور الكلور المتحرر في تدمير الأوزون","marks":1},{"element":"ربط ذلك بتناقص سُمك طبقة الأوزون","marks":1},{"element":"الحكم بأن العبارة غير صحيحة كليًّا","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تقويم كامل يبيّن الصحيح من العبارة وسبب عدم أمانها للبيئة"},{"level":"2–3 درجات","description":"تقويم صحيح ينقصه ربط بتناقص الأوزون أو الحكم"},{"level":"1 درجة","description":"حكم صحيح دون تعليل كافٍ"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول العبارة كما هي","رفضها دون الاعتراف بعدم سمية CFCs","الخلط بين عدم السمية للإنسان والأمان للبيئة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:32:48.085Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
