('mcq', 1, 'في أي عام اجتمع زعماء عدة دول في مونتريال بكندا ووقّعوا ميثاق مونتريال؟', null, '["1928م","1987م","2005م","2012م"]'::jsonb, 'تذكر', 'تذكر حقيقة', 'سهل', 'الكتاب ص 30 — ميثاق مونتريال'),
('mcq', 2, 'ما الهدف الرئيس من اجتماع زعماء الدول في مونتريال عام 1987م؟', null, '["إنهاء استعمال مركبات CFCs ووضع قيود على كيفية استعمالها","تشجيع استعمال مركبات CFCs بدلًا من الأمونيا في الثلاجات","توحيد أجهزة قياس كمية الأوزون المستعملة في دول العالم","تحديد الدولة المسؤولة عن ثقب الأوزون ومحاسبتها"]'::jsonb, 'فهم', 'توضيح هدف', 'سهل', 'الكتاب ص 30 — ميثاق مونتريال'),
('mcq', 3, 'لماذا تصدّت دول كثيرة لمشكلة تناقص طبقة الأوزون؟', null, '["لأن مركبات CFCs سامة تضر بالإنسان عند استنشاقها","لأن طبقة الأوزون تمنع وصول حرارة الشمس إلى سطح الأرض","لأن تناقص الأوزون يسمح بوصول مزيد من الأشعة فوق البنفسجية الضارة إلى الأرض","لأن نقص الأوزون يحرم المخلوقات الحية من الأكسجين اللازم للتنفس"]'::jsonb, 'فهم', 'تعليل سبب', 'سهل', 'الكتاب ص 15 و30 — طبقة الأوزون، ميثاق مونتريال'),
('mcq', 4, 'أيّ العبارات الآتية تصف مشاركة المملكة العربية السعودية في معالجة مشكلة تناقص طبقة الأوزون؟', null, '["غابت عن اجتماع مونتريال ولم تنضم إلى أي نظام يخص المواد المستنفذة للأوزون","حضرت اجتماع مونتريال لكنها امتنعت عن التوقيع على الميثاق المتفق عليه","اقتصر دورها على قياس كمية الأوزون فوق أراضيها وإعلان نتائجها للعالم","وقّعت الميثاق ووافقت مع دول الخليج على نظام موحد لإحلال بدائل آمنة"]'::jsonb, 'فهم', 'توضيح دور', 'متوسط', 'الكتاب ص 30 — ميثاق مونتريال'),
('mcq', 5, 'ما أحد الأهداف التي يسعى إليها النظام الموحد لدول مجلس التعاون الخليجي بشأن المواد المستنفذة لطبقة الأوزون (المعدّل 2012م)؟', null, '["التخلص التام من استهلاك هذه المواد وإحلال بدائل آمنة محلها","الاكتفاء بتقليل إنتاج هذه المواد دون البحث عن بدائل لها","زيادة تصدير هذه المواد إلى الدول التي لم توقّع الميثاق","منع استعمال الثلاجات وأجهزة التكييف في دول المجلس"]'::jsonb, 'تذكر', 'تذكر هدف', 'متوسط', 'الكتاب ص 30 — ميثاق مونتريال'),
('mcq', 6, 'قررت شركة تصنّع الثلاجات وأجهزة التكييف الالتزام بهدف ميثاق مونتريال. أيّ الإجراءات الآتية يحقق هذا الالتزام؟', null, '["رفع إنتاج مركبات CFCs لأنها غير سامة للإنسان","نقل استعمال مركبات CFCs من الثلاجات إلى علب الرش فقط","استبدال مركبات CFCs في أجهزتها بمواد بديلة آمنة على الأوزون","الاستمرار في استعمال CFCs مع الإعلان عن عدم سميتها"]'::jsonb, 'تطبيق', 'تطبيق الهدف على موقف', 'صعب', 'الكتاب ص 30 — ميثاق مونتريال'),
('mcq', 7, 'بعد توقيع ميثاق مونتريال تراجع الاستهلاك العالمي لمركبات CFCs، بينما لم تتقلص كمياتها فوق القارة المتجمدة الجنوبية مباشرة. أيّ الاستنتاجات الآتية أنسب؟', null, '["الميثاق لم يؤثر في استعمال هذه المركبات في العالم","خفض الاستعمال العالمي لا ينعكس فورًا على كمية CFCs الموجودة في الجو","كمية CFCs فوق القارة تتحدد باستهلاك دول القارة وحدها","مركبات CFCs تتحلل كلها في الجو بمجرد توقف استعمالها"]'::jsonb, 'تحليل', 'استنتاج من بيانات', 'صعب', 'الكتاب ص 30 — ميثاق مونتريال (الاستهلاك العالمي لـ CFCs وكمياتها فوق القارة)'),
('essay', 1, 'وضّح الهدف من اجتماع زعماء الدول في مونتريال عام 1987م، مبيّنًا ما الذي نصّ عليه الميثاق الذي وقّعوه.', null, null, 'فهم', 'توضيح هدف', 'متوسط', 'الكتاب ص 30 — ميثاق مونتريال'),
('essay', 2, 'اشرح العلاقة بين تناقص طبقة الأوزون واجتماع زعماء الدول في مونتريال، ثم بيّن ما الذي يضيفه النظام الموحد لدول مجلس التعاون الخليجي (المعدّل 2012م) إلى هدف الميثاق.', null, null, 'فهم', 'شرح علاقة', 'متوسط', 'الكتاب ص 30 — ميثاق مونتريال، النظام الموحد لدول مجلس التعاون'),
('essay', 3, 'بيّنت بيانات الفترة 1980–2000م أن الاستهلاك العالمي لمركبات CFCs ظل مرتفعًا حتى نحو عام 1987م ثم تراجع بشدة بعد ذلك، بينما استمر تركيز CFCs فوق القارة المتجمدة الجنوبية في الارتفاع قبل أن يستقر عند مستوى مرتفع دون أن يتقلص مباشرة. قال طالب: «ميثاق مونتريال لم يحقق هدفه». قوّم قول الطالب، موضحًا الدليل على أثر الميثاق وما يحتاج إلى وقت.', null, null, 'تقويم', 'تقويم ادعاء من بيانات', 'صعب', 'الكتاب ص 30 و32 — ميثاق مونتريال، عودة طبقة الأوزون')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K1-C1-L1-O08') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'اجتمع زعماء الدول في مونتريال بكندا عام 1987م، ووقّعوا الميثاق الذي يقضي بإنهاء استعمال مركبات CFCs ووضع قيود على كيفية استعمالها.', '["1928م هو العام الذي حضّر فيه ميجلي أول مركب من مركبات CFCs، وليس عام الميثاق.","","2005م هو العام الذي وصل فيه سمك طبقة الأوزون فوق القارة المتجمدة الجنوبية إلى أقل مستوى له، وليس عام الميثاق.","2012م هو عام تعديل النظام الموحد لدول مجلس التعاون الخليجي بشأن المواد المستنفذة لطبقة الأوزون، وليس عام الميثاق."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:32:48.085Z"}'::jsonb),
('mcq', 2, 0, 'لأن تناقص طبقة الأوزون أصبح موضع اهتمام العالم، اجتمع الزعماء ووقّعوا ميثاقًا يقضي بإنهاء استعمال مركبات CFCs ووضع قيود على كيفية استعمالها.', '["","هذا عكس الهدف؛ فقد استُعملت CFCs بدلًا من الأمونيا في الثلاجات قبل اكتشاف أضرارها، أما الميثاق فجاء لإنهاء استعمالها.","لم يكن الاجتماع لتوحيد أجهزة القياس، بل لمعالجة تناقص الأوزون بإنهاء استعمال المركبات المسببة له.","الميثاق لا يحاسب دولة بعينها؛ وإنما اتفقت الدول الموقّعة على إنهاء استعمال هذه المركبات وتقييدها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-10-18T03:32:48.086Z"}'::jsonb),
('mcq', 3, 2, 'يمتص غاز الأوزون معظم الأشعة فوق البنفسجية الضارة قبل وصولها إلى الأرض؛ فتناقصه يعني وصول مزيد منها يضر بالإنسان والنباتات والحيوان، ولذلك أصبح موضع اهتمام العالم.', '["مركبات CFCs غير سامة لأنها لا تتفاعل مباشرة مع المواد الأخرى؛ وضررها في تفكيك الأوزون وليس في سميتها.","الأوزون يمتص الأشعة فوق البنفسجية الضارة ولا يمنع الحرارة؛ فالقلق من وصول هذه الأشعة وليس من الحرارة.","","الأوزون O₃ ليس الغاز الذي يتنفسه الإنسان؛ فنقصه لا يحرم الكائنات من الأكسجين، لكنه يزيد وصول الأشعة فوق البنفسجية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:32:48.086Z"}'::jsonb),
('mcq', 4, 3, 'كانت المملكة العربية السعودية من بين الدول التي اجتمع زعماؤها في مونتريال ووقّعت الميثاق، كما وافقت دول مجلس التعاون الخليجي على نظام موحد بشأن المواد المستنفذة لطبقة الأوزون لإحلال البدائل الآمنة.', '["المملكة كانت بين الدول التي اجتمعت في مونتريال، ووافقت كذلك على النظام الخليجي الموحد.","المملكة وقّعت الميثاق مع الدول الأخرى ولم تمتنع عن التوقيع.","لم يقتصر دورها على القياس؛ فقد وقّعت الميثاق ووافقت على نظام موحد لإحلال البدائل الآمنة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:32:48.086Z"}'::jsonb),
('mcq', 5, 0, 'من أهداف النظام الموحد المعدّل عام 2012م التخلص التام من استهلاك المواد المستنفذة لطبقة الأوزون وإحلال البدائل الآمنة، بما يتوافق مع بروتوكول مونتريال.', '["","الهدف هو التخلص التام من الاستهلاك وإحلال البدائل الآمنة، وليس الاكتفاء بتقليل الإنتاج دون بدائل.","زيادة التصدير تخالف هدف الميثاق القاضي بإنهاء استعمال هذه المواد.","النظام لا يمنع الأجهزة نفسها، بل يحل مواد بديلة آمنة محل المواد المستنفذة للأوزون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-18T03:32:48.086Z"}'::jsonb),
('mcq', 6, 2, 'هدف الميثاق إنهاء استعمال مركبات CFCs ووضع قيود على كيفية استعمالها؛ لذلك يتحقق الالتزام باستبدالها بمواد بديلة آمنة على طبقة الأوزون.', '["عدم سمية CFCs لا يبرر زيادة إنتاجها؛ فالميثاق يقضي بإنهاء استعمالها لأنها تتفكك فتقلل الأوزون.","نقل الاستعمال إلى علب الرش يبقي المركبات في الجو؛ والميثاق يقضي بإنهاء استعمالها لا بتغيير مجال استعمالها.","","الاستمرار في الاستعمال يخالف الميثاق، والمشكلة ليست في السمية بل في تأثيرها في طبقة الأوزون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:32:48.086Z"}'::jsonb),
('mcq', 7, 1, 'تراجع الاستهلاك بعد الميثاق يدل على أنه أثّر في الاستعمال، أما بقاء الكمية فوق القارة دون تقلص مباشر فيدل على أن أثر خفض الاستعمال في الجو لا يظهر فورًا.', '["تراجع الاستهلاك العالمي بعد الميثاق يدل على أنه أثّر في الاستعمال فعلًا.","","المركبات تنتشر في الجو فوق القارة من استعمالها العالمي، ولا تعتمد على استهلاك دول القارة وحدها.","لو تحللت كلها فور توقف الاستعمال لتقلصت كميتها فوق القارة مباشرة، لكن البيانات تبين أنها لم تتقلص مباشرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:32:48.087Z"}'::jsonb),
('essay', 1, null::int, null, null, 'لأن تناقص طبقة الأوزون أصبح موضع اهتمام العالم، اجتمع زعماء عدة دول (منها المملكة العربية السعودية) في مونتريال بكندا عام 1987م لمعالجة هذه المشكلة. ووقّعوا ميثاق مونتريال الذي يقضي، بموافقة الدول الموقّعة، بإنهاء استعمال مركبات CFCs ووضع قيود على كيفية استعمالها.', '["اجتمع الزعماء لمواجهة مشكلة تناقص طبقة الأوزون","الميثاق يقضي بإنهاء استعمال مركبات CFCs","ووضع قيود على كيفية استعمالها بموافقة الدول الموقّعة"]'::jsonb, '[]'::jsonb, '[{"element":"ربط الاجتماع بمشكلة تناقص طبقة الأوزون","marks":1},{"element":"إنهاء استعمال مركبات CFCs","marks":1},{"element":"وضع قيود على كيفية استعمالها بموافقة الدول الموقّعة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"ذكر المشكلة التي جمعت الزعماء، وإنهاء استعمال CFCs، ووضع القيود على استعمالها"},{"level":"2 درجتان","description":"ذكر عنصرين صحيحين من العناصر الثلاثة"},{"level":"1 درجة","description":"ذكر عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الهدف هو قياس كمية الأوزون أو اكتشاف ثقبه","ذكر إنهاء الاستعمال دون القيود، أو العكس","الخلط بين ميثاق مونتريال والنظام الخليجي الموحد المعدّل عام 2012م"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-10-18T03:32:48.087Z"}'::jsonb),
('essay', 2, null::int, null, null, 'يمتص الأوزون معظم الأشعة فوق البنفسجية الضارة، ولما أصبح تناقصه موضع اهتمام العالم اجتمع الزعماء في مونتريال ووقّعوا ميثاقًا يقضي بإنهاء استعمال مركبات CFCs ووضع قيود على استعمالها. وجاء النظام الموحد لدول مجلس التعاون الخليجي (المعدّل عام 2012م) ليوافق بروتوكول مونتريال، وأحد أهدافه التخلص التام من استهلاك المواد المستنفذة لطبقة الأوزون وإحلال البدائل الآمنة محلها.', '["تناقص الأوزون يزيد وصول الأشعة فوق البنفسجية الضارة وأصبح موضع اهتمام العالم","الاجتماع أنتج ميثاقًا لإنهاء استعمال CFCs وتقييده","النظام الخليجي الموحد يوافق بروتوكول مونتريال","هدفه التخلص التام من استهلاك المواد المستنفذة وإحلال البدائل الآمنة"]'::jsonb, '[]'::jsonb, '[{"element":"ربط تناقص الأوزون بالاهتمام العالمي والاجتماع","marks":1},{"element":"نص الميثاق: إنهاء استعمال CFCs وتقييده","marks":1},{"element":"النظام الخليجي الموحد وتوافقه مع بروتوكول مونتريال","marks":1},{"element":"التخلص التام من الاستهلاك وإحلال البدائل الآمنة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"شرح العلاقة بين تناقص الأوزون والاجتماع ونص الميثاق، وذكر النظام الخليجي وهدفه كاملًا"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة من العناصر الأربعة"},{"level":"1–2 درجة","description":"عنصر أو عنصران صحيحان فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ النظام الخليجي بديلًا عن ميثاق مونتريال لا متوافقًا معه","إغفال هدف إحلال البدائل الآمنة","نسبة ميثاق مونتريال إلى عام 2012م"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-18T03:32:48.087Z"}'::jsonb),
('essay', 3, null::int, null, null, 'قول الطالب غير دقيق. فالدليل على أثر الميثاق أن الاستهلاك العالمي لمركبات CFCs تراجع بشدة بعد توقيعه عام 1987م، وهذا ما يهدف إليه الميثاق من إنهاء الاستعمال وتقييده. أما بقاء تركيز CFCs فوق القارة المتجمدة دون تقلص مباشر فيدل على أن أثر خفض الاستعمال في كمية المركبات الموجودة في الجو لا يظهر فورًا، وأن استعادة الطبقة لوضعها تحتاج إلى وقت طويل، إذ توقع العلماء عودتها إلى وضعها نحو عام 2050م، وتتوقع النماذج الحديثة ألا يكون ذلك قبل عام 2068م، مع استمرار الجهود الدولية.', '["الحكم: قول الطالب غير دقيق","الدليل: تراجع الاستهلاك العالمي بشدة بعد 1987م","بقاء كمية CFCs فوق القارة دون تقلص مباشر لا يعني فشل الميثاق","أثر خفض الاستعمال في الجو بطيء ويحتاج إلى وقت (عودة الطبقة متوقعة بعد عشرات السنين)"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم على قول الطالب بأنه غير دقيق","marks":1},{"element":"الاستدلال بتراجع الاستهلاك العالمي بعد الميثاق","marks":1},{"element":"تفسير بقاء كمية CFCs فوق القارة دون تقلص مباشر","marks":1},{"element":"بيان أن التعافي يحتاج إلى وقت طويل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح معلل بتراجع الاستهلاك، مع تفسير بقاء الكمية وحاجة التعافي إلى وقت"},{"level":"3 درجات","description":"حكم صحيح مع دليلين من الأدلة الثلاثة"},{"level":"1–2 درجة","description":"حكم صحيح دون تعليل كافٍ، أو دليل واحد فقط"},{"level":"صفر","description":"تأييد قول الطالب أو إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ بقاء كمية CFCs فوق القارة دليلًا على فشل الميثاق","إغفال بيانات تراجع الاستهلاك العالمي","الاعتقاد أن CFCs تختفي من الجو بمجرد توقف استعمالها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:32:48.088Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
