from (values
('mcq', 1, 'في أي فصل من فصول السنة يتكوّن ثقب الأوزون سنويًا فوق القارة المتجمدة الجنوبية؟', null, '["الصيف","الخريف","الشتاء","الربيع"]'::jsonb, 'تذكر', 'تذكر حقيقة', 'سهل', 'الكتاب ص 31 — ثقب الأوزون حاليًا'),
('mcq', 2, 'عند أي درجة حرارة تتكوّن الغيوم الجليدية في الستراتوسفير فوق القارة المتجمدة الجنوبية؟', null, '["0 °C","−78 °C","−18 °C","78 °C"]'::jsonb, 'تذكر', 'تذكر قيمة', 'سهل', 'الكتاب ص 31 — ثقب الأوزون حاليًا'),
('mcq', 3, 'ما الدور الذي تؤديه الغيوم الجليدية في تكوّن ثقب الأوزون؟', null, '["تحدث فيها تغيرات تساعد على إنتاج كلور وبروم نشطين كيميائيًا","تمتص CFCs من الجو فتقل كميتها فوق القارة المتجمدة","تحوّل غاز الأوزون مباشرة إلى جليد فتقل كميته","تمنع وصول الأشعة فوق البنفسجية إلى القارة المتجمدة"]'::jsonb, 'فهم', 'توضيح دور', 'سهل', 'الكتاب ص 31 — ثقب الأوزون حاليًا'),
('mcq', 4, 'لماذا يبدأ تناقص الأوزون الشديد فوق القارة المتجمدة الجنوبية عند حلول الربيع؟', null, '["لأن الغيوم الجليدية لا تتكون إلا في فصل الربيع","لأن مركبات CFCs تنتج في الربيع فقط","لأن ارتفاع الحرارة يجعل الكلور والبروم النشطين يبدآن التفاعل مع الأوزون","لأن أشعة الشمس تغيب تمامًا عن القارة في الربيع"]'::jsonb, 'فهم', 'تعليل سبب', 'متوسط', 'الكتاب ص 31 — ثقب الأوزون حاليًا'),
('mcq', 5, 'أيّ مما يأتي يمثل العوامل التي تستثير تكوّن ثقب الأوزون فوق القارة القطبية الجنوبية؟', null, '["ارتفاع الحرارة فوق −78 °C في الشتاء وتكوّن غيوم جليدية","انخفاض الحرارة إلى −78 °C وتكوّن غيوم جليدية، ثم ارتفاعها في الربيع","أشعة الشمس العمودية القوية وتيارات الهواء في الستراتوسفير","زيادة تركيز غاز الأكسجين مع انخفاض الضغط الجوي"]'::jsonb, 'فهم', 'تحديد عوامل', 'متوسط', 'الكتاب ص 31 — ثقب الأوزون حاليًا (ماذا قرأت؟)'),
('mcq', 6, 'تبيّن البيانات التقريبية الآتية درجة الحرارة وكمية الأوزون على ارتفاع 20–24 km فوق القارة المتجمدة الجنوبية في أشهر مختلفة. أيّ الاستنتاجات الآتية تتفق مع البيانات وما يعرف عن تكوّن الثقب؟', '{"headers":["الشهر","درجة الحرارة (°C)","كمية الأوزون (DU)"],"rows":[["يناير","−35","300"],["أبريل","−60","270"],["يوليو","−88","250"],["سبتمبر","−70","110"],["ديسمبر","−42","320"]]}'::jsonb, '["سُجلت أقل كمية أوزون عند أخفض درجة حرارة","بقيت كمية الأوزون ثابتة تقريبًا طوال السنة","انخفضت كمية الأوزون إلى أدناها بعد أن بدأت الحرارة بالارتفاع من أخفض قيمة لها","ارتفعت كمية الأوزون كلما ارتفعت درجة الحرارة"]'::jsonb, 'تحليل', 'تفسير بيانات', 'صعب', 'الكتاب ص 31–32 — ثقب الأوزون حاليًا، مختبر تحليل البيانات'),
('mcq', 7, 'قال طالب: «يتكوّن فوق القطب الشمالي ثقب أوزون بحجم الثقب فوق القارة المتجمدة الجنوبية نفسه». أيّ التقويمات الآتية لقوله صحيح؟', null, '["صحيح؛ لأن الغيوم الجليدية تتكوّن فوق القطبين بالقدر نفسه","غير صحيح؛ لأن الأوزون لا يتناقص فوق القطب الشمالي إطلاقًا","غير صحيح؛ لأن CFCs لا تصل إلى الجو فوق القطب الشمالي","غير صحيح؛ لأن الحرارة فوق القطب الشمالي لا تبقى منخفضة مدة كافية فيكون النقص أقل"]'::jsonb, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 31 — ثقب الأوزون حاليًا'),
('essay', 1, 'وضّح العوامل التي تستثير تكوّن ثقب الأوزون سنويًا فوق القارة المتجمدة الجنوبية.', null, null, 'فهم', 'توضيح عوامل', 'متوسط', 'الكتاب ص 31 — ثقب الأوزون حاليًا'),
('essay', 2, 'يحدث تناقص لغاز الأوزون فوق القطبين الشمالي والجنوبي، لكن الثقب الأكبر يتكوّن فوق القارة المتجمدة الجنوبية. فسّر ذلك.', null, null, 'فهم', 'تفسير فرق', 'متوسط', 'الكتاب ص 31 — ثقب الأوزون حاليًا'),
('essay', 3, 'سجّل باحثون عند ارتفاع 20–24 km فوق القارة المتجمدة الجنوبية البيانات الآتية: في يوليو كانت الحرارة −88 °C وكمية الأوزون 250 DU، وفي سبتمبر كانت الحرارة −70 °C وكمية الأوزون 110 DU، وفي ديسمبر كانت الحرارة −42 °C وكمية الأوزون 320 DU. حلّل هذه البيانات: ما الشهر الذي تقل فيه كمية الأوزون إلى أدنى مستوى، وكيف تفسر ذلك بالعوامل التي تستثير تكوّن الثقب؟ وما دلالة عودة الكمية إلى 320 DU في ديسمبر؟', null, null, 'تحليل', 'تحليل بيانات وتفسير', 'صعب', 'الكتاب ص 31–32 — ثقب الأوزون حاليًا، مختبر تحليل البيانات')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
