from (values
('mcq', 1, 3, 'يتكوّن ثقب الأوزون سنويًا فوق القارة المتجمدة الجنوبية في فصل الربيع، عندما ترتفع درجة الحرارة فيبدأ الكلور والبروم النشطان التفاعل مع الأوزون.', '["في الصيف تكون الحرارة مرتفعة ولا تتكون الغيوم الجليدية التي تنتج الكلور والبروم النشطين.","الخريف ليس الفصل الذي يبدأ فيه التفاعل مع الأوزون؛ فارتفاع الحرارة الذي يحفزه يحدث في الربيع.","في الشتاء تتكوّن الغيوم الجليدية وينتج الكلور والبروم النشطان، لكن تفاعلهما مع الأوزون يبدأ عند ارتفاع الحرارة في الربيع.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-18T03:32:48.088Z"}'::jsonb),
('mcq', 2, 1, 'تتكوّن الغيوم الجليدية في طبقة الستراتوسفير فوق القارة المتجمدة الجنوبية عندما تنخفض درجة الحرارة إلى −78 °C.', '["0 °C هي درجة تجمد الماء عند سطح الأرض، أما الغيوم الجليدية في الستراتوسفير فتحتاج إلى حرارة أقل بكثير.","","−18 °C أعلى بكثير من الحرارة اللازمة لتكوّن هذه الغيوم.","78 °C درجة حرارة موجبة مرتفعة؛ أما الغيوم الجليدية فتتكوّن عند حرارة سالبة هي −78 °C."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-18T03:32:48.089Z"}'::jsonb),
('mcq', 3, 0, 'تحدث في الغيوم الجليدية تغيرات تساعد على إنتاج كلور وبروم نشطين كيميائيًا، ثم يتفاعل هذان العنصران مع الأوزون عند ارتفاع الحرارة في الربيع فيتناقص.', '["","الغيوم الجليدية لا تزيل CFCs من الجو، بل تساعد على إنتاج الكلور والبروم النشطين اللذين يفككان الأوزون.","الأوزون لا يتحول إلى جليد؛ وإنما يتفاعل معه الكلور والبروم النشطان فيتناقص.","ليس دور الغيوم حجب الأشعة فوق البنفسجية؛ فدورها إنتاج كلور وبروم نشطين كيميائيًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:32:48.089Z"}'::jsonb),
('mcq', 4, 2, 'تتكوّن الغيوم الجليدية وينتج الكلور والبروم النشطان عند انخفاض الحرارة، وعندما تبدأ الحرارة بالارتفاع في الربيع يبدأ هذان العنصران التفاعل مع الأوزون فيتناقص.', '["الغيوم الجليدية تتكوّن عند انخفاض الحرارة إلى −78 °C، أي قبل الربيع، وليس في الربيع.","CFCs مركبات مصنّعة موجودة في الجو على مدار العام، ولا ترتبط بفصل بعينه.","","تغيب الشمس في شتاء القارة لا في ربيعها؛ والسبب الفعلي هو ارتفاع الحرارة الذي يحفز تفاعل الكلور والبروم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-18T03:32:48.089Z"}'::jsonb),
('mcq', 5, 1, 'تنخفض الحرارة إلى −78 °C فتتكوّن غيوم جليدية تساعد على إنتاج كلور وبروم نشطين، ثم ترتفع الحرارة في الربيع فيبدأ هذان العنصران التفاعل مع الأوزون فيتكوّن الثقب.', '["الغيوم الجليدية لا تتكوّن عند ارتفاع الحرارة؛ فهي تحتاج إلى انخفاضها إلى −78 °C.","","هذان عاملا تكوّن الأوزون فوق خط الاستواء، وليسا سبب الثقب فوق القارة المتجمدة.","زيادة الأكسجين وانخفاض الضغط لا علاقة لهما بتكوّن الثقب؛ فسببه الكلور والبروم النشطان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-10-18T03:32:48.089Z"}'::jsonb),
('mcq', 6, 2, 'أخفض حرارة (−88 °C) كانت في يوليو وكانت كمية الأوزون 250 DU، ثم بدأت الحرارة بالارتفاع فبلغ الأوزون أدنى قيمة (110 DU) في سبتمبر؛ وهذا يتفق مع أن تفاعل الكلور والبروم النشطين مع الأوزون يبدأ عند ارتفاع الحرارة بعد تكوّن الغيوم الجليدية.', '["أخفض حرارة (−88 °C) كانت في يوليو وكان الأوزون فيها 250 DU، أما أدنى قيمة (110 DU) فكانت في سبتمبر.","تتراوح الكمية بين 110 DU و320 DU، وهذا تغير كبير وليس ثباتًا.","","في سبتمبر ارتفعت الحرارة عن يوليو (من −88 °C إلى −70 °C) فانخفض الأوزون من 250 DU إلى 110 DU، فالعلاقة ليست طردية بسيطة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-18T03:32:48.089Z"}'::jsonb),
('mcq', 7, 3, 'يتناقص الأوزون فوق القطب الشمالي أيضًا، لكن درجة الحرارة هناك لا تبقى منخفضة مدة كافية، فيكون التناقص أقل منه فوق القارة المتجمدة الجنوبية.', '["الحرارة فوق القطب الشمالي لا تبقى منخفضة مدة كافية، فلا يتكوّن الثقب بالقدر نفسه.","يحدث تناقص للأوزون فوق القطب الشمالي أيضًا، لكنه أقل.","الفرق بين القطبين سببه مدة بقاء الحرارة منخفضة، وليس عدم وصول CFCs؛ فالأوزون يتناقص فوق القطب الشمالي أيضًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-18T03:32:48.090Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تنخفض درجة الحرارة في الستراتوسفير فوق القارة المتجمدة الجنوبية إلى −78 °C فتتكوّن غيوم جليدية. تحدث في هذه الغيوم تغيرات تساعد على إنتاج كلور وبروم نشطين كيميائيًا. وعندما ترتفع درجة الحرارة في فصل الربيع يبدأ هذان العنصران النشطان بالتفاعل مع غاز الأوزون فيتناقص، فيتكوّن ثقب الأوزون.', '["انخفاض الحرارة إلى −78 °C","تكوّن غيوم جليدية في الستراتوسفير","إنتاج كلور وبروم نشطين كيميائيًا","ارتفاع الحرارة في الربيع وتفاعل الكلور والبروم مع الأوزون فيتناقص"]'::jsonb, '[]'::jsonb, '[{"element":"انخفاض الحرارة إلى −78 °C وتكوّن غيوم جليدية في الستراتوسفير","marks":1},{"element":"إنتاج كلور وبروم نشطين كيميائيًا بسبب التغيرات في الغيوم","marks":1},{"element":"ارتفاع الحرارة في الربيع","marks":1},{"element":"تفاعل الكلور والبروم مع الأوزون وتناقصه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"ذكر العوامل الأربعة بالترتيب المنطقي: البرودة والغيوم، والكلور والبروم النشطان، وارتفاع الحرارة، والتفاعل مع الأوزون"},{"level":"3 درجات","description":"ذكر ثلاثة عوامل صحيحة"},{"level":"1–2 درجة","description":"ذكر عامل أو عاملين صحيحين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الثقب يتكوّن بسبب ارتفاع الحرارة وحده","إغفال دور الغيوم الجليدية في إنتاج الكلور والبروم النشطين","عدّ الثقب فراغًا خاليًا من الأوزون تمامًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-10-18T03:32:48.090Z"}'::jsonb),
('essay', 2, null::int, null, null, 'يتناقص الأوزون فوق القطب الشمالي أيضًا، إلا أن درجة الحرارة هناك لا تبقى منخفضة مدة كافية، بينما تبقى منخفضة فوق القارة المتجمدة الجنوبية مدة تسمح بتكوّن الغيوم الجليدية وإنتاج كلور وبروم نشطين. لذلك يكون تناقص الأوزون عند القطب الشمالي أقل منه فوق القارة المتجمدة الجنوبية.', '["يحدث تناقص الأوزون فوق القطب الشمالي أيضًا","الحرارة فوق القطب الشمالي لا تبقى منخفضة مدة كافية","فيكون التناقص هناك أقل منه فوق القارة المتجمدة الجنوبية"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر أن التناقص يحدث عند القطب الشمالي أيضًا","marks":1},{"element":"الحرارة لا تبقى منخفضة مدة كافية فوق القطب الشمالي","marks":1},{"element":"النتيجة: تناقص أقل عند القطب الشمالي","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تفسير كامل يربط مدة بقاء الحرارة منخفضة بحجم التناقص"},{"level":"2 درجتان","description":"ذكر عنصرين صحيحين"},{"level":"1 درجة","description":"ذكر عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الأوزون لا يتناقص فوق القطب الشمالي إطلاقًا","نسبة الفرق إلى اختلاف كمية CFCs فقط","إغفال دور مدة بقاء الحرارة منخفضة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-18T03:32:48.090Z"}'::jsonb),
('essay', 3, null::int, null, null, 'تقل كمية الأوزون إلى أدنى مستوى (110 DU) في سبتمبر، وهي أقل بكثير من المستوى الطبيعي 300 DU. أخفض حرارة (−88 °C) كانت في يوليو، وفيها تتكوّن الغيوم الجليدية وينتج الكلور والبروم النشطان، لكن الأوزون ما زال 250 DU لأن التفاعل لم يبدأ. وعند ارتفاع الحرارة في الربيع (سبتمبر، −70 °C) بدأ الكلور والبروم النشطان التفاعل مع الأوزون فهبطت كميته إلى 110 DU. وعودة الكمية إلى 320 DU في ديسمبر مع ارتفاع الحرارة إلى −42 °C تدل على أن الثقب موسمي يتكوّن سنويًا في الربيع ثم تتعافى الكمية.', '["أدنى كمية للأوزون في سبتمبر (110 DU)","أخفض حرارة في يوليو والأوزون ما زال 250 DU","تفسير بالغيوم الجليدية والكلور والبروم النشطين ثم ارتفاع الحرارة في الربيع","عودة الكمية إلى 320 DU في ديسمبر تدل على أن الثقب يتكوّن سنويًا في فترة محددة"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد سبتمبر (110 DU) أدنى كمية ومقارنتها بالمستوى الطبيعي 300 DU","marks":1},{"element":"ملاحظة أن أخفض حرارة في يوليو والأوزون ما زال مرتفعًا نسبيًا","marks":1},{"element":"تفسير النقص بتكوّن الغيوم الجليدية وإنتاج الكلور والبروم النشطين","marks":1},{"element":"ربط النقص بارتفاع الحرارة في الربيع وبدء التفاعل مع الأوزون","marks":1},{"element":"دلالة عودة الكمية في ديسمبر: ثقب موسمي سنوي","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تحليل كامل للبيانات وتفسير النقص بالعوامل الثلاثة (البرودة والغيوم، الكلور والبروم، ارتفاع الحرارة) ودلالة العودة في ديسمبر"},{"level":"3–4 درجات","description":"تحديد الشهر الصحيح وتفسير جزئي مع إغفال عنصر أو عنصرين"},{"level":"1–2 درجة","description":"تحديد الشهر الصحيح أو ذكر عامل واحد دون ربط بالبيانات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ يوليو أدنى شهر في الأوزون لأنه الأبرد","القول إن انخفاض الحرارة وحده يفكك الأوزون","إغفال أن الثقب موسمي وتعود الكمية للارتفاع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"a