('mcq', 2, 0, 'يتكوّن الأوزون فوق خط الاستواء لأن أشعة الشمس تكون عمودية وقوية هناك، فتحلل جزيئات O₂ إلى ذرات تتحد مع جزيئات O₂ أخرى لتكوّن O₃.', '["","انخفاض الحرارة إلى −78 °C يرتبط بتكوّن الغيوم الجليدية فوق القارة المتجمدة الجنوبية لا بتكوّن الأوزون.","الغيوم الجليدية ترتبط بتكوّن ثقب الأوزون فوق القارة المتجمدة الجنوبية، وليس بتكوّن الأوزون عند خط الاستواء.","CFCs تفكك الأوزون ولا تكوّنه؛ فتركزها لا يفسر تكوّن الأوزون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-18T03:32:48.091Z"}'::jsonb),
('mcq', 3, 3, 'تسقط أشعة الشمس فوق خط الاستواء عمودية وقوية، فتتحلل جزيئات O₂ إلى ذرات أكسجين أكثر، وتتحد هذه الذرات مع جزيئات O₂ لتكوّن O₃؛ فيزداد تكوّن الأوزون.', '["نسبة الأكسجين في الهواء متقاربة في المناطق المختلفة؛ والعامل الحاسم هو شدة أشعة الشمس وزاوية سقوطها.","الأشعة فوق خط الاستواء تسقط عمودية لا مائلة؛ والميل يضعف الأشعة ولا يقويها.","انخفاض الحرارة إلى −78 °C ليس شرط تكوّن الأوزون؛ بل يرتبط بتكوّن الغيوم الجليدية عند القطب الجنوبي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-18T03:32:48.091Z"}'::jsonb),
('mcq', 4, 1, 'عند تعرض غاز الأكسجين O₂ للأشعة فوق البنفسجية تتحلل جزيئاته إلى ذرات منفردة O، ثم تتفاعل ذرة O مع جزيء O₂ فيتكوّن جزيء الأوزون O₃.', '["الأوزون لا يتكوّن باتحاد جزيئين من O₂ مباشرة؛ يلزم أولًا تحلل O₂ بالأشعة فوق البنفسجية إلى ذرات.","","هذه ليست طريقة تكوّن الأوزون؛ فالأوزون يتكوّن من تحلل O₂ ثم اتحاد ذرة O مع جزيء O₂، ولا يدخل النيتروجين.","مركبات CFCs تفكك الأوزون ولا تكوّنه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:32:48.091Z"}'::jsonb),
('mcq', 5, 0, 'يتكوّن الأوزون فوق خط الاستواء ثم ينتقل حول الأرض بفعل تيارات الهواء في الستراتوسفير؛ لذلك فإن تتبع حركته يساعد على معرفة حركة الرياح في هذه الطبقة.', '["","لو بقي ثابتًا لما أمكن تتبع الرياح به؛ إذ يتحرك الأوزون حول الأرض بفعل تيارات الهواء.","الأوزون يتكوّن في الستراتوسفير لا في التروبوسفير.","الأوزون لا يوقف تيارات الهواء، بل تحمله هذه التيارات حول الأرض."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (71%)"}],"at":"2026-10-18T03:32:48.092Z"}'::jsonb),
('mcq', 6, 2, 'يتكوّن الأوزون فوق خط الاستواء حيث أشعة الشمس عمودية وقوية، ثم يتحرك حول الأرض بفعل تيارات الهواء في الستراتوسفير؛ فيمكن أن يصل إلى مدينة بعيدة عنه.', '["الأشعة العمودية القوية تكون فوق خط الاستواء، لا فوق مدينة تبعد عنه آلاف الكيلومترات.","الأوزون في هذه الحالة في الستراتوسفير، وهو يتكوّن فيها لا في التروبوسفير.","","تحلل CFCs لا ينتج الأوزون؛ فهذه المركبات تفكك الأوزون وتقلل كميته."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:32:48.092Z"}'::jsonb),
('mcq', 7, 3, 'يتكوّن الأوزون فوق خط الاستواء لأن أشعة الشمس تكون عمودية وقوية هناك، وليس بسبب برودة القطبين؛ فقول الطالب غير صحيح.', '["البرودة لا تكوّن الأوزون؛ فتكوّنه يحتاج إلى أشعة شمس قوية تحلل O₂ إلى ذرات.","الأوزون يتكوّن عند خط الاستواء بسبب قوة أشعة الشمس، وليس بسبب تحلله في الحرارة.","ليس تكوّن الأوزون متساويًا في كل مكان؛ فهو يتكوّن فوق خط الاستواء حيث تكون الأشعة عمودية وقوية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:32:48.092Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تكون أشعة الشمس فوق خط الاستواء عمودية وقوية، فتتحلل جزيئات غاز الأكسجين O₂ في الأجزاء العليا من الستراتوسفير إلى ذرات منفردة O. ثم تتفاعل ذرة O مع جزيء O₂ فيتكوّن جزيء الأوزون O₃. ولهذا يتكوّن الأوزون فوق خط الاستواء بكميات أكبر.', '["أشعة الشمس عمودية وقوية فوق خط الاستواء","تحلل O₂ إلى ذرات O","اتحاد ذرة O مع جزيء O₂ لتكوين O₃"]'::jsonb, '[]'::jsonb, '[{"element":"أشعة الشمس عمودية وقوية فوق خط الاستواء","marks":1},{"element":"تحلل جزيئات O₂ إلى ذرات O","marks":1},{"element":"اتحاد ذرة O مع جزيء O₂ لتكوين O₃","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعليل كامل: الأشعة العمودية القوية، تحلل O₂، تكوّن O₃"},{"level":"2 درجتان","description":"ذكر عنصرين صحيحين"},{"level":"1 درجة","description":"ذكر عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعليل التكوّن بانخفاض الحرارة أو بالغيوم الجليدية","القول إن الأوزون يتكوّن من اتحاد ثلاث ذرات O مباشرة","إغفال دور الأشعة فوق البنفسجية في تحلل O₂"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:32:48.092Z"}'::jsonb),
('essay', 2, null::int, null, null, 'يتكوّن الأوزون فوق خط الاستواء لأن أشعة الشمس عمودية وقوية هناك، أي أن موضع تكوّنه معروف. ثم يتحرك حول الأرض بفعل تيارات الهواء في الستراتوسفير، فإذا تتبعنا انتقاله من مكان تكوّنه استدللنا على اتجاه هذه التيارات وحركة الرياح.', '["الأوزون يتكوّن في موضع معروف هو فوق خط الاستواء","يتحرك حول الأرض بفعل تيارات الهواء في الستراتوسفير","تتبع حركته يدل على حركة الرياح"]'::jsonb, '[]'::jsonb, '[{"element":"تكوّن الأوزون في موضع معروف فوق خط الاستواء","marks":1},{"element":"حركته حول الأرض بفعل تيارات الهواء","marks":1},{"element":"الاستدلال بتتبع حركته على حركة الرياح","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تفسير كامل يربط موضع التكوّن بحركته بفعل التيارات ثم بتتبع الرياح"},{"level":"2 درجتان","description":"ذكر عنصرين صحيحين"},{"level":"1 درجة","description":"ذكر عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الأوزون يبقى ثابتًا في مكانه","القول إن الأوزون هو الذي يسبب حركة الرياح","الخلط بين طبقة الستراتوسفير وطبقة التروبوسفير"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (71%)"}],"at":"2026-10-18T03:32:48.092Z"}'::jsonb),
('essay', 3, null::int, null, null, 'يقل تكوّن الأوزون فوق خط الاستواء؛ لأن الأشعة الضعيفة تحلل عددًا أقل من جزيئات O₂ إلى ذرات O، فتقل الذرات التي تتحد مع جزيئات O₂ لتكوين O₃. وبقلة الأوزون المتكوّن هناك لا تبقى للمؤشر كمية كافية تنتقل بفعل تيارات الهواء حول الأرض، فتقل صلاحيته لتتبع حركة الرياح في الستراتوسفير، لأن صلاحيته قائمة على تكوّنه بقوة فوق خط الاستواء ثم انتقاله مع تيارات الهواء.', '["توقع نقص تكوّن الأوزون","الأشعة الضعيفة تحلل عددًا أقل من جزيئات O₂ إلى ذرات O","قلة ذرات O تعني قلة O₃ المتكوّن","تقل صلاحية الأوزون مؤشرًا لأن صلاحيته مبنية على تكوّنه القوي فوق خط الاستواء وانتقاله مع التيارات"]'::jsonb, '[]'::jsonb, '[{"element":"توقع نقص تكوّن الأوزون فوق خط الاستواء","marks":1},{"element":"تعليل ذلك بتحلل عدد أقل من جزيئات O₂ إلى ذرات O","marks":1},{"element":"ربط قلة ذرات O بقلة O₃ المتكوّن","marks":1},{"element":"بيان أثر ذلك في صلاحية الأوزون مؤشرًا لحركة الرياح","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"توقع صحيح معلل بسلسلة الأسباب (أشعة أضعف، O₂ أقل تحللًا، O₃ أقل) مع بيان الأثر في المؤشر"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"1–2 درجة","description":"توقع صحيح دون تعليل كافٍ، أو عنصر واحد أو اثنان فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["توقع زيادة تكوّن الأوزون عند ضعف الأشعة","إغفال دور الأشعة في تحلل O₂ إلى ذرات","عدم ربط قلة الأوزون بصلاحيته مؤشرًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-18T03:32:48.093Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
