from (values
('mcq', 1, 0, 'مطياف بريور من الأجهزة الموجودة على الأرض التي تستعمل لقياس كمية غاز الأوزون ومراقبتها في الغلاف الجوي.', '["","البارومتر يقيس الضغط الجوي ولا يقيس كمية الأوزون.","الدوبسون (DU) وحدة قياس كمية الأوزون وليس جهازًا.","المجهر الإلكتروني يستعمل لرؤية الأجسام الدقيقة جدًا، ولا يقيس كمية غاز الأوزون في الجو."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-10-18T03:32:48.093Z"}'::jsonb),
('mcq', 2, 3, 'تقاس كمية غاز الأوزون في طبقة الستراتوسفير بأجهزة على الأرض أو بالونات أو أقمار اصطناعية أو صواريخ؛ والأقمار الاصطناعية هي التي تعمل من الفضاء وتصوّر طبقة الأوزون.', '["محطات الأرصاد الأرضية تعمل على سطح الأرض وليست في الفضاء.","الغواصات تعمل في البحار وليست من وسائل قياس الأوزون.","الرادارات البحرية تستعمل في الملاحة وليست من وسائل قياس الأوزون.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-18T03:32:48.093Z"}'::jsonb),
('mcq', 3, 1, 'تُقاس كمية غاز الأوزون في طبقة الستراتوسفير بأجهزة على الأرض أو بالونات أو أقمار اصطناعية أو صواريخ؛ فالمجموعة الصحيحة هي التي تضم البالونات والصواريخ والأقمار الاصطناعية.', '["الأقمار الاصطناعية وسيلة صحيحة، لكن المناطيد المائية والغواصات ليست من وسائل قياس الأوزون.","","الأقمار الاصطناعية وسيلة صحيحة، أما السفن والمجاهر الضوئية فليست من وسائل قياس الأوزون.","الصواريخ وسيلة صحيحة، أما المحاليل الكيميائية والمقاييس الحرارية فلا تقيس كمية الأوزون في الجو."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-18T03:32:48.094Z"}'::jsonb),
('mcq', 4, 2, 'يستعمل جهاز مطياف الأشعة فوق البنفسجية والمرئية لقياس كمية غاز الأوزون والغازات الأخرى الموجودة في الستراتوسفير في أشهر الشتاء المعتمة في القارة المتجمدة الجنوبية.', '["الميزان الحساس يقيس الكتلة ولا يقيس الأوزون في الجو.","المجهر الإلكتروني يرى الأجسام الدقيقة جدًا ولا يقيس كمية الأوزون.","","مقياس الضغط الجوي يقيس الضغط ولا يقيس كمية الأوزون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:32:48.094Z"}'::jsonb),
('mcq', 5, 3, 'مطياف بريور جهاز موجود على الأرض يقيس كمية الأوزون في الجو، أما الأقمار الاصطناعية والبالونات والصواريخ فتحمل أجهزة القياس إلى الجو أو الفضاء.', '["الأقمار الاصطناعية تدور في الفضاء ولا توجد على الأرض.","البالونات ترتفع في الجو حاملة أجهزة القياس ولا تبقى على الأرض.","الصواريخ تنطلق عبر الجو وليست أجهزة ثابتة على الأرض.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-10-18T03:32:48.094Z"}'::jsonb),
('mcq', 6, 0, 'أيّدت قياسات البالونات والطائرات والأقمار الاصطناعية القياسات الأولى التي أشارت إلى تقلص سمك طبقة الأوزون؛ فاستعمال وسائل مختلفة يتيح التحقق من النتيجة وزيادة الثقة بها.', '["","الوسائل كلها تقيس كمية الأوزون، وتتنوع لتتحقق من النتائج.","الأجهزة الأرضية تقيس الأوزون فعلًا، ومنها مطياف بريور.","القمر الاصطناعي يعمل مستقلًا في مداره ولا يحتاج إلى بالون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-18T03:32:48.094Z"}'::jsonb),
('mcq', 7, 1, 'الدوبسون (DU) وحدة تقاس بها كمية غاز الأوزون في الجو، وليست جهازًا؛ فالمستوى الطبيعي للأوزون 300 DU، أما أجهزة القياس فأمثلتها مطياف بريور والأقمار الاصطناعية.', '["الجهاز الأرضي هو مثل مطياف بريور، أما الدوبسون فوحدة قياس.","","الدوبسون وحدة قياس لا قمر اصطناعي؛ فالأقمار الاصطناعية تحمل الأجهزة وتصوّر طبقة الأوزون.","البالونات وسيلة قياس مستقلة، والدوبسون وحدة قياس لا نوع من البالونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:32:48.094Z"}'::jsonb),
('essay', 1, null::int, null, null, 'من الوسائل والأجهزة المستعملة: الأجهزة الموجودة على الأرض مثل مطياف بريور ومطياف الأشعة فوق البنفسجية والمرئية، والبالونات، والأقمار الاصطناعية، والصواريخ، والطائرات. ويكفي ذكر ثلاث منها.', '["مطياف بريور أو أجهزة أرضية أخرى مثل مطياف الأشعة فوق البنفسجية والمرئية","البالونات","الأقمار الاصطناعية","الصواريخ أو الطائرات"]'::jsonb, '[]'::jsonb, '[{"element":"الوسيلة الأولى الصحيحة","marks":1},{"element":"الوسيلة الثانية الصحيحة","marks":1},{"element":"الوسيلة الثالثة الصحيحة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"ذكر ثلاث وسائل صحيحة مختلفة"},{"level":"2 درجتان","description":"ذكر وسيلتين صحيحتين"},{"level":"1 درجة","description":"ذكر وسيلة صحيحة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر الدوبسون على أنه جهاز وهو وحدة قياس","ذكر أجهزة لا تقيس الأوزون مثل البارومتر","تكرار وسيلة واحدة بصيغتين مختلفتين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-18T03:32:48.094Z"}'::jsonb),
('essay', 2, null::int, null, null, 'مطياف بريور جهاز موجود على الأرض. أما البالونات والصواريخ فتحمل أجهزة القياس إلى الجو (إلى طبقة الستراتوسفير)، والأقمار الاصطناعية تعمل في الفضاء. ويفضّل الجمع بين أكثر من وسيلة لأن قياساتها المتعددة يؤيد بعضها بعضًا، فتزداد الثقة بالنتيجة، كما حدث حين أيّدت قياسات البالونات والطائرات والأقمار الاصطناعية قياسات فريق القارة المتجمدة الجنوبية.', '["مطياف بريور: جهاز على الأرض","البالونات والصواريخ: تعمل في الجو","الأقمار الاصطناعية: تعمل في الفضاء","تعدد الوسائل يتيح تأييد القياسات والتحقق منها"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف مطياف بريور جهازًا أرضيًا","marks":1},{"element":"تصنيف البالونات والصواريخ وسيلتين تعملان في الجو","marks":1},{"element":"تصنيف الأقمار الاصطناعية وسيلة تعمل في الفضاء","marks":1},{"element":"تعليل الجمع بين الوسائل بتأييد القياسات والتحقق منها","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تصنيف الوسائل الأربع تصنيفًا صحيحًا مع تعليل الجمع بينها"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"1–2 درجة","description":"عنصر أو عنصران صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ مطياف بريور وسيلة فضائية","عدّ البالونات أجهزة أرضية","إغفال التعليل واكتفاء التصنيف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.095Z"}'::jsonb),
('essay', 3, null::int, null, null, 'يمكن استعمال البالونات التي ترتفع إلى الستراتوسفير وتحمل أجهزة القياس، والأقمار الاصطناعية التي تصوّر طبقة الأوزون من الفضاء (ويمكن كذلك الطائرات أو الصواريخ). وعندما تعطي هذه الوسائل المختلفة النتيجة نفسها (انخفاض سمك الطبقة) التي أعطاها الجهاز الأرضي، يؤيد بعضها بعضًا، فيقل احتمال أن يكون الانخفاض خطأ في جهاز واحد، وتزداد الثقة بالنتيجة، كما حدث مع قياسات فريق القارة المتجمدة الجنوبية.', '["اقتراح وسيلة أولى مناسبة (بالونات أو طائرات أو صواريخ)","اقتراح وسيلة ثانية مختلفة مناسبة (الأقمار الاصطناعية)","اتفاق نتائج الوسائل المختلفة يؤيد بعضها بعضًا","تقل احتمالية الخطأ في جهاز واحد فتزداد الثقة بالنتيجة"]'::jsonb, '[]'::jsonb, '[{"element":"اقتراح وسيلة أولى مناسبة","marks":1},{"element":"اقتراح وسيلة ثانية مناسبة ومختلفة عن الأولى","marks":1},{"element":"تفسير أن اتفاق النتائج يؤيد بعضها بعضًا","marks":1},{"element":"تقليل احتمال الخطأ في جهاز واحد وزيادة الثقة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"وسيلتان صحيحتان مختلفتان مع تفسير تعزيز الثقة بالنتيجة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"1–2 درجة","description":"عنصر أو عنصران صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اقتراح جهاز أرضي آخر لا وسيلة مختلفة","اقتراح أجهزة لا تقيس الأوزون","الاكتفاء بذكر الوسائل دون تفسير تعزيز الثقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:32:48.095Z"}'::jsonb)
