('essay', 3, 'قارن بين الأمونيا ومركبات CFCs من حيث الأمان عند استعمالهما مبرّدًا في الثلاجات، ثم بيّن لماذا استُعملت CFCs أيضًا في علب الرش والبوليمرات.', null, null, 'تحليل', 'مقارنة وربط', 'صعب', 'الكتاب ص 17–18 — مركبات الكلوروفلوروكربون')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
