from (values
('mcq', 1, 1, 'مركبات الكلوروفلوروكربون CFCs مواد مكوّنة من الكلور والفلور والكربون، ومن هنا جاء اسمها.', '["النيتروجين ليس من عناصر هذه المركبات؛ فالعنصر الثالث هو الكربون.","","البروم ليس من عناصر CFCs؛ والعنصر الثاني فيها هو الفلور.","الأكسجين ليس من عناصر CFCs، والكلور عنصر أساسي فيها وقد غاب عن هذا البديل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-18T03:32:48.095Z"}'::jsonb),
('mcq', 2, 2, 'استُعملت مركبات CFCs في دفع الرذاذ من علب الرش، كما في علب ملطفات الجو وعلب المبيدات الحشرية المنزلية، وفي الثلاجات والتكييف وتصنيع البوليمرات.', '["لم تستعمل CFCs في تنقية مياه الشرب.","لم تستعمل CFCs في صناعة الزجاج.","","لم تستعمل CFCs وقودًا للمركبات؛ فاستعمالها كان في التبريد ودفع الرذاذ وتصنيع البوليمرات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:32:48.095Z"}'::jsonb),
('mcq', 3, 0, 'بدأ عام 1935م استعمال CFCs في صناعة أجهزة التكييف المنزلية، كما دخلت في صناعة الثلاجات، لأنها مبردات مثالية.', '["","الأفران والمواقد أجهزة تسخين لا تبريد.","المصابيح والمكاوي أجهزة تعمل بالتسخين أو الإضاءة ولا تحتاج مبرّدات.","الغسالات والمكانس الكهربائية لا تحتاج إلى مبرّدات من نوع CFCs."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-18T03:32:48.096Z"}'::jsonb),
('mcq', 4, 3, 'حضّر العالم توماس ميجلي عام 1928م أول مركّب من مركبات الكلوروفلوروكربون CFCs.', '["مولينا وضع مع رولاند فرضية دور CFCs في تفكيك الأوزون، ولم يحضّر أول مركّب منها.","رولاند شارك مولينا في وضع فرضية تفكيك CFCs للأوزون، ولم يحضّر أول مركّب.","دوبسون عالم بدأ قياس كمية الأوزون في الغلاف الجوي، وليس محضّر CFCs.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-18T03:32:48.096Z"}'::jsonb),
('mcq', 5, 1, 'كانت الأمونيا ضارة وقد تتسرب أبخرتها فتؤذي أفراد البيت، فبحث الكيميائيون عن مبرّدات أكثر أمانًا؛ وCFCs غير سامة ولا تتفاعل مباشرة مع المواد الأخرى فهي مبرّدات مثالية.', '["CFCs مركبات مصنّعة لا تتكوّن طبيعيًا، وسبب اختيارها الأمان لا الثمن.","","لم تُختر CFCs لرائحتها؛ بل لأنها غير سامة ولا تتفاعل مباشرة.","اتضح لاحقًا أن CFCs تقلل سمك طبقة الأوزون، ولم يكن هذا سبب استعمالها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-18T03:32:48.096Z"}'::jsonb),
('mcq', 6, 2, 'مركبات CFCs مواد مصنّعة تُحضّر في المختبر ولا تتكوّن طبيعيًا، وهي مكوّنة من الكلور والفلور والكربون.', '["CFCs لا توجد طبيعيًا؛ بل تُحضّر في المختبر.","CFCs غير سامة لأنها لا تتفاعل مباشرة مع المواد الأخرى.","","العنصر الثالث في CFCs هو الكربون وليس الهيدروجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-18T03:32:48.096Z"}'::jsonb),
('mcq', 7, 0, 'المركبات المكوّنة من الكلور والفلور والكربون والمستعملة في التبريد ودفع الرذاذ هي مركبات الكلوروفلوروكربون CFCs.', '["","الأمونيا (NH₃) تتكوّن من النيتروجين والهيدروجين، وكانت مبرّدًا ضارًا قبل ظهور CFCs.","الأوزون O₃ يتكوّن من الأكسجين فقط وليس من الكلور والفلور والكربون.","البوليمرات مواد تصنّع أحيانًا باستعمال CFCs، ولا تتكوّن من هذه العناصر الثلاثة وحدها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.096Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تتكوّن مركبات CFCs من ثلاثة عناصر هي الكلور والفلور والكربون. ومن مجالات استعمالها: صناعة أجهزة التكييف المنزلية، وصناعة الثلاجات، وتصنيع البوليمرات، ودفع الرذاذ من علب الرش (كعلب ملطفات الجو وعلب المبيدات الحشرية المنزلية).', '["العناصر: الكلور والفلور والكربون","ثلاثة مجالات من: أجهزة التكييف، الثلاجات، تصنيع البوليمرات، دفع الرذاذ من علب الرش"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر العناصر الثلاثة: الكلور والفلور والكربون","marks":1},{"element":"المجال الأول الصحيح","marks":1},{"element":"المجال الثاني الصحيح","marks":1},{"element":"المجال الثالث الصحيح","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"ذكر العناصر الثلاثة وثلاثة مجالات صحيحة"},{"level":"3 درجات","description":"ثلاثة من العناصر الأربعة المطلوبة صحيحة"},{"level":"1–2 درجة","description":"عنصر أو عنصران صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر البروم أو الهيدروجين بدلًا من الكلور أو الفلور","ذكر مجالات غير صحيحة مثل تنقية الماء","ذكر مجال واحد بصيغتين مختلفتين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-18T03:32:48.097Z"}'::jsonb),
('essay', 2, null::int, null, null, 'ازداد إنتاج الثلاجات في عشرينيات القرن الماضي، وكانت تستعمل غازات ضارة منها الأمونيا للتبريد، وقد تتسرب أبخرة الأمونيا من الثلاجة وتؤذي أفراد البيت. لذلك بحث الكيميائيون عن مبرّدات أكثر أمانًا، فحضّر توماس ميجلي عام 1928م أول مركّب من CFCs. وهي غير سامة ولا تتفاعل مباشرة مع المواد الأخرى، فاعتُبرت مبرّدات مثالية وبدأ استعمالها في أجهزة التكييف والثلاجات.', '["الغازات المستعملة سابقًا مثل الأمونيا ضارة وقد تتسرب","البحث عن مبرّدات أكثر أمانًا","CFCs غير سامة","CFCs لا تتفاعل مباشرة مع المواد الأخرى"]'::jsonb, '[]'::jsonb, '[{"element":"ضرر الأمونيا وتسرب أبخرتها","marks":1},{"element":"البحث عن مبرّدات أكثر أمانًا وتحضير CFCs","marks":1},{"element":"CFCs غير سامة","marks":1},{"element":"CFCs لا تتفاعل مباشرة مع المواد الأخرى","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعليل كامل يشمل ضرر الأمونيا والبحث عن بديل وخاصيتي CFCs"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"1–2 درجة","description":"عنصر أو عنصران صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن CFCs صُنعت لتحمي طبقة الأوزون","عدّ CFCs مواد سامة","إغفال سبب البحث عن بديل للأمونيا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-18T03:32:48.097Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الأمونيا ضارة وقد تتسرب أبخرتها من الثلاجة فتؤذي أفراد البيت، أما CFCs فغير سامة وغير نشطة، لأنها لا تتفاعل مباشرة مع المواد الأخرى، فهي أكثر أمانًا وتُعدّ مبرّدات مثالية. ولأنها لا تتفاعل مباشرة مع المواد الأخرى ولا تضر باستنشاقها استُعملت أيضًا في دفع الرذاذ من علب الرش (كملطفات الجو والمبيدات الحشرية المنزلية) وفي تصنيع البوليمرات.', '["الأمونيا ضارة وأبخرتها قد تؤذي أفراد البيت عند التسرب","CFCs غير سامة ولا تتفاعل مباشرة مع المواد الأخرى فهي أكثر أمانًا","استعمال CFCs في دفع الرذاذ من علب الرش","استعمال CFCs في تصنيع البوليمرات","ربط الاستعمالات الأخرى بخاصيتي عدم السمية وعدم التفاعل المباشر"]'::jsonb, '[]'::jsonb, '[{"element":"بيان ضرر الأمونيا","marks":1},{"element":"بيان أمان CFCs (غير سامة ولا تتفاعل مباشرة)","marks":1},{"element":"ذكر استعمالها في علب الرش","marks":1},{"element":"ذكر استعمالها في تصنيع البوليمرات","marks":1},{"element":"ربط الاستعمالات بخصائص CFCs","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة صحيحة بين المادتين مع استعمالين آخرين وربطهما بخصائص CFCs"},{"level":"3–4 درجات","description":"مقارنة صحيحة مع نقص في الاستعمالات أو في الربط"},{"level":"1–2 درجة","description":"عنصر أو عنصران صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الأمونيا أكثر أمانًا من CFCs","ذكر الأوزون مبرّدًا","إغفال ربط الاستعمالات بعدم تفاعل CFCs مباشرة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:32:48.097Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
