('mcq', 3, 'تمثل البيانات الآتية تركيز CFC-11 في الغلاف الجوي. في أيّ الفترات الآتية كان ارتفاع التركيز أبطأ ما يمكن؟', '{"headers":["السنة (م)","تركيز CFC-11 (ppt)"],"rows":[["1977","140"],["1981","172"],["1985","200"],["1989","250"],["1991","265"],["1995","272"]]}'::jsonb, '["1977–1981م","1985–1989م","1991–1995م","1981–1985م"]'::jsonb, 'تحليل', 'مقارنة معدلات من بيانات', 'سهل', 'الكتاب ص 18 — مركبات الكلوروفلوروكربون (تركيز CFC-11)'),
('mcq', 4, 'كان تركيز CFC في الغلاف الجوي عام 1995م يساوي 272 ppt، علمًا أن ppt تعني جزءًا من تريليون (10¹²). ما النسبة المئوية التي يمثلها هذا التركيز؟', null, '["2.72 × 10⁻⁸ %","2.72 × 10⁻¹⁰ %","2.72 × 10⁻⁵ %","2.72 × 10¹⁶ %"]'::jsonb, 'تطبيق', 'تحويل وحدة تركيز إلى نسبة مئوية', 'متوسط', 'الكتاب ص 18 و38 — تركيز CFC (السؤال 30)'),
('mcq', 5, 'تبيّن البيانات التقريبية الآتية الاستهلاك العالمي لمركبات CFCs وتركيزها فوق القارة المتجمدة الجنوبية. أيّ الاستنتاجات الآتية تتفق مع البيانات؟', '{"headers":["السنة (م)","الاستهلاك العالمي (ألف طن)","تركيز CFCs فوق القارة (ppt)"],"rows":[["1986","1050","440"],["1990","720","480"],["1994","330","520"],["1998","190","535"],["2000","150","540"]]}'::jsonb, '["تراجع الاستهلاك والتركيز فوق القارة بالمعدل نفسه","ارتفع الاستهلاك والتركيز فوق القارة معًا","بقي الاستهلاك ثابتًا بينما ارتفع التركيز فوق القارة","تراجع الاستهلاك بشدة بينما لم ينخفض التركيز فوق القارة خلال الفترة"]'::jsonb, 'تحليل', 'استنتاج من رسم بياني', 'صعب', 'الكتاب ص 30 — ميثاق مونتريال (استهلاك CFCs وكمياتها فوق القارة)'),
('mcq', 6, 'تبيّن البيانات الآتية كمية الأوزون فوق القارة المتجمدة الجنوبية في أربعة أشهر، علمًا أن المستوى الطبيعي لكمية الأوزون يساوي 300 DU. في أيّ شهر كان النقص عن المستوى الطبيعي أكبر، وما نسبته المئوية؟', '{"headers":["الشهر","كمية الأوزون (DU)"],"rows":[["يوليو","240"],["أغسطس","170"],["سبتمبر","110"],["أكتوبر","125"]]}'::jsonb, '["أكتوبر، بنسبة 58 %","سبتمبر، بنسبة 37 %","سبتمبر، بنسبة 63 %","أغسطس، بنسبة 43 %"]'::jsonb, 'تحليل', 'تحليل بيانات وحساب نسبة', 'صعب', 'الكتاب ص 31–32 — ثقب الأوزون حاليًا، مختبر تحليل البيانات'),
('mcq', 7, 'في رسم بياني يمثل تركيز CFC-11 على المحور الرأسي والسنة على المحور الأفقي، أيّ شكل للمنحنى يدل على أن التركيز استقر عند قيمة مرتفعة بعد فترة من الارتفاع؟', null, '["خط يرتفع بميل يزداد مع مرور الزمن","خط يرتفع بميل ثم يصبح شبه أفقي","خط ينحدر نحو الأسفل بميل ثابت","خط ينحدر ثم يصبح شبه أفقي عند قيمة منخفضة"]'::jsonb, 'فهم', 'قراءة شكل منحنى', 'سهل', 'الكتاب ص 18 — اختبار الرسم البياني (تركيز CFC-11)'),
('essay', 1, 'كان تركيز CFC-11 في الغلاف الجوي 140 ppt عام 1977م، و200 ppt عام 1985م، و265 ppt عام 1991م، و272 ppt عام 1995م. احسب معدل ارتفاع التركيز بين 1977 و1985م وبين 1991 و1995م، ثم فسّر الفرق بين المعدلين.', null, null, 'تحليل', 'حساب معدل وتفسير', 'متوسط', 'الكتاب ص 18 — مركبات الكلوروفلوروكربون (تركيز CFC-11)'),
('essay', 2, 'بلغ الاستهلاك العالمي لمركبات CFCs نحو 1050 ألف طن عام 1986م وتركيزها فوق القارة المتجمدة الجنوبية نحو 440 ppt؛ وبلغ الاستهلاك نحو 330 ألف طن عام 1994م والتركيز نحو 520 ppt؛ وبلغ الاستهلاك نحو 150 ألف طن عام 2000م والتركيز نحو 540 ppt. صف اتجاه تغير كلٍّ من الاستهلاك والتركيز، ثم فسّر لماذا لا يعني تراجع الاستهلاك تقلص التركيز فورًا.', null, null, 'تحليل', 'وصف وتفسير علاقة بين متغيرين', 'متوسط', 'الكتاب ص 30 — ميثاق مونتريال (الاستهلاك العالمي لـ CFCs وكمياتها)'),
('essay', 3, 'سجّل باحثون عند ارتفاع 20–24 km فوق القارة المتجمدة الجنوبية: في يوليو حرارة −88 °C وكمية أوزون 250 DU، وفي سبتمبر حرارة −70 °C وكمية أوزون 110 DU، وفي ديسمبر حرارة −42 °C وكمية أوزون 320 DU. قال طالب: «انخفاض درجة الحرارة وحده هو سبب نقص الأوزون». قوّم قوله اعتمادًا على البيانات.', null, null, 'تقويم', 'تقويم ادعاء من بيانات', 'صعب', 'الكتاب ص 31–32 — ثقب الأوزون حاليًا، مختبر تحليل البيانات')
