('mcq', 1, 3, 'ارتفع التركيز من 140 ppt إلى 272 ppt، وكان ارتفاعه سريعًا في الفترات الأولى، أما بين 1991 و1995م فارتفع من 265 ppt إلى 272 ppt فقط، أي تباطأ الارتفاع.', '["التركيز لم ينخفض؛ فقد زادت قيمه من 140 ppt إلى 272 ppt.","التركيز لم يبقَ ثابتًا؛ فقد ارتفع بنحو الضعف تقريبًا.","معدل الارتفاع لم يكن ثابتًا؛ فهو أكبر بين 1985 و1989م منه بين 1991 و1995م.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-18T03:32:48.097Z"}'::jsonb),
('mcq', 2, 1, 'معدل الارتفاع = (250 − 200) ÷ (1989 − 1985) = 50 ÷ 4 = 12.5 ppt/سنة.', '["هذه قيمة الفرق في التركيز (50 ppt) دون قسمته على عدد السنوات.","","هذا معدل الارتفاع بين 1977 و1981م ((172 − 140) ÷ 4) وليس بين 1985 و1989م.","هذا ناتج قسمة عدد السنوات على فرق التركيز (4 ÷ 50) بدلًا من العكس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-10-18T03:32:48.098Z"}'::jsonb),
('mcq', 3, 2, 'معدلات الارتفاع: 8.0 ppt/سنة (1977–1981)، و7.0 ppt/سنة (1981–1985)، و12.5 ppt/سنة (1985–1989)، و1.75 ppt/سنة (1991–1995)؛ فأبطأ ارتفاع كان بين 1991 و1995م.', '["معدل الارتفاع في هذه الفترة 8.0 ppt/سنة، وهو أكبر من معدل 1991–1995م (1.75 ppt/سنة).","هذه أسرع فترة ارتفاعًا (12.5 ppt/سنة) وليست أبطأها.","","معدل الارتفاع في هذه الفترة 7.0 ppt/سنة، وهو أكبر من معدل 1991–1995م (1.75 ppt/سنة)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-10-18T03:32:48.098Z"}'::jsonb),
('mcq', 4, 0, 'النسبة المئوية = (272 ÷ 10¹²) × 100 = 2.72 × 10⁻⁸ %.', '["","هذه قيمة الكسر 272 ÷ 10¹² دون ضربه في 100 لتحويله إلى نسبة مئوية.","هذه النتيجة تحصل عند اعتبار التريليون 10⁹ (مليارًا) بدلًا من 10¹².","هذه النتيجة تحصل بضرب 272 في 10¹² ثم في 100 بدلًا من القسمة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:32:48.098Z"}'::jsonb),
('mcq', 5, 3, 'انخفض الاستهلاك العالمي من 1050 إلى 150 ألف طن، أما التركيز فوق القارة فارتفع من 440 إلى 540 ppt مع تباطؤ ارتفاعه؛ أي لم تتقلص كميات CFCs فوق القارة مباشرة رغم تراجع الاستهلاك.', '["التركيز فوق القارة لم يتراجع أصلًا؛ بل ارتفع من 440 إلى 540 ppt.","الاستهلاك لم يرتفع؛ بل تراجع من 1050 إلى 150 ألف طن.","الاستهلاك لم يبقَ ثابتًا؛ بل تراجع بشدة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:32:48.099Z"}'::jsonb),
('mcq', 6, 2, 'أقل كمية كانت في سبتمبر (110 DU)؛ فالنقص = 300 − 110 = 190 DU، ونسبته = (190 ÷ 300) × 100 ≈ 63 %.', '["أكتوبر (125 DU) نقصه 175 DU أي 58 %، لكنه أقل من نقص سبتمبر.","37 % هي نسبة الأوزون المتبقي (110 ÷ 300) وليست نسبة النقص.","","أغسطس (170 DU) نقصه 43 %، وهو أقل من نقص سبتمبر الذي هو أكبر نقص."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:32:48.099Z"}'::jsonb),
('mcq', 7, 1, 'ارتفاع التركيز يظهر على شكل خط صاعد، واستقراره عند قيمة مرتفعة يظهر حين يصبح الخط شبه أفقي في أعلى الرسم بعد صعوده.', '["الميل المتزايد يعني أن التركيز يرتفع بسرعة أكبر مع الزمن ولا يستقر.","","الخط المنحدر نحو الأسفل يعني أن التركيز يتناقص، وليس أنه استقر عند قيمة مرتفعة.","هذا يعني استقرار التركيز عند قيمة منخفضة بعد انخفاضه، لا عند قيمة مرتفعة بعد ارتفاعه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.099Z"}'::jsonb),
('essay', 1, null::int, null, null, 'معدل الارتفاع = (التركيز النهائي − التركيز الابتدائي) ÷ عدد السنوات. بين 1977 و1985م: (200 − 140) ÷ 8 = 7.5 ppt/سنة. بين 1991 و1995م: (272 − 265) ÷ 4 = 1.75 ppt/سنة. المعدل الثاني أصغر بنحو 4.3 مرات من الأول؛ أي إن التركيز استمر في الارتفاع لكن ارتفاعه تباطأ كثيرًا واتجه إلى الاستقرار عند مستوى مرتفع قرب 272 ppt.', '["معدل 1977–1985م = 7.5 ppt/سنة","معدل 1991–1995م = 1.75 ppt/سنة","المعدل الثاني أصغر بكثير من الأول","تفسير: تباطأ الارتفاع واتجه التركيز إلى الاستقرار عند مستوى مرتفع"]'::jsonb, '["معدل الارتفاع = (التركيز النهائي − التركيز الابتدائي) ÷ عدد السنوات","1977–1985م: (200 − 140) ÷ (1985 − 1977) = 60 ÷ 8 = 7.5 ppt/سنة","1991–1995م: (272 − 265) ÷ (1995 − 1991) = 7 ÷ 4 = 1.75 ppt/سنة","المقارنة: 7.5 ÷ 1.75 ≈ 4.3؛ فالمعدل الأول أكبر بنحو 4.3 مرات"]'::jsonb, '[{"element":"حساب معدل 1977–1985م = 7.5 ppt/سنة بخطوات صحيحة","marks":1},{"element":"حساب معدل 1991–1995م = 1.75 ppt/سنة بخطوات صحيحة","marks":1},{"element":"مقارنة المعدلين","marks":1},{"element":"تفسير التباطؤ واتجاه التركيز إلى الاستقرار","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حساب المعدلين حسابًا صحيحًا بالوحدة، ومقارنتهما وتفسير التباطؤ"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"1–2 درجة","description":"حساب أحد المعدلين فقط أو خطأ في الوحدة مع صحة المنهج"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان القسمة على عدد السنوات","استعمال عدد سنوات خاطئ (حساب 1985 − 1977 خطأ)","القول إن التركيز انخفض لأن المعدل صغر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:32:48.099Z"}'::jsonb),
('essay', 2, null::int, null, null, 'تراجع الاستهلاك العالمي بشدة من 1050 إلى 330 ثم إلى 150 ألف طن، بينما ارتفع التركيز فوق القارة من 440 إلى 520 ثم إلى 540 ppt؛ أي إن ارتفاعه تباطأ ولم يتقلص. ويفسَّر ذلك بأن خفض الاستعمال يوقف زيادة المركبات الجديدة التي تصل إلى الجو، لكن ما تراكم منها في الغلاف الجوي يبقى فيه مدة، فلا ينعكس تراجع الاستهلاك فورًا على كميتها فوق القارة.', '["الاستهلاك تراجع بشدة","التركيز فوق القارة ارتفع مع تباطؤ ارتفاعه ولم يتقلص","خفض الاستعمال يمنع زيادة المركبات الجديدة","المركبات المتراكمة تبقى في الجو مدة فلا يظهر الأثر فورًا"]'::jsonb, '[]'::jsonb, '[{"element":"وصف تراجع الاستهلاك بقيم من البيانات","marks":1},{"element":"وصف ارتفاع التركيز فوق القارة وتباطؤه دون تقلص","marks":1},{"element":"بيان أن خفض الاستعمال يوقف زيادة المركبات الجديدة","marks":1},{"element":"بيان أن المركبات المتراكمة تبقى في الجو مدة فلا يظهر الأثر فورًا","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"وصف صحيح للاتجاهين بقيم من البيانات وتفسير منطقي لعدم تقلص التركيز فورًا"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"1–2 درجة","description":"وصف أحد الاتجاهين فقط أو تفسير جزئي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن التركيز تراجع مع الاستهلاك","الاكتفاء بالوصف دون تفسير","عدّ استمرار التركيز دليلًا على أن الاستهلاك لم يتراجع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:32:48.100Z"}'::jsonb),
('essay', 3, null::int, null, null, 'قول الطالب غير صحيح. أخفض حرارة (−88 °C) كانت في يوليو، لكن كمية الأوزون كانت ما تزال 250 DU؛ فلو كان انخفاض الحرارة وحده سبب النقص لكانت أقل كمية عند أخفض حرارة. أما أقل كمية (110 DU، بنقص نحو 63 % عن المستوى الطبيعي 300 DU) فكانت في سبتمبر بعد أن بدأت الحرارة بالارتفاع إلى −70 °C. وهذا يتفق مع أن انخفاض الحرارة يكوّن الغيوم الجليدية التي تساعد على إنتاج كلور وبروم نشطين، ثم يبدأ هذان العنصران بالتفاعل مع الأوزون عند ارتفاع الحرارة في الربيع. وعودة الكمية إلى 320 DU في ديسمبر تدل على أن النقص موسمي.', '["الحكم: قول الطالب غير صحيح","أخفض حرارة في يوليو والأوزون 250 DU، وأقل كمية في سبتمبر 110 DU","النقص نحو 63 % عن المستوى الطبيعي 300 DU","التفسير: البرودة تكوّن الغيوم وتنتج كلورًا وبرومًا نشطين، ثم يتفاعلان مع الأوزون عند ارتفاع الحرارة","عودة الكمية في ديسمبر تدل على أن النقص موسمي"]'::jsonb, '["نسبة النقص في سبتمبر = (300 − 110) ÷ 300 × 100 = 190 ÷ 300 × 100 ≈ 63 %"]'::jsonb, '[{"element":"الحكم بأن قول الطالب غير صحيح","marks":1},{"element":"الاستدلال بأن أقل كمية لم تكن عند أخفض حرارة (يوليو 250 DU مقابل سبتمبر 110 DU)","marks":1},{"element":"حساب نسبة النقص في سبتمبر ≈ 63 %","marks":1},{"element":"التفسير بالغيوم الجليدية والكلور والبروم النشطين وارتفاع الحرارة","marks":1},{"element":"دلالة عودة الكمية إلى 320 DU في ديسمبر","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حكم صحيح مدعوم بالبيانات والحساب، وتفسير كامل، وربط بعودة الكمية في ديسمبر"},{"level":"3–4 درجات","description":"حكم صحيح مع دليل وتفسير جزئيين"},{"level":"1–2 درجة","description":"حكم صحيح دون دليل كافٍ أو دليل واحد فقط"},{"level":"صفر","description":"تأييد قول الطالب أو إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ يوليو أقل شهر لأنه الأبرد","حساب نسبة الأوزون المتبقي (37 %) بدلًا من نسبة النقص","إغفال دور الكلور والبروم النشطين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.100Z"}'::jsonb)
