('mcq', 4, 2, 'كل جزيء O₃ يحتاج إلى 3 ذرات أكسجين؛ فعدد الذرات = 8 × 3 = 24 ذرة.', '["8 هو عدد الجزيئات نفسه، ولم يُضرب في عدد الذرات في كل جزيء.","11 ناتج جمع 8 و3 بدلًا من ضربهما.","","16 ناتج ضرب 8 في 2، أي معاملة الجزيء كأنه O₂."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-10-18T03:32:48.101Z"}'::jsonb),
('mcq', 5, 3, 'تبيّن المعادلة أن كل جزيء O₃ ينتج جزيئًا واحدًا من O₂ (النسبة 1 : 1)؛ فلإنتاج 18 جزيئًا من O₂ يلزم 18 جزيئًا من O₃.', '["6 ناتج قسمة 18 على 3، أي خلط بين عدد ذرات الأكسجين في الجزيء وعدد الجزيئات المتفاعلة.","54 ناتج ضرب 18 في 3، والنسبة بين O₃ وO₂ في المعادلة 1 : 1 وليست 3 : 1.","36 ناتج ضرب 18 في 2، والنسبة في المعادلة 1 : 1 وليست 2 : 1.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-18T03:32:48.102Z"}'::jsonb),
('mcq', 6, 0, 'عدد الجزيئات = عدد الذرات ÷ 3 = (9.0 × 10²²) ÷ 3 = 3.0 × 10²² جزيء.', '["","2.7 × 10²³ ناتج ضرب 9.0 × 10²² في 3 بدلًا من القسمة عليه.","4.5 × 10²² ناتج القسمة على 2، أي معاملة الأوزون كأنه O₂.","الرقم 3.0 صحيح لكن الأس (21) خطأ؛ فقسمة 9.0 × 10²² على 3 لا تغيّر الأس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-10-18T03:32:48.102Z"}'::jsonb),
('mcq', 7, 1, '20 ÷ 3 = 6 والباقي 2؛ فتتكوّن 6 جزيئات كاملة تستعمل 18 ذرة، وتبقى ذرتان لا تكفيان لتكوين جزيء آخر.', '["7 جزيئات تحتاج إلى 21 ذرة، ولا تتوفر سوى 20 ذرة.","","6 جزيئات تستعمل 18 ذرة فقط، فتبقى ذرتان ولا تبقى صفر ذرة.","10 جزيئات ناتج قسمة 20 على 2، أي معاملة الأوزون كأنه O₂."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-18T03:32:48.102Z"}'::jsonb),
('essay', 1, null::int, null, null, 'كل جزيء أوزون يتكوّن من 3 ذرات أكسجين، فعدد الجزيئات = عدد الذرات ÷ 3. من 18 ذرة: 18 ÷ 3 = 6 جزيئات. من 33 ذرة: 33 ÷ 3 = 11 جزيئًا. من 75 ذرة: 75 ÷ 3 = 25 جزيئًا.', '["عدد الجزيئات = عدد الذرات ÷ 3","18 ذرة تعطي 6 جزيئات","33 ذرة تعطي 11 جزيئًا","75 ذرة تعطي 25 جزيئًا"]'::jsonb, '["كل جزيء O₃ يحتوي 3 ذرات أكسجين","عدد الجزيئات = عدد الذرات ÷ 3","18 ÷ 3 = 6 جزيئات","33 ÷ 3 = 11 جزيئًا","75 ÷ 3 = 25 جزيئًا"]'::jsonb, '[{"element":"كتابة العلاقة: عدد الجزيئات = عدد الذرات ÷ 3","marks":1},{"element":"حساب 6 جزيئات من 18 ذرة","marks":1},{"element":"حساب 11 جزيئًا من 33 ذرة","marks":1},{"element":"حساب 25 جزيئًا من 75 ذرة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"العلاقة صحيحة والنتائج الثلاث صحيحة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"1–2 درجة","description":"عنصر أو عنصران صحيحان، أو منهج صحيح مع أخطاء حسابية"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ضرب عدد الذرات في 3 بدلًا من القسمة","القسمة على 2 كأن الجزيء O₂","الخلط بين عدد الذرات وعدد الجزيئات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-10-18T03:32:48.102Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المعادلة: C + O₃ → CO + O₂. عدّ الذرات: الكربون 1 في كل طرف، والأكسجين 3 في المتفاعلات (من O₃) و3 في النواتج (1 في CO و2 في O₂)؛ فالمعادلة موزونة. النسبة بين O₃ وO₂ هي 1 : 1، وبين C وO₂ هي 1 : 1، فلإنتاج 36 جزيئًا من O₂ يلزم 36 جزيئًا من O₃ و36 ذرة كربون.', '["المعادلة C + O₃ → CO + O₂","تحقق الوزن: كربون 1 = 1، أكسجين 3 = 3","النسبة O₃ : O₂ = 1 : 1","36 جزيء O₃ و36 ذرة كربون"]'::jsonb, '["المعادلة: C + O₃ → CO + O₂","عدّ الذرات: C: 1 في كل طرف؛ O: 3 في المتفاعلات، و1 + 2 = 3 في النواتج","النسبة بين O₃ وO₂ هي 1 : 1","عدد جزيئات O₃ = 36 × 1 = 36 جزيئًا","عدد ذرات C = 36 × 1 = 36 ذرة"]'::jsonb, '[{"element":"كتابة المعادلة الصحيحة C + O₃ → CO + O₂","marks":1},{"element":"التحقق من وزن المعادلة بعدّ ذرات الكربون والأكسجين","marks":1},{"element":"حساب 36 جزيئًا من O₃","marks":1},{"element":"حساب 36 ذرة كربون","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"معادلة صحيحة وموزونة مع تحقق بعدّ الذرات وحساب العددين صحيحًا"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"1–2 درجة","description":"عنصر أو عنصران صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ضرب 36 في 3 بحجة أن O₃ يحتوي 3 ذرات","كتابة O بدلًا من O₂ في النواتج","إغفال عدّ ذرات الأكسجين في CO عند التحقق من الوزن"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-18T03:32:48.102Z"}'::jsonb),
('essay', 3, null::int, null, null, 'عدد جزيئات O₃ = (4.5 × 10²⁴) ÷ 3 = 1.5 × 10²⁴ جزيء. عدد جزيئات O₂ = (4.5 × 10²⁴) ÷ 2 = 2.25 × 10²⁴ جزيء. عدد جزيئات O₂ أكبر بمقدار 1.5 مرة من عدد جزيئات O₃. والسبب أن جزيء الأوزون يحتاج إلى 3 ذرات أكسجين، أما جزيء O₂ فيحتاج إلى ذرتين فقط؛ فالذرات نفسها تكوّن عددًا أكبر من الجزيئات الصغيرة.', '["O₃: 4.5 × 10²⁴ ÷ 3 = 1.5 × 10²⁴ جزيء","O₂: 4.5 × 10²⁴ ÷ 2 = 2.25 × 10²⁴ جزيء","المقارنة: عدد جزيئات O₂ أكبر بـ 1.5 مرة","التفسير: O₃ يحتاج 3 ذرات و O₂ يحتاج ذرتين"]'::jsonb, '["جزيئات O₃ = (4.5 × 10²⁴) ÷ 3 = 1.5 × 10²⁴","جزيئات O₂ = (4.5 × 10²⁴) ÷ 2 = 2.25 × 10²⁴","النسبة = (2.25 × 10²⁴) ÷ (1.5 × 10²⁴) = 1.5","السبب: عدد الذرات في الجزيء 3 في O₃ وذرتان في O₂"]'::jsonb, '[{"element":"حساب جزيئات O₃ = 1.5 × 10²⁴","marks":1},{"element":"حساب جزيئات O₂ = 2.25 × 10²⁴","marks":1},{"element":"المقارنة بين العددين (النسبة 1.5)","marks":1},{"element":"تفسير الفرق بعدد الذرات في كل جزيء","marks":1},{"element":"كتابة الناتج بالصيغة العلمية الصحيحة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حساب العددين حسابًا صحيحًا بالصيغة العلمية، والمقارنة، وتفسير الفرق بعدد الذرات في الجزيء"},{"level":"3–4 درجات","description":"حساب صحيح للعددين مع نقص في المقارنة أو التفسير"},{"level":"1–2 درجة","description":"حساب صحيح لأحد العددين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ضرب عدد الذرات في 3 بدلًا من القسمة","خطأ في الأس عند القسمة (تغيير الأس 24)","القول إن O₃ أكثر عددًا لأنه أكبر جزيئًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-18T03:32:48.103Z"}'::jsonb)
