from (values
('mcq', 1, 'ما السبب الرئيس لوجود عدة فروع لعلم الكيمياء؟', null, '["اختلاف قوانين الكيمياء المطبقة من فرع إلى آخر","حرص الكيميائيين على إبعاد الدراسات بعضها عن بعض","وجود أنواع كثيرة من المادة تتنوع معها مجالات الدراسة","اقتصار علم الكيمياء على نوع واحد من المادة"]'::jsonb, 'فهم', 'تفسير سبب', 'سهل', 'الكتاب ص 21 — الكيمياء: علم أساسي (سبب تعدد الفروع)'),
('mcq', 2, 'تشترك الكيمياء العضوية وكيمياء البلمرات في دراسة البلاستيك. ماذا يدل ذلك على فروع الكيمياء؟', null, '["أن مجالات دراسة كثير من الفروع تتداخل مع بعضها","أن أحد الفرعين لا حاجة إليه ويمكن الاستغناء عنه","أن الفرعين يدرسان المادة بالأسلوب نفسه ولا فرق بينهما","أن البلاستيك مادة لا تنتمي إلى أي فرع من الفروع"]'::jsonb, 'فهم', 'استنتاج من مثال', 'متوسط', 'الكتاب ص 21 — الكيمياء: علم أساسي (تداخل الفروع)'),
('mcq', 3, 'يدرس مختبر مادة بلاستيكية جديدة؛ يهتم فريق فيه بأنها تحتوي على الكربون، ويهتم فريق آخر بعملية البلمرة التي أنتجتها. أيّ فرعين من فروع الكيمياء يعمل فيهما الفريقان على الترتيب؟', null, '["الكيمياء غير العضوية وكيمياء البلمرات","الكيمياء العضوية والكيمياء الحرارية","الكيمياء التحليلية والكيمياء البيئية","الكيمياء العضوية وكيمياء البلمرات"]'::jsonb, 'تطبيق', 'تطبيق على موقف', 'صعب', 'الكتاب ص 21 — الكيمياء: علم أساسي (تداخل الفروع)'),
('mcq', 4, 'فيما يأتي بعض فروع الكيمياء ومجال دراسة كل منها. ماذا تدل عليه الفروق بين مجالات الدراسة؟', '{"headers":["الفرع","مجال الدراسة"],"rows":[["الكيمياء العضوية","المواد التي تحتوي على الكربون"],["الكيمياء الفيزيائية","سلوك المادة وتغيراتها وتغيرات الطاقة المصاحبة لها"],["الكيمياء الحيوية","المادة والعمليات الحيوية في المخلوقات الحية"]]}'::jsonb, '["أن كل فرع يدرس مادة لا يدرسها أي فرع آخر","أن كل فرع يركز على جانب معين من المادة أو تغيراتها","أن بعض الفروع أهم من غيرها في فهم المادة","أن الفروع تدرس المادة نفسها بالطريقة نفسها"]'::jsonb, 'فهم', 'تفسير بيانات', 'متوسط', 'الكتاب ص 21 — الكيمياء: علم أساسي؛ ص 21 — بعض فروع الكيمياء'),
('mcq', 5, 'ما الذي يُتوقع أن يحدث لمجالات الدراسة في الكيمياء إذا اكتُشفت أنواع جديدة من المادة؟', null, '["تتوقف الدراسة لأن الفروع الحالية اكتملت","تُدمج جميع الفروع في فرع واحد","تتسع مجالات الدراسة وقد تظهر فروع جديدة","تقل مجالات الدراسة لأن المادة صارت أكثر تعقيدًا"]'::jsonb, 'فهم', 'توقع من التعليل', 'صعب', 'الكتاب ص 21 — الكيمياء: علم أساسي (سبب تعدد الفروع)'),
('mcq', 6, 'لماذا يُعدّ فهم الكيمياء أساسًا لعلوم الأحياء والفيزياء والأرض والبيئة؟', null, '["لأن هذه العلوم تدرس الكائنات الحية وحدها","لأن كل هذه العلوم فروع من علم الكيمياء","لأن الكيمياء تدرس الأجسام الكبيرة فقط","لأن هذه العلوم تتعامل مع المادة والتغيرات التي تطرأ عليها"]'::jsonb, 'فهم', 'تفسير أهمية', 'سهل', 'الكتاب ص 21 — الكيمياء: علم أساسي'),
('mcq', 7, 'لماذا خُصّص فرع للكيمياء الحيوية وفرع آخر للكيمياء البيئية؟', null, '["لأن المادة توجد في الكائنات الحية وفي البيئة، ولكل منهما مجال دراسة خاص","لأن الكائنات الحية والبيئة لا تحتويان على مادة","لأن الفرعين يدرسان الموضوع نفسه ولا فرق بينهما","لأن المادة في الكائنات الحية لا تخضع لقوانين الكيمياء"]'::jsonb, 'فهم', 'تفسير تعدد الفروع', 'متوسط', 'الكتاب ص 21 — الكيمياء: علم أساسي؛ ص 21 — بعض فروع الكيمياء'),
('essay', 1, 'فسّر سبب وجود عدة فروع لعلم الكيمياء، واذكر مثالًا على فرعين تتداخل مجالا دراستهما.', null, null, 'فهم', 'تفسير مع مثال', 'سهل', 'الكتاب ص 21 — الكيمياء: علم أساسي'),
('essay', 2, 'يعمل ثلاثة باحثين: الأول يدرس الأدوية، والثاني يدرس المعادن والفلزات، والثالث يدرس تلوث الماء. فسّر لماذا يعمل كل منهم في فرع مختلف من الكيمياء، وسمِّ الفرع المناسب لكل باحث.', null, null, 'تطبيق', 'تطبيق على مواقف', 'متوسط', 'الكتاب ص 21 — الكيمياء: علم أساسي؛ ص 21 — بعض فروع الكيمياء'),
('essay', 3, 'قال طالب: «لو جُمعت فروع الكيمياء في علم واحد دون تقسيم لكان أفضل، لأن الفروع تتداخل أصلًا». قوّم هذا الرأي مبينًا ما يبرر وجود الفروع وما يعنيه تداخلها.', null, null, 'تقويم', 'تقويم رأي', 'صعب', 'الكتاب ص 21 — الكيمياء: علم أساسي')
