from (values
('mcq', 1, 2, 'المادة في الكون أنواع كثيرة، فتتنوع مجالات الدراسة في الكيمياء، ولذلك تقسَّم تقليديًّا إلى فروع؛ فسبب تعدد الفروع هو وجود أنواع كثيرة من المادة تتنوع معها مجالات الدراسة.', '["قوانين الكيمياء واحدة؛ والفروع تتميز بنوع المادة والتغيرات التي تدرسها لا باختلاف القوانين.","الفروع يتداخل كثير منها؛ فالتقسيم ليس لعزل الدراسات بل لتركيز كل فرع على مجال معين.","","الكيمياء تدرس أنواعًا كثيرة من المادة، ولهذا تعددت فروعها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:32:48.103Z"}'::jsonb),
('mcq', 2, 0, 'دراسة فرعين مختلفين للبلاستيك نفسه تعني أن المادة الواحدة تُدرس من أكثر من جانب، فمجالات دراسة كثير من الفروع تتداخل مع بعضها.', '["","كل فرع يدرس جوانب مختلفة من المادة نفسها، فلا يغني أحدهما عن الآخر.","لكل فرع تركيزه الخاص؛ فالتداخل في مادة واحدة لا يعني تطابق الفرعين.","البلاستيك يُدرس في فرعين على الأقل، هما العضوية وكيمياء البلمرات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:32:48.103Z"}'::jsonb),
('mcq', 3, 3, 'احتواء المادة على الكربون مجال الكيمياء العضوية، وعملية البلمرة والمواد البلاستيكية مجال كيمياء البلمرات؛ لذلك يعمل الفريقان في الكيمياء العضوية وكيمياء البلمرات، وهذا مثال على تداخل الفروع.', '["المواد المحتوية على الكربون تُدرس في الكيمياء العضوية، أما غير العضوية فتدرس المواد التي لا تحتوي على كربون عمومًا.","عملية البلمرة تُدرس في كيمياء البلمرات، أما الحرارية فتدرس الحرارة الناتجة عن العمليات الكيميائية.","التحليلية تدرس أنواع المواد ومكوناتها، والبيئية تدرس المادة والبيئة؛ وليس هذا ما يهتم به الفريقان.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:32:48.104Z"}'::jsonb),
('mcq', 4, 1, 'تختلف مجالات الدراسة بين الكيمياء العضوية (المواد المحتوية على كربون) والفيزيائية (السلوك والتغيرات والطاقة) والحيوية (المادة في المخلوقات الحية)، فهذا يدل على أن كل فرع يركز على جانب معين من المادة أو تغيراتها.', '["الفروع يتداخل كثير منها؛ فقد تُدرس المادة الواحدة في أكثر من فرع.","","التنوع في مجالات الدراسة لا يعني تفاضل الفروع، بل يعكس تنوع المادة.","مجالات الدراسة المعروضة مختلفة؛ فلكل فرع تركيز مختلف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:32:48.104Z"}'::jsonb),
('mcq', 5, 2, 'مجالات الدراسة تتنوع بسبب كثرة أنواع المادة، فإذا اكتُشفت أنواع جديدة اتسعت مجالات الدراسة وقد تظهر فروع جديدة.', '["تنوع المادة هو سبب تنوع مجالات الدراسة؛ فاكتشاف أنواع جديدة يزيد الدراسة ولا يوقفها.","زيادة أنواع المادة تزيد تنوع المجالات، فلا يؤدي ذلك إلى الدمج.","","كثرة أنواع المادة سبب في تنوع مجالات الدراسة لا في نقصانها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:32:48.104Z"}'::jsonb),
('mcq', 6, 3, 'الكيمياء هي دراسة المادة والتغيرات التي تطرأ عليها، والعلوم الأخرى تتعامل مع المادة والتغيرات نفسها، ولذلك يُعدّ فهم الكيمياء أساسًا لها.', '["الفيزياء وعلوم الأرض لا تقتصر على الكائنات الحية؛ والجامع بينها دراسة المادة وتغيراتها.","هي علوم مستقلة تعتمد على فهم الكيمياء، وليست فروعًا منها.","الكيمياء تدرس المادة وتغيراتها بأحجامها كلها، ومنها الذرات الدقيقة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-18T03:32:48.104Z"}'::jsonb),
('mcq', 7, 0, 'تنوع المادة يعني أن لها مواضع متعددة؛ فهي توجد في الكائنات الحية وفي البيئة، وتتنوع مجالات الدراسة، فخُصّص لكل منهما فرع.', '["","كل شيء في الكون مكوّن من مادة، ومنها ما في الكائنات الحية والبيئة.","الحيوية تدرس المادة والعمليات الحيوية في المخلوقات الحية، والبيئية تدرس المادة والبيئة.","تخضع المادة في الكائنات الحية للكيمياء أيضًا، ولذلك تُدرس عملياتها كيميائيًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-18T03:32:48.104Z"}'::jsonb),
('essay', 1, null::int, null, null, 'توجد فروع عدة للكيمياء لأن أنواع المادة كثيرة ومتنوعة، فتتنوع مجالات الدراسة في الكيمياء، ولذلك تُقسَّم تقليديًّا إلى فروع يركز كل منها على دراسة معينة. وكثير من هذه الفروع يتداخل؛ فالكيمياء العضوية وكيمياء البلمرات تشتركان في دراسة البلاستيك.', '["كثرة أنواع المادة وتنوعها","تنوع مجالات الدراسة وتقسيم الكيمياء إلى فروع يركز كل منها على دراسة معينة","ذكر فرعين متداخلين (العضوية وكيمياء البلمرات)","مجال التداخل: دراسة البلاستيك"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر أن سبب الفروع كثرة أنواع المادة","marks":1},{"element":"ربط ذلك بتنوع مجالات الدراسة وتركيز كل فرع على دراسة معينة","marks":1},{"element":"ذكر فرعين متداخلين","marks":1},{"element":"ذكر مجال التداخل (مثل البلاستيك)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل مع مثال صحيح لفرعين متداخلين ومجال تداخلهما"},{"level":"2–3 درجات","description":"تفسير صحيح مع نقص في المثال أو مجال التداخل"},{"level":"1 درجة","description":"ذكر السبب أو المثال فقط دون ربط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الفروع منفصلة تمامًا ولا تتداخل","تعليل التقسيم بسبب لا علاقة له بتنوع المادة","ذكر فرعين دون بيان ما يشتركان فيه"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:32:48.105Z"}'::jsonb),
('essay', 2, null::int, null, null, 'يعمل الباحثون في فروع مختلفة لأن أنواع المادة التي يدرسونها مختلفة، فتتنوع مجالات الدراسة. الأول يدرس الأدوية وهي مواد تحتوي على الكربون، فيعمل في الكيمياء العضوية. والثاني يدرس المعادن والفلزات وهي مواد لا تحتوي على كربون عمومًا، فيعمل في الكيمياء غير العضوية. والثالث يدرس التلوث أي المادة والبيئة، فيعمل في الكيمياء البيئية.', '["الأدوية: الكيمياء العضوية (مواد تحتوي على كربون)","المعادن والفلزات: الكيمياء غير العضوية (مواد لا تحتوي على كربون عمومًا)","تلوث الماء: الكيمياء البيئية (المادة والبيئة)","اختلاف الفروع سببه اختلاف نوع المادة ومجال الدراسة"]'::jsonb, '[]'::jsonb, '[{"element":"الأدوية: العضوية مع المبرر","marks":1},{"element":"المعادن والفلزات: غير العضوية مع المبرر","marks":1},{"element":"تلوث الماء: البيئية مع المبرر","marks":1},{"element":"ربط اختلاف الفروع باختلاف أنواع المادة ومجالات الدراسة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تسمية الفروع الثلاثة بمبرراتها مع تفسير عام صحيح"},{"level":"2–3 درجات","description":"تسمية صحيحة لفرعين أو ثلاثة مع نقص في المبرر أو التفسير العام"},{"level":"1 درجة","description":"تسمية فرع واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الأدوية من الكيمياء غير العضوية","الخلط بين الكيمياء البيئية والحيوية","تسمية الفروع دون تفسير سبب اختلافها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-18T03:32:48.105Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الرأي غير مقنع. فالكيمياء قُسِّمت إلى فروع بسبب وجود أنواع كثيرة من المادة تتنوع معها مجالات الدراسة، فيركز كل فرع على دراسة معينة (كالمواد المحتوية على كربون، أو العمليات الحيوية، أو البيئة). أما تداخل الفروع فلا ينفي الحاجة إليها؛ فهو يعني أن المادة الواحدة تُدرس من جوانب متعددة، كالبلاستيك الذي تدرس العضوية احتواءه على الكربون وتدرس كيمياء البلمرات البلمرة والمواد البلاستيكية.', '["الحكم بأن الرأي غير مقنع","تبرير الفروع بتنوع المادة وتنوع مجالات الدراسة","التداخل يعني دراسة المادة الواحدة من جوانب متعددة","مثال على التداخل (البلاستيك في العضوية وكيمياء البلمرات)"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم على الرأي","marks":1},{"element":"تبرير وجود الفروع بتنوع المادة ومجالات الدراسة","marks":2},{"element":"تفسير معنى التداخل مع مثال","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"حكم صحيح مع تبرير كامل للفروع وتفسير للتداخل بمثال"},{"level":"3–4 درجات","description":"حكم صحيح مع تبرير أو تفسير ناقص"},{"level":"1–2 درجة","description":"حكم صحيح دون تبرير مقنع"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الموافقة على الرأي لأن التداخل يلغي الحاجة إلى الفروع","عدّ التداخل دليلًا على أن الفروع خاطئة","ذكر أن الفروع وُجدت لاختلاف القوانين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:32:48.105Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K1-C1-L2-O01') and x.type = v.type and x.number = v.number
