('mcq', 1, 'ما الفرق الأساسي بين الكتلة والوزن؟', null, '["الكتلة تتغير بتغير المكان، أما الوزن فثابت دائمًا","الكتلة ثابتة في أي مكان، أما الوزن فيتغير بتغير قوة الجاذبية","كلتاهما ثابتة في أي مكان داخل الأرض أو خارجها","كلتاهما تتغير بتغير قوة الجاذبية"]'::jsonb, 'تحليل', 'مقارنة', 'سهل', 'الكتاب ص 19 — الكتلة والوزن'),
('mcq', 2, 'لماذا يستعمل العلماء الكتلة بدلًا من الوزن في قياساتهم؟', null, '["لأن الوزن لا يعتمد على كمية المادة إطلاقًا","لأن قياس الكتلة أسهل من قياس الوزن في كل الأحوال","لأن قوة الجاذبية ثابتة في كل الأماكن فلا حاجة إلى الوزن","لأن الكتلة مستقلة عن قوة الجاذبية فلا تتغير من مكان إلى آخر"]'::jsonb, 'فهم', 'تفسير سبب', 'سهل', 'الكتاب ص 20 — الكتلة والوزن'),
('mcq', 3, 'كتلة جسم 30 kg. إذا كان تسارع الجاذبية على سطح القمر 1.6 m/s² فما وزن الجسم على القمر؟ (وزن الجسم = كتلته × تسارع الجاذبية المحلي)', null, '["48 N","294 N","30 N","19 N"]'::jsonb, 'تطبيق', 'حساب الوزن', 'متوسط', 'الكتاب ص 20 — الكتلة والوزن'),
('mcq', 4, 'كيف يُحسب وزن جسم ما؟', null, '["بقسمة كتلته على تسارع الجاذبية الأرضية","بجمع كتلته مع حجمه","بضرب كتلته في تسارع الجاذبية الأرضية المحلي","بالاكتفاء بكتلته دون النظر إلى الجاذبية"]'::jsonb, 'تذكر', 'تذكر قانون', 'سهل', 'الكتاب ص 20 — الكتلة والوزن'),
('mcq', 5, 'قيست كتلة شخص ووزنه في مدينتين مختلفتين في الارتفاع عن سطح البحر. ماذا تستنتج من القياسات؟', '{"headers":["المدينة","الارتفاع عن سطح البحر","الكتلة المقيسة","الوزن المقيس"],"rows":[["جدة","0 m","70.00 kg","686.7 N"],["أبها","2200 m","70.00 kg","686.2 N"]]}'::jsonb, '["الكتلة أقل في أبها لأن كمية المادة في الجسم نقصت","الكتلة لم تتغير، والوزن أقل في أبها لأن قوة الجاذبية تقل مع الارتفاع","الوزن لم يتغير لأن الفرق بين القيمتين صغير لا يُعتد به","الكتلة والوزن كلاهما أقل في أبها"]'::jsonb, 'تحليل', 'تحليل بيانات', 'متوسط', 'الكتاب ص 20 — الكتلة والوزن؛ ص 38 — إتقان حل المسائل'),
('mcq', 6, 'نُقلت حقيبة إلى القمر فقلّ وزنها. قال طالب: «نقصت كمية المادة في الحقيبة». ما تقويمك لهذا القول؟', null, '["صحيح؛ لأن الوزن مقياس لكمية المادة وحدها","صحيح؛ لأن الكتلة تقل كلما ضعفت الجاذبية","خطأ؛ فكتلة الحقيبة ثابتة والوزن قلّ بسبب ضعف جاذبية القمر","خطأ؛ لأن الوزن لا يتغير بتغير المكان"]'::jsonb, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 20 — الكتلة والوزن'),
('mcq', 7, 'نُقل جسم من الأرض إلى كوكب جاذبيته ضعف جاذبية الأرض. كيف تتغير كتلته ووزنه؟', null, '["تتضاعف الكتلة ويبقى الوزن ثابتًا","تتضاعف الكتلة والوزن معًا","تبقى الكتلة ثابتة ويقل الوزن إلى النصف","تبقى الكتلة ثابتة ويتضاعف الوزن"]'::jsonb, 'تحليل', 'تحليل أثر تغير الجاذبية', 'صعب', 'الكتاب ص 20 — الكتلة والوزن'),
('essay', 1, 'قارن بين الكتلة والوزن من حيث ما يقيسه كل منهما، وتأثر كل منهما بتغير موضع الجسم.', null, null, 'تحليل', 'مقارنة', 'سهل', 'الكتاب ص 19 — الكتلة والوزن؛ ص 20'),
('essay', 2, 'كتلة جسم 5.0 kg. تسارع الجاذبية على سطح الأرض 9.8 m/s² وعلى سطح القمر 1.6 m/s². احسب وزن الجسم على كل منهما، ثم حدّد كتلته على القمر، وفسّر الفرق بين الوزنين.', null, null, 'تطبيق', 'حساب مع تفسير', 'متوسط', 'الكتاب ص 20 — الكتلة والوزن'),
('essay', 3, 'اقترح طالب أن يستعمل العلماء الوزن بدلًا من الكتلة في قياساتهم لأنه الأقرب إلى الاستعمال اليومي. قوّم هذا الاقتراح مبينًا لماذا يفضّل العلماء الكتلة، وما الذي يلزم معرفته عند المقارنة بين وزنين في مكانين مختلفين.', null, null, 'تقويم', 'تقويم اقتراح', 'صعب', 'الكتاب ص 20 — الكتلة والوزن')
