from (values
('mcq', 1, 1, 'الكتلة مقياس لكمية المادة وهي ثابتة في أي مكان، أما الوزن فمقياس لكمية المادة ولقوة جذب الأرض لها وتتغير هذه القوة من مكان إلى آخر؛ فالكتلة ثابتة في أي مكان، والوزن يتغير بتغير قوة الجاذبية.', '["هذا عكس الصحيح؛ فالوزن هو الذي يتغير بتغير المكان، والكتلة ثابتة.","","الوزن يعتمد على قوة الجذب التي تتغير من مكان إلى آخر، فليس ثابتًا.","الكتلة مقياس لكمية المادة ولا تعتمد على قوة الجاذبية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:32:48.106Z"}'::jsonb),
('mcq', 2, 3, 'تختلف قوة الجاذبية من مكان إلى آخر فيختلف الوزن، أما الكتلة فثابتة في أي مكان، ولذلك يستعمل العلماء الكتلة لأنها مستقلة عن قوة الجاذبية.', '["الوزن يعتمد على كمية المادة وعلى قوة الجذب معًا.","السبب هو ثبات الكتلة واستقلالها عن الجاذبية، لا سهولة القياس.","قوة الجاذبية ليست ثابتة؛ فهي تقل عند الابتعاد عن سطح الأرض.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:32:48.106Z"}'::jsonb),
('mcq', 3, 0, 'الوزن = الكتلة × تسارع الجاذبية المحلي = 30 kg × 1.6 m/s² = 48 N؛ فوزن الجسم على القمر 48 N.', '["","استُعمل تسارع جاذبية الأرض (9.8 m/s²) بدلًا من تسارع جاذبية القمر المعطى.","خلط بين الوزن والكتلة؛ فالوزن يُحسب بضرب الكتلة في تسارع الجاذبية.","قسمة الكتلة على تسارع الجاذبية بدلًا من ضربها فيه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-10-18T03:32:48.106Z"}'::jsonb),
('mcq', 4, 2, 'وزن الجسم هو حاصل ضرب كتلته في تسارع الجاذبية الأرضية المحلي، أي يُحسب بضرب كتلته في تسارع الجاذبية الأرضية المحلي.', '["الوزن حاصل ضرب لا حاصل قسمة.","الحجم لا يدخل في حساب الوزن، والجمع غير صحيح.","","الوزن يعتمد على قوة الجذب أيضًا، فلا يساوي الكتلة وحدها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:32:48.106Z"}'::jsonb),
('mcq', 5, 1, 'الكتلة 70.00 kg في المدينتين فهي ثابتة، والوزن 686.2 N في أبها أقل من 686.7 N في جدة بسبب نقصان قوة الجاذبية مع الارتفاع؛ فالكتلة لم تتغير والوزن أقل في أبها.', '["كمية المادة لم تتغير؛ والقياسان يُظهران كتلة واحدة في المدينتين.","","الفرق صغير لكنه حقيقي، وسببه اختلاف قوة الجاذبية بين الموضعين.","الكتلة المقيسة واحدة في المدينتين؛ والوزن فقط هو الذي قلّ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:32:48.106Z"}'::jsonb),
('mcq', 6, 2, 'الكتلة مقياس لكمية المادة وهي ثابتة في أي مكان، والذي قلّ هو الوزن بسبب ضعف جاذبية القمر؛ فالقول خطأ، وكتلة الحقيبة ثابتة والوزن قلّ بسبب ضعف جاذبية القمر.', '["الوزن يقيس كمية المادة وقوة الجذب معًا، وقلته هنا سببها قوة الجذب.","الكتلة ثابتة في أي مكان ولا تتأثر بقوة الجاذبية.","","الوزن يتغير بتغير المكان؛ وقد قلّ فعلًا في هذا الموقف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-10-18T03:32:48.106Z"}'::jsonb),
('mcq', 7, 3, 'الكتلة مستقلة عن قوة الجاذبية فتبقى ثابتة، والوزن = الكتلة × تسارع الجاذبية فإذا تضاعفت الجاذبية تضاعف الوزن؛ أي تبقى الكتلة ثابتة ويتضاعف الوزن.', '["الكتلة هي التي تبقى ثابتة؛ والوزن هو الذي يتغير بتغير الجاذبية.","الكتلة لا تتأثر بقوة الجاذبية فلا تتضاعف.","الوزن يتناسب طرديًّا مع الجاذبية؛ فمضاعفة الجاذبية تضاعف الوزن ولا تنصّفه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:32:48.107Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الكتلة مقياس لكمية المادة، وهي ثابتة في أي مكان. أما الوزن فمقياس لكمية المادة ولقوة جذب الأرض لها، وهو يتغير بتغير موضع الجسم لأن قوة الجذب ليست ثابتة في جميع الأماكن؛ فيقل الوزن عند الابتعاد عن سطح الأرض.', '["الكتلة مقياس لكمية المادة","الوزن مقياس لكمية المادة ولقوة جذب الأرض لها","الكتلة ثابتة في أي مكان","الوزن يتغير بتغير الموضع لاختلاف قوة الجذب (يقل عند الابتعاد عن سطح الأرض)"]'::jsonb, '[]'::jsonb, '[{"element":"ما تقيسه الكتلة","marks":1},{"element":"ما يقيسه الوزن","marks":1},{"element":"ثبات الكتلة","marks":1},{"element":"تغير الوزن مع بيان سببه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة كاملة في الوجهين"},{"level":"2–3 درجات","description":"مقارنة صحيحة في وجه واحد أو مقارنة ناقصة في الوجهين"},{"level":"1 درجة","description":"تعريف واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الوزن لا علاقة له بقوة الجاذبية","القول إن كتلة الجسم تقل عند الابتعاد عن الأرض","عدّ الكتلة والوزن شيئًا واحدًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:32:48.107Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الوزن على الأرض = 5.0 kg × 9.8 m/s² = 49 N. الوزن على القمر = 5.0 kg × 1.6 m/s² = 8.0 N. كتلة الجسم على القمر 5.0 kg لأن الكتلة ثابتة في أي مكان. اختلف الوزنان لأن الوزن يعتمد على قوة الجاذبية، وهي أقل على القمر.', '["الوزن على الأرض 49 N","الوزن على القمر 8.0 N","الكتلة على القمر 5.0 kg","الفرق سببه اختلاف قوة الجاذبية"]'::jsonb, '["الوزن على الأرض = الكتلة × تسارع جاذبية الأرض = 5.0 kg × 9.8 m/s² = 49 N","الوزن على القمر = 5.0 kg × 1.6 m/s² = 8.0 N","الكتلة ثابتة في أي مكان، فكتلة الجسم على القمر = 5.0 kg"]'::jsonb, '[{"element":"كتابة العلاقة الصحيحة (الوزن = الكتلة × تسارع الجاذبية)","marks":1},{"element":"الوزن على الأرض 49 N","marks":1},{"element":"الوزن على القمر 8.0 N","marks":1},{"element":"الكتلة على القمر 5.0 kg","marks":1},{"element":"تفسير الفرق باختلاف قوة الجاذبية","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حل كامل صحيح بالوحدات والتفسير"},{"level":"3–4 درجات","description":"حساب صحيح مع نقص في الكتلة أو التفسير"},{"level":"1–2 درجة","description":"العلاقة أو حساب واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب وزن القمر بقسمة الكتلة على 1.6","القول إن الكتلة على القمر 8.0 kg","نسيان الوحدات أو كتابتها خطأ"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-10-18T03:32:48.107Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الاقتراح غير عملي. فكتلة الجسم ثابتة في أي مكان، أما وزنه فيختلف من مكان إلى آخر بسبب اختلاف قوة الجاذبية. ولذلك يتطلب استعمال الوزن في المقارنة بين مكانين معرفة قوة الجاذبية في كل منهما. ولما كانت الكتلة مستقلة عن قوة الجاذبية فإن العلماء يستعملونها في قياساتهم.', '["الحكم بأن الاقتراح غير عملي","الكتلة ثابتة في أي مكان","الوزن يختلف من مكان إلى آخر بسبب اختلاف قوة الجاذبية","المقارنة بالوزن تتطلب معرفة قوة الجاذبية في الأماكن المقارنة","الكتلة مستقلة عن الجاذبية فيستعملها العلماء"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم على الاقتراح","marks":1},{"element":"ثبات الكتلة","marks":1},{"element":"تغير الوزن مع بيان سببه","marks":1},{"element":"لزوم معرفة قوة الجاذبية عند المقارنة بالوزن","marks":1},{"element":"استقلال الكتلة عن الجاذبية سببًا لتفضيلها","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حكم صحيح مع تبرير كامل للعناصر الأربعة"},{"level":"3–4 درجات","description":"حكم صحيح مع نقص عنصر أو عنصرين"},{"level":"1–2 درجة","description":"حكم دون تبرير كافٍ أو تبرير جزئي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الموافقة على الاقتراح لأن الوزن أبسط","القول إن الوزن ثابت في كل الأماكن","عدّ سبب تفضيل الكتلة سهولة قياسها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:32:48.107Z"}'::jsonb)
