('mcq', 1, 'ما سبب اهتمام الكيميائيين بالوصف تحت المجهري للمادة؟', null, '["لأن الخواص الملحوظة لا علاقة لها بتركيب المادة","لأن ما نلاحظه من خواص المادة وتغيراتها يعتمد على تركيب ذراتها وما يحدث لها","لأن الذرات يمكن رؤيتها بسهولة بالمجاهر الضوئية","لأن الوصف بالعين المجردة يكفي لتفسير كل التغيرات"]'::jsonb, 'فهم', 'تفسير سبب', 'سهل', 'الكتاب ص 20 — التركيب والخواص الملحوظة'),
('mcq', 2, 'لماذا لا تُرى الذرات بالمجاهر الضوئية؟', null, '["لأنها لا تشغل حيزًا من الفراغ أبدًا","لأنها توجد في المواد الغازية فقط","لأنها تتغير باستمرار فلا يمكن تثبيتها","لأنها صغيرة جدًّا؛ فتريليون ذرة تشغل حيزًا كنقطة في آخر جملة"]'::jsonb, 'فهم', 'تفسير سبب', 'سهل', 'الكتاب ص 20 — التركيب والخواص الملحوظة'),
('mcq', 3, 'لا نرى من خارج مبنى المدرسة قضبان الحديد داخل جدرانه، مع أنها تعطي المبنى شكله وثباته. ما الذي يقابل هذه القضبان في دراسة المادة؟', null, '["الذرات وسلوكها التي لا تُرى لكنها تفسّر الخواص الملحوظة للمادة","النماذج التي يرسمها العلماء لتمثيل المادة","الخواص الواضحة التي لا تحتاج إلى مجهر","الأجهزة التي يقيس بها الكيميائيون الكتلة"]'::jsonb, 'فهم', 'تفسير بالقياس', 'متوسط', 'الكتاب ص 20 — التركيب والخواص الملحوظة'),
('mcq', 4, 'لاحظ طالب أن مسمارًا حديديًّا تحوّل لونه إلى البني المحمر بعد تركه في الهواء الرطب. كيف يساعد الوصف تحت المجهري على تفسير هذه الملاحظة؟', null, '["يُغني عن ملاحظة تغير اللون أصلًا","يبيّن أن اللون تغيّر دون أن تتأثر الذرات","يفسّر تغيّر اللون بما يطرأ على ذرات المادة من تغيرات","يُظهر أن المادة لم تتغير لأن شكل المسمار بقي كما هو"]'::jsonb, 'فهم', 'تطبيق على موقف', 'متوسط', 'الكتاب ص 20 — التركيب والخواص الملحوظة'),
('mcq', 5, 'إذا كان تريليون ذرة يمكن أن يوضع فوق نقطة في نهاية جملة، فماذا يعني ذلك لدراسة الكيميائيين للذرات؟', null, '["يحتاجون إلى وسائل غير الرؤية المباشرة، كالنماذج، لتفسير سلوكها","يمكنهم عدّ الذرات المنفردة بالعين المجردة","يمكنهم دراستها بالمجاهر الضوئية الشائعة","لا يمكن تفسير سلوكها بأي وسيلة"]'::jsonb, 'فهم', 'استنتاج', 'صعب', 'الكتاب ص 20 — التركيب والخواص الملحوظة'),
('mcq', 6, 'إلام تهدف الكيمياء فيما يتعلق بالأحداث التي لا تُرى بالعين المجردة؟', null, '["إلى تجاهلها لأن التغيرات الملحوظة تكفي","إلى رؤيتها مباشرة بالمجاهر الضوئية","إلى حصر دراستها في فرع واحد من الكيمياء","إلى تفسيرها لأنها ينتج عنها تغيرات يمكن ملاحظتها"]'::jsonb, 'فهم', 'تحديد هدف', 'سهل', 'الكتاب ص 20 — التركيب والخواص الملحوظة'),
('mcq', 7, 'أيّ العبارات الآتية تمثّل وصفًا على المستوى تحت المجهري لقطعة من الحديد؟', null, '["لونها رمادي وسطحها لامع ظاهر للعين","كتلتها 25 g وتشغل حيزًا يمكن قياسه","تتركب من ذرات لا تُرى بالمجهر الضوئي","تنجذب إلى المغناطيس انجذابًا يمكن ملاحظته"]'::jsonb, 'فهم', 'تمييز مستوى الوصف', 'متوسط', 'الكتاب ص 20 — التركيب والخواص الملحوظة'),
('essay', 1, 'فسّر لماذا يهتم الكيميائيون بوصف المادة على المستوى تحت المجهري.', null, null, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 20 — التركيب والخواص الملحوظة'),
('essay', 2, 'يرى من يشاهد مبنى مدرسة من الخارج جدرانه ولا يرى قضبان الحديد داخلها. استعمل هذا المثال لتوضيح العلاقة بين ما نلاحظه من خواص المادة وما يحدث على المستوى تحت المجهري، موضحًا ما يقابل القضبان في المادة.', null, null, 'تطبيق', 'تفسير بالقياس', 'متوسط', 'الكتاب ص 20 — التركيب والخواص الملحوظة'),
('essay', 3, 'قال طالب: «ما دمنا نرى المادة وخواصها بوضوح فلا حاجة إلى دراسة الذرات». قوّم هذا القول مستندًا إلى حجم الذرات وإلى علاقة الملاحظات بتركيب المادة.', null, null, 'تقويم', 'تقويم قول', 'صعب', 'الكتاب ص 20 — التركيب والخواص الملحوظة')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K1-C1-L2-O03') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'تفسَّر بنية المادة وتركيبها وسلوكها على المستوى تحت المجهري، وكل ما نلاحظه يعتمد على تركيب الذرات والتغيرات التي تحدث لها؛ فالكيميائيون يهتمون بالوصف تحت المجهري لأن ما نلاحظه من خواص المادة وتغيراتها يعتمد على تركيب ذراتها وما يحدث لها.', '["كل ما نلاحظه عن المادة يعتمد على تركيب الذرات والتغيرات التي تحدث لها.","","الذرات صغيرة جدًّا فلا ترى بالمجاهر الضوئية.","العين المجردة لا ترى ما يحدث للذرات، وهو الذي يفسر التغيرات الملحوظة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:32:48.108Z"}'::jsonb),
('mcq', 2, 3, 'الذرات صغيرة جدًّا حتى إن تريليون ذرة يمكن أن تشغل حيزًا يساوي نقطة في آخر جملة، ولذلك لا يمكن رؤيتها بالمجاهر الضوئية؛ فهي جسيمات تحت مجهرية.', '["الذرات مادة وتشغل حيزًا، لكن حيزها صغير جدًّا.","الذرات تتركب منها المواد جميعها، ولا تقتصر على الغازات.","السبب هو صغر حجمها الشديد لا تغيرها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.108Z"}'::jsonb),
('mcq', 3, 0, 'قضبان الحديد مخفية داخل الجدران لكنها تعطي المبنى شكله وثباته، كذلك الذرات لا تُرى لكنها تحدد تركيب المادة وسلوكها وما نلاحظه من خواصها؛ فالذرات وسلوكها التي لا تُرى هي ما يقابل القضبان.', '["","النماذج أدوات لتمثيل ما لا يُرى، أما ما يعطي المادة تركيبها وخواصها فهو الذرات.","هذه تقابل ما يُرى من المبنى، وهو الجدران لا القضبان.","الأجهزة لا تحدد تركيب المادة؛ فما يقابل القضبان هو الذرات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:32:48.108Z"}'::jsonb),
('mcq', 4, 2, 'التغيرات الملحوظة، ومنها تغير اللون، تنتج عن أحداث لا ترى بالعين المجردة تحدث للذرات؛ فالوصف تحت المجهري يفسّر تغيّر اللون بما يطرأ على ذرات المادة من تغيرات.', '["الملاحظات هي نقطة البداية، والوصف تحت المجهري يفسرها ولا يلغيها.","ما نلاحظه يعتمد على تركيب الذرات والتغيرات التي تحدث لها.","","تغير اللون ملاحظة تدل على تغير في المادة، وبقاء الشكل لا ينفي ذلك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:32:48.108Z"}'::jsonb),
('mcq', 5, 0, 'صغر الذرات الشديد يعني أنها لا تُرى بالعين ولا بالمجاهر الضوئية، فيحتاج الكيميائيون إلى وسائل غير الرؤية المباشرة، كالنماذج، لتفسير سلوكها.', '["","الذرات أصغر من أن تُرى بالعين المجردة فلا يمكن عدّها بها.","الذرات صغيرة جدًّا حتى لا يمكن رؤيتها بالمجاهر الضوئية.","تفسَّر بنية المادة وسلوكها على المستوى تحت المجهري باستعمال وسائل مثل النماذج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-18T03:32:48.108Z"}'::jsonb),
('mcq', 6, 3, 'تهدف الكيمياء إلى تفسير الأحداث التي لا تُرى بالعين المجردة والتي ينتج عنها تغيرات ملحوظة؛ أي إلى تفسيرها لأنها ينتج عنها تغيرات يمكن ملاحظتها.', '["التغيرات الملحوظة تنتج عن هذه الأحداث وتحتاج إلى تفسير.","هذه الأحداث تحدث للذرات التي لا تُرى بالمجاهر الضوئية.","ليست مقصورة على فرع واحد؛ فهدف الكيمياء عمومًا تفسير ما لا يُرى.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.108Z"}'::jsonb),
('mcq', 7, 2, 'الوصف تحت المجهري يتناول الذرات التي تتركب منها المادة وهي لا تُرى بالمجاهر الضوئية؛ أما اللون واللمعان والكتلة والانجذاب إلى المغناطيس فملاحظات على المستوى المرئي؛ فالعبارة الصحيحة أنها تتركب من ذرات لا تُرى بالمجهر الضوئي.', '["اللون واللمعان من الخواص الملحوظة بالعين المجردة، وليسا وصفًا تحت مجهري.","الكتلة والحيز خاصيتان يُمكن قياسهما على المستوى المرئي.","","الانجذاب إلى المغناطيس ملاحظة عيانية تُفسَّر تحت المجهرية، وليست وصفًا تحت مجهري."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:32:48.109Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تتركب المواد من ذرات صغيرة جدًّا لا ترى بالعين المجردة ولا بالمجاهر الضوئية. وتفسَّر بنية المادة وتركيبها وسلوكها على المستوى تحت المجهري؛ فكل ما نلاحظه عن المادة يعتمد على تركيب الذرات والتغيرات التي تحدث لها. لذلك يهتم الكيميائيون بهذا المستوى لأن هدف الكيمياء تفسير الأحداث التي لا تُرى بالعين المجردة والتي ينتج عنها تغيرات ملحوظة.', '["الذرات صغيرة جدًّا لا ترى بالعين المجردة أو المجاهر الضوئية","بنية المادة وسلوكها تفسَّر تحت المجهري","الملاحظات تعتمد على تركيب الذرات والتغيرات التي تحدث لها","هدف الكيمياء تفسير الأحداث التي لا تُرى والتي ينتج عنها تغيرات ملحوظة"]'::jsonb, '[]'::jsonb, '[{"element":"صغر الذرات وتعذر رؤيتها","marks":1},{"element":"تفسير البنية والسلوك على المستوى تحت المجهري","marks":1},{"element":"اعتماد الملاحظات على تركيب الذرات وتغيراتها","marks":1},{"element":"هدف الكيمياء تفسير ما لا يُرى","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل بالعناصر الأربعة"},{"level":"2–3 درجات","description":"تفسير صحيح مع نقص عنصر أو عنصرين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الذرات تُرى بالمجاهر الضوئية","الاكتفاء بقول إن الذرات صغيرة دون ربطها بالتفسير","القول إن الملاحظات لا علاقة لها بالذرات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:32:48.109Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الجدران وشكل المبنى هي ما يمكن ملاحظته مباشرة، وتقابل الخواص والتغيرات التي نلاحظها في المادة. أما قضبان الحديد داخل الجدران فلا تُرى لكنها تعطي المبنى شكله واستقراره وثباته، وتقابل الذرات وسلوكها التي لا تُرى لكنها تحدد تركيب المادة وما نلاحظه من خواصها. فلا يكفي النظر الخارجي لفهم المبنى، وكذلك لا تكفي الملاحظة المباشرة لفهم المادة؛ لذلك يدرس الكيميائيون المستوى تحت المجهري.', '["الجدران وشكل المبنى تقابل الخواص والتغيرات الملحوظة","القضبان تقابل الذرات وسلوكها","القضبان تعطي المبنى شكله واستقراره كما تحدد الذرات تركيب المادة","الملاحظة المباشرة وحدها لا تكفي فتُدرس الذرات"]'::jsonb, '[]'::jsonb, '[{"element":"ما يقابل المرئي في المبنى (الجدران) في المادة","marks":1},{"element":"ما يقابل القضبان (الذرات وسلوكها)","marks":1},{"element":"دور القضبان والذرات في الشكل والثبات والتركيب","marks":1},{"element":"الاستنتاج: الحاجة إلى دراسة ما لا يُرى","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"توضيح كامل للتناظر والاستنتاج"},{"level":"2–3 درجات","description":"تناظر صحيح مع نقص في الدور أو الاستنتاج"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل القضبان مقابلة للخواص الظاهرة للمادة","جعل الجدران مقابلة للذرات","ذكر المثال دون ربطه بالمستوى تحت المجهري"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:32:48.109Z"}'::jsonb),
('essay', 3, null::int, null, null, 'القول غير صحيح. فالذرات صغيرة جدًّا لا ترى بالعين المجردة ولا بالمجاهر الضوئية، فتريليون ذرة تشغل حيزًا يعادل نقطة في آخر جملة، لذلك لا نرى ما يجري لها مباشرة. وكل ما نلاحظه عن المادة يعتمد على تركيب الذرات والتغيرات التي تحدث لها، فالتغيرات الملحوظة نتيجة أحداث تحت مجهرية لا تُرى. ولهذا فإن تفسير ما نراه يتطلب دراسة الذرات وسلوكها، وهذا هو هدف الكيمياء.', '["الحكم بأن القول غير صحيح","الذرات صغيرة جدًّا لا ترى (تريليون ذرة بحجم نقطة)","الملاحظات تعتمد على تركيب الذرات","التغيرات الملحوظة تنتج عن أحداث تحدث للذرات","تفسير ما نراه يتطلب دراسة الذرات"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم على القول","marks":1},{"element":"حجم الذرات الصغير جدًّا","marks":1},{"element":"اعتماد الملاحظات على تركيب الذرات","marks":1},{"element":"التغيرات الملحوظة نتيجة أحداث تحدث للذرات","marks":1},{"element":"الاستنتاج: دراسة الذرات ضرورية للتفسير","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حكم صحيح مع تبرير كامل"},{"level":"3–4 درجات","description":"حكم صحيح مع نقص في التبرير"},{"level":"1–2 درجة","description":"حكم صحيح بتبرير جزئي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الموافقة على القول لأن الخواص واضحة","القول إن الذرات تُرى بالمجاهر الضوئية العادية","عدّ المستوى تحت المجهري منفصلًا عما نلاحظه"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:32:48.109Z"}'::jsonb)
