('essay', 1, null::int, null, null, 'الكيمياء العضوية: تدرس المواد التي تحتوي على الكربون. الكيمياء غير العضوية: تدرس المواد التي لا تحتوي على كربون عمومًا. الكيمياء الفيزيائية: تدرس سلوك المادة وتغيراتها وتغيرات الطاقة المصاحبة لها. الكيمياء التحليلية: تدرس أنواع المواد ومكوناتها.', '["العضوية: المواد التي تحتوي على الكربون","غير العضوية: المواد التي لا تحتوي على كربون عمومًا","الفيزيائية: سلوك المادة وتغيراتها وتغيرات الطاقة المصاحبة لها","التحليلية: أنواع المواد ومكوناتها"]'::jsonb, '[]'::jsonb, '[{"element":"مجال العضوية","marks":1},{"element":"مجال غير العضوية","marks":1},{"element":"مجال الفيزيائية","marks":1},{"element":"مجال التحليلية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مجالات الفروع الأربعة صحيحة"},{"level":"2–3 درجات","description":"مجالان أو ثلاثة صحيحة"},{"level":"1 درجة","description":"مجال واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس مجالي العضوية وغير العضوية","الخلط بين الفيزيائية والتحليلية","ذكر أمثلة فقط دون ذكر المجال"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:32:48.111Z"}'::jsonb),
