('mcq', 2, 2, 'موجات الراديو ليست مادة لأنها ليس لها كتلة ولا تشغل حيزًا، أما الأوزون والهواء والأكسجين فمواد لها كتلة وتشغل حيزًا.', '["غاز الأوزون مادة؛ له كتلة ويشغل حيزًا.","الهواء مادة؛ فهو يشغل حيزًا وله كتلة.","","غاز الأكسجين مادة؛ له كتلة ويشغل حيزًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:32:48.111Z"}'::jsonb),
('mcq', 3, 1, 'تمدد البالون يدل على أن الهواء يشغل حيزًا، وازدياد ثقله يدل على أن له كتلة؛ فالهواء مادة لأن له كتلة ويشغل حيزًا.', '["عدم رؤية الهواء لا يعني أنه ليس مادة؛ والمعيار الكتلة والحيز.","","الهواء لا يُرى، ولا تُعدّ الرؤية معيارًا للمادة.","ازدياد ثقل البالون دليل على أن للهواء كتلة، وإن كانت صغيرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-18T03:32:48.111Z"}'::jsonb),
('mcq', 4, 3, 'المادة كل ما له كتلة ويشغل حيزًا، والحرارة ليس لها كتلة ولا تشغل حيزًا؛ فهي ليست مادة.', '["الهواء لا يُرى أيضًا وهو مادة؛ فعدم الرؤية ليس المعيار.","انتقال الشيء ليس معيارًا؛ فالمواد تنتقل أيضًا.","نحس بالحرارة، والمعيار هو الكتلة والحيز.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:32:48.112Z"}'::jsonb),
('mcq', 5, 2, 'العينة ع غاز كتلته 0.0012 g ويشغل حيزًا قدره 1.0 mL؛ فلها كتلة وتشغل حيزًا، وإن كانت لا ترى، فهي مادة. أما س وص ول فكتلة كل منها صفر ولا تشغل حيزًا.', '["كتلة العينة صفر ولا تشغل حيزًا، فهي ضوء وليست مادة.","كتلة العينة صفر ولا تشغل حيزًا، فهي حرارة وليست مادة.","","كتلة العينة صفر ولا تشغل حيزًا، فهي موجات راديو وليست مادة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:32:48.112Z"}'::jsonb),
('mcq', 6, 1, 'المادة هي كل ما له كتلة ويشغل حيزًا، والهواء له كتلة ويشغل حيزًا؛ فالقول غير صحيح، والهواء مادة وإن لم يُرَ.', '["الرؤية ليست معيار المادة؛ فالهواء له كتلة ويشغل حيزًا.","","للهواء كتلة؛ فالبالون المنفوخ أثقل منه فارغًا.","الإحساس بالهواء ليس شرطًا أيضًا؛ المعيار الكتلة والحيز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-18T03:32:48.112Z"}'::jsonb),
('mcq', 7, 3, 'الهواء والحديد وغاز الأوزون لكل منها كتلة وتشغل حيزًا، فهي كلها مواد؛ أما الضوء والحرارة والمجال المغناطيسي فليست مادة.', '["الضوء ليس مادة لأنه ليس له كتلة ولا يشغل حيزًا.","الحرارة ليست مادة لأنها ليس لها كتلة ولا تشغل حيزًا.","المجال المغناطيسي ليس مادة؛ فليس له كتلة ولا يشغل حيزًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-18T03:32:48.112Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المادة هي كل ما له كتلة ويشغل حيزًا. ولإثبات أن الهواء مادة ننفخ بالونًا؛ فيتمدد البالون ليسمح للهواء بالدخول فيه، وهذا يدل على أن الهواء يشغل حيزًا، ويصبح البالون أثقل مما كان فارغًا وهذا يدل على أن للهواء كتلة؛ فالهواء مادة.', '["المادة: كل ما له كتلة ويشغل حيزًا","تمدد البالون دليل على أن الهواء يشغل حيزًا","ازدياد ثقل البالون دليل على أن للهواء كتلة","الاستنتاج: الهواء مادة"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف (الكتلة والحيز)","marks":2},{"element":"الدليل على أن الهواء يشغل حيزًا","marks":1},{"element":"الدليل على أن للهواء كتلة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف كامل ودليلان صحيحان"},{"level":"2–3 درجات","description":"تعريف صحيح مع دليل واحد أو دليلان ناقصان"},{"level":"1 درجة","description":"تعريف جزئي أو دليل واحد دون تعريف"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الهواء مادة لأنه نحس به","اشتراط الرؤية في تعريف المادة","ذكر الكتلة وإغفال الحيز في التعريف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:32:48.112Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الهواء: مادة لأنه له كتلة ويشغل حيزًا. الضوء: ليس مادة لأنه ليس له كتلة ولا يشغل حيزًا. الحديد: مادة لأنه له كتلة ويشغل حيزًا. الحرارة: ليست مادة لأنها ليس لها كتلة ولا تشغل حيزًا. موجات الراديو: ليست مادة لأنه ليس لها كتلة ولا تشغل حيزًا. الأفكار: ليست مادة لأنها ليس لها كتلة ولا تشغل حيزًا.', '["الهواء مادة","الضوء ليس مادة","الحديد مادة","الحرارة ليست مادة","موجات الراديو ليست مادة","الأفكار ليست مادة","التبرير بالكتلة والحيز"]'::jsonb, '[]'::jsonb, '[{"element":"الهواء مع التبرير","marks":1},{"element":"الضوء مع التبرير","marks":1},{"element":"الحديد مع التبرير","marks":1},{"element":"الحرارة مع التبرير","marks":1},{"element":"موجات الراديو مع التبرير","marks":1},{"element":"الأفكار مع التبرير","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"تصنيف الستة بتبريرها بالكتلة والحيز"},{"level":"4–5 درجات","description":"تصنيف صحيح لأربعة أو خمسة مع التبرير"},{"level":"2–3 درجات","description":"تصنيف صحيح لاثنين أو ثلاثة أو تصنيف دون تبرير"},{"level":"1 درجة","description":"تصنيف صحيح لواحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الضوء مادة لأنه يُرى","عدّ الهواء ليس مادة لأنه لا يُرى","عدّ الحرارة مادة لأنها تنتقل بين الأجسام"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:32:48.112Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الهواء مادة لأنه يشغل حيزًا وله كتلة؛ فالبالون المنفوخ يتمدد ويصبح أثقل من ذي قبل. أما الضوء فليس مادة لأنه ليس له كتلة ولا يشغل حيزًا. والقول «ما لا نراه ليس مادة» غير صحيح؛ فالهواء لا نراه وهو مادة، والضوء قد نراه وهو ليس مادة. فالمعيار هو الكتلة وشغل الحيز لا إمكان الرؤية.', '["الهواء مادة لأن له كتلة ويشغل حيزًا","الضوء ليس مادة لأنه ليس له كتلة ولا يشغل حيزًا","الهواء لا يُرى وهو مادة","الضوء يُرى وهو ليس مادة","المعيار هو الكتلة والحيز لا الرؤية"]'::jsonb, '[]'::jsonb, '[{"element":"الهواء مادة مع التعليل","marks":2},{"element":"الضوء ليس مادة مع التعليل","marks":1},{"element":"نقض القول بمثال الهواء","marks":1},{"element":"بيان أن المعيار الكتلة والحيز وأن الضوء يُرى وليس مادة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة صحيحة وتقويم مبرر للقول"},{"level":"3–4 درجات","description":"مقارنة صحيحة مع نقص في التقويم"},{"level":"1–2 درجة","description":"تصنيف صحيح دون تعليل أو تقويم"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الموافقة على القول لأن الهواء لا يُرى","عدّ الضوء مادة لأنه يُرى","إغفال ذكر الكتلة والحيز معيارًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-18T03:32:48.112Z"}'::jsonb)
