('mcq', 5, 0, 'الذرات صغيرة جدًّا لا تُرى بالعين المجردة، فيستعمل الكيميائيون نماذج لتمثيلها وتفسير سلوكها.', '["","الذرات صغيرة جدًّا لا كبيرة.","النموذج وسيلة لتفسير السلوك لا بديل عن تفسيره.","الذرات تحدث لها تغيرات تنتج عنها ملاحظات تحتاج إلى تفسير."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-10-18T03:32:48.113Z"}'::jsonb),
('mcq', 6, 1, 'النموذج تفسير مرئي أو لفظي أو رياضي للبيانات، والمعادلة والرسم والوصف اللفظي من هذه الصور، أما قراءة الكتلة المسجلة فبيانات لا تفسير؛ فهي ما لا يُعدّ نموذجًا.', '["المعادلة الرياضية تفسير رياضي للبيانات، فهي نموذج.","","الرسم تفسير مرئي، فهو نموذج.","الوصف اللفظي تفسير لفظي للبيانات، فهو نموذج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:32:48.113Z"}'::jsonb),
('mcq', 7, 3, 'الشرح بالكلمات وحدها تفسير لفظي للبيانات، فهو نموذج لفظي.', '["النموذج الرياضي يستعمل معادلات أو علاقات رياضية، وهي غير موجودة هنا.","النموذج المرئي يستعمل رسمًا أو صورة، والشرح هنا بالكلمات فقط.","النموذج الحاسوبي يُنشأ على الحاسوب، ولم يُستعمل هنا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-18T03:32:48.114Z"}'::jsonb),
('essay', 1, null::int, null, null, 'النموذج تفسير مرئي أو لفظي أو رياضي للبيانات التجريبية. من النماذج التي يستعملها العلماء: مجسم توسعة الحرم المكي، وفائدته توضيح تصميم المبنى المعقد قبل إنشائه؛ والنموذج الحاسوبي للطائرة، وفائدته اختبار تصميم جديد قبل إنتاجها؛ ونماذج الذرات التي يستعملها الكيميائيون، وفائدتها تمثيل المادة والذرات التي يصعب مشاهدتها.', '["النموذج تفسير مرئي أو لفظي أو رياضي للبيانات التجريبية","نموذج مادي (مجسم) مع فائدته","نموذج حاسوبي مع فائدته","نموذج للذرات مع فائدته"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف النموذج","marks":1},{"element":"نموذج أول مع فائدته","marks":1},{"element":"نموذج ثانٍ مع فائدته","marks":1},{"element":"نموذج ثالث مع فائدته","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح وثلاثة نماذج بفوائدها"},{"level":"2–3 درجات","description":"تعريف صحيح مع نموذجين، أو ثلاثة نماذج دون فوائد كافية"},{"level":"1 درجة","description":"تعريف أو نموذج واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ أجهزة القياس نماذج","ذكر نماذج دون بيان الفائدة","تعريف النموذج بأنه نسخة طبق الأصل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:32:48.114Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المادة تتركب من ذرات صغيرة جدًّا لا تُرى بالعين المجردة ولا بالمجاهر الضوئية، فلا يمكن مشاهدة ما يحدث لها مباشرة. والنماذج تمثّل الأشياء التي يصعب مشاهدتها وتوضح الأفكار المعقدة، فيستعملها الكيميائيون لتمثيل الذرات وتفسير سلوكها وما ينتج عنه من تغيرات نلاحظها.', '["الذرات لا تُرى بالعين المجردة","النماذج تمثّل ما يصعب مشاهدته","النماذج تفسر سلوك الذرات والتغيرات الملحوظة"]'::jsonb, '[]'::jsonb, '[{"element":"الذرات لا تُرى فلا تشاهَد مباشرة","marks":1},{"element":"النماذج تمثّل ما يصعب مشاهدته","marks":1},{"element":"النماذج تفسر سلوك الذرات والملاحظات","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"استنتاج كامل بالعناصر الثلاثة"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن النماذج تغني عن دراسة الذرات","القول إن الذرات يمكن رؤيتها مباشرة","ذكر أن النماذج للزينة فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-18T03:32:48.114Z"}'::jsonb),
('essay', 3, null::int, null, null, 'استعمال النموذج الحاسوبي للطائرة قرار مناسب؛ لأنه يتيح اختبار التصميم الجديد قبل إنتاج الطائرة فعليًّا، ويوضح فكرة معقدة (تركيب الطائرة) يصعب تقويمها دون تمثيل. ووجه الشبه مع الكيميائيين أن النماذج تمثل ما يصعب مشاهدته أو اختباره مباشرة؛ فالكيميائيون يمثلون الذرات التي لا تُرى بنماذج لتفسير سلوكها، كما تُمثَّل الطائرة قبل صنعها.', '["الحكم بأن استعمال النموذج الحاسوبي مناسب","اختبار التصميم قبل الإنتاج","توضيح فكرة معقدة","وجه الشبه: تمثيل ما يصعب مشاهدته (الذرات)","النماذج تفسر السلوك أو تختبر التصميم"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم على استعمال النموذج","marks":1},{"element":"اختبار التصميم قبل الإنتاج","marks":1},{"element":"توضيح الفكرة المعقدة","marks":1},{"element":"وجه الشبه: تمثيل ما يصعب مشاهدته كالذرات","marks":1},{"element":"ربط النماذج بتفسير السلوك أو اختبار الفكرة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تقويم مبرر ووجه شبه صحيح مكتمل"},{"level":"3–4 درجات","description":"تقويم مبرر مع نقص في وجه الشبه"},{"level":"1–2 درجة","description":"حكم دون تبرير كافٍ"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن النموذج الحاسوبي يغني عن إنتاج الطائرة نهائيًّا","ذكر وجه شبه لا علاقة له بتمثيل ما يصعب مشاهدته","إغفال الربط بالذرات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:32:48.114Z"}'::jsonb)
