('mcq', 1, 2, 'الطريقة العلمية طريقة منظمة تُستعمل في الدراسات العلمية، كيميائية كانت أم حيوية أم فيزيائية، لحل المشكلات؛ فالإجابة الصحيحة هي أنها طريقة منظمة تُستعمل في الدراسات العلمية لحل المشكلات.', '["التخمين غير المختبر ليس طريقة منظمة؛ فالطريقة العلمية تقوم على الملاحظة والاختبار.","الطريقة العلمية أسلوب منظم لحل المشكلات وليست قائمة أسئلة ثابتة.","","الجهاز أداة قياس، أما الطريقة العلمية فأسلوب منظم وليست أداة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:32:48.114Z"}'::jsonb),
('mcq', 2, 0, 'تُستعمل الطريقة العلمية في الدراسات العلمية كلها سواء أكانت كيميائية أم حيوية أم فيزيائية أم غير ذلك؛ فهي غير محصورة في فرع واحد.', '["","الطريقة العلمية لا تقتصر على الكيمياء ولا على المختبر؛ إذ تُستعمل في كل الدراسات العلمية.","تُستعمل في الكيمياء أيضًا، فلا تُستثنى منها.","لا تقتصر على القياسات الرقمية؛ فالملاحظات النوعية جزء منها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:32:48.115Z"}'::jsonb),
('mcq', 3, 3, 'تُستعمل الطريقة العلمية في الدراسات الكيميائية والحيوية والفيزيائية؛ لذلك يتبع كل منهم الطريقة العلمية، وهي أسلوب منظم لحل المشكلات.', '["الملاحظات النوعية جزء أساسي من الطريقة العلمية إلى جانب البيانات الكمية.","لا يقصد بخطوات الطريقة العلمية أن تُنفَّذ بالترتيب نفسه دائمًا.","تختلف الأجهزة باختلاف المجال؛ والمشترك هو الأسلوب المنظم لا الأجهزة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:32:48.115Z"}'::jsonb),
('mcq', 4, 1, 'يتبع العلماء الطريقة العلمية لحل المشكلات وللتحقق من عمل العلماء الآخرين، وهذا ما تنص عليه الإجابة المختارة.', '["لا يمكن إثبات فرضية ما؛ فالبيانات المؤيدة تشير فقط إلى أنها قد تكون صحيحة.","","الطريقة العلمية تعتمد على التجارب ولا تُجنّب إجراءها.","الهدف حل المشكلات والتحقق، وليس جعل النتائج متشابهة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-18T03:32:48.115Z"}'::jsonb),
('mcq', 5, 3, 'الطالبة بدأت بملاحظة، ثم اقترحت تفسيرًا قابلًا للاختبار، ثم اختبرته بتجربة؛ وهذا أسلوب منظم لحل المشكلة، فهو استعمال للطريقة العلمية.', '["رأي الأغلبية لا يغني عن الاختبار؛ فالطريقة العلمية تعتمد على البيانات.","الشعور بصحة الفكرة ليس اختبارًا لها.","الطريقة العلمية تتطلب التحقق من النتائج لا نقلها دون فحص.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:32:48.115Z"}'::jsonb),
('mcq', 6, 0, 'الطريقة العلمية أسلوب منظم يصفه العلماء ليتمكن غيرهم من تأكيد النتائج، وهذا ما يميزها عن المحاولة العشوائية؛ فهي منظمة ويمكن تكرارها للتحقق من النتائج.', '["","لا يمكن إثبات فرضية ما، وقد تنتهي الطريقة برفض الفرضية أو تعديلها.","التحقق من عمل العلماء الآخرين جزء من الطريقة العلمية، فلا تعتمد على رأي واحد دون مراجعة.","تبدأ الطريقة العلمية بملاحظات وبيانات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:32:48.115Z"}'::jsonb),
('mcq', 7, 1, 'الطريقة النظامية هي أسلوب منظم لحل المشكلات؛ فهي المصطلح المطلوب.', '["الفرضية تفسير مؤقت قابل للاختبار وليست أسلوبًا لحل المشكلات.","","القانون العلمي يصف علاقة في الطبيعة تدعمها عدة تجارب.","المتغير المستقل هو ما يخطط الباحث لتغييره في التجربة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:32:48.115Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الطريقة العلمية طريقة منظمة تُستعمل في الدراسات العلمية، سواء أكانت كيميائية أم حيوية أم فيزيائية. ويتبعها العلماء لحل المشكلات، وللتحقق من عمل العلماء الآخرين.', '["طريقة منظمة","تُستعمل في الدراسات العلمية (كيميائية أو حيوية أو فيزيائية)","الغرض الأول: حل المشكلات","الغرض الثاني: التحقق من عمل العلماء الآخرين"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الطريقة العلمية بأنها طريقة منظمة تُستعمل في الدراسات العلمية","marks":2},{"element":"ذكر الغرض الأول: حل المشكلات","marks":1},{"element":"ذكر الغرض الثاني: التحقق من عمل العلماء الآخرين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف كامل مع ذكر الغرضين"},{"level":"2–3 درجات","description":"تعريف صحيح مع غرض واحد، أو غرضان مع تعريف ناقص"},{"level":"1 درجة","description":"ذكر جزء من التعريف أو غرض واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وصفها بأنها مجموعة تجارب فقط دون ذكر أنها منظمة","الاكتفاء بغرض واحد","القول إن غرضها إثبات الفرضيات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-18T03:32:48.115Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الطالب الأول استعمل الطريقة العلمية؛ لأنه اتبع أسلوبًا منظمًا لحل المشكلة يبدأ بالملاحظة ثم تفسير قابل للاختبار ثم تجربة، أما الثاني فخمّن السبب وحكم بصحته دون اختبار. وأسلوب الأول أوثق؛ لأن العلماء الآخرين يستطيعون تكرار خطواته نفسها للتحقق من نتائجه، بينما لا يمكن التحقق من تخمين لم يُختبر.', '["الأول استعمل الطريقة العلمية","أسلوبه منظم: ملاحظة، تفسير قابل للاختبار، تجربة","الثاني خمّن دون اختبار","غيره يستطيع تكرار خطواته والتحقق من النتائج"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد الطالب الأول","marks":1},{"element":"تعليل بالأسلوب المنظم (ملاحظة، تفسير قابل للاختبار، تجربة)","marks":2},{"element":"بيان أن الثاني لم يختبر تخمينه","marks":1},{"element":"بيان إمكان تكرار الآخرين لخطواته للتحقق","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تحديد صحيح مع تعليل كامل وبيان إمكان التحقق"},{"level":"3–4 درجات","description":"تحديد صحيح مع تعليل جزئي أو دون بيان التحقق"},{"level":"1–2 درجة","description":"تحديد صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تحديد الطالب الثاني لأن تخمينه أسرع","الاكتفاء بالقول إن الأول أدق دون ذكر التنظيم","إغفال أن الآخرين يحتاجون إلى تكرار الخطوات للتحقق"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:32:48.115Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الطريقة العلمية أسلوب منظم؛ أي أن العالم يسير في حل المشكلة وفق خطوات مرتبة منطقيًا (ملاحظات وفرضية وتجارب واستنتاج) بدل المحاولات العشوائية. وعندما تكون الطريقة منظمة ومعروفة يستطيع عالم آخر أن يكرر العمل بالأسلوب نفسه ليتحقق من النتائج، فإذا حصل على النتائج نفسها ازدادت الثقة بها.', '["أسلوب منظم بخطوات مرتبة بدل العشوائية","من خطواته الملاحظات والفرضية والتجارب والاستنتاج","يستطيع عالم آخر تكرار العمل بالأسلوب نفسه","تأكيد النتائج يزيد الثقة بها"]'::jsonb, '[]'::jsonb, '[{"element":"شرح معنى «منظم» بأنه خطوات مرتبة غير عشوائية","marks":2},{"element":"ذكر بعض الخطوات (الملاحظات، الفرضية، التجارب، الاستنتاج)","marks":1},{"element":"بيان أن تكرار العالم الآخر للأسلوب يمكّنه من التحقق من النتائج ويزيد الثقة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"شرح كامل لمعنى التنظيم مع ربطه بالتحقق"},{"level":"2–3 درجات","description":"شرح صحيح لأحد الجانبين فقط"},{"level":"1 درجة","description":"عبارات عامة دون ربط بالتحقق"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين التنظيم وتنفيذ الخطوات بترتيب جامد","عدم الربط بين وصف الطريقة وإمكان التحقق","القول إن التحقق يعني أن يوافق العالم الآخر رأي الأول"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.116Z"}'::jsonb)
