from (values
('mcq', 1, 1, 'درجة الغليان 78 °C قيمة رقمية ناتجة عن قياس، والمعلومات الرقمية تسمى بيانات كمية؛ فهي كمية لأنها معلومة رقمية ناتجة عن قياس.', '["كون الخاصية فيزيائية لا يجعلها نوعية؛ فالبيانات النوعية وصف بالحواس، وهنا قيمة رقمية.","","الحواس لا تقدّر درجة الغليان رقميًا؛ والقيمة الرقمية بيانات كمية.","البيانة الواحدة تُصنَّف إما نوعية (وصف) وإما كمية (رقم)، وهذه رقمية فهي كمية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:32:48.116Z"}'::jsonb),
('mcq', 2, 3, 'وصف اللون واللمعان يعتمد على الحواس دون قيمة رقمية؛ لذا فعبارة بلورات السكر بيضاء ولامعة بيانات نوعية.', '["الكتلة 6.6 g قيمة رقمية، فهي بيانات كمية.","الحجم 25 mL قيمة رقمية، فهو بيانات كمية.","درجة الحرارة 40 °C قيمة رقمية، فهي بيانات كمية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-18T03:32:48.116Z"}'::jsonb),
('mcq', 3, 0, 'البيانات النوعية ملاحظات توصف باستعمال الحواس كاللون والرائحة، أما الكمية فمعلومات رقمية كالكتلة والحجم؛ وهذا ما تقرره العبارة الأولى.', '["","هذا عكس التعريف الصحيح؛ فالرقمية كمية والموصوفة بالحواس نوعية.","الحواس مصدر النوعية والقياس مصدر الكمية، وليس العكس.","لا علاقة لنوع البيانات بحالة المادة؛ فكلا النوعين يُجمع عن أي مادة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:32:48.117Z"}'::jsonb),
('mcq', 4, 2, 'الملاحظات الكمية هي ما يحتوي قيمة رقمية: حجم الغاز 45 mL، وارتفاع الحرارة من 22 °C إلى 31 °C، وكتلة الراسب 1.8 g، وزمن التفاعل 90 s؛ فعددها أربع، أما اللون والرائحة والملمس فنوعية.', '["عددت بعض القياسات فقط؛ فالقياسات الرقمية في الجدول أربعة.","هذا عدد الملاحظات النوعية (اللون والرائحة والملمس)، لا الكمية.","","عددت جميع الملاحظات ومنها النوعية التي لا تحتوي أرقامًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-18T03:32:48.117Z"}'::jsonb),
('mcq', 5, 0, 'الرائحة النفاذة وصف بالحواس فهي نوعية، وكتلة الغاز 0.8 g قيمة رقمية فهي كمية؛ فالزوج الأول يطابق الترتيب المطلوب.', '["","الزوج صحيح التصنيف لكن ترتيبه معكوس: الكمية أولًا ثم النوعية.","كلتا البيانتين نوعية، ولا توجد بيانة كمية.","كلتا البيانتين كمية، ولا توجد بيانة نوعية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.117Z"}'::jsonb),
('mcq', 6, 3, 'العبارة «الماء ساخن» وصف يعتمد على الإحساس ولا تحتوي قيمة رقمية، فهي بيانات نوعية؛ وقول الطالب غير صحيح لهذا السبب.', '["موضوع القياس لا يحدد نوع البيانات؛ المعيار وجود قيمة رقمية، وهي غائبة هنا.","العبارة لا تتضمن رقمًا، والإحساس وحده لا يعطي قيمة قياس.","جُمعت عن الماء الساخن هنا بيانات (وصف بالحواس)، فهي نوعية؛ فليس صحيحًا أنه لا تُجمع عنه أي بيانات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:32:48.118Z"}'::jsonb),
('mcq', 7, 2, 'المخبار المدرج يعطي حجمًا بقيمة رقمية، والمعلومات الرقمية بيانات كمية؛ أما الشم والنظر واللمس فتعطي أوصافًا نوعية.', '["الشم يعطي وصفًا نوعيًا للرائحة لا قيمة رقمية.","النظر يعطي وصفًا نوعيًا للون.","","اللمس يعطي وصفًا نوعيًا للملمس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-18T03:32:48.118Z"}'::jsonb),
('essay', 1, null::int, null, null, 'البيانات النوعية ملاحظات تصف الأشياء باستعمال الحواس الخمس، وتُحصل عليها بالمشاهدة والشم واللمس والتذوق، ومثالها: لون المحلول أحمر أو رائحته نفاذة. أما البيانات الكمية فمعلومات رقمية تُحصل عليها بالقياس، ومثالها: درجة الحرارة 25 °C أو الحجم 40 mL. فالنوعية وصف بلا أرقام، والكمية أرقام ناتجة عن قياس.', '["النوعية ملاحظات توصف بالحواس","الكمية معلومات رقمية","النوعية تُجمع بالحواس والكمية بالقياس","مثال نوعي صحيح (لون أو رائحة أو شكل أو ملمس)","مثال كمي صحيح (درجة حرارة أو حجم أو كتلة…)"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف البيانات النوعية وطريقة الحصول عليها","marks":1},{"element":"تعريف البيانات الكمية وطريقة الحصول عليها","marks":1},{"element":"مثال نوعي صحيح","marks":1},{"element":"مثال كمي صحيح","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة كاملة من حيث التعريف وطريقة الحصول، مع مثالين صحيحين"},{"level":"2–3 درجات","description":"مقارنة صحيحة لأحد النوعين مع المثالين، أو مقارنة دون أمثلة"},{"level":"1 درجة","description":"ذكر تعريف نوع واحد أو مثال واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ العبارات الوصفية التي تتضمن مقدارًا دون رقم بيانات كمية","القول إن النوعية غير علمية","إعطاء مثال لا يطابق نوع البيانات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:32:48.118Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) كمية؛ لأنها قيمة رقمية ناتجة عن قياس الكتلة. (ب) نوعية؛ لأنها وصف للون واللمعان بالحواس دون أرقام. (ج) نوعية؛ لأنها وصف لألوان تُرى بالعين دون قيمة رقمية.', '["(أ) كمية","تعليل (أ): قيمة رقمية ناتجة عن قياس","(ب) نوعية","تعليل (ب): وصف اللون واللمعان بالحواس","(ج) نوعية","تعليل (ج): وصف الألوان بالحواس دون أرقام"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف (أ) مع التعليل","marks":2},{"element":"تصنيف (ب) مع التعليل","marks":2},{"element":"تصنيف (ج) مع التعليل","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"تصنيف الحالات الثلاث تصنيفًا صحيحًا مع تعليل"},{"level":"3–5 درجات","description":"تصنيف صحيح لحالتين أو لثلاث مع تعليل ناقص"},{"level":"1–2 درجة","description":"تصنيف صحيح لحالة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ كتلة الكأس بيانات نوعية لأنها خاصية للكأس","عدّ اللون بيانات كمية لأنه يمكن أن يقاس بجهاز","التصنيف دون ذكر الأساس (رقم أو حواس)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.118Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) البيانات النوعية: اللون برتقالي، والملمس ناعم؛ لأنهما وصف بالحواس دون أرقام. والبيانات الكمية: درجة الانصهار 1085 °C والكثافة 8.92 g/cm³؛ لأنهما قيمتان رقميتان ناتجتان عن قياس. (ب) مثال نوعي: العينة لامعة. ومثال كمي: كتلة العينة 12.5 g (أو حجمها أو طولها).', '["النوعية: اللون والملمس","الكمية: درجة الانصهار والكثافة","التعليل: وصف بالحواس مقابل قيمة رقمية","مثال نوعي إضافي صحيح","مثال كمي إضافي صحيح"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد البيانتين النوعيتين","marks":1},{"element":"تحديد البيانتين الكميتين","marks":1},{"element":"التعليل بأساس التصنيف","marks":1},{"element":"مثال نوعي إضافي صحيح","marks":1},{"element":"مثال كمي إضافي صحيح","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تصنيف صحيح مع تعليل ومثالين إضافيين صحيحين"},{"level":"3–4 درجات","description":"تصنيف صحيح مع نقص في التعليل أو في أحد المثالين"},{"level":"1–2 درجة","description":"تصنيف جزئي فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الكثافة بيانات نوعية لأنها خاصية للمادة","عدّ اللون بيانات كمية","إعطاء مثال كمي بلا قيمة رقمية مثل «ثقيل»"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.118Z"}'::jsonb)
