('mcq', 4, 'وصف عالم علاقة بين كميتين في الطبيعة، فوجدها صحيحة في جميع التجارب التي أُجريت دون أي استثناء. ماذا تسمى هذه العبارة؟', null, '["قانون علمي","فرضية علمية","نظرية علمية","بيانات نوعية"]'::jsonb, 'تطبيق', 'تصنيف عبارة', 'متوسط', 'الكتاب ص 26 — النظرية والقانون العلمي'),
('mcq', 5, 'لماذا توصف الفرضية بأنها مؤقتة؟', null, '["لأنها لا يمكن اختبارها بأي تجربة","لأنها تصبح قانونًا بعد وقت قصير","لأنها قد تُرفض أو تُعدَّل إذا لم تدعمها البيانات","لأنها تتعلق بظواهر لا تتكرر في الطبيعة"]'::jsonb, 'فهم', 'تفسير صفة', 'سهل', 'الكتاب ص 23 — الفرضية'),
('mcq', 6, 'أيّ العبارات الآتية تصف الفرق بين النظرية والقانون العلمي وصفًا صحيحًا؟', null, '["النظرية تصف علاقة بلا استثناءات، والقانون يفسّر الظاهرة ويبقى عرضة للتعديل","النظرية تفسّر ظاهرة طبيعية وتبقى عرضة للتعديل، والقانون يصف علاقة دون استثناءات","النظرية فرضية غير مختبرة، والقانون نظرية ثبتت صحتها نهائيًا","لا فرق بينهما إلا في عدد العلماء الذين يؤيدونهما"]'::jsonb, 'فهم', 'مقارنة النظرية بالقانون', 'صعب', 'الكتاب ص 26 — النظرية والقانون العلمي'),
('mcq', 7, 'أيّ العبارات الآتية تمثل فرضية؟', null, '["ينمو القمح أسرع إذا أُضيف إليه سماد نيتروجيني، ويمكن اختبار ذلك بتجربة","تعود الأجسام المقذوفة إلى الأرض دائمًا دون أي استثناء","تتكون المادة من ذرات، وهي فكرة دعمتها مشاهدات عدة عبر الزمن","درجة غليان الماء في العينة 100 °C"]'::jsonb, 'تطبيق', 'تمييز فرضية', 'صعب', 'الكتاب ص 23 — الفرضية وص 26'),
('essay', 1, 'اشرح الفرق بين الفرضية والنظرية والقانون العلمي، ببيان تعريف كل منها وخاصية تميزه.', null, null, 'فهم', 'شرح الفروق', 'متوسط', 'الكتاب ص 23 — الفرضية وص 26'),
('essay', 2, 'صنّف كل عبارة مما يأتي إلى فرضية أو نظرية أو قانون علمي مع التعليل: (أ) تتحلل مركبات CFCs في طبقات الجو العليا بفعل الأشعة فوق البنفسجية الآتية من الشمس، وهي عبارة قابلة للاختبار لم تُختبر بعد. (ب) تتجاذب جميع الأجسام بقوة، وقد دعمت ذلك تجارب عدة ولم يجد العلماء أي استثناء. (ج) تتكون المادة من ذرات، وهي فكرة تفسّر مشاهدات كثيرة وتبقى عرضة للبحث والتعديل.', null, null, 'تطبيق', 'تصنيف عبارات مع تعليل', 'متوسط', 'الكتاب ص 23 — الفرضية وص 26'),
('essay', 3, 'وصف العالم شارل علاقة مباشرة بين درجة الحرارة وحجم جميع الغازات عند ضغط ثابت. هل تسمى هذه العلاقة قانون شارل أم نظرية شارل؟ علّل إجابتك مبينًا الفرق بين القانون والنظرية.', null, null, 'فهم', 'تمييز بين القانون والنظرية', 'صعب', 'الكتاب ص 26 — النظرية والقانون العلمي')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
