from (values
('mcq', 1, 3, 'الفرضية عبارة عن تفسير مؤقت لظاهرة ما أو لحدث تمت ملاحظته، وهي قابلة للاختبار؛ وهذا ما تنص عليه الإجابة المختارة.', '["الحقائق الثابتة المدعومة بتجارب ليست فرضيات؛ والفرضية تفسير مؤقت.","هذا وصف القانون العلمي لا الفرضية.","الحكم القائم على المعلومات بعد التجربة هو الاستنتاج لا الفرضية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-18T03:32:48.119Z"}'::jsonb),
('mcq', 2, 1, 'القانون العلمي يصف علاقة في الطبيعة تدعمها عدة تجارب دون استثناءات، كقانون نيوتن للجاذبية؛ وهذا ما يميزه.', '["هذا وصف النظرية التي تفسر ظاهرة وتبقى عرضة للبحث والتعديل.","","الفرضية تفسير مؤقت لكنها قابلة للاختبار، والقانون مدعوم بتجارب عدة.","القانون يستند إلى تجارب عدة لا إلى ملاحظة واحدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:32:48.119Z"}'::jsonb),
('mcq', 3, 2, 'تُعدّ النظرية ناجحة إذا أمكن استعمالها للقيام بتوقعات صحيحة؛ فالنجاح يُقاس بصحة توقعاتها لا بانتهاء البحث فيها.', '["النظريات كلها تبقى عرضة للبحث وقد تُعدَّل، ولا يشترط لنجاحها توقف البحث.","تجربة واحدة لا تثبت النظرية نهائيًا.","","النظريات غالبًا ما تؤدي إلى استنتاجات جديدة، وهذا لا يخل بنجاحها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-18T03:32:48.119Z"}'::jsonb),
('mcq', 4, 0, 'العبارة تصف علاقة في الطبيعة تدعمها عدة تجارب دون استثناءات، وهذا تعريف القانون العلمي.', '["","الفرضية تفسير مؤقت قابل للاختبار ولم تدعمها بعد تجارب عدة دون استثناء.","النظرية تفسّر ظاهرة طبيعية، أما هذه العبارة فتصف علاقة.","البيانات النوعية وصف بالحواس لا علاقة بين كميتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:32:48.119Z"}'::jsonb),
('mcq', 5, 2, 'الفرضية تفسير مؤقت؛ فإن جاءت بيانات لا تدعمها وجب رفضها أو تعديلها، ولذلك وُصفت بأنها مؤقتة.', '["الفرضية قابلة للاختبار، وليست مستحيلة الاختبار.","الفرضية لا تتحول إلى قانون بمرور الوقت؛ فالقانون يصف علاقة تدعمها تجارب عدة.","","كون الظاهرة تتكرر أو لا تتكرر لا يحدد صفة التأقيت."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:32:48.119Z"}'::jsonb),
('mcq', 6, 1, 'النظرية تفسّر ظاهرة طبيعية بناءً على مشاهدات واستقصاءات وتبقى عرضة للبحث والتعديل، أما القانون فيصف علاقة تدعمها تجارب عدة دون استثناءات؛ وهذا ما في العبارة المختارة.', '["عكست العبارة التعريفين؛ فالذي يفسّر ويُعدَّل هو النظرية، والذي يصف علاقة هو القانون.","","النظرية ليست فرضية غير مختبرة، وليس القانون نظرية ثبتت نهائيًا؛ فكل منهما مفهوم مختلف.","الفرق في طبيعة كل منهما (تفسير أو وصف علاقة) لا في عدد المؤيدين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:32:48.119Z"}'::jsonb),
('mcq', 7, 0, 'العبارة الأولى تفسير أو توقع مؤقت قابل للاختبار بتجربة، وهذا ما يميز الفرضية.', '["","هذه علاقة تدعمها تجارب عدة دون استثناء، فهي قانون علمي.","هذه فكرة تفسر مشاهدات عدة وتدعمها تجارب مع الزمن، فهي أقرب إلى النظرية.","هذه بيانة كمية ناتجة عن قياس لا تفسير مؤقتًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:32:48.119Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الفرضية: تفسير مؤقت لظاهرة ما أو لحدث تمت ملاحظته، وتتميز بأنها قابلة للاختبار وقد تُرفض أو تُعدَّل. النظرية: تفسير لظاهرة طبيعية بناءً على مشاهدات واستقصاءات مع مرور الزمن، وتبقى عرضة للبحث وقد تُعدَّل، وتعد ناجحة إذا أمكن استعمالها للتوقع الصحيح. القانون العلمي: وصف لعلاقة في الطبيعة تدعمها عدة تجارب دون استثناءات، مثل قانون نيوتن للجاذبية.', '["الفرضية تفسير مؤقت قابل للاختبار","النظرية تفسر ظاهرة طبيعية وتبقى عرضة للتعديل وتنجح بالتوقع الصحيح","القانون يصف علاقة تدعمها تجارب عدة دون استثناءات"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الفرضية وخاصية تميزها","marks":2},{"element":"تعريف النظرية وخاصية تميزها","marks":2},{"element":"تعريف القانون العلمي وخاصية تميزه","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"تعريف كل منها مع خاصية مميزة صحيحة"},{"level":"3–5 درجات","description":"تعريف صحيح للثلاثة دون الخصائص، أو تعريفان مع خصائصهما"},{"level":"1–2 درجة","description":"تعريف واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين النظرية والقانون وعدّ القانون نظرية ثبتت","القول إن الفرضية تخمين غير قابل للاختبار","الاكتفاء بالأسماء دون تعريف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:32:48.119Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) فرضية؛ لأنها تفسير مؤقت قابل للاختبار لم يُختبر بعد. (ب) قانون علمي؛ لأنها تصف علاقة في الطبيعة تدعمها تجارب عدة دون استثناءات. (ج) نظرية؛ لأنها تفسّر ظاهرة بناءً على مشاهدات كثيرة وتبقى عرضة للبحث والتعديل.', '["(أ) فرضية: تفسير مؤقت قابل للاختبار","(ب) قانون: علاقة تدعمها تجارب عدة دون استثناءات","(ج) نظرية: تفسير مبني على مشاهدات وتبقى عرضة للتعديل"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف (أ) وتعليله","marks":2},{"element":"تصنيف (ب) وتعليله","marks":2},{"element":"تصنيف (ج) وتعليله","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"تصنيف الثلاث تصنيفًا صحيحًا مع تعليل"},{"level":"3–5 درجات","description":"تصنيف صحيح لاثنتين مع التعليل أو للثلاث دون تعليل"},{"level":"1–2 درجة","description":"تصنيف صحيح لواحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ العبارة (ج) قانونًا لأنها صحيحة غالبًا","عدّ العبارة (أ) نظرية لأنها تفسير","تصنيف دون تعليل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-18T03:32:48.120Z"}'::jsonb),
('essay', 3, null::int, null, null, 'تسمى قانون شارل؛ لأن القانون العلمي يصف علاقة في الطبيعة تدعمها تجارب عدة دون استثناءات، وهذه علاقة بين الحرارة والحجم يصفها العالم. أما النظرية فتفسّر ظاهرة طبيعية بناءً على مشاهدات واستقصاءات وتبقى عرضة للبحث والتعديل، وهذه العلاقة وصف لما يحدث لا تفسير لسببه.', '["قانون شارل","القانون يصف علاقة تدعمها تجارب عدة دون استثناءات","النظرية تفسّر ظاهرة وتبقى عرضة للتعديل","العلاقة المذكورة وصف لا تفسير"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد أنها قانون","marks":1},{"element":"تعليل بأن القانون يصف علاقة تدعمها تجارب","marks":1},{"element":"بيان أن النظرية تفسر ظاهرة وتبقى عرضة للتعديل","marks":1},{"element":"ربط العلاقة بأنها وصف لا تفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد صحيح مع تعليل كامل وتمييز عن النظرية"},{"level":"2–3 درجات","description":"تحديد صحيح مع تعليل ناقص"},{"level":"1 درجة","description":"تحديد صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسميتها نظرية لأن العلاقة تشمل جميع الغازات","القول إن القانون لا يحتاج إلى تجارب","الخلط بين وصف العلاقة وتفسير سببها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:32:48.120Z"}'::jsonb)
