('mcq', 6, 'أيّ مما يأتي لا يستطيع الباحث التحكم في كيفية تغيره؟', null, '["المتغير التابع","المتغير المستقل","العامل الثابت","الضابط"]'::jsonb, 'فهم', 'تمييز خاصية', 'متوسط', 'الكتاب ص 24 — التجارب: المتغيرات'),
('mcq', 7, 'بحثت طالبة أثر حجم جسيمات السكر (مكعبات ثم حبيبات ثم مسحوق) في سرعة ذوبانه، فأضافت كل نوع إلى كأس ماء مماثلة للأخرى في الحجم، وحركت المحلول 10 ثوانٍ، وسجلت زمن الذوبان. أيّ مما يأتي عامل ثابت في هذه التجربة؟', null, '["زمن ذوبان السكر","حجم جسيمات السكر","سرعة ذوبان السكر","زمن تحريك المحلول"]'::jsonb, 'تطبيق', 'تحديد العامل الثابت', 'صعب', 'الكتاب ص 24 و41 — التجارب: عوامل أخرى'),
