('essay', 2, 'وجد طالب في تجربة أن حجم بالون يزداد عند تسخينه. حدّد المتغير المستقل والمتغير التابع، واذكر عاملين ينبغي أن يبقيا ثابتين، وعلّل لماذا يُعدّ حجم البالون متغيرًا تابعًا.', null, null, 'تطبيق', 'تحديد المتغيرات في تجربة', 'متوسط', 'الكتاب ص 24 — التجارب: المتغيرات وص 26'),
('essay', 3, 'تبحث طالبة في تأثير حجم الجسيمات في سرعة ذوبان السكر، فتضيف مكعبات سكر، وحبيبات سكر، وسكرًا مطحونًا على الترتيب إلى ثلاثة أكواب ماء، وتحرك كل محلول 10 ثوانٍ، وتسجل الوقت الذي يستغرقه كل نوع للذوبان. حدّد المتغير المستقل والمتغير التابع، وبيّن كيف تميّز بينهما، ثم اذكر عاملًا يجب أن يبقى ثابتًا ولماذا.', null, null, 'تحليل', 'تحليل تجربة', 'صعب', 'الكتاب ص 24 و41 — المتغيرات والعوامل الثابتة')
