from (values
('mcq', 1, 2, 'تظهر التجربة قدرًا كبيرًا من البيانات يحللها العلماء ويقارنونها بالفرضية للتوصل إلى استنتاج؛ فالإجابة هي الاستنتاج.', '["القانون العلمي يحتاج إلى تجارب عدة دون استثناءات، ولا ينتج مباشرة من مقارنة البيانات بالفرضية.","النظرية تبنى على مشاهدات واستقصاءات مع الزمن لا على مقارنة واحدة.","","الفرضية تسبق التجربة، وليست ما يُتوصل إليه من مقارنة البيانات بها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-18T03:32:48.123Z"}'::jsonb),
('mcq', 2, 3, 'لا نستطيع إثبات فرضية ما؛ فعندما تؤيدها البيانات يشير ذلك فقط إلى أنها قد تكون صحيحة.', '["التأييد لا يعني الإثبات النهائي؛ فلا يمكن إثبات فرضية ما.","لا تتحول الفرضية إلى قانون بمجرد تأييد بيانات تجربة لها.","التجربة هي ما أنتج البيانات المؤيدة، فكانت ضرورية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:32:48.123Z"}'::jsonb),
('mcq', 3, 1, 'الملح ذاب في 1 min عند 40 °C وفي 3 min عند 20 °C، أي أسرع في الماء الساخن، وهذا يوافق توقع الفرضية فيدعمها، لكن البيانات لا تثبتها نهائيًا.', '["لا يمكن إثبات فرضية بنتائج تجربة واحدة؛ فالبيانات تدعمها فقط.","","النتائج توافق توقع الفرضية، فلا يوجد سبب لرفضها.","النتائج تتعلق بالمتغيرين المذكورين في الفرضية، فلها علاقة بها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:32:48.123Z"}'::jsonb),
('mcq', 4, 0, 'تُحلَّل النتائج وتقارَن بما توقعته الفرضية لاختبارها؛ فالدور الأساسي للنتائج هو اختبار الفرضية.', '["","البيانات لا تثبت الفرضية إثباتًا قاطعًا، بل تدعمها أو لا تدعمها.","القانون العلمي يحتاج إلى تجارب عدة، ولا يحل محل الفرضية بنتائج واحدة.","المتغير المستقل يحدد قبل التجربة، أما النتائج فتنتج بعد تنفيذها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.124Z"}'::jsonb),
('mcq', 5, 3, 'النتائج هي القياسات والملاحظات المسجلة بعد تنفيذ التجربة، والاستنتاج حكم قائم على المعلومات التي تم الحصول عليها؛ فالعبارة الأولى صحيحة.', '["عكس هذه العبارة صحيح؛ فالاستنتاج هو الحكم المبني على النتائج.","النتائج بيانات مسجلة، والاستنتاج حكم مبني عليها؛ فهما مختلفان.","النتائج تنتج من تنفيذ التجربة فلا تُكتب قبلها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-18T03:32:48.124Z"}'::jsonb),
('mcq', 6, 2, 'الزمن عند 40 °C (5 min) أكبر منه عند 20 °C (3 min)، وهذا يخالف توقع الفرضية؛ فالبيانات لا تدعمها، وعندئذ تُرفض الفرضية أو تُعدَّل.', '["النتيجة المخالفة ليست فشلًا؛ فهي معلومة تفيد في اختبار الفرضية.","وضوح النتائج لا يعني أنها وافقت الفرضية؛ والنتيجة هنا مخالفة لها.","","إهمال النتيجة غير علمي؛ فإذا لم تدعم البيانات الفرضية رُفضت أو عُدّلت."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:32:48.124Z"}'::jsonb),
('mcq', 7, 0, 'تسجيل النتائج بدقة يمكّن الآخرين من تكرار التجربة ومقارنة نتائجهم بنتائجك، وبذلك يتحقق من عمل العلماء.', '["","التحليل خطوة ضرورية لا يغني عنها التسجيل.","النتائج الدقيقة قد تخالف الفرضية؛ فدقتها لا تثبت الفرضية.","حذف النتائج المخالفة غير علمي؛ فالاستنتاج يُبنى على كل النتائج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:32:48.124Z"}'::jsonb),
('essay', 1, null::int, null, null, 'بعد تنفيذ التجربة تُسجَّل القياسات والملاحظات وهي النتائج، ثم تُحلَّل وتُقارَن بما توقعته الفرضية لاختبارها. فإذا اتفقت مع التوقع دعمت الفرضية وأشارت إلى أنها قد تكون صحيحة دون إثباتها نهائيًا. وإذا خالفت التوقع فالبيانات لا تدعم الفرضية، فتُرفض أو تُعدَّل. ثم يكتب الباحث استنتاجًا هو حكم مبني على النتائج.', '["النتائج قياسات وملاحظات تُحلَّل وتُقارَن بتوقع الفرضية","الاتفاق يدعم الفرضية دون إثباتها","المخالفة تعني رفض الفرضية أو تعديلها","الاستنتاج حكم مبني على النتائج"]'::jsonb, '[]'::jsonb, '[{"element":"بيان أن النتائج تُحلَّل وتُقارَن بتوقع الفرضية","marks":1},{"element":"اتفاق النتائج يدعم الفرضية ولا يثبتها","marks":2},{"element":"مخالفة النتائج تعني رفض الفرضية أو تعديلها","marks":1},{"element":"ذكر أن الاستنتاج حكم مبني على النتائج","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة تشمل الدور والاتفاق والمخالفة والاستنتاج"},{"level":"3–4 درجات","description":"إجابة صحيحة لعناصر دون الاستنتاج، أو دون التفريق بين الدعم والإثبات"},{"level":"1–2 درجة","description":"ذكر دور النتائج فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن اتفاق النتائج يثبت الفرضية","القول إن النتيجة المخالفة تعني فشل التجربة","الخلط بين النتائج والاستنتاج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:32:48.124Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) نعم، تدعمها؛ لأن زمن الذوبان يقل من 4 min إلى 2 min إلى 1 min كلما ارتفعت الحرارة من 20 °C إلى 60 °C، أي أن الذوبان يصبح أسرع، وهذا ما توقعته الفرضية. (ب) الاستنتاج: النتائج تدعم الفرضية، وارتفاع درجة الحرارة يزيد سرعة ذوبان الملح في الماء ضمن هذه الظروف. (ج) لأن تأييد البيانات في تجربة محددة يشير فقط إلى أن الفرضية قد تكون صحيحة، ولا يمكن إثبات فرضية ما، وقد تظهر بيانات مخالفة في تجارب أخرى.', '["النتائج تدعم الفرضية","التعليل: نقص الزمن من 4 إلى 2 إلى 1 min بارتفاع الحرارة","الاستنتاج: ارتفاع الحرارة يزيد سرعة الذوبان","لا يمكن إثبات الفرضية؛ التأييد يعني أنها قد تكون صحيحة"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم بأن النتائج تدعم الفرضية","marks":1},{"element":"التعليل بتناقص زمن الذوبان مع ارتفاع الحرارة","marks":1},{"element":"صياغة استنتاج مبني على النتائج","marks":1},{"element":"بيان أن البيانات لا تثبت الفرضية","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة للأجزاء الثلاثة"},{"level":"3–4 درجات","description":"إجابة صحيحة لجزأين أو لثلاثة مع نقص في التعليل"},{"level":"1–2 درجة","description":"حكم صحيح بالدعم دون تعليل أو استنتاج"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن النتائج لا تدعم الفرضية لأن الزمن قل","كتابة الاستنتاج «الفرضية صحيحة تمامًا»","عدّ الاستنتاج تكرارًا للنتائج دون حكم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:32:48.125Z"}'::jsonb),
('essay', 3, null::int, null, null, 'النتائج هي القياسات والملاحظات التي تسجَّل بعد تنفيذ التجربة، مثل أزمنة الذوبان في جدول؛ أما الاستنتاج فحكم مبني على هذه النتائج بعد تحليلها ومقارنتها بالفرضية. ولكي تكون النتائج موثوقة يُغيَّر المتغير المستقل وحده ويُقاس المتغير التابع، وتبقى العوامل الثابتة دون تغيير؛ لأن تغير عامل آخر قد يغيّر النتائج فلا يمكن نسب التغير إلى المتغير المستقل.', '["النتائج قياسات وملاحظات مسجلة","الاستنتاج حكم مبني على النتائج","يُغيَّر المتغير المستقل وحده","تبقى العوامل الثابتة دون تغيير","تغير عامل آخر يمنع نسب التغير إلى المستقل"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف النتائج","marks":1},{"element":"تعريف الاستنتاج وعلاقته بالنتائج","marks":1},{"element":"تغيير المتغير المستقل وحده وإبقاء العوامل الثابتة","marks":1},{"element":"تعليل أهمية الضبط لموثوقية النتائج","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة لكل العناصر"},{"level":"3–4 درجات","description":"إجابة صحيحة لأحد المحورين كاملًا والآخر ناقصًا"},{"level":"1–2 درجة","description":"ذكر تعريف واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين النتائج والاستنتاج","القول إن تغيير أكثر من متغير يسرّع الوصول إلى النتيجة","ذكر الضبط دون تعليل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-18T03:32:48.125Z"}'::jsonb)
