('mcq', 1, 'لماذا لا يستعمل العلماء مجموعة محددة من الخطوات بالترتيب نفسه في كل بحث؟', null, '["لأن الخطوات غير مهمة في الدراسات العلمية","لأن الطريقة العلمية تُستعمل في الكيمياء وحدها","لأن العلماء لا يحتاجون إلى تجارب في أبحاثهم","لأن كل عالم يحاول فهم عالمه بناءً على رؤية فردية وإبداع ذاتي"]'::jsonb, 'فهم', 'تفسير سبب', 'سهل', 'الكتاب ص 22 — الطريقة النظامية في البحث'),
('mcq', 2, 'يقصد بخطوات الطريقة العلمية أنها:', null, '["وصفة جامدة يجب على كل عالم اتباعها بالترتيب نفسه","خطوات يستعملها علماء الكيمياء دون غيرهم","نظرة عامة على الخطوات لا يلزم تنفيذها بالترتيب نفسه دائمًا","إجراءات لا تُطبَّق إلا على المشكلات التي تُحل بتجربة واحدة"]'::jsonb, 'فهم', 'توضيح المقصود', 'سهل', 'الكتاب ص 22 — الطريقة النظامية في البحث'),
('mcq', 3, 'لماذا يجب أن يصف العلماء طرائقهم عند عرض نتائج أبحاثهم؟', null, '["ليتمكن علماء آخرون من تأكيد النتائج بتكرار الخطوات نفسها","ليتشابه عمل جميع العلماء في كل بحث","لأن الوصف يغني عن إجراء التجربة","لأن النتائج لا تُقبل إلا من عالم واحد معروف"]'::jsonb, 'فهم', 'تفسير سبب الوصف', 'متوسط', 'الكتاب ص 22 — الطريقة النظامية في البحث'),
('mcq', 4, 'عرضت مجموعة بحثية نتائجها دون وصف طريقتها، ولم يستطع علماء آخرون الحصول على النتائج نفسها. ما الأثر المتوقع؟', null, '["تُعدّ النتائج صحيحة لأن المجموعة وحدها أجرتها","يوجد شك في صدق النتائج","تتحول النتائج إلى قانون علمي","لا أثر؛ فوصف الطريقة غير مهم"]'::jsonb, 'تطبيق', 'توقع أثر موقف', 'متوسط', 'الكتاب ص 22 — الطريقة النظامية في البحث'),
('mcq', 5, 'بدأ كيميائي دراسته بملاحظات، ثم عاد إلى جمع ملاحظات إضافية بعد وضع فرضيته؛ في حين بدأ زميله بفرضية مبنية على معرفته السابقة. هل يعني اختلاف ترتيب خطواتهما أن أحدهما لا يتبع الطريقة العلمية؟', null, '["نعم؛ لأن الطريقة العلمية لا تقبل اختلاف الترتيب","نعم؛ لأن العالم الأقل خبرة هو من يغيّر ترتيب الخطوات","لا؛ فالخطوات نظرة عامة لا يلزم تنفيذها بالترتيب نفسه، بشرط أن يصف كل منهما طريقته","لا؛ لأن الطريقة العلمية لا تتطلب وصف الخطوات أصلًا"]'::jsonb, 'تطبيق', 'تقويم موقف', 'صعب', 'الكتاب ص 22 — الطريقة النظامية في البحث'),
('mcq', 6, 'لماذا قد يكون من المفيد مع ذلك أن يستعمل العلماء خطوات موحدة لتنفيذ تجاربهم؟', null, '["لأن الخطوات الموحدة تجعل النتائج صحيحة دائمًا","لأن العالم الواحد لا يستطيع إجراء تجربة بمفرده","لأن الخطوات الموحدة تغني عن وصف الطرائق","لأن أعمال عدة علماء تُستخلص معًا للوصول إلى فهم جديد للموضوع"]'::jsonb, 'فهم', 'تفسير فائدة', 'صعب', 'الكتاب ص 22 — الطريقة النظامية في البحث'),
('mcq', 7, 'أيّ مما يأتي يُعدّ نتيجة مباشرة لعمل كل عالم برؤية فردية وإبداع ذاتي؟', null, '["حصول جميع العلماء على النتائج نفسها دائمًا","اختلاف الطرائق التي يتبعها العلماء من بحث إلى آخر","عدم الحاجة إلى وصف الطرائق","توقف العلماء عن مراجعة أعمال بعضهم"]'::jsonb, 'فهم', 'استنتاج أثر', 'متوسط', 'الكتاب ص 22 — الطريقة النظامية في البحث'),
('essay', 1, 'فسّر لماذا لا يستعمل العلماء مجموعة محددة من الخطوات بالترتيب نفسه في كل بحث، وماذا يجب عليهم أن يفعلوه عند عرض نتائجهم.', null, null, 'فهم', 'تفسير وتعليل', 'متوسط', 'الكتاب ص 22 — الطريقة النظامية في البحث'),
('essay', 2, 'أعلنت مجموعة بحثية (أ) نتيجة جديدة دون ذكر طريقتها، وحاولت مجموعة (ب) الحصول على النتيجة نفسها باتباع خطوات اجتهدت في تخمينها، فلم تنجح. (1) ما الشك الذي يثيره ذلك؟ (2) ما الذي كان ينبغي للمجموعة (أ) فعله؟ (3) لماذا لا يكفي أن تكون المجموعة (أ) قد اتبعت ترتيبًا مختلفًا من الخطوات ليصح الحكم عليها بأنها غير علمية؟', null, null, 'تطبيق', 'تحليل موقف بحثي', 'صعب', 'الكتاب ص 22 — الطريقة النظامية في البحث'),
