('mcq', 3, 0, 'عندما يصف العلماء طرائقهم يستطيع غيرهم تكرار الخطوات نفسها لتأكيد النتائج؛ لذلك يجب الوصف.', '["","اختلاف الطرائق مقبول؛ فالوصف لا يهدف إلى توحيد عمل جميع العلماء.","الوصف لا يغني عن التجربة، بل يمكّن غيرك من تكرارها.","النتائج تُقبل حين يستطيع علماء آخرون تأكيدها، لا بسبب شهرة عالم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:32:48.128Z"}'::jsonb),
('mcq', 4, 1, 'إذا لم يستطع العلماء الآخرون تأكيد النتائج باتباع الخطوات نفسها فإن هناك شكًا في صدق النتائج.', '["عدم القدرة على التأكيد يثير الشك، ولا يجعل النتائج صحيحة بمجرد أن مجموعة واحدة أجرتها.","","القانون يحتاج إلى تجارب عدة تدعمه دون استثناءات، وهنا لم تُؤكَّد النتائج.","وصف الطريقة مهم لأنه يتيح تأكيد النتائج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:32:48.128Z"}'::jsonb),
('mcq', 5, 2, 'اختلاف الترتيب مقبول لأن الخطوات نظرة عامة وليست ترتيبًا ملزمًا، لكن على كل منهما أن يصف طريقته ليتمكن غيره من تأكيد النتائج؛ فالجواب أنه لا يعني أن أحدهما لا يتبع الطريقة العلمية.', '["لا يقصد بخطوات الطريقة العلمية أن تُنفَّذ بالترتيب نفسه دائمًا.","تغيير الترتيب ليس دليلًا على قلة الخبرة، فهو نتيجة اختلاف الرؤى والإبداع الفردي.","","وصف الطريقة ضروري ليتمكن الآخرون من تأكيد النتائج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-18T03:32:48.128Z"}'::jsonb),
('mcq', 6, 3, 'غالبًا ما تُستخلص أعمال عدة علماء للوصول إلى فهم جديد للموضوع؛ لذلك قد يكون من المفيد استعمال خطوات موحدة في تنفيذ التجارب.', '["توحيد الخطوات لا يضمن صحة النتائج.","يستطيع العالم إجراء تجاربه بمفرده، والفائدة تتعلق بجمع أعمال عدة علماء.","وصف الطرائق ما زال لازمًا حتى مع الخطوات الموحدة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:32:48.129Z"}'::jsonb),
('mcq', 7, 1, 'عمل كل عالم برؤية فردية وإبداع ذاتي يؤدي إلى اختلاف الطرائق التي يتبعونها من بحث إلى آخر.', '["الاختلاف في الطرائق لا يضمن اتفاق النتائج.","","اختلاف الطرائق يجعل وصفها أكثر أهمية لا أقل.","التحقق من عمل الآخرين جزء من الطريقة العلمية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-18T03:32:48.129Z"}'::jsonb),
('essay', 1, null::int, null, null, 'لأن كل عالم يحاول فهم عالمه بناءً على رؤية فردية وإبداع ذاتي، ولا يقصد بخطوات الطريقة العلمية أن تُنفَّذ بالترتيب؛ فهي نظرة عامة. ولذلك يجب على العلماء أن يصفوا طرائقهم عند عرض نتائج أبحاثهم ليتمكن علماء آخرون من تأكيد النتائج باتباع الخطوات نفسها.', '["رؤية فردية وإبداع ذاتي لكل عالم","الخطوات نظرة عامة لا يلزم تنفيذها بالترتيب","وجوب وصف الطرائق","ليتمكن الآخرون من تأكيد النتائج"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر الرؤية الفردية والإبداع الذاتي","marks":1},{"element":"بيان أن الخطوات نظرة عامة لا تُنفَّذ بالترتيب","marks":1},{"element":"وجوب وصف الطرائق عند عرض النتائج","marks":1},{"element":"تعليل الوصف بتمكين الآخرين من التأكيد","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل مع وجوب الوصف وتعليله"},{"level":"2–3 درجات","description":"تفسير صحيح مع نقص في الوصف أو تعليله"},{"level":"1 درجة","description":"ذكر عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الخطوات غير ضرورية","القول إن الإبداع يغني عن وصف الطرائق","ذكر الوصف دون تعليله"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (58%)"}],"at":"2026-10-18T03:32:48.129Z"}'::jsonb),
('essay', 2, null::int, null, null, '(1) يثير ذلك شكًا في صدق النتائج؛ لأن علماء آخرين لم يستطيعوا تأكيدها باتباع الخطوات نفسها. (2) كان ينبغي للمجموعة (أ) أن تصف طريقتها بالتفصيل عند عرض نتائجها ليتمكن غيرها من تكرارها وتأكيد النتائج. (3) لأن خطوات الطريقة العلمية نظرة عامة لا يقصد تنفيذها بالترتيب نفسه في كل بحث، ويختلف العلماء بحسب رؤاهم وإبداعهم؛ والمهم أن تكون الطريقة منظمة وموصوفة.', '["شك في صدق النتائج","وصف الطريقة عند عرض النتائج","الخطوات نظرة عامة لا يلزم ترتيبها","اختلاف الترتيب لا يعني أن البحث غير علمي"]'::jsonb, '[]'::jsonb, '[{"element":"الشك في صدق النتائج لعدم تأكيدها","marks":1},{"element":"وصف الطريقة عند عرض النتائج","marks":2},{"element":"بيان أن اختلاف الترتيب لا يجعل البحث غير علمي مع تعليله","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"إجابة صحيحة للأجزاء الثلاثة مع تعليل"},{"level":"3–4 درجات","description":"إجابة صحيحة لجزأين أو نقص في التعليل"},{"level":"1–2 درجة","description":"إجابة صحيحة لجزء واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن عدم نجاح المجموعة (ب) يعني خطأ المجموعة (ب)","القول إن اختلاف الترتيب دليل على أن البحث غير علمي","عدم ذكر وصف الطريقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:32:48.129Z"}'::jsonb),
('essay', 3, null::int, null, null, 'قول الطالبة غير صحيح في جزأيه. فالخطوات نظرة عامة على الطريقة العلمية ولا يقصد بها أن تُنفَّذ بالترتيب نفسه؛ لأن كل عالم يعمل على فهم عالمه برؤية فردية وإبداع ذاتي. وكذلك يجب على العالم أن يصف طريقته عند عرض النتائج ليتمكن غيره من تأكيدها، وإلا كان هناك شك في صدق النتائج. والصحيح في كلامها أن الطريقة العلمية منظمة لحل المشكلات، وليست عشوائية.', '["الحكم بعدم صحة قولها","الخطوات نظرة عامة لا تُنفَّذ بالترتيب دائمًا","السبب: رؤية فردية وإبداع ذاتي","وجوب وصف الطريقة وإلا شك في الصدق","الصحيح: الطريقة العلمية منظمة"]'::jsonb, '[]'::jsonb, '[{"element":"تصحيح فكرة الترتيب الثابت","marks":1},{"element":"ذكر السبب: الرؤية الفردية والإبداع","marks":1},{"element":"تصحيح فكرة عدم الحاجة إلى وصف الطريقة","marks":1},{"element":"بيان الشك في الصدق عند غياب الوصف","marks":1},{"element":"ذكر ما يصح (الطريقة منظمة)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تقويم كامل يفصل الصحيح من الخطأ مع التفسير"},{"level":"3–4 درجات","description":"تصحيح الجزأين دون ذكر الصحيح أو دون تفسير كامل"},{"level":"1–2 درجة","description":"تصحيح جزء واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الموافقة على قول الطالبة كله","القول إن الطريقة العلمية عشوائية","عدم تفسير سبب الاختلاف في الترتيب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:32:48.129Z"}'::jsonb)
