('mcq', 1, 'ما دور الضابط في التجربة؟', null, '["تُقارَن به نتائج المجموعات الأخرى في التجربة","يغيّره الباحث عمدًا ليرى أثره في النتائج","يُستعمل لقياس المتغير التابع بالأرقام","يُهمل عند تحليل البيانات"]'::jsonb, 'تذكر', 'تذكر دور الضابط', 'سهل', 'الكتاب ص 24 — الضابط'),
('mcq', 2, 'في تجربة لاختبار أثر درجة الحرارة في سرعة ذوبان الملح، قارنت مجموعة نتائجها بنتيجة ملح في ماء عند درجة حرارة الغرفة (20 °C). ما هذا الماء؟', null, '["متغير تابع","ضابط للمقارنة","متغير مستقل","عامل ثابت"]'::jsonb, 'تطبيق', 'تحديد الضابط', 'سهل', 'الكتاب ص 24 — الضابط'),
('mcq', 3, 'أُضيف كاشف كيميائي إلى ثلاثة أنابيب: الأول فيه محلول حمضي فتحول لون الكاشف إلى الأحمر، والثاني فيه ماء فبقي الكاشف أصفر، والثالث فيه محلول قاعدي فتحول لونه إلى الأزرق. لماذا تُعدّ هذه الأنابيب ضوابط؟', null, '["لأن ألوانها تتغير دائمًا بتغير درجة الحرارة","لأنها تمثل المتغير المستقل في التجربة","لأن حموضة محاليلها معروفة، فيمكن مقارنة المحلول المجهول بألوانها","لأن الكاشف لا يُضاف إلى المحلول المجهول"]'::jsonb, 'فهم', 'تعليل كون الأنابيب ضوابط', 'متوسط', 'الكتاب ص 24 — الضابط والشكل 1-12'),
('mcq', 4, 'يتحول لون كاشف إلى الأحمر في المحلول الحمضي المعروف، ويبقى أصفر في الماء، ويصبح أزرق في المحلول القاعدي المعروف. أُضيف هذا الكاشف إلى محلول مجهول الحموضة فتحول لونه إلى الأحمر. ما الحكم الصحيح بمقارنته بالضوابط؟', null, '["قاعدي؛ لأن الكاشف يتحول إلى الأحمر في المحاليل القاعدية","متعادل؛ لأن الكاشف يتحول إلى الأحمر في الماء","لا يمكن تحديد حموضته؛ لأن لونه لا يطابق أي ضابط","حمضي؛ لأن لونه يطابق لون الكاشف في المحلول الحمضي المعروف"]'::jsonb, 'تطبيق', 'استعمال الضوابط في التحديد', 'متوسط', 'الكتاب ص 24 — الضابط والشكل 1-12'),
('mcq', 5, 'درس طلاب أثر شرب الصودا في معدل ضربات القلب، وسُجلت النتائج في الجدول الآتي. أيّ الطلاب استُخدم ضابطًا في التجربة؟', '{"headers":["الطالب","عدد علب الصودا","عدد ضربات القلب (ضربة/دقيقة)"],"rows":[["1","صفر","73"],["2","1","84"],["3","2","89"],["4","3","96"]]}'::jsonb, '["الطالب 1","الطالب 2","الطالب 3","الطالب 4"]'::jsonb, 'تطبيق', 'تحديد الضابط من جدول', 'صعب', 'الكتاب ص 24 — الضابط وص 41'),
('mcq', 6, 'في تجربة لدراسة أثر نوعين من السماد في نمو نبات القمح، زُرعت ثلاث مجموعات: الأولى بالسماد (أ)، والثانية بالسماد (ب)، والثالثة بلا أي سماد، مع تساوي بقية الظروف. أيّ المجموعات تمثل الضابط؟', null, '["المجموعة الأولى بالسماد (أ)","المجموعة الثانية بالسماد (ب)","المجموعتان الأولى والثانية معًا","المجموعة الثالثة بلا سماد"]'::jsonb, 'تطبيق', 'تحديد الضابط في موقف', 'متوسط', 'الكتاب ص 24 — الضابط'),
('mcq', 7, 'أيّ العبارات الآتية تميّز الضابط من العامل الثابت؟', null, '["الضابط عامل يغيّره الباحث، والعامل الثابت عامل يقيسه فقط","الضابط والعامل الثابت اسمان للمتغير التابع","الضابط حالة يُقارَن بها، والعامل الثابت عامل يُبقيه الباحث دون تغيير","الضابط يبقى ثابتًا في كل المجموعات، والعامل الثابت هو ما يُقارَن به"]'::jsonb, 'فهم', 'تمييز الضابط من العامل الثابت', 'صعب', 'الكتاب ص 24 — الضابط وص 26'),
('essay', 1, 'وضّح دور الضابط في التجربة، ثم حدّد الضابط في تجربة اختبار أثر درجة الحرارة في سرعة ذوبان الملح، مبيّنًا كيف تُستعمل المقارنة به.', null, null, 'فهم', 'توضيح دور وتحديد ضابط', 'متوسط', 'الكتاب ص 24 — الضابط'),
('essay', 2, 'درس أربعة طلاب أثر شرب الصودا في معدل ضربات القلب، فسجّلوا عدد ضربات القلب في الدقيقة: الطالب 1 (صفر علب) 73، والطالب 2 (علبة واحدة) 84، والطالب 3 (علبتان) 89، والطالب 4 (ثلاث علب) 96. (أ) حدّد الضابط مع التعليل. (ب) احسب زيادة معدل ضربات القلب لكل طالب عن الضابط. (ج) اكتب ما تدل عليه المقارنة بالضابط.', null, null, 'تطبيق', 'تحديد الضابط وحساب الفروق', 'متوسط', 'الكتاب ص 24 — الضابط وص 41'),
('essay', 3, 'استُعملت ثلاثة أنابيب ضوابط تحوي كاشفًا كيميائيًا: في المحلول الحمضي يتحول لونه إلى الأحمر، وفي الماء يبقى أصفر، وفي المحلول القاعدي يتحول إلى الأزرق. أُضيف الكاشف نفسه إلى ثلاثة محاليل مجهولة الحموضة، فصار لون الكاشف في المحلول (س) أزرق، وفي (ص) أصفر، وفي (ع) أحمر. حدّد حموضة كل محلول، ثم فسّر لماذا لا يمكن تحديدها دون الضوابط.', null, null, 'تطبيق', 'استعمال الضوابط في التحديد', 'صعب', 'الكتاب ص 24 — الضابط والشكل 1-12')
