('mcq', 1, 0, 'الضابط يوجد للمقارنة؛ فتُقارن به نتائج المجموعات الأخرى في التجربة.', '["","الذي يغيّره الباحث عمدًا هو المتغير المستقل لا الضابط.","القياس يتعلق بالمتغير التابع، أما الضابط فلمقارنة النتائج.","الضابط أساسي في المقارنة ولا يُهمل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:32:48.130Z"}'::jsonb),
('mcq', 2, 1, 'الماء عند درجة حرارة الغرفة تُقارَن به نتائج الماء الساخن، فهو ضابط للمقارنة.', '["المتغير التابع هو سرعة الذوبان التي تُقاس.","","المتغير المستقل هو درجة الحرارة التي تُغيَّر.","العامل الثابت (كالملح والماء والتحريك) لا يتغير، وليس هو ما يقارن به."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:32:48.130Z"}'::jsonb),
('mcq', 3, 2, 'حموضة محاليل الأنابيب الثلاثة معروفة، فتُقارَن بألوانها نتيجة المحلول المجهول؛ ولذلك تُعدّ ضوابط.', '["ليس السبب ارتباط الألوان بدرجة الحرارة، بل أن حموضة محاليلها معروفة.","المتغير المستقل هو ما يغيّره الباحث، أما الضوابط فتستعمل للمقارنة.","","الكاشف يُضاف إلى المحلول المجهول أيضًا ليقارن لونه بالضوابط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:32:48.131Z"}'::jsonb),
('mcq', 4, 3, 'اللون الأحمر هو لون الكاشف في المحلول الحمضي المعروف، فبمقارنته بالضوابط يكون المحلول المجهول حمضيًا.', '["الكاشف يصبح أزرق في المحلول القاعدي المعروف لا أحمر.","الكاشف يبقى أصفر في الماء (المتعادل) لا أحمر.","لون المحلول يطابق لون الكاشف في المحلول الحمضي، فيمكن تحديد حموضته.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-18T03:32:48.131Z"}'::jsonb),
('mcq', 5, 0, 'الطالب 1 لم يشرب أي علبة صودا (صفر)، فتُقارن به نتائج الطلاب الآخرين؛ فهو الضابط.', '["","الطالب 2 شرب علبة واحدة، فهو ضمن مجموعات المتغير المستقل.","الطالب 3 شرب علبتين، فهو ضمن مجموعات المتغير المستقل.","الطالب 4 شرب ثلاث علب، فهو ضمن مجموعات المتغير المستقل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:32:48.131Z"}'::jsonb),
('mcq', 6, 3, 'المجموعة الثالثة لا تحتوي أي سماد، فتُقارَن بها نتائج المجموعتين المعالجتين بالسماد؛ فهي الضابط.', '["المجموعة الأولى تتعرض للمتغير المستقل (السماد أ)، فتُقارَن بالضابط ولا تمثله.","المجموعة الثانية تتعرض للمتغير المستقل (السماد ب)، فتُقارَن بالضابط ولا تمثله.","المجموعتان المعالجتان بالسماد هما ما تتم مقارنته بالضابط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:32:48.132Z"}'::jsonb),
('mcq', 7, 2, 'الضابط حالة معروفة تُقارَن بها النتائج، أما العامل الثابت فيُبقيه الباحث دون تغيير في كل العينات؛ وهذا ما تصفه العبارة المختارة.', '["الضابط لا يغيّره الباحث ليرى أثره، والعامل الثابت لا يُقاس بل يُترك دون تغيير.","المتغير التابع هو ما يتغير تبعًا للمستقل، وليس الضابط ولا العامل الثابت.","","هذه العبارة تعكس الدورين؛ فالذي يُقارَن به هو الضابط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.132Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الضابط يُستعمل للمقارنة بنتائج التجربة. وفي تجربة أثر درجة الحرارة في سرعة ذوبان الملح يكون الضابط هو الماء عند درجة حرارة الغرفة (20 °C). تُقارَن به نتيجة ذوبان الملح في الماء الساخن (مثلًا عند 40 °C)، فإذا ذاب الملح في زمن أقصر عند 40 °C منه في الضابط دلّ ذلك على أثر ارتفاع الحرارة في سرعة الذوبان.', '["الضابط يُستعمل للمقارنة","الضابط هو الماء عند 20 °C","تُقارَن نتيجة الماء الساخن بنتيجة الضابط","الفرق بين الزمنين يدل على أثر درجة الحرارة"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر أن الضابط للمقارنة","marks":1},{"element":"تحديد الضابط: الماء عند 20 °C","marks":1},{"element":"بيان مقارنة نتيجة الماء الساخن بنتيجة الضابط","marks":1},{"element":"ربط الفرق بين النتيجتين بأثر درجة الحرارة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة تشمل الدور والتحديد والمقارنة وربطها بالأثر"},{"level":"2–3 درجات","description":"إجابة صحيحة لعنصرين أو ثلاثة"},{"level":"1 درجة","description":"ذكر دور الضابط فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الماء الساخن ضابطًا","الخلط بين الضابط والعامل الثابت","ذكر الضابط دون بيان كيف يقارن به"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:32:48.132Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) الضابط هو الطالب 1؛ لأنه لم يشرب أي علبة صودا، فتُقارَن به نتائج الطلاب الآخرين. (ب) الزيادة عن الضابط: الطالب 2: 84 − 73 = 11 ضربة/دقيقة، الطالب 3: 89 − 73 = 16 ضربة/دقيقة، الطالب 4: 96 − 73 = 23 ضربة/دقيقة. (ج) تدل المقارنة على أن معدل ضربات القلب يزداد بزيادة عدد علب الصودا المشروبة، فالزيادة عن الضابط أكبر كلما زاد عددها.', '["الضابط: الطالب 1 (صفر علب)","التعليل: يقارن به الباقون","الزيادات: 11 و16 و23 ضربة/دقيقة","المقارنة: يزداد معدل القلب بزيادة عدد العلب"]'::jsonb, '["الضابط هو الطالب 1 (صفر علب)، ومعدله 73 ضربة/دقيقة","الطالب 2: 84 − 73 = 11 ضربة/دقيقة","الطالب 3: 89 − 73 = 16 ضربة/دقيقة","الطالب 4: 96 − 73 = 23 ضربة/دقيقة"]'::jsonb, '[{"element":"تحديد الضابط (الطالب 1)","marks":1},{"element":"تعليل اختياره","marks":1},{"element":"حساب الزيادات الثلاث صحيحة","marks":2},{"element":"الاستنتاج من المقارنة بالضابط","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تحديد الضابط وتعليله والحسابات الصحيحة والاستنتاج"},{"level":"3–4 درجات","description":"تحديد صحيح مع خطأ في إحدى الزيادات أو نقص في الاستنتاج"},{"level":"1–2 درجة","description":"تحديد الضابط فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الطالب 4 ضابطًا لأن قيمته الأكبر","طرح القيم من الطالب 4 بدل الضابط","الاكتفاء بسرد الأرقام دون استنتاج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:32:48.133Z"}'::jsonb),
('essay', 3, null::int, null, null, 'المحلول (س) قاعدي؛ لأن لون الكاشف فيه أزرق كما في الضابط القاعدي. المحلول (ص) متعادل؛ لأن لونه أصفر كما في الماء. المحلول (ع) حمضي؛ لأن لونه أحمر كما في الضابط الحمضي. ولا يمكن التحديد دون الضوابط؛ لأن حموضة محاليلها معروفة، فيُقارَن بألوانها لون الكاشف في المحاليل المجهولة، وبدونها لا يُعرف ماذا يعني كل لون.', '["س قاعدي","ص متعادل","ع حمضي","الضوابط حموضتها معروفة","المقارنة بألوانها تفسّر ألوان المجهولة"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد حموضة (س) مع الأساس","marks":1},{"element":"تحديد حموضة (ص) مع الأساس","marks":1},{"element":"تحديد حموضة (ع) مع الأساس","marks":1},{"element":"بيان أن حموضة الضوابط معروفة","marks":1},{"element":"بيان أن المقارنة بالضوابط تفسر ألوان المحاليل المجهولة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تحديد صحيح للمحاليل الثلاثة مع تفسير دور الضوابط"},{"level":"3–4 درجات","description":"تحديد صحيح لاثنين أو ثلاثة مع تفسير ناقص"},{"level":"1–2 درجة","description":"تحديد صحيح لمحلول واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس لوني الحمضي والقاعدي","عدّ الماء الأصفر محلولًا حمضيًا","القول إن الكاشف وحده يحدد الحموضة دون مقارنة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-18T03:32:48.133Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
