select (select id from public.objectives where code = 'K1-C1-L3-O09'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'إذا لم تدعم البيانات التي جمعتها في أثناء التجربة الفرضية، فماذا يجب عليك أن تفعل تجاه الفرضية؟', null, '["رفضها أو تعديلها بما يتفق مع البيانات","الاحتفاظ بها وتجاهل البيانات المخالفة","تكرار تسجيل القياسات حتى تتفق معها","اعتمادها قانونًا علميًا مباشرة"]'::jsonb, 'تقويم', 'تحديد الإجراء المناسب', 'سهل', 'الكتاب ص 25 — الاستنتاج وص 38'),
('mcq', 2, 'جاءت بيانات تجربة موافقة لتوقع فرضية. أيّ العبارات الآتية هي أنسب تقويم لدعم البيانات للفرضية؟', null, '["البيانات تؤيد الفرضية وتشير إلى أنها قد تكون صحيحة دون أن تثبتها","البيانات أثبتت الفرضية فلا حاجة إلى أي اختبار آخر","البيانات لا قيمة لها لأنها وافقت الفرضية","البيانات حوّلت الفرضية إلى حقيقة لا تقبل التعديل"]'::jsonb, 'تقويم', 'تقويم درجة الدعم', 'سهل', 'الكتاب ص 25 — الاستنتاج'),
('mcq', 3, 'وضع طالب الفرضية الآتية: «تزداد كتلة CO₂ المذابة في مشروب غازي بارتفاع درجة الحرارة». وسجّل بيانات تجربته في الجدول الآتي. ما تقويمك لدعم البيانات للفرضية؟', '{"headers":["درجة الحرارة (°C)","كتلة CO₂ المذابة (g)"],"rows":[["0","0.30"],["10","0.22"],["25","0.15"]]}'::jsonb, '["تدعمها؛ لأن الكتلة المذابة تزداد بارتفاع الحرارة","تدعمها؛ لأن CO₂ يوجد في جميع العينات","لا يمكن الحكم عليها؛ لأن القياسات ثلاثة فقط","لا تدعمها؛ فكتلة CO₂ المذابة تنقص بارتفاع درجة الحرارة"]'::jsonb, 'تقويم', 'تقويم دعم بيانات', 'متوسط', 'الكتاب ص 25 — الاستنتاج وص 40'),
('mcq', 4, 'وضع طالب الفرضية: «ارتفاع درجة حرارة الماء يزيد سرعة ذوبان ملح الطعام». سجّلت أربع مجموعات أزمنة الذوبان (بالدقائق) كما في الجدول الآتي. أيّ المجموعات تدعم الفرضية على أقوى نحو؟', '{"headers":["المجموعة","20 °C","40 °C","60 °C"],"rows":[["أ","3","3","3"],["ب","1","3","5"],["ج","3","3","1"],["د","4","2","1"]]}'::jsonb, '["المجموعة أ","المجموعة ب","المجموعة ج","المجموعة د"]'::jsonb, 'تقويم', 'مقارنة قوة الدعم', 'صعب', 'الكتاب ص 25 — الاستنتاج'),
('mcq', 5, 'وضع طالب الفرضية: «زيادة كمية السماد تزيد طول نبات القمح». وبعد أسابيع سجّل الجدول الآتي. ما أنسب إجراء في ضوء هذه البيانات؟', '{"headers":["كمية السماد (g)","طول النبات (cm)"],"rows":[["0","15"],["5","11"],["10","8"]]}'::jsonb, '["تجاهل البيانات والاحتفاظ بالفرضية لأنها منطقية","رفض الفرضية أو تعديلها لأن طول النبات ينقص بزيادة السماد","قبول الفرضية لأن النبات تأثر بالسماد","الاعتماد على القياس الأول (15 cm) وحده"]'::jsonb, 'تقويم', 'اختيار إجراء مناسب', 'صعب', 'الكتاب ص 25 — الاستنتاج وص 38'),
('mcq', 6, 'بعد تجربة لم تدعم بياناتها فرضيتها، قال الطالب أ: «سأحذف البيانات المخالفة»، وقال الطالب ب: «سأغيّر البيانات لتوافق فرضيتي»، وقالت الطالبة ج: «سأعدّل الفرضية أو أرفضها وأجري اختبارًا جديدًا». من تصرّف تصرفًا علميًا سليمًا؟', null, '["الطالب أ فقط","الطالب ب فقط","الطالبة ج فقط","الطالبان أ وب"]'::jsonb, 'تقويم', 'تقويم تصرفات', 'سهل', 'الكتاب ص 25 — الاستنتاج وص 38'),
('mcq', 7, 'بيّنت بيانات تجربة أن كتلة CO₂ المذابة في مشروب غازي تنقص من 0.30 g عند 0 °C إلى 0.15 g عند 25 °C، في حين كانت الفرضية أنها تزداد بارتفاع الحرارة. أيّ الصياغات الآتية تمثل تعديلًا مناسبًا للفرضية؟', null, '["تقل كتلة CO₂ المذابة في المشروب الغازي بارتفاع درجة الحرارة","لا تتأثر كتلة CO₂ المذابة بدرجة الحرارة","يذوب CO₂ في المشروب الغازي عند درجات الحرارة المرتفعة فقط","ذوبان CO₂ في السوائل مماثل لذوبان المواد الصلبة في كل الحالات"]'::jsonb, 'تقويم', 'تعديل فرضية', 'متوسط', 'الكتاب ص 25 — الاستنتاج وص 40'),
('essay', 1, 'وضع طالب فرضية: «تزداد كتلة CO₂ المذابة في مشروب غازي بارتفاع درجة الحرارة». وقاس كتلة CO₂ المذابة فوجدها 0.30 g عند 0 °C، و0.22 g عند 10 °C، و0.15 g عند 25 °C. قوّم دعم هذه البيانات للفرضية، وحدّد ما يجب فعله، واقترح فرضية معدلة.', null, null, 'تقويم', 'تقويم بيانات وتعديل فرضية', 'متوسط', 'الكتاب ص 25 — الاستنتاج وص 40'),
('essay', 2, 'وضعت طالبة فرضية: «ارتفاع درجة حرارة الماء يزيد سرعة ذوبان ملح الطعام»، فسجّلت زمن ذوبان الكتلة نفسها من الملح: 4 min عند 20 °C، و2 min عند 40 °C، و1 min عند 60 °C. وكتبت استنتاجها: «ثبتت صحة فرضيتي نهائيًا». قوّم مدى دعم البيانات للفرضية، ثم قوّم استنتاج الطالبة وأعد صياغته صياغة سليمة، وبيّن ما يلزم لمزيد من الثقة بالفرضية.', null, null, 'تقويم', 'تقويم استنتاج', 'صعب', 'الكتاب ص 25 — الاستنتاج'),
('essay', 3, 'قال ثلاثة طلاب بعد تجارب مختلفة: (1) «بياناتي أيدت فرضيتي، فهي إذن صحيحة تمامًا ولا تحتاج إلى أي اختبار آخر». (2) «بياناتي لم تدعم فرضيتي، فسأرفضها أو أعدّلها وأجري تجارب جديدة». (3) «بياناتي لم تدعم فرضيتي، فسأغيّر القياسات لتوافقها». قوّم كل قول، ثم اذكر المبدأ العلمي الذي تستند إليه في أحكامك.', null, null, 'تقويم', 'تقويم أقوال', 'متوسط', 'الكتاب ص 25 — الاستنتاج وص 38')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
