('mcq', 1, 0, 'عندما تأتي بيانات لا تدعم الفرضية فعلينا رفض الفرضية أو تعديلها بما يتفق مع البيانات.', '["","تجاهل البيانات المخالفة غير علمي؛ فالاستنتاج مبني على البيانات.","تعديل القياسات لتوافق الفرضية خطأ علمي.","القانون العلمي يتطلب دعم تجارب عدة، لا بيانات لا تدعم الفرضية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:32:48.134Z"}'::jsonb),
('mcq', 2, 0, 'لا يمكن إثبات فرضية ما؛ فعندما تؤيدها البيانات يشير ذلك فقط إلى أنها قد تكون صحيحة، وهذا ما تقرره العبارة الأولى.', '["","لا يمكن إثبات الفرضية نهائيًا، وقد تلزم اختبارات أخرى.","موافقة البيانات للتوقع هي ما يمنحها قيمة في دعم الفرضية.","الفرضية تبقى عرضة للتعديل مهما أيدتها البيانات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:32:48.135Z"}'::jsonb),
('mcq', 3, 3, 'الكتلة المذابة تنقص من 0.30 g عند 0 °C إلى 0.22 g عند 10 °C ثم إلى 0.15 g عند 25 °C، وهذا يخالف توقع الفرضية؛ فالبيانات لا تدعمها.', '["الجدول يبيّن أن الكتلة المذابة تنقص بارتفاع الحرارة لا أنها تزداد.","وجود CO₂ في العينات لا يكفي لدعم فرضية تتعلق بتأثير الحرارة.","القياسات الثلاثة تُظهر اتجاهًا واضحًا مخالفًا لتوقع الفرضية، فيمكن الحكم عليها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-18T03:32:48.135Z"}'::jsonb),
('mcq', 4, 3, 'في المجموعة د يقل زمن الذوبان بانتظام من 4 min إلى 2 min إلى 1 min مع ارتفاع الحرارة، فهذا أقوى دعم للفرضية.', '["زمن الذوبان ثابت (3 min) في الدرجات الثلاث، فلا أثر للحرارة.","زمن الذوبان يزداد بارتفاع الحرارة، فهذا يخالف الفرضية.","الزمن ثابت بين 20 °C و40 °C ثم يقل عند 60 °C، فالدعم جزئي أضعف من المجموعة د.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:32:48.135Z"}'::jsonb),
('mcq', 5, 1, 'الطول ينقص من 15 cm إلى 11 cm ثم 8 cm بزيادة السماد من 0 g إلى 5 g ثم 10 g، وهذا يخالف توقع الفرضية؛ فالإجراء المناسب رفض الفرضية أو تعديلها.', '["البيانات هي أساس الحكم؛ ومنطقية الفرضية لا تغني عن دعم البيانات.","","تأثر النبات بالسماد لا يعني دعم الفرضية؛ فالاتجاه مخالف لتوقعها.","اختيار قياس واحد وإهمال الباقي يتجاهل اتجاه البيانات كلها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:32:48.136Z"}'::jsonb),
('mcq', 6, 2, 'عند عدم دعم البيانات للفرضية يجب رفضها أو تعديلها، وهذا ما قالته الطالبة ج؛ أما حذف البيانات أو تغييرها فغير علمي.', '["حذف البيانات المخالفة تجاهل لما تقوله التجربة.","تغيير البيانات تزوير لا يجوز علميًا.","","كلا التصرفين لا يتفق مع ما يجب فعله عند عدم دعم البيانات للفرضية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:32:48.136Z"}'::jsonb),
('mcq', 7, 0, 'البيانات تُظهر أن الكتلة المذابة تنقص بارتفاع الحرارة؛ فالتعديل المناسب للفرضية هو أن كتلة CO₂ المذابة تقل بارتفاع درجة الحرارة.', '["","النقص من 0.30 g إلى 0.15 g يدل على تأثر الذوبان بدرجة الحرارة.","الكتلة الأكبر كانت عند الحرارة المنخفضة لا المرتفعة.","لا تدعم البيانات تعميم تشابه ذوبان CO₂ مع المواد الصلبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-18T03:32:48.136Z"}'::jsonb),
('essay', 1, null::int, null, null, 'البيانات لا تدعم الفرضية؛ لأن كتلة CO₂ المذابة تنقص بارتفاع درجة الحرارة (من 0.30 g إلى 0.15 g) في حين توقعت الفرضية أن تزداد. وعندما لا تدعم البيانات الفرضية يجب رفضها أو تعديلها. ويمكن اقتراح فرضية معدلة: تقل كتلة CO₂ المذابة في المشروب الغازي بارتفاع درجة الحرارة، ثم تُختبر بتجارب جديدة، ولا يُعدّ ذلك إثباتًا للفرضية الجديدة بل دعمًا لها إن أيدتها البيانات.', '["البيانات لا تدعم الفرضية","التعليل: الكتلة المذابة تنقص من 0.30 إلى 0.15 g","يجب رفض الفرضية أو تعديلها","فرضية معدلة: تقل الكتلة المذابة بارتفاع الحرارة","اختبار الفرضية المعدلة بتجارب جديدة"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم بأن البيانات لا تدعم الفرضية","marks":1},{"element":"التعليل بنقص الكتلة المذابة بارتفاع الحرارة","marks":1},{"element":"رفض الفرضية أو تعديلها","marks":1},{"element":"صياغة فرضية معدلة متسقة مع البيانات","marks":1},{"element":"اختبار الفرضية المعدلة بتجارب جديدة دون ادعاء إثباتها","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تقويم صحيح مع تعليل وإجراء وفرضية معدلة"},{"level":"3–4 درجات","description":"تقويم وتعليل صحيحان مع نقص في الإجراء أو الفرضية المعدلة"},{"level":"1–2 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن البيانات تدعم الفرضية","اقتراح تغيير البيانات لتوافق الفرضية","صياغة فرضية معدلة تخالف البيانات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-18T03:32:48.136Z"}'::jsonb),
('essay', 2, null::int, null, null, 'البيانات تدعم الفرضية دعمًا جيدًا؛ لأن زمن الذوبان يقل بانتظام بارتفاع درجة الحرارة (4 min ثم 2 min ثم 1 min). لكن استنتاج الطالبة غير سليم؛ لأننا لا نستطيع إثبات فرضية ما، فتأييد البيانات يشير فقط إلى أنها قد تكون صحيحة. والصياغة السليمة: «تدعم البيانات فرضية أن ارتفاع درجة الحرارة يزيد سرعة ذوبان الملح، وقد تكون الفرضية صحيحة». ولمزيد من الثقة تُجرى تجارب أخرى، فإذا ظهرت بيانات لا تدعمها وجب رفض الفرضية أو تعديلها.', '["البيانات تدعم الفرضية؛ نقص الزمن بارتفاع الحرارة","استنتاج الطالبة غير سليم؛ لا يمكن إثبات الفرضية","الصياغة: البيانات تدعم الفرضية وقد تكون صحيحة","مزيد من التجارب لزيادة الثقة","رفض أو تعديل الفرضية إذا ظهرت بيانات لا تدعمها"]'::jsonb, '[]'::jsonb, '[{"element":"تقويم دعم البيانات للفرضية مع التعليل","marks":1},{"element":"بيان أن عبارة «ثبتت نهائيًا» غير سليمة","marks":1},{"element":"إعادة صياغة الاستنتاج صياغة سليمة","marks":1},{"element":"اقتراح مزيد من التجارب لزيادة الثقة","marks":1},{"element":"بيان ما يُفعل عند ظهور بيانات لا تدعم الفرضية","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تقويم كامل للبيانات وللاستنتاج مع صياغة سليمة وخطوات لاحقة"},{"level":"3–4 درجات","description":"تقويم صحيح للبيانات والاستنتاج مع نقص في الصياغة أو الخطوات"},{"level":"1–2 درجة","description":"الحكم بدعم البيانات دون تقويم الاستنتاج"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول عبارة «ثبتت نهائيًا»","القول إن البيانات لا تدعم الفرضية","إعادة صياغة تتضمن كلمة الإثبات القاطع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:32:48.137Z"}'::jsonb),
('essay', 3, null::int, null, null, '(1) غير سليم؛ لأن تأييد البيانات يشير فقط إلى أن الفرضية قد تكون صحيحة، ولا يمكن إثبات فرضية ما. (2) سليم؛ لأن البيانات التي لا تدعم الفرضية تعني رفضها أو تعديلها ثم اختبارها من جديد. (3) غير سليم؛ لأن تغيير القياسات ليوافق الفرضية يلغي قيمة التجربة، والاستنتاج حكم قائم على المعلومات التي تم الحصول عليها. والمبدأ: الاستنتاج يُبنى على البيانات المحصلة، والبيانات تؤيد الفرضية أو لا تدعمها ولا تثبتها.', '["(1) غير سليم: لا يمكن إثبات الفرضية","(2) سليم: رفض أو تعديل ثم تجارب جديدة","(3) غير سليم: لا تُغيَّر القياسات","المبدأ: الاستنتاج مبني على البيانات"]'::jsonb, '[]'::jsonb, '[{"element":"تقويم القول (1) مع التعليل","marks":1},{"element":"تقويم القول (2) مع التعليل","marks":1},{"element":"تقويم القول (3) مع التعليل","marks":1},{"element":"ذكر المبدأ العلمي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تقويم صحيح للأقوال الثلاثة مع المبدأ"},{"level":"2–3 درجات","description":"تقويم صحيح لقولين مع المبدأ أو للثلاثة دون المبدأ"},{"level":"1 درجة","description":"تقويم صحيح لقول واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول القول (1) لأن البيانات أيدت الفرضية","رفض القول (2) لأن الفرضية يجب أن تبقى","عدم ذكر المبدأ المشترك"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:32:48.137Z"}'::jsonb)
