('mcq', 1, 'ما الصفة التي تجعل النموذج العلمي جيدًا؟', null, '["لا يمكن اختباره في المختبر أو في الطبيعة","يمكن فحصه واستعماله للقيام بتوقعات","يغني عن إجراء أي تجارب","لا يتغير مهما ظهرت بيانات جديدة"]'::jsonb, 'فهم', 'صفة النموذج الجيد', 'سهل', 'الكتاب ص 25 — الاستنتاج: النموذج العلمي'),
('mcq', 2, 'ماذا توقع نموذج مولينا ورولاند؟', null, '["زيادة غاز الأوزون في الستراتوسفير","تحول الأوزون إلى مركبات CFCs","اختفاء الأشعة فوق البنفسجية من الجو","تكوّن الكلور وتناقص غاز الأوزون"]'::jsonb, 'تذكر', 'تذكر توقع النموذج', 'سهل', 'الكتاب ص 25 — الاستنتاج: النموذج العلمي'),
('mcq', 3, 'إذا ازدادت كمية مركبات CFCs في الجو، فماذا يتوقع نموذج مولينا ورولاند عن كمية غاز الأوزون؟', null, '["تقل كمية الأوزون؛ لأن الكلور الناتج يحطم جزيئاته","تزداد كمية الأوزون؛ لأن CFCs تتحول إليه","لا تتغير؛ لأن CFCs لا تتفاعل مع الأوزون","تزداد ثم تثبت؛ لأن الكلور يحمي الأوزون"]'::jsonb, 'تطبيق', 'توقع من النموذج', 'متوسط', 'الكتاب ص 25 — الاستنتاج: النموذج العلمي وص 26'),
('mcq', 4, 'كيف تأكد العلماء من توقع نموذج مولينا ورولاند؟', null, '["أعاد مولينا ورولاند صياغة النموذج دون أي قياسات","اكتفى العلماء برأي عالم واحد دون اختبار","وجدت مجموعة بحثية أخرى بقياسات في الستراتوسفير دليلًا على تفاعل الأوزون والكلور","قارن العلماء النموذج بنموذج لا علاقة له بالغلاف الجوي"]'::jsonb, 'فهم', 'كيفية اختبار التوقع', 'سهل', 'الكتاب ص 25 — الاستنتاج: النموذج العلمي'),
('mcq', 5, 'لماذا يصعب اختبار نموذج تناقص الأوزون مباشرة في الجو؟', null, '["لأن غاز الأوزون لا يمكن قياس كميته في الجو أبدًا","لأن مركبات CFCs لا توجد في الجو إطلاقًا","لأن النموذج لا يتضمن أي توقعات قابلة للاختبار","لأن ضبط المتغيرات صعب؛ إذ توجد غازات أخرى، وتتغير الرياح والأشعة فوق البنفسجية"]'::jsonb, 'فهم', 'تفسير صعوبة ضبط المتغيرات', 'صعب', 'الكتاب ص 25 — الاستنتاج: النموذج العلمي'),
('mcq', 6, 'كيف يمكن التغلب على صعوبة ضبط المتغيرات في الجو عند اختبار النموذج؟', null, '["إهمال المتغيرات الأخرى وعدم قياسها","محاكاة الظروف في المختبر بحيث تُضبط المتغيرات بسهولة","إجراء القياسات مرة واحدة فقط في الجو","الاكتفاء بالنموذج دون أي اختبار"]'::jsonb, 'فهم', 'حل صعوبة الاختبار', 'متوسط', 'الكتاب ص 25 — الاستنتاج: النموذج العلمي وص 26'),
('mcq', 7, 'كيف يمكن لعدد قليل من ذرات الكلور أن يحطم كمية كبيرة من الأوزون وفق نموذج مولينا ورولاند؟', null, '["لأن الكلور يتجدد في التفاعل، فيتفاعل مع جزيئات أوزون أخرى مرة بعد أخرى","لأن ذرة الكلور تُستهلك كاملة عند تفاعلها الأول مع جزيء أوزون واحد","لأن ذرات الكلور تتحول إلى أوزون بعد كل تفاعل","لأن الأشعة فوق البنفسجية تحلل الأوزون وحدها دون الكلور"]'::jsonb, 'فهم', 'تفسير آلية النموذج', 'صعب', 'الكتاب ص 25 — الاستنتاج: النموذج العلمي والشكل 1-13'),
('essay', 1, 'وضّح كيف استُعمل نموذج مولينا ورولاند في إجراء توقع يمكن اختباره، وكيف أيّدت القياسات الأخرى هذا التوقع.', null, null, 'فهم', 'توضيح استعمال النموذج', 'متوسط', 'الكتاب ص 25 — الاستنتاج: النموذج العلمي'),
('essay', 2, 'لماذا يصعب ضبط المتغيرات عند اختبار نموذج تناقص الأوزون في الجو؟ وكيف يمكن اختبار النموذج مخبريًا؟', null, null, 'فهم', 'تفسير وحل', 'متوسط', 'الكتاب ص 25 — الاستنتاج: النموذج العلمي'),
('essay', 3, 'اكتُشف مركب جديد يطلق ذرات كلور عند تعرضه للأشعة فوق البنفسجية. استنادًا إلى نموذج مولينا ورولاند: (أ) ما توقعك لأثر هذا المركب في غاز الأوزون؟ برّر. (ب) صمّم اختبارًا مخبريًا لتوقعك، محدّدًا المتغير المستقل والمتغير التابع وعاملين ثابتين.', null, null, 'تطبيق', 'توقع وتصميم اختبار', 'صعب', 'الكتاب ص 25 — الاستنتاج: النموذج العلمي وص 26')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K1-C1-L3-O10') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'النماذج العلمية الجيدة يمكن فحصها واستعمالها للقيام بتوقعات؛ وهذه هي الصفة المطلوبة.', '["النموذج الجيد يمكن اختباره، فلا قيمة علمية لنموذج لا يُختبر.","","النموذج يختبر بالتجارب والقياسات ولا يغني عنها.","النموذج قد يُعدَّل إذا ظهرت بيانات جديدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-18T03:32:48.138Z"}'::jsonb),
('mcq', 2, 3, 'توقع نموذج مولينا ورولاند تكوّن الكلور وتناقص غاز الأوزون؛ فهذا هو التوقع القابل للاختبار.', '["النموذج توقع تناقص الأوزون لا زيادته.","النموذج يصف تحطم الأوزون بفعل الكلور، لا تحوله إلى CFCs.","الأشعة فوق البنفسجية هي التي تفصل الكلور عن CFCs، ولا تختفي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-18T03:32:48.138Z"}'::jsonb),
('mcq', 3, 0, 'كلما زادت CFCs تكوّن مزيد من الكلور الذي يحطم جزيئات الأوزون وفق النموذج؛ لذا يتوقع النموذج نقص كمية الأوزون.', '["","النموذج يتوقع تحطم الأوزون بالكلور لا تكوّنه من CFCs.","الكلور الناتج عن CFCs يتفاعل مع الأوزون ويحطمه.","الكلور لا يحمي الأوزون بل يحطمه وفق النموذج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:32:48.138Z"}'::jsonb),
('mcq', 4, 2, 'أُجريت قياسات في طبقة الستراتوسفير وجدت بها مجموعة بحثية أخرى دليلًا على تفاعل الأوزون والكلور، فأيّدت توقع النموذج.', '["إعادة الصياغة دون قياسات لا تختبر النموذج.","رأي عالم واحد دون اختبار لا يؤكد التوقع.","","المقارنة بنموذج لا علاقة له بالغلاف الجوي لا تختبر توقعات النموذج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-18T03:32:48.138Z"}'::jsonb),
('mcq', 5, 3, 'في الجو غازات أخرى غير الأوزون، كما أن الرياح وتغير الأشعة فوق البنفسجية قد تغير النتائج في أي وقت؛ فيصعب ضبط المتغيرات.', '["الأوزون يمكن قياسه، وقد أُجريت قياسات في الستراتوسفير.","CFCs موجودة في الجو وتبقى ثابتة فيه فترة طويلة.","النموذج توقع تكوّن الكلور وتناقص الأوزون، وهي توقعات قابلة للاختبار.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-10-18T03:32:48.138Z"}'::jsonb),
('mcq', 6, 1, 'قد يكون من الأسهل أحيانًا محاكاة الظروف مخبريًا بحيث يمكن ضبط المتغيرات بسهولة؛ فهذا هو الحل.', '["إهمال المتغيرات يجعل المقارنة أصعب.","","قياس واحد في الجو لا يضبط المتغيرات ولا يختبر النموذج.","النموذج الجيد يُفحص ولا يُكتفى به دون اختبار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-10-18T03:32:48.138Z"}'::jsonb),
('mcq', 7, 0, 'يتحد الكلور مع الأوزون فيتكون O₂ وClO، ثم يتفاعل ClO مع ذرة أكسجين فيتكون O₂ ويتحرر الكلور من جديد ليتفاعل مع جزيء أوزون آخر؛ لذلك تتكرر العملية.', '["","الكلور لا يُستهلك بل يتحرر من جديد في الخطوة التالية.","الكلور لا يتحول إلى أوزون؛ بل يحطمه.","الكلور هو ما يحطم الأوزون؛ والأشعة تفصل الكلور عن CFCs."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:32:48.139Z"}'::jsonb),
('essay', 1, null::int, null, null, 'ينص النموذج على أن الأشعة فوق البنفسجية تجعل الكلور ينفصل عن مركبات CFCs، ثم يقوم الكلور بتدمير غاز الأوزون بالاتحاد معه وتكوين O₂ وأول أكسيد الكلور ClO، ثم يتفاعل ClO مع ذرة أكسجين فيتكون O₂ ويتحرر الكلور ليتفاعل مجددًا. ومن النموذج توقعا تكوّن الكلور وتناقص غاز الأوزون، وهو توقع يمكن اختباره. وأيّدت قياسات أجرتها مجموعة بحثية أخرى في طبقة الستراتوسفير هذا التوقع إذ وجدت دليلًا على تفاعل الأوزون والكلور.', '["الأشعة تفصل الكلور عن CFCs","الكلور يتحد مع الأوزون ويدمره","التوقع: تكوّن الكلور وتناقص الأوزون","قياسات مجموعة أخرى أيدت تفاعل الأوزون والكلور"]'::jsonb, '[]'::jsonb, '[{"element":"وصف خطوة انفصال الكلور بفعل الأشعة","marks":1},{"element":"وصف تدمير الكلور للأوزون","marks":1},{"element":"ذكر التوقع القابل للاختبار","marks":1},{"element":"ذكر القياسات المؤيدة","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"وصف كامل للنموذج وتوقعه والقياسات المؤيدة"},{"level":"3–4 درجات","description":"وصف صحيح لعنصرين أو ثلاثة"},{"level":"1–2 درجة","description":"ذكر التوقع فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الأشعة فوق البنفسجية هي التي تحطم الأوزون مباشرة","الخلط بين التوقع والنتيجة المقيسة","ذكر القياسات دون ربطها بالتوقع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-18T03:32:48.139Z"}'::jsonb),
('essay', 2, null::int, null, null, 'يصعب ضبط المتغيرات في الجو لأن فيه غازات أخرى غير الأوزون قد تسبب تناقصه، ولأن الرياح وتغير الأشعة فوق البنفسجية قد يغيران نتائج أي تجربة في أي وقت، مما يجعل المقارنة صعبة. ولذلك قد يكون من الأسهل أحيانًا محاكاة الظروف مخبريًا بحيث يمكن ضبط المتغيرات بسهولة.', '["وجود غازات أخرى","الرياح وتغير الأشعة فوق البنفسجية يغيران النتائج","صعوبة المقارنة","محاكاة الظروف مخبريًا لضبط المتغيرات"]'::jsonb, '[]'::jsonb, '[{"element":"وجود غازات أخرى يصعب معه تحديد سبب التناقص","marks":1},{"element":"الرياح وتغير الأشعة يغيران النتائج","marks":1},{"element":"صعوبة المقارنة","marks":1},{"element":"المحاكاة المخبرية لضبط المتغيرات","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"ذكر الأسباب الثلاثة مع الحل المخبري"},{"level":"2–3 درجات","description":"ذكر سببين مع الحل أو ثلاثة أسباب دون الحل"},{"level":"1 درجة","description":"ذكر سبب واحد أو الحل فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الأوزون لا يمكن قياسه","القول إن المختبر لا يصلح لاختبار النماذج","عدم ربط الصعوبة بضبط المتغيرات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-10-18T03:32:48.139Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) أتوقع أن يتناقص غاز الأوزون؛ لأن الكلور الناتج يتفاعل مع جزيئات الأوزون ويحطمها مرة بعد أخرى كما في النموذج. (ب) أحاكي ظروف الجو في وعاء مخبري يحتوي مقدارًا معلومًا من الأوزون، وأعرّضه للأشعة فوق البنفسجية مع كميات مختلفة من المركب الجديد. المتغير المستقل: كمية المركب الجديد. المتغير التابع: كمية الأوزون المتبقية بعد مدة محددة. عاملان ثابتان: شدة الأشعة فوق البنفسجية ومدة التعريض (أو الحجم ودرجة الحرارة وكمية الأوزون الابتدائية).', '["توقع تناقص الأوزون","التبرير: الكلور يتفاعل مع الأوزون ويحطمه","المستقل: كمية المركب","التابع: كمية الأوزون المتبقية","عاملان ثابتان صحيحان"]'::jsonb, '[]'::jsonb, '[{"element":"توقع تناقص الأوزون","marks":1},{"element":"تبرير التوقع بالنموذج","marks":1},{"element":"المتغير المستقل الصحيح","marks":1},{"element":"المتغير التابع الصحيح","marks":1},{"element":"عاملان ثابتان صحيحان","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"توقع مبرر وتصميم صحيح بمتغيرين وعاملين ثابتين"},{"level":"3–4 درجات","description":"توقع صحيح مع تصميم ناقص"},{"level":"1–2 درجة","description":"توقع صحيح دون تصميم"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["توقع زيادة الأوزون","عدّ كمية الأوزون المتبقية متغيرًا مستقلًا","عدم ذكر عوامل ثابتة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:32:48.139Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
