from (values
('mcq', 1, 'أيّ العبارات الآتية تصف البحث التطبيقي؟', null, '["بحث يُجرى للحصول على المعرفة نفسها","بحث يُجرى لحل مشكلة محددة","بحث يُجرى بدافع حب الاستطلاع فقط","بحث لا يستعمل الطرائق العلمية"]'::jsonb, 'فهم', 'تمييز تعريف', 'سهل', 'الكتاب ص 27 — أنواع الدراسات والأبحاث العلمية'),
('mcq', 2, 'أيّ الأبحاث الآتية مثال على بحث نظري؟', null, '["إيجاد طرائق لإبطاء صدأ الحديد","البحث عن أنواع أخرى من الوقود لتسيير السيارات","إنتاج مواد بلاستيكية مقاومة للحرارة لاستعمالها في الأفران المنزلية","إنتاج عناصر اصطناعية لدراسة خواصها"]'::jsonb, 'تطبيق', 'تصنيف أمثلة', 'سهل', 'الكتاب ص 41 — اختبار مقنن (سؤال 6)، ص 27'),
('mcq', 3, 'كان علماء يدرسون أنابيب التفريغ الكهربائي بدافع حب الاستطلاع، فاكتشفوا الأشعة السينية، ثم استُعملت هذه الأشعة في التشخيص الطبي. كيف يوصف ما حدث؟', null, '["بدأ الأمر ببحث نظري، ثم استُعملت نتائجه لتلبية حاجة طبية محددة","بدأ الأمر ببحث تطبيقي، ثم تحوّل إلى بحث نظري لدراسة الأنابيب","كان الأمر كله بحثًا نظريًّا لأن الأشعة اكتُشفت بدافع الاستطلاع","كان الأمر كله بحثًا تطبيقيًّا لأن الأشعة مفيدة طبيًّا"]'::jsonb, 'تحليل', 'تحليل موقف تاريخي', 'متوسط', 'الكتاب ص 27 — الربط مع الحياة (الأشعة السينية)'),
('mcq', 4, 'درس مولينا ورولاند مركبات CFCs وتفاعلاتها مع الأوزون بدافع حب الاستطلاع، ثم أُشير عام 1985م إلى وجود ثقب في طبقة الأوزون، فصارت دراسة CFCs تُجرى لمراقبة كمياتها والبحث عن بدائل لها. ما سبب تحوّل هذا البحث من نظري إلى تطبيقي؟', null, '["توقف العلماء عن استعمال الطرائق العلمية في دراسته","لم تعد مركبات CFCs تتفاعل مع غاز الأوزون","أصبح يُجرى لحل مشكلة محددة هي تناقص غاز الأوزون","أصبح يُجرى للحصول على المعرفة نفسها فقط"]'::jsonb, 'تحليل', 'تحليل سبب', 'متوسط', 'الكتاب ص 27 — أنواع الدراسات والأبحاث العلمية'),
('mcq', 5, 'أيّ المقارنات الآتية بين البحث النظري والبحث التطبيقي صحيحة؟', null, '["النظري هدفه حل مشكلة محددة، والتطبيقي هدفه المعرفة نفسها","النظري يستعمل الطرائق العلمية، أما التطبيقي فلا يستعملها","النظري لا يتحول إلى تطبيقي أبدًا، أما التطبيقي فيتحول إلى نظري","النظري هدفه المعرفة نفسها، والتطبيقي هدفه حل مشكلة محددة"]'::jsonb, 'تحليل', 'مقارنة', 'سهل', 'الكتاب ص 27 — أنواع الدراسات والأبحاث العلمية'),
('mcq', 6, 'في ما يأتي أهداف أربع دراسات علمية. أيّ الدراستين تُعدّان بحثين تطبيقيين؟', '{"headers":["الدراسة","الهدف"],"rows":[["1","دراسة بنية بلورة معدن جديد لمعرفة سبب شكلها فقط"],["2","تطوير طلاء يبطئ صدأ أنابيب الحديد"],["3","قياس كمية CFCs في الجو كل عام لمتابعة مشكلة الأوزون"],["4","دراسة سلوك غاز جديد بدافع حب الاستطلاع"]]}'::jsonb, '["الدراستان 1 و4","الدراستان 2 و3","الدراستان 1 و2","الدراستان 3 و4"]'::jsonb, 'تحليل', 'تصنيف دراسات من بيانات', 'متوسط', 'الكتاب ص 27 — أنواع الدراسات والأبحاث العلمية'),
('mcq', 7, 'قال طالب: «لا قيمة للبحث النظري لأنه لا يحل مشكلة محددة». أيّ الردود الآتية أدق علميًّا؟', null, '["الرأي غير دقيق؛ فقد تُستعمل معرفة البحث النظري لاحقًا، كما استُعملت الأشعة السينية في التشخيص الطبي","الرأي دقيق؛ لأن نتائج البحث النظري لا يمكن استعمالها في أي تطبيق","الرأي دقيق؛ لأن الغرض من كل بحث علمي هو حل مشكلة محددة","الرأي غير دقيق؛ لأن البحث النظري هو الذي يراقب كميات الملوثات في الجو"]'::jsonb, 'تقويم', 'تقويم رأي', 'صعب', 'الكتاب ص 27 — الربط مع الحياة'),
('essay', 1, 'قارن بين البحث النظري والبحث التطبيقي من حيث الهدف، وأعطِ مثالًا من دراسة مركبات CFCs على كل منهما.', null, null, 'تحليل', 'مقارنة مع أمثلة', 'متوسط', 'الكتاب ص 27 — أنواع الدراسات والأبحاث العلمية'),
('essay', 2, 'اشرح كيف تحوّل البحث في مركبات CFCs من بحث نظري إلى بحث تطبيقي، مع ذكر الحدث الذي سبّب هذا التحول ومثالين على البحوث التطبيقية التي أُجريت بعده.', null, null, 'تحليل', 'تحليل تحول', 'صعب', 'الكتاب ص 27 — أنواع الدراسات والأبحاث العلمية'),
('essay', 3, 'صنّف كل دراسة مما يأتي إلى بحث نظري أو بحث تطبيقي مع التعليل: (أ) دراسة تفاعلات CFCs مع الأوزون في المختبر بدافع حب الاستطلاع. (ب) البحث عن مادة بديلة لمركبات CFCs. (ج) قياس تركيز الأوزون في الستراتوسفير كل سنة. (د) دراسة خواص عنصر اصطناعي جديد لمعرفة خواصه فقط.', null, null, 'تحليل', 'تصنيف مع تعليل', 'سهل', 'الكتاب ص 27 — أنواع الدراسات والأبحاث العلمية')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
