from (values
('mcq', 1, 1, 'البحث التطبيقي بحث يُجرى لحل مشكلة محددة، كمراقبة كميات CFCs في الجو أو البحث عن بدائل لها؛ فالعبارة الصحيحة هي «بحث يُجرى لحل مشكلة محددة».', '["هذا وصف البحث النظري؛ فهو الذي يُجرى للحصول على المعرفة نفسها.","","حب الاستطلاع هو دافع البحث النظري، أما البحث التطبيقي فله هدف عملي محدد.","الطرائق العلمية تُستعمل في البحوث النظرية والتطبيقية معًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-18T03:32:48.140Z"}'::jsonb),
('mcq', 2, 3, 'إنتاج عناصر اصطناعية لدراسة خواصها يهدف إلى معرفة الخواص نفسها دون حل مشكلة محددة، فهو بحث نظري.', '["يهدف إلى حل مشكلة محددة هي صدأ الحديد، فهو بحث تطبيقي.","يهدف إلى حل مشكلة محددة هي إيجاد وقود بديل، فهو بحث تطبيقي.","يهدف إلى تلبية حاجة محددة هي استعمال المادة في الأفران، فهو بحث تطبيقي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:32:48.140Z"}'::jsonb),
('mcq', 3, 0, 'دراسة أنابيب التفريغ بدافع حب الاستطلاع بحث نظري، واستعمال الأشعة الناتجة في التشخيص الطبي تلبية لحاجة محددة؛ فالصحيح «بدأ الأمر ببحث نظري، ثم استُعملت نتائجه لتلبية حاجة طبية محددة».', '["","البداية كانت بدافع الاستطلاع وليس لحل مشكلة، فالتحول جرى من النظري إلى التطبيقي لا العكس.","الاستعمال الطبي اللاحق للأشعة تطبيق عملي للمعرفة، فلا يصح عدّ الأمر كله نظريًّا.","الدراسة الأولى لم تكن لحل مشكلة محددة، فلا تُعدّ بحثًا تطبيقيًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:32:48.140Z"}'::jsonb),
('mcq', 4, 2, 'بعد اكتشاف ثقب الأوزون صار الهدف حل مشكلة محددة هي تناقص الأوزون، فتحوّل البحث إلى تطبيقي؛ والصحيح «أصبح يُجرى لحل مشكلة محددة هي تناقص غاز الأوزون».', '["الطرائق العلمية تُستعمل في البحث التطبيقي كما تُستعمل في النظري، وتغيّر الهدف هو سبب التحول.","التحول لم يحدث لأن التفاعل توقف؛ فالمشكلة قائمة لأن CFCs تسرّع تفكك الأوزون.","","هذا هدف البحث النظري، أما بعد ظهور المشكلة فالهدف حلها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:32:48.140Z"}'::jsonb),
('mcq', 5, 3, 'يُجرى البحث النظري من أجل المعرفة نفسها، ويُجرى التطبيقي لحل مشكلة محددة؛ فالمقارنة الصحيحة هي «النظري هدفه المعرفة نفسها، والتطبيقي هدفه حل مشكلة محددة».', '["الهدفان معكوسان في هذه العبارة.","الطرائق العلمية تُستعمل في النوعين معًا.","قد يتحول البحث النظري إلى تطبيقي، كما حدث في دراسة CFCs بعد اكتشاف ثقب الأوزون.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-18T03:32:48.140Z"}'::jsonb),
('mcq', 6, 1, 'تطوير طلاء يبطئ الصدأ (الدراسة 2) وقياس كمية CFCs سنويًّا لمتابعة مشكلة الأوزون (الدراسة 3) كلتاهما لحل مشكلة محددة؛ فالجواب «الدراستان 2 و3».', '["الدراسة 1 والدراسة 4 هدفهما معرفة الظاهرة نفسها دون مشكلة محددة، فهما نظريتان.","","الدراسة 1 نظرية، وإن كانت الدراسة 2 تطبيقية.","الدراسة 4 نظرية، وإن كانت الدراسة 3 تطبيقية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (2%)"}],"at":"2026-10-18T03:32:48.141Z"}'::jsonb),
('mcq', 7, 0, 'المعرفة التي ينتجها البحث النظري قد تُطبَّق لاحقًا، فالأشعة السينية اكتُشفت في بحث نظري ثم استُعملت في التشخيص الطبي؛ فالرد الأدق هو أن الرأي غير دقيق لهذا السبب.', '["","الرأي غير دقيق؛ فنتائج البحث النظري تُستعمل في تطبيقات لاحقة، كاستعمال الأشعة السينية في التشخيص الطبي.","حل مشكلة محددة هدف البحث التطبيقي فقط، أما النظري فهدفه المعرفة نفسها.","مراقبة كميات الملوثات من أعمال البحث التطبيقي لا النظري."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:32:48.141Z"}'::jsonb),
('essay', 1, null::int, null, null, 'البحث النظري يُجرى للحصول على المعرفة نفسها بدافع حب الاستطلاع، ومثاله دراسة مولينا ورولاند لمركبات CFCs وتفاعلاتها مع غاز الأوزون. أما البحث التطبيقي فيُجرى لحل مشكلة محددة، ومثاله مراقبة كميات CFCs في الجو والتغيرات السنوية في غاز الأوزون، أو البحث عن بدائل لمركبات CFCs.', '["هدف البحث النظري: المعرفة نفسها","هدف البحث التطبيقي: حل مشكلة محددة","مثال نظري من CFCs","مثال تطبيقي من CFCs"]'::jsonb, '[]'::jsonb, '[{"element":"هدف البحث النظري","marks":1},{"element":"هدف البحث التطبيقي","marks":1},{"element":"مثال نظري من CFCs","marks":1},{"element":"مثال تطبيقي من CFCs","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"هدفان صحيحان مع مثالين صحيحين"},{"level":"2–3 درجات","description":"هدفان صحيحان دون أمثلة، أو بعض العناصر ناقصة"},{"level":"1 درجة","description":"ذكر هدف واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس هدفي النوعين","القول إن الطريقة العلمية تُستعمل في أحد النوعين فقط","عدّ مراقبة كميات CFCs بحثًا نظريًّا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-18T03:32:48.141Z"}'::jsonb),
('essay', 2, null::int, null, null, 'بدأ البحث نظريًّا عندما درس مولينا ورولاند مركبات CFCs وتفاعلاتها مع غاز الأوزون بدافع حب الاستطلاع، وبيّنا أنها قد تسرّع تفكك الأوزون. وفي عام 1985م أُشير إلى وجود ثقب في طبقة الأوزون، فأصبحت المشكلة محددة، وصار الهدف حلها، فتحوّل البحث إلى تطبيقي. ومن البحوث التطبيقية بعده: مراقبة كميات CFCs في الجو والتغيرات السنوية في كمية الأوزون، والبحث عن بدائل لمركبات CFCs التي أصبحت ممنوعة.', '["البداية نظرية بدافع حب الاستطلاع","الحدث: اكتشاف ثقب الأوزون عام 1985م","السبب: ظهور مشكلة محددة هدفها الحل","مثالان تطبيقيان: مراقبة CFCs والأوزون، والبحث عن بدائل"]'::jsonb, '[]'::jsonb, '[{"element":"وصف البداية النظرية","marks":1},{"element":"ذكر الحدث (ثقب الأوزون 1985م)","marks":1},{"element":"تعليل التحول بظهور مشكلة محددة","marks":1},{"element":"مثالان تطبيقيان (درجة لكل مثال)","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"شرح كامل: بداية نظرية، حدث، تعليل، ومثالان"},{"level":"3–4 درجات","description":"شرح صحيح مع نقص في الحدث أو التعليل أو أحد المثالين"},{"level":"1–2 درجة","description":"ذكر جزء من التسلسل فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن التحول سببه التوقف عن استعمال الطرائق العلمية","عدم ربط التحول بظهور مشكلة محددة","عدّ دراسة مولينا ورولاند بحثًا تطبيقيًّا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:32:48.141Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) بحث نظري؛ لأن هدفه المعرفة نفسها بدافع حب الاستطلاع. (ب) بحث تطبيقي؛ لأن هدفه حل مشكلة محددة هي إيجاد بديل لمركبات ممنوعة. (ج) بحث تطبيقي؛ لأن هدفه مراقبة مشكلة تناقص الأوزون. (د) بحث نظري؛ لأن هدفه معرفة خواص العنصر دون مشكلة محددة.', '["أ نظري","ب تطبيقي","ج تطبيقي","د نظري","تعليل كل تصنيف بهدف الدراسة"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف (أ) مع التعليل","marks":1},{"element":"تصنيف (ب) مع التعليل","marks":1},{"element":"تصنيف (ج) مع التعليل","marks":1},{"element":"تصنيف (د) مع التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تصنيف الدراسات الأربع صحيحًا مع تعليل كل منها"},{"level":"2–3 درجات","description":"تصنيف صحيح لدراستين أو ثلاث مع تعليلها"},{"level":"1 درجة","description":"تصنيف صحيح لدراسة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ قياس تركيز الأوزون بحثًا نظريًّا لأنه قياس فقط","التصنيف دون ذكر الهدف الذي يبرره","الخلط بين الدراسة المخبرية والبحث النظري"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:32:48.141Z"}'::jsonb)
